"use client"
import { usePermissions } from "@/hooks/usePermissions"
import { useRequestGuard } from "@/hooks/useRequestGuard"

import { boundedFullList } from "@/lib/bounded-records"
import { useCallback, useEffect, useState } from "react"
import Link from "next/link"
import { homePagesCollection } from "@/lib/pb-collections"
import { formatDate } from "@/lib/format-date"
import { HomePage } from "@/types/cms"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Eye, Loader2, Plus, Pencil, Lock, Trash2 } from "lucide-react"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { useAuth } from "@/hooks/useAuth"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"

export default function CmsHomePagesListPage() {
  const access = usePermissions()
  const { lang } = useLang()
  const { isSuperAdmin } = useAuth()
  const [pages, setPages] = useState<HomePage[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreate, setShowCreate] = useState(false)
  const [newSlug, setNewSlug] = useState("")
  const [newTitle, setNewTitle] = useState("")
  const [creatingPage, setCreatingPage] = useState(false)
  const [loadError, setLoadError] = useState("")
  const beginRequest = useRequestGuard("cms-home-pages")

  const loadPages = useCallback(async () => {
    const isCurrent = beginRequest()
    setLoading(true)
    setLoadError("")
    try {
      const data = await boundedFullList(pb.collection("home_pages"))
      if (isCurrent()) setPages(data as unknown as HomePage[])
    } catch (error) {
      if (isCurrent()) setLoadError(getErrorMessage(error))
    } finally {
      if (isCurrent()) setLoading(false)
    }
  }, [beginRequest])

  useEffect(() => {
    void loadPages()
  }, [loadPages])

  const handleCreate = async () => {
    if (!newSlug.trim() || !newTitle.trim()) return
    setCreatingPage(true)
    try {
      await homePagesCollection.create({
        slug: newSlug.trim(),
        title: newTitle.trim(),
      })
      setNewSlug("")
      setNewTitle("")
      setShowCreate(false)
      loadPages()
    } catch (err) {
      toast.error(
        t(
          {
            en: "Failed to create page. Slug must be unique.",
            ar: "فشل إنشاء الصفحة. يجب أن يكون المعرف (slug) فريداً.",
          },
          lang
        ),
        { description: getErrorMessage(err) }
      )
    } finally {
      setCreatingPage(false)
    }
  }

  const togglePublish = async (page: HomePage) => {
    try {
      const updated = await homePagesCollection.update(page.id, {
        is_published: !page.is_published,
      })
      setPages((prev) => prev.map((p) => (p.id === page.id ? updated : p)))
    } catch (err) {
      toast.error(
        t({ en: "Failed to update status.", ar: "فشل تحديث الحالة." }, lang),
        { description: getErrorMessage(err) }
      )
    }
  }

  const handleDelete = async (page: HomePage) => {
    if (
      !confirm(
        t(
          {
            en: `Delete "${page.title_en}"? This cannot be undone.`,
            ar: `حذف "${page.title_en}"؟ لا يمكن التراجع عن هذا.`,
          },
          lang
        )
      )
    )
      return
    try {
      await homePagesCollection.delete(page.id)
      setPages((prev) => prev.filter((p) => p.id !== page.id))
    } catch (err) {
      toast.error(
        t({ en: "Failed to delete page.", ar: "فشل حذف الصفحة." }, lang),
        { description: getErrorMessage(err) }
      )
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold">
            {t({ en: "Home Pages", ar: "صفحات رئيسية" }, lang)}
          </h1>
          <p className="text-muted-foreground">
            {t(
              {
                en: "Manage About Us, Contact Us, and other site pages",
                ar: "إدارة صفحات من نحن وتواصل معنا وصفحات الموقع الأخرى",
              },
              lang
            )}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isSuperAdmin && (
            <Button
              variant="outline"
              disabled={!access.can("cms.create")}
              onClick={() => setShowCreate(!showCreate)}
            >
              <Plus className="mr-2 h-4 w-4" />
              {t({ en: "New Page", ar: "صفحة جديدة" }, lang)}
            </Button>
          )}
        </div>
      </div>

      {isSuperAdmin && showCreate && (
        <div className="rounded-md border bg-gray-50 p-4">
          <div className="dsc-form-grid">
            <div className="space-y-2">
              <Label htmlFor="slug">
                {t({ en: "URL Slug", ar: "معرف الرابط (Slug)" }, lang)}
              </Label>
              <Input
                id="slug"
                value={newSlug}
                onChange={(e) =>
                  setNewSlug(e.target.value.toLowerCase().replace(/\s+/g, "-"))
                }
                placeholder={t(
                  {
                    en: "e.g., about, contact, privacy",
                    ar: "مثال: about، contact، privacy",
                  },
                  lang
                )}
              />
              <p className="text-xs text-muted-foreground">
                {t(
                  { en: "This will be the URL: /", ar: "سيكون الرابط: /" },
                  lang
                )}
                {newSlug || "slug"}
              </p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="title">
                {t({ en: "Page Title", ar: "عنوان الصفحة" }, lang)}
              </Label>
              <Input
                id="title"
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                placeholder={t(
                  { en: "e.g., About Us", ar: "مثال: من نحن" },
                  lang
                )}
              />
            </div>
          </div>
          <div className="mt-4 flex justify-end gap-2">
            <Button variant="outline" onClick={() => setShowCreate(false)}>
              {t(UI_STRINGS.cancel, lang)}
            </Button>
            <Button
              onClick={handleCreate}
              disabled={
                !access.can("cms.create") ||
                creatingPage ||
                !newSlug.trim() ||
                !newTitle.trim()
              }
            >
              {creatingPage ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : null}
              {t({ en: "Create Page", ar: "إنشاء الصفحة" }, lang)}
            </Button>
          </div>
        </div>
      )}

      {loadError ? (
        <div role="alert" className="space-y-3 rounded-md border border-destructive p-4">
          <p>{t({ en: "Unable to load pages.", ar: "تعذر تحميل الصفحات." }, lang)} {loadError}</p>
          <Button variant="outline" onClick={() => void loadPages()}>
            {t({ en: "Retry", ar: "إعادة المحاولة" }, lang)}
          </Button>
        </div>
      ) : loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      ) : pages.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <p className="text-muted-foreground">
            {t({ en: "No pages yet.", ar: "لا توجد صفحات بعد." }, lang)}
          </p>
          {isSuperAdmin && (
            <Button
              disabled={!access.can("cms.create")}
              onClick={() => setShowCreate(true)}
              className="mt-4"
            >
              {t(
                { en: "Create your first page", ar: "أنشئ صفحتك الأولى" },
                lang
              )}
            </Button>
          )}
        </div>
      ) : (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t({ en: "Title", ar: "العنوان" }, lang)}</TableHead>
                <TableHead>
                  {t({ en: "Last Updated", ar: "آخر تحديث" }, lang)}
                </TableHead>
                <TableHead>{t({ en: "Status", ar: "الحالة" }, lang)}</TableHead>
                <TableHead className="w-24">
                  {t({ en: "Actions", ar: "إجراءات" }, lang)}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {pages.map((page) => (
                <TableRow key={page.id}>
                  <TableCell className="font-medium">{page.title_en}</TableCell>
                  <TableCell>{formatDate(page.updated)}</TableCell>
                  <TableCell>
                    <button
                      disabled={!access.can("cms.update")}
                      onClick={() => togglePublish(page)}
                      className="flex items-center gap-1"
                    >
                      {page.is_published ? (
                        <Badge className="bg-green-600 text-white">
                          <Eye className="mr-1 h-3 w-3" />
                          {t(UI_STRINGS.published, lang)}
                        </Badge>
                      ) : (
                        <Badge variant="secondary">
                          <Lock className="mr-1 h-3 w-3" />
                          {t(UI_STRINGS.draft, lang)}
                        </Badge>
                      )}
                    </button>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      <Button variant="ghost" size="icon" asChild>
                        <Link href={`/cms/home-pages/${page.slug}`}>
                          <Pencil className="h-4 w-4" />
                        </Link>
                      </Button>
                      {isSuperAdmin && (
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleDelete(page)}
                        >
                          <Trash2 className="h-4 w-4 text-red-500" />
                        </Button>
                      )}
                      {page.is_published && (
                        <Button variant="ghost" size="icon" asChild>
                          <Link href={`/${page.slug}`} target="_blank">
                            <Eye className="h-4 w-4 text-green-600" />
                          </Link>
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  )
}

"use client"
import { useUiTranslation } from "@/hooks/useUiTranslation"

import { useEffect, useState, useCallback, useRef } from "react"
import { useParams, useRouter } from "next/navigation"
import Link from "next/link"
import { usePortals } from "@/hooks/usePortals"
import { infoPagesCollection } from "@/lib/pb-collections"
import pb, { getErrorMessage } from "@/lib/pb"
import type { InfoPage } from "@/types/cms"
import type { Lang } from "@/types/form"
import { RichTextEditor } from "@/components/cms/RichTextEditor"
import { CmsPreviewDialog } from "@/components/cms/CmsPreviewDialog"
import { Switch } from "@/components/ui/switch"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card } from "@/components/ui/card"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { ArrowLeft, ArrowRight, Eye, Loader2, Copy, Trash2 } from "lucide-react"
import { toast } from "sonner"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"

function extractIcon(record: Record<string, unknown>): string {
  const icon = record.icon
  if (!icon) return ""
  if (Array.isArray(icon)) return icon[0] || ""
  return icon as string
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

async function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file)
    const img = new Image()
    img.onload = () => {
      URL.revokeObjectURL(url)
      resolve(img)
    }
    img.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error("Invalid image"))
    }
    img.src = url
  })
}

async function resizeIconToSquare(file: File, size = 256): Promise<File> {
  const img = await loadImage(file)
  const canvas = document.createElement("canvas")
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext("2d")
  if (!ctx) throw new Error("Canvas not supported")

  const side = Math.min(img.naturalWidth, img.naturalHeight)
  const sx = (img.naturalWidth - side) / 2
  const sy = (img.naturalHeight - side) / 2
  ctx.drawImage(img, sx, sy, side, side, 0, 0, size, size)

  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("Failed to process image"))),
      "image/png"
    )
  })
  return new File([blob], "icon.png", { type: "image/png" })
}

export default function CmsServiceEditorPage() {
  const ui = useUiTranslation()

  const { lang } = useLang()
  const { portals: PORTALS } = usePortals()
  const getPortalById = (id: string) => PORTALS.find((portal) => portal.id === id)
  const BackIcon = lang === "ar" ? ArrowRight : ArrowLeft
  const params = useParams()
  const router = useRouter()
  const portalId = params.portalId as string
  const slug = params.slug as string
  const portal = getPortalById(portalId)
  const [activeLang, setActiveLang] = useState<Lang>("en")

  const [page, setPage] = useState<InfoPage | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [publishing, setPublishing] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const [uploadingIcon, setUploadingIcon] = useState(false)
  const [previewOpen, setPreviewOpen] = useState(false)

  const [pageSlug, setPageSlug] = useState(slug)
  const [enTitle, setEnTitle] = useState("")
  const [arTitle, setArTitle] = useState("")
  const [enContent, setEnContent] = useState("")
  const [arContent, setArContent] = useState("")
  const [isPublished, setIsPublished] = useState(false)
  const [iconUrl, setIconUrl] = useState<string | null>(null)

  const [resetKey, setResetKey] = useState(0)

  const isInitialMount = useRef(true)
  const pageRecordRef = useRef<Record<string, unknown> | null>(null)

  useEffect(() => {
    async function load() {
      const data = await infoPagesCollection.getBySlug(slug)
      if (!data) {
        setLoading(false)
        return
      }
      pageRecordRef.current = data as unknown as Record<string, unknown>
      const iconFile = extractIcon(pageRecordRef.current)
      setIconUrl(
        iconFile && pageRecordRef.current
          ? pb.files.getURL(pageRecordRef.current, iconFile)
          : null
      )
      setPage(data)
      setPageSlug(data.slug)
      setEnTitle(data.title_en)
      setArTitle(data.title_ar || "")
      setEnContent(data.content_en)
      setArContent(data.content_ar || "")
      setIsPublished(data.is_published)
      setLoading(false)
    }
    load()
  }, [slug, portalId])

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false
      return
    }
    setPageSlug(slugify(enTitle))
  }, [enTitle])

  const handleSave = useCallback(
    async (overrideContent?: string) => {
      if (!page) return
      setSaving(true)
      try {
        const contentField = `content_${activeLang}` as const
        const contentValue =
          overrideContent !== undefined
            ? overrideContent
            : activeLang === "en"
              ? enContent
              : arContent
        const updated = await infoPagesCollection.update(page.id, {
          portal_name: page.portal_name || portalId,
          slug: pageSlug,
          title_en: enTitle,
          title_ar: arTitle,
          is_published: isPublished,
          [contentField]: contentValue,
        })
        setPage(updated)
        setEnTitle(updated.title_en)
        setArTitle(updated.title_ar || "")
        setEnContent(updated.content_en)
        setArContent(updated.content_ar || "")
        if (updated.slug !== pageSlug) {
          router.push(`/cms/info/${portalId}/${updated.slug}`)
        }
      } catch (err) {
        toast.error(
          t(
            { en: "Failed to save. Make sure the slug is unique.", ar: "فشل الحفظ. تأكد من أن المعرف (slug) فريد." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        setSaving(false)
      }
    },
    [
      page,
      pageSlug,
      enTitle,
      arTitle,
      enContent,
      arContent,
      isPublished,
      activeLang,
      portalId,
      router,
      lang,
      setEnTitle,
      setArTitle,
    ]
  )

  const handleContentChange = useCallback(
    (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
    },
    [activeLang]
  )

  const handleContentSave = useCallback(
    async (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
      await handleSave(html)
    },
    [handleSave, activeLang]
  )

  const copyFromEnglish = useCallback(() => {
    setArTitle(enTitle)
    setArContent(enContent)
    setResetKey(t => t + 1)
  }, [enTitle, enContent, setArTitle])

  const handleDiscard = useCallback(async () => {
    const data = await infoPagesCollection.getBySlug(slug)
    if (!data) return
    pageRecordRef.current = data as unknown as Record<string, unknown>
    setPage(data)
    setPageSlug(data.slug)
    setEnTitle(data.title_en)
    setArTitle(data.title_ar || "")
    setEnContent(data.content_en)
    setArContent(data.content_ar || "")
    setIsPublished(data.is_published)
    const iconFile = extractIcon(pageRecordRef.current)
    setIconUrl(iconFile ? pb.files.getURL(pageRecordRef.current, iconFile) : null)
    setResetKey(t => t + 1)
  }, [slug, setEnTitle, setArTitle])

  const togglePublish = useCallback(async () => {
    if (!page) return
    setPublishing(true)
    try {
      const updated = await infoPagesCollection.update(page.id, {
        is_published: !page.is_published,
      })
      setPage(updated)
      setIsPublished(updated.is_published)
    } finally {
      setPublishing(false)
    }
  }, [page])

  const handleImageUpload = useCallback(
    async (file: File): Promise<string> => {
      if (!page) throw new Error("No page loaded")
      const updated = await infoPagesCollection.updateWithFiles(page.id, {}, [file])
      const newMedia = updated.media as string[]
      const filename = newMedia[newMedia.length - 1]
      setPage((prev) => (prev ? { ...prev, media: newMedia } : null))
      return pb.files.getURL(updated, filename)
    },
    [page]
  )

  const handleIconUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file || !page) return
      setUploadingIcon(true)
      try {
        const resized = await resizeIconToSquare(file)
        const updated = await infoPagesCollection.updateIcon(page.id, resized)
        setPage(updated)
        pageRecordRef.current = updated as unknown as Record<string, unknown>
        const iconFile = extractIcon(pageRecordRef.current)
        setIconUrl(
          iconFile ? pb.files.getURL(pageRecordRef.current, iconFile) : null
        )
      } catch (err) {
        toast.error(
          t(
            { en: "Please upload a valid image.", ar: "يرجى رفع صورة صالحة." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        e.target.value = ""
        setUploadingIcon(false)
      }
    },
    [page, lang]
  )

  const handleRemoveIcon = useCallback(async () => {
    if (!page) return
    try {
      const updated = await infoPagesCollection.removeIcon(page.id)
      setPage(updated)
      pageRecordRef.current = updated as unknown as Record<string, unknown>
      setIconUrl(null)
    } catch (err) {
      toast.error(
        t(
          { en: "Failed to remove icon.", ar: "فشل إزالة الأيقونة." },
          lang
        ),
        { description: getErrorMessage(err) }
      )
    }
  }, [page, lang])

  const handleDelete = useCallback(async () => {
    if (!page) return
    if (
      !confirm(
        t(
          {
            en: `Delete "${page.title_en}"? This cannot be undone.`,
            ar: `حذف "${page.title_en}"؟ لا يمكن التراجع عن هذا.`,
          },
          lang
        )
      )
    )
      return
    setDeleting(true)
    try {
      await infoPagesCollection.delete(page.id)
      router.push(`/cms/info/${portalId}`)
    } catch (err) {
      toast.error(getErrorMessage(err))
      setDeleting(false)
    }
  }, [page, portalId, router, lang])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (!page) {
    return (
      <div className="space-y-4">
        <Link
          href={`/cms/info/${portalId}`}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
        <p>{t({ en: "Page not found.", ar: "الصفحة غير موجودة." }, lang)}</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link
          href={`/cms/info/${portalId}`}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
      </div>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold">
            {t({ en: "Edit Page", ar: "تعديل الصفحة" }, lang)}
          </h1>
          <p className="text-muted-foreground">
            {t({ en: "Manage info page details", ar: "إدارة تفاصيل صفحة المعلومات" }, lang)}
          </p>
        </div>

        <div className="flex items-center gap-3">
          {/* <Button variant="destructive" size="sm" onClick={handleDelete} disabled={deleting}>
            {deleting ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Trash2 className="mr-2 h-4 w-4" />
            )}
            Delete
          </Button> */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPreviewOpen(true)}
          >
            <Eye className="me-2 h-4 w-4" />
            {t(UI_STRINGS.preview, lang)}
          </Button>
          <div className="flex items-center gap-2">
            <Switch
              id="publish"
              checked={isPublished}
              onCheckedChange={togglePublish}
              disabled={publishing}
            />
            <Label htmlFor="publish" className="font-medium">
              {isPublished ? t(UI_STRINGS.published, lang) : t(UI_STRINGS.draft, lang)}
            </Label>
          </div>
        </div>
      </div>

      <Card className="space-y-4 p-4">
        <div className="space-y-2">
          <Label>{t({ en: "Portal", ar: "البوابة" }, lang)}</Label>
          <p className="text-sm text-muted-foreground">
            {portal ? t(portal.title, lang) : portalId}
          </p>
        </div>

        {/* <div className="space-y-2">
          <Label htmlFor="slug">Slug</Label>
          <Input
            id="slug"
            value={pageSlug}
            onChange={(e) => setPageSlug(e.target.value)}
            placeholder="page-slug"
            className="max-w-xs w-72"
          />
        </div> */}

        <div className="space-y-2">
          <Label>{t({ en: "Icon", ar: "الأيقونة" }, lang)}</Label>
          {iconUrl && (
            <div className="relative mb-2 w-24 overflow-hidden rounded-lg border">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={iconUrl}
                alt={t({ en: "Icon", ar: "الأيقونة" }, lang)}
                className="h-auto w-full object-contain"
              />
              <Button
                variant="destructive"
                size="sm"
                className="absolute right-1 top-1"
                onClick={handleRemoveIcon}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          )}
          <div className="flex items-center gap-2">
            <Input
              type="file"
              accept="image/*"
              onChange={handleIconUpload}
              disabled={uploadingIcon}
              className="w-72"
            />
            {uploadingIcon && <Loader2 className="h-4 w-4 animate-spin" />}
          </div>
        </div>
      </Card>

      <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as Lang)}>
        <TabsList>
          <TabsTrigger value="en">{ui("English")}</TabsTrigger>
          <TabsTrigger value="ar">العربية</TabsTrigger>
        </TabsList>
      </Tabs>

      {activeLang === "en" ? (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="en-title">
              {t({ en: "Title (English)", ar: "العنوان (إنجليزي)" }, lang)}
            </Label>
            <Input
              id="en-title"
              value={enTitle}
              onChange={(e) => setEnTitle(e.target.value)}
              placeholder={t({ en: "Page title", ar: "عنوان الصفحة" }, lang)}
            />
          </div>
          <RichTextEditor
            key={`${resetKey}-en`}
            title={t({ en: "English Content", ar: "المحتوى (إنجليزي)" }, lang)}
            initialContent={enContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
          />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <Label htmlFor="ar-title">
              {t({ en: "Title (Arabic)", ar: "العنوان (عربي)" }, lang)}
            </Label>
            <Button variant="outline" size="sm" onClick={copyFromEnglish}>
              <Copy className="mr-2 h-4 w-4" />
              {t({ en: "Copy from English", ar: "نسخ من الإنجليزية" }, lang)}
            </Button>
          </div>
          <Input
            id="ar-title"
            value={arTitle}
            onChange={(e) => setArTitle(e.target.value)}
            placeholder="عنوان الصفحة"
          />
          <RichTextEditor
            key={`${resetKey}-ar`}
            title={t({ en: "Arabic Content", ar: "المحتوى (عربي)" }, lang)}
            initialContent={arContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
            direction="rtl"
          />
        </div>
      )}

      <CmsPreviewDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        title={activeLang === "ar" && arTitle ? arTitle : enTitle}
        html={activeLang === "en" ? enContent : arContent}
        lang={activeLang}
        path={`/info/${pageSlug}`}
      >
        {iconUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={iconUrl}
            alt=""
            className="mb-6 h-16 w-16 rounded-xl object-contain"
          />
        )}
      </CmsPreviewDialog>
    </div>
  )
}

"use client"
import { usePermissions } from "@/hooks/usePermissions"
import { useState, useEffect } from "react"
import Link from "next/link"
import { Plus, Pencil, Trash2, RotateCcw } from "lucide-react"
import pb, { getErrorMessage } from "@/lib/pb"
import { usePortals } from "@/hooks/usePortals"
import { useLang } from "@/lib/lang-context"
import type { Portal } from "@/lib/portals"
import { PortalIcon, portalIcons } from "@/components/portal/PortalIcon"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { PageLoader } from "@/components/ui/page-loader"
import { DataError } from "@/components/ui/data-error"
type Draft = {
  key: string
  en: string
  ar: string
  descriptionEn: string
  descriptionAr: string
  icon: string
  registration: string
  accent: string
  order: number
}
const iconLabels: Record<string, [string, string]> = {
  heartHandshake: ["Support", "الدعم"],
  brain: ["Mind", "العقل"],
  graduationCap: ["Education", "التعليم"],
  building2: ["Organization", "المؤسسة"],
  heart: ["Wellbeing", "العافية"],
  users: ["Community", "المجتمع"],
  bookOpen: ["Learning", "التعلم"],
  lightbulb: ["Ideas", "الأفكار"],
  briefcase: ["Work", "العمل"],
  globe: ["Global", "العالم"],
}
const empty: Draft = {
  key: "",
  en: "",
  ar: "",
  descriptionEn: "",
  descriptionAr: "",
  icon: "globe",
  registration: "individual",
  accent: "#0b3d60",
  order: 0,
}
export default function CmsPortalsPage() {
  const access = usePermissions()
  const { lang } = useLang()
  const ar = lang === "ar"
  const text = (en: string, arabic: string) => (ar ? arabic : en)
  const { portals, isLoading, error, reload } = usePortals(true)
  const [editing, setEditing] = useState<Portal | null | undefined>(undefined),
    [draft, setDraft] = useState<Draft>(empty),
    [picture, setPicture] = useState<File | null>(null),
    [preview, setPreview] = useState(""),
    [removePicture, setRemovePicture] = useState(false),
    [saving, setSaving] = useState(false),
    [notice, setNotice] = useState(""),
    [failure, setFailure] = useState(""),
    [pictureError, setPictureError] = useState(""),
    [showRemoved, setShowRemoved] = useState(false)
  useEffect(() => {
    const url = picture ? URL.createObjectURL(picture) : ""
    const timer = window.setTimeout(() => setPreview(url), 0)
    return () => {
      window.clearTimeout(timer)
      if (url) URL.revokeObjectURL(url)
    }
  }, [picture])
  const start = (p: Portal | null) => {
    if (!access.can(p ? "cms.update" : "cms.create")) return
    setEditing(p)
    setDraft(
      p
        ? {
            key: p.id,
            en: p.title.en,
            ar: p.title.ar,
            descriptionEn: p.tagline.en,
            descriptionAr: p.tagline.ar,
            icon: p.icon || "globe",
            registration: p.registrationType || "individual",
            accent: p.accent,
            order: p.order || 0,
          }
        : { ...empty, order: portals.length }
    )
    setPicture(null)
    setPictureError("")
    setRemovePicture(false)
    setFailure("")
    setNotice("")
  }
  const update = (field: keyof Draft, value: string | number) =>
    setDraft({ ...draft, [field]: value })
  const changed = async () => {
    await reload()
    window.dispatchEvent(new Event("portals-updated"))
  }
  const save = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!access.can(editing ? "cms.update" : "cms.create")) return
    setFailure("")
    setNotice("")
    if (!/^[a-z0-9-]{1,80}$/.test(draft.key)) {
      setFailure(
        text(
          "Use lowercase letters, numbers and hyphens for the portal address.",
          "استخدم الحروف الإنجليزية الصغيرة والأرقام والشرطات لعنوان البوابة."
        )
      )
      return
    }
    if (
      [draft.en, draft.ar].some((s) => s.trim().length < 2) ||
      [draft.descriptionEn, draft.descriptionAr].some((s) => !s.trim())
    ) {
      setFailure(
        text(
          "Enter both titles and descriptions.",
          "أدخل العنوان والوصف باللغتين."
        )
      )
      return
    }
    setSaving(true)
    try {
      const data = new FormData()
      Object.entries({
        portal_key: draft.key,
        title_en: draft.en.trim(),
        title_ar: draft.ar.trim(),
        description_en: draft.descriptionEn.trim(),
        description_ar: draft.descriptionAr.trim(),
        icon: draft.icon,
        registration_type: draft.registration,
        accent: draft.accent,
        order: draft.order,
      }).forEach(([key, value]) => data.append(key, String(value)))
      if (picture) data.append("picture", picture)
      else if (removePicture) data.append("picture", "")
      if (editing?.recordId)
        await pb.collection("portals").update(editing.recordId, data)
      else await pb.collection("portals").create(data)
      await changed()
      setEditing(undefined)
      setNotice(text("Portal saved.", "تم حفظ البوابة."))
    } catch (e) {
      setFailure(getErrorMessage(e))
    } finally {
      setSaving(false)
    }
  }
  const archive = async (p: Portal) => {
    setSaving(true)
    setFailure("")
    try {
      await pb
        .collection("portals")
        .update(p.recordId!, { is_deleted: !p.isDeleted })
      await changed()
      setNotice(
        p.isDeleted
          ? text("Portal restored.", "تمت استعادة البوابة.")
          : text(
              "Portal removed. You can restore it below.",
              "تم حذف البوابة. يمكنك استعادتها أدناه."
            )
      )
    } catch (e) {
      setFailure(getErrorMessage(e))
    } finally {
      setSaving(false)
    }
  }
  const image = preview || (!removePicture && editing?.picture) || ""
  return (
    <div className="mx-auto max-w-6xl space-y-6" dir={ar ? "rtl" : "ltr"}>
      <header className="flex flex-wrap items-start justify-between gap-4 border-b pb-5">
        <div>
          <p className="mb-2 text-xs font-semibold tracking-widest text-[#9b7621]">
            CMS
          </p>
          <h1 className="text-3xl font-bold text-[#0b3d60]">
            {text("Portals", "البوابات")}
          </h1>
          <p className="mt-2 max-w-xl text-sm text-slate-600">
            {text(
              "Manage the support areas displayed on your website. Edit their names, descriptions and visual identity.",
              "إدارة مجالات الدعم المعروضة على موقعك. عدّل الأسماء والأوصاف والصورة أو الأيقونة."
            )}
          </p>
        </div>
        <Button
          onClick={() => start(null)}
          disabled={saving || !access.can("cms.create")}
        >
          <Plus size={16} />
          {text("Add portal", "إضافة بوابة")}
        </Button>
      </header>
      {notice && (
        <p
          role="status"
          className="rounded-md bg-emerald-50 p-3 text-sm text-emerald-800"
        >
          {notice}
        </p>
      )}
      {failure && (
        <p
          role="alert"
          className="rounded-md bg-red-50 p-3 text-sm text-red-800"
        >
          {failure}
        </p>
      )}
      {editing === undefined && isLoading ? (
        <PageLoader />
      ) : editing === undefined && error ? (
        <DataError
          message={text("Unable to load portals.", "تعذر تحميل البوابات.")}
          onRetry={() => void reload()}
        />
      ) : editing !== undefined ? (
        <form
          onSubmit={save}
          className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_280px]"
        >
          <div className="min-w-0 space-y-6 rounded-xl border bg-white p-4 sm:p-6">
            <h2 className="text-xl font-semibold">
              {editing
                ? text("Edit portal", "تعديل البوابة")
                : text("New portal", "بوابة جديدة")}
            </h2>
            <div className="space-y-2">
              <Label htmlFor="portal-key">
                {text("Portal address", "عنوان البوابة")}
              </Label>
              <Input
                id="portal-key"
                dir="ltr"
                value={draft.key}
                readOnly={!!editing}
                maxLength={80}
                onChange={(e) => update("key", e.target.value)}
                placeholder="family-support"
                required
              />
              <p className="text-xs text-slate-500" dir="ltr">
                /portal/{draft.key || "family-support"}
              </p>
            </div>
            <div className="grid gap-5 sm:grid-cols-2">
              {(["en", "ar"] as const).map((language) => (
                <fieldset
                  key={language}
                  className="min-w-0 space-y-4"
                  dir={language === "ar" ? "rtl" : "ltr"}
                >
                  <legend className="mb-3 text-sm font-semibold text-[#0b3d60]">
                    {language === "en" ? "English" : "العربية"}
                  </legend>
                  <div className="space-y-2">
                    <Label htmlFor={`title-${language}`}>
                      {language === "en" ? "Title" : "العنوان"}
                    </Label>
                    <Input
                      id={`title-${language}`}
                      value={draft[language]}
                      onChange={(e) => update(language, e.target.value)}
                      required
                      minLength={2}
                      maxLength={120}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor={`description-${language}`}>
                      {language === "en" ? "Description" : "الوصف"}
                    </Label>
                    <Textarea
                      id={`description-${language}`}
                      value={
                        language === "en"
                          ? draft.descriptionEn
                          : draft.descriptionAr
                      }
                      onChange={(e) =>
                        update(
                          language === "en" ? "descriptionEn" : "descriptionAr",
                          e.target.value
                        )
                      }
                      required
                      maxLength={600}
                      rows={5}
                    />
                    <p className="text-xs text-slate-500">
                      {
                        (language === "en"
                          ? draft.descriptionEn
                          : draft.descriptionAr
                        ).length
                      }
                      /600
                    </p>
                  </div>
                </fieldset>
              ))}
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="portal-icon">{text("Icon", "الأيقونة")}</Label>
                <select
                  id="portal-icon"
                  className="h-11 w-full rounded-md border px-3"
                  value={draft.icon}
                  onChange={(e) => update("icon", e.target.value)}
                >
                  {Object.keys(portalIcons).map((name) => (
                    <option key={name} value={name}>
                      {text(...iconLabels[name])}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="portal-color">
                  {text("Accent color", "لون البوابة")}
                </Label>
                <Input
                  id="portal-color"
                  type="color"
                  value={draft.accent}
                  onChange={(e) => update("accent", e.target.value)}
                  className="h-11"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="portal-picture">
                {text("Picture (optional)", "الصورة (اختياري)")}
              </Label>
              <Input
                id="portal-picture"
                type="file"
                aria-invalid={!!pictureError}
                aria-describedby="portal-picture-help portal-picture-error"
                accept="image/png,image/jpeg,image/webp,image/gif"
                onChange={(e) => {
                  const file = e.target.files?.[0] || null
                  if (
                    file &&
                    (file.size > 5 * 1024 * 1024 ||
                      ![
                        "image/jpeg",
                        "image/png",
                        "image/webp",
                        "image/gif",
                      ].includes(file.type))
                  ) {
                    setPictureError(
                      text(
                        "Choose a JPG, PNG, WebP or GIF up to 5 MB.",
                        "اختر صورة JPG أو PNG أو WebP أو GIF بحجم لا يتجاوز 5 ميجابايت."
                      )
                    )
                    e.target.value = ""
                    return
                  }
                  setPictureError("")
                  setPicture(file)
                  setRemovePicture(false)
                }}
              />
              {pictureError && (
                <p
                  id="portal-picture-error"
                  role="alert"
                  className="text-sm text-red-700"
                >
                  {pictureError}
                </p>
              )}
              {picture && (
                <p role="status" className="text-sm text-emerald-700">
                  {picture.name} —{" "}
                  {text(
                    "Selected. Click Save portal to upload.",
                    "تم اختيار الصورة. اضغط حفظ البوابة لرفعها."
                  )}
                </p>
              )}
              <p id="portal-picture-help" className="text-xs text-slate-500">
                {text(
                  "Maximum 5 MB. A picture replaces the icon and appears on the portal page.",
                  "الحد الأقصى 5 ميجابايت. تحل الصورة محل الأيقونة وتظهر في صفحة البوابة."
                )}
              </p>
              {(editing?.picture || picture) && (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setPicture(null)
                    setRemovePicture(true)
                  }}
                >
                  {text("Remove picture", "حذف الصورة")}
                </Button>
              )}
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="portal-registration">
                  {text("Registration account type", "نوع حساب التسجيل")}
                </Label>
                <select
                  id="portal-registration"
                  className="h-11 w-full rounded-md border px-3"
                  value={draft.registration}
                  onChange={(e) => update("registration", e.target.value)}
                >
                  {[
                    ["all", "All", "الكل"],
                    ["parent", "Parent", "ولي أمر"],
                    ["care_foundation", "Care Foundation", "مؤسسة الرعاية"],
                    ["individual", "Individual", "فرد"],
                    ["organization", "Organization", "مؤسسة"],
                    ["expert", "Expert", "خبير"],
                  ].map(([key, en, arabic]) => (
                    <option key={key} value={key}>
                      {text(en, arabic)}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="portal-order">
                  {text("Display order", "ترتيب العرض")}
                </Label>
                <Input
                  id="portal-order"
                  fieldWidth="short" type="number"
                  min={0}
                  step={1}
                  value={draft.order}
                  onChange={(e) => update("order", Number(e.target.value))}
                  required
                />
              </div>
            </div>
            <div className="flex flex-wrap gap-3 border-t pt-5">
              <Button disabled={saving}>
                {saving
                  ? text("Saving…", "جارٍ الحفظ…")
                  : text("Save portal", "حفظ البوابة")}
              </Button>
              <Button
                type="button"
                variant="outline"
                disabled={saving}
                onClick={() => setEditing(undefined)}
              >
                {text("Cancel", "إلغاء")}
              </Button>
            </div>
          </div>
          <aside className="space-y-3">
            <h3 className="text-sm font-semibold text-slate-600">
              {text("Card preview", "معاينة البطاقة")}
            </h3>
            <div
              className={`min-w-0 overflow-hidden rounded-xl border bg-white p-6 ${image ? "min-h-[432px]" : ""}`}
              style={{ borderTop: `4px solid ${draft.accent}` }}
            >
              <div
                className={
                  image
                    ? "-mx-6 -mt-6 mb-5 h-54 overflow-hidden bg-slate-50"
                    : "mb-6 flex h-16 w-16 items-center justify-center overflow-hidden rounded-lg bg-slate-50"
                }
                style={{ color: draft.accent }}
              >
                {image ? (
                  <img
                    src={image}
                    alt=""
                    className="h-full w-full object-cover"
                  />
                ) : (
                  <PortalIcon name={draft.icon} size={32} />
                )}
              </div>
              <h3 className="text-lg font-bold break-words text-[#0b3d60]">
                {(ar ? draft.ar : draft.en) ||
                  text("Portal title", "عنوان البوابة")}
              </h3>
              <p className="mt-3 text-sm leading-relaxed break-words text-slate-600">
                {(ar ? draft.descriptionAr : draft.descriptionEn) ||
                  text(
                    "Your description appears here.",
                    "يظهر وصف البوابة هنا."
                  )}
              </p>
              <div
                className="mt-8 flex flex-wrap items-center justify-between gap-3 text-xs font-semibold"
                style={{ color: draft.accent }}
              >
                <span>{text("Explore support →", "استكشف المجال ←")}</span>
              </div>
            </div>
          </aside>
        </form>
      ) : (
        <>
          <div className="space-y-3">
            {portals
              .filter((p) => !p.isDeleted)
              .map((p) => (
                <article
                  key={p.id}
                  className="flex flex-wrap items-center gap-4 rounded-xl border bg-white p-4 sm:p-5"
                >
                  <div
                    className="flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-slate-50"
                    style={{ color: p.accent }}
                  >
                    {p.picture ? (
                      <img
                        src={p.picture}
                        alt=""
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <PortalIcon name={p.icon} />
                    )}
                  </div>
                  <div className="min-w-0 flex-1 basis-40">
                    <h2 className="text-lg font-semibold break-words text-[#0b3d60]">
                      {p.title[lang]}
                    </h2>
                    <p className="mt-1 text-sm break-words text-slate-600">
                      {p.tagline[lang]}
                    </p>
                    <p className="mt-2 text-xs text-slate-500" dir="ltr">
                      /portal/{p.id}
                    </p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      variant="outline"
                      onClick={() => start(p)}
                      disabled={saving || !access.can("cms.update")}
                    >
                      <Pencil size={15} />
                      {text("Edit", "تعديل")}
                    </Button>
                    <Button variant="outline" asChild>
                      <Link href={`/portal/${p.id}`} target="_blank">
                        {text("View", "عرض")}
                      </Link>
                    </Button>
                    <Button
                      variant="ghost"
                      onClick={() => {
                        if (access.can("cms.delete")) void archive(p)
                      }}
                      disabled={saving || !access.can("cms.delete")}
                    >
                      <Trash2 size={15} />
                      {text("Remove", "حذف")}
                    </Button>
                  </div>
                </article>
              ))}
          </div>
          {!portals.some((p) => !p.isDeleted) && (
            <div className="rounded-xl border border-dashed p-8 text-center">
              <h2 className="font-semibold">
                {text("No active portals", "لا توجد بوابات نشطة")}
              </h2>
              <p className="mt-2 text-sm text-slate-600">
                {text(
                  "Add your first portal or restore a removed one.",
                  "أضف بوابة جديدة أو استعد إحدى البوابات المحذوفة."
                )}
              </p>
            </div>
          )}
          {portals.some((p) => p.isDeleted) && (
            <section className="border-t pt-5">
              <Button
                variant="outline"
                onClick={() => setShowRemoved(!showRemoved)}
              >
                {text("Removed portals", "البوابات المحذوفة")} (
                {portals.filter((p) => p.isDeleted).length})
              </Button>
              {showRemoved && (
                <div className="mt-4 space-y-3">
                  {portals
                    .filter((p) => p.isDeleted)
                    .map((p) => (
                      <article
                        key={p.id}
                        className="flex flex-wrap items-center justify-between gap-3 rounded-lg border bg-slate-50 p-4"
                      >
                        <h3 className="min-w-0 font-medium break-words">
                          {p.title[lang]}
                        </h3>
                        <Button
                          variant="outline"
                          onClick={() => {
                            if (access.can("cms.delete")) void archive(p)
                          }}
                          disabled={saving || !access.can("cms.delete")}
                        >
                          <RotateCcw size={15} />
                          {text("Restore", "استعادة")}
                        </Button>
                      </article>
                    ))}
                </div>
              )}
            </section>
          )}
        </>
      )}
    </div>
  )
}

"use client"
import pb from "@/lib/pb"
import { ProtectedFileLink } from "@/components/ProtectedFileLink"
import { usePermissions } from "@/hooks/usePermissions"

import { use, useEffect } from "react"
import { usePathname, useRouter } from "next/navigation"
import { DataError } from "@/components/ui/data-error"
import { ExpertTaskAssignment } from "@/components/dashboard/ExpertTaskAssignment"
import { PageLoader } from "@/components/ui/page-loader"
import { useAuth } from "@/hooks/useAuth"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { SurveyPreview } from "@/components/tool-renderers/SurveyPreview"
import { MultipleChoicePreview } from "@/components/tool-renderers/MultipleChoicePreview"
import { MediaPreview } from "@/components/tool-renderers/MediaPreview"
import { PlanPreview } from "@/components/tool-renderers/PlanPreview"
import { ReportPreview } from "@/components/tool-renderers/ReportPreview"
import { ArrowLeft, FileText, Download, Edit } from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  MultipleChoiceConfig,
  MediaConfig,
  PlanConfig,
  ReportConfig,
} from "@/types/tool"
import type { AssignmentStatus } from "@/types/assignment"
import { getToolTypeLabel, getToolTypeMeta } from "@/lib/tool-types"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التكليف" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

interface AssignmentDetailPageProps {
  params: Promise<{ id: string }>
}

export default function AssignmentDetailPage({
  params,
}: AssignmentDetailPageProps) {
  const { id: assignmentId } = use(params)
  const router = useRouter()
  const pathname = usePathname()
  const casePath = pathname.match(/^\/dashboard\/admin\/cases\/([^/]+)\/tasks\//)
  const backHref = casePath ? `/dashboard/admin/cases/${casePath[1]}#case-assignments` : "/dashboard/admin/cases"
  const { lang } = useLang()
  const {
    assignments,
    updateAssignment,
    loadError: assignmentsError,
    refresh: refreshAssignments,
    isLoading: assignmentsLoading,
  } = useAssignments()
  const { currentUser } = useAuth()
  const access = usePermissions()
  const isExpert = currentUser?.role === "expert"
  const { profiles, isLoading: profilesLoading } = useProfiles(
    isExpert || access.can("cases.read")
  )
  const {
    toolTypes,
    isLoading: toolTypesLoading,
    fetchToolTypes,
    getToolTypeById,
  } = useToolTypes(isExpert || access.can("tools.read"))

  const assignment = assignments.find((a) => a.id === assignmentId)
  const profile = assignment
    ? profiles.find((p) => p.id === assignment.case)
    : undefined

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  const toolType = assignment?.type
    ? getToolTypeById(assignment.type)
    : undefined
  const typeName = toolType?.key || "Unknown"

  const config = assignment?.config

  const isLoading = assignmentsLoading || toolTypesLoading || profilesLoading

  if (isLoading) {
    return <PageLoader />
  }

  if (assignmentsError)
    return <DataError message={assignmentsError} onRetry={refreshAssignments} />

  if (!assignment) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "لم يتم العثور على التكليف" : "Assignment not found"}
        </h2>
        <Button onClick={() => router.push(backHref)}>
          {lang === "ar" ? "العودة إلى التكليفات" : "Back to Assignments"}
        </Button>
      </div>
    )
  }

  if (!profile && (isExpert || access.can("cases.read"))) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "لم يتم العثور على الحالة" : "Case not found"}
        </h2>
        <p className="mb-4 text-muted-foreground">
          {lang === "ar"
            ? "تم حذف الحالة المرتبطة بهذا التكليف."
            : "The linked case for this assignment was deleted."}
        </p>
        <Button onClick={() => router.push(backHref)}>
          {lang === "ar" ? "العودة إلى التكليفات" : "Back to Assignments"}
        </Button>
      </div>
    )
  }

  const Icon = getToolTypeMeta(typeName)?.icon || FileText
  const canEdit =
    (isExpert || access.can("assignments.update")) &&
    (typeName === "plan" || typeName === "report")

  const renderToolPreview = () => {
    if (!config) return null

    switch (typeName) {
      case "survey":
        return <SurveyPreview config={config as SurveyConfig} />
      case "multiple_answer":
        return <MultipleChoicePreview config={config as MultipleChoiceConfig} />
      case "media_question":
        return <MediaPreview config={config as MediaConfig} />
      case "attachment_request":
        return (
          <div className="rounded-lg border bg-muted/30 p-6">
            <h3 className="text-lg font-semibold">
              {(config as { title?: { en: string; ar: string } }).title?.[
                lang
              ] || (lang === "ar" ? "طلب إرفاق ملف" : "Request for Attachment")}
            </h3>
            <p className="mt-2 text-muted-foreground">
              {lang === "ar"
                ? "سيظهر طلب رفع الملف هنا"
                : "File upload request will appear here"}
            </p>
          </div>
        )
      case "plan":
        return <PlanPreview config={config as PlanConfig} />
      case "report":
        return <ReportPreview config={config as ReportConfig} />
      default:
        return (
          <div className="rounded-lg border bg-muted/30 p-6">
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "المعاينة غير متاحة لهذا النوع من الأدوات"
                : "Preview not available for this tool type"}
            </p>
          </div>
        )
    }
  }

  const renderSurveyResponse = (surveyConfig: SurveyConfig) => {
    const responses = assignment.responses || {}
    const questions = surveyConfig.questions || []

    if (questions.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد أسئلة في هذا الاستبيان."
            : "No questions in this survey."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {questions.map((question, idx) => {
          const answer = responses[question.id]
          return (
            <div key={question.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{question.text}</p>
                  <div className="mt-2 rounded bg-muted/30 p-3">
                    {answer !== undefined &&
                    answer !== null &&
                    answer !== "" ? (
                      <p className="text-sm">{String(answer)}</p>
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {lang === "ar" ? "لا إجابة" : "No answer"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderMultipleChoiceResponse = (mcConfig: MultipleChoiceConfig) => {
    const responses = assignment.responses || {}
    const questions = mcConfig.questions || []

    if (questions.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد أسئلة في هذا الاستبيان."
            : "No questions in this survey."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {questions.map((question, idx) => {
          const answer = responses[question.id]
          return (
            <div key={question.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{question.text}</p>
                  <div className="mt-2 space-y-1">
                    {answer !== undefined && answer !== null ? (
                      Array.isArray(answer) ? (
                        answer.map((val, i) => (
                          <p key={i} className="text-sm">
                            {question.options?.find((o) => o.value === val)
                              ?.label || val}
                          </p>
                        ))
                      ) : (
                        <p className="text-sm">
                          {question.options?.find((o) => o.value === answer)
                            ?.label || String(answer)}
                        </p>
                      )
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {lang === "ar" ? "لا إجابة" : "No answer"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderMediaResponse = (mediaConfig: MediaConfig) => {
    const responses = assignment.responses || {}
    const items = mediaConfig.items || []

    if (items.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد عناصر وسائط في هذا التكليف."
            : "No media items in this assignment."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {items.map((item, idx) => {
          const answer = responses[item.id]
          return (
            <div key={item.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{item.question}</p>
                  <div className="mt-2 rounded bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      answer ? (
                        <p className="text-sm">{String(answer)}</p>
                      ) : (
                        <p className="text-sm text-muted-foreground">
                          {lang === "ar" ? "لا إجابة" : "No answer"}
                        </p>
                      )
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {answer
                          ? `${lang === "ar" ? "ملف" : "File"}: ${answer}`
                          : lang === "ar"
                            ? "لم يتم رفع ملف"
                            : "No file uploaded"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderAttachmentResponse = () => {
    const responses = assignment.responses || {}
    const responseKeys = Object.keys(responses)

    if (
      responseKeys.length === 0 &&
      (!assignment.media || assignment.media.length === 0)
    ) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لم يتم رفع أي ملفات بعد."
            : "No files uploaded yet."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {responseKeys.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "استجابات الملفات" : "File Responses"}
            </h4>
            <ul className="space-y-2">
              {responseKeys.map((key) => (
                <li key={key} className="flex items-center gap-2">
                  <span className="text-sm">{key}:</span>
                  <span className="text-sm text-muted-foreground">
                    {String(responses[key])}
                  </span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {assignment.media && assignment.media.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "الملفات المرفوعة" : "Uploaded Files"}
            </h4>
            <ul className="space-y-2">
              {assignment.media.map((file, idx) => (
                <li key={idx}>
                  <ProtectedFileLink
                    href={mediaFileUrl(file)}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-primary hover:underline"
                  >
                    <Download className="h-4 w-4" />
                    {lang === "ar" ? "ملف" : "File"} {idx + 1}
                  </ProtectedFileLink>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    )
  }

  const mediaFileUrl = (file: string) => {
    if (/^https?:\/\//i.test(file)) {
      try {
        const url = new URL(file)
        return url.origin === new URL(pb.baseURL).origin &&
          url.pathname.includes("/api/files/")
          ? url.toString()
          : ""
      } catch {
        return ""
      }
    }
    return pb.files.getURL(
      { collectionId: "case_tools", id: assignmentId },
      file
    )
  }
  const renderGenericResponse = () => {
    return (
      <div className="space-y-4">
        {assignment.media && assignment.media.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "الملفات المرفوعة" : "Uploaded Files"}
            </h4>
            <ul className="space-y-2">
              {assignment.media.map((file, idx) => (
                <li key={idx}>
                  <ProtectedFileLink
                    href={mediaFileUrl(file)}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-primary hover:underline"
                  >
                    <Download className="h-4 w-4" />
                    {lang === "ar" ? "ملف" : "File"} {idx + 1}
                  </ProtectedFileLink>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    )
  }

  const renderResponseView = () => {
    if (assignment.status !== "completed") {
      return (
        <div className="flex flex-col items-center justify-center py-12">
          <FileText className="mb-4 h-12 w-12 text-muted-foreground" />
          <h3 className="mb-2 text-lg font-medium">
            {lang === "ar" ? "لم تكتمل بعد" : "Not Yet Completed"}
          </h3>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "هذا التكليف لا تزال قيد الانتظار. ستظهر الردود هنا بمجرد اكتمال الحالة لها."
              : "This assignment is still pending. Responses will appear here once the case completes it."}
          </p>
        </div>
      )
    }

    if (
      !assignment.responses ||
      Object.keys(assignment.responses).length === 0
    ) {
      if (!assignment.media || assignment.media.length === 0) {
        return (
          <div className="flex flex-col items-center justify-center py-12">
            <FileText className="mb-4 h-12 w-12 text-muted-foreground" />
            <h3 className="mb-2 text-lg font-medium">
              {lang === "ar" ? "لا توجد ردود" : "No Responses"}
            </h3>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "لا توجد بيانات استجابة متاحة لهذا التكليف."
                : "No response data available for this assignment."}
            </p>
          </div>
        )
      }
    }

    switch (typeName) {
      case "survey":
        return (
          <SurveyPreview
            config={config as SurveyConfig}
            responses={assignment.responses}
            readOnly
          />
        )
      case "multiple_answer":
        return (
          <MultipleChoicePreview
            config={config as MultipleChoiceConfig}
            responses={assignment.responses}
            readOnly
          />
        )
      case "media_question":
        return (
          <MediaPreview
            config={config as MediaConfig}
            responses={assignment.responses as Record<string, string>}
            readOnly
          />
        )
      case "attachment_request":
        return renderAttachmentResponse()
      default:
        return renderGenericResponse()
    }
  }

  return (
    <div className="space-y-6">
      {access.can("assignments.update") &&
        access.can("allocations.read") &&
        access.can("experts.read") && (
          <ExpertTaskAssignment
            key={assignment.id}
            task={assignment}
            onSaved={updateAssignment}
          />
        )}
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.push(backHref)}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "تفاصيل التكليف" : "Assignment Details"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "عرض التكليف والردود"
                : "View assignment and responses"}
            </p>
          </div>
        </div>
        {canEdit && (
          <Link
            href={`/dashboard/admin/tools/${typeName}/edit/${assignmentId}`}
          >
            <Button variant="outline">
              <Edit className="mr-2 h-4 w-4" />
              {lang === "ar" ? "تعديل" : "Edit"}
            </Button>
          </Link>
        )}
      </div>

      {/* Assignment Info Card */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Icon className="h-5 w-5 text-primary" />
            <CardTitle className="text-lg">
              {lang === "ar" ? "معلومات التكليف" : "Assignment Information"}
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "الحالة" : "Case"}
              </span>
              <p>
                <Link
                  href={profile ? `/dashboard/cases/${profile.id}` : "#"}
                  className="hover:text-primary hover:underline"
                >
                  {profile?.name || assignment.case}
                </Link>
              </p>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "التكليف" : "Assignment"}
              </span>
              <p>
                {assignment.name_en ||
                  (lang === "ar" ? "تكليف بدون اسم" : "Unnamed Assignment")}
              </p>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "النوع" : "Type"}
              </span>
              <div>
                <Badge variant="outline">
                  {getToolTypeLabel(toolType, lang)}
                </Badge>
              </div>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "الحالة" : "Status"}
              </span>
              <div>
                <Badge className={statusColors[assignment.status]}>
                  {statusLabels[assignment.status]?.[lang] ||
                    (lang === "ar" ? "حالة غير معروفة" : "Unknown status")}
                </Badge>
              </div>
            </div>
          </div>
          <div className="mt-4 border-t pt-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <span className="text-sm font-medium text-muted-foreground">
                  {lang === "ar" ? "تاريخ التكليف" : "Assigned Date"}
                </span>
                <p>
                  {formatDate(assignment.assigned_at || assignment.created)}
                </p>
              </div>
              <div>
                <span className="text-sm font-medium text-muted-foreground">
                  {lang === "ar" ? "مرئي للمستخدم" : "Visible to User"}
                </span>
                <p>
                  {assignment.is_visible_to_user
                    ? lang === "ar"
                      ? "نعم"
                      : "Yes"
                    : lang === "ar"
                      ? "لا"
                      : "No"}
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tabs */}
      <Tabs defaultValue="view" className="space-y-4">
        <TabsList>
          <TabsTrigger value="view">
            {lang === "ar" ? "عرض" : "View"}
          </TabsTrigger>
          <TabsTrigger value="response">
            {lang === "ar" ? "الرد" : "Response"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="view">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معاينة الأداة" : "Tool Preview"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "كيف تظهر الأداة للحالة (باستخدام لقطة الإعدادات)"
                  : "How the tool appears to the case (using config snapshot)"}
              </CardDescription>
            </CardHeader>
            <CardContent>{renderToolPreview()}</CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="response">
          <Card>
            <CardHeader>
              <CardTitle>{lang === "ar" ? "الرد" : "Response"}</CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "الردود المقدمة والملفات المرفوعة"
                  : "Submitted responses and uploaded files"}
              </CardDescription>
            </CardHeader>
            <CardContent>{renderResponseView()}</CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}

"use client"
import { CaseName } from "@/components/cases/CaseName"
import { usePermissions } from "@/hooks/usePermissions"

import { useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useLang } from "@/lib/lang-context"
import { useAuth } from "@/hooks/useAuth"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"

import { SkeletonTable } from "@/components/ui/skeleton"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  ArrowLeft,
  Trash2,
  FileText,
  ClipboardList,
  Search,
  Eye,
} from "lucide-react"
import { Switch } from "@/components/ui/switch"
import { SmartLink } from "@/components/smart-link"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import type { AssignmentStatus } from "@/types/assignment"
import { getToolTypeLabel, getToolTypeMeta } from "@/lib/tool-types"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التكليف" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function AssignmentsPage() {
  const access = usePermissions()
  const router = useRouter()
  const { lang } = useLang()
  const { currentUser } = useAuth()
  const isExpert = currentUser?.role === "expert"
  const canReadCases = isExpert || access.can("cases.read")
  const canReadTools = isExpert || access.can("tools.read")
  const {
    assignments,
    deleteAssignment,
    updateAssignment,
    isLoading: isAssignmentsLoading,
  } = useAssignments()
  const { profiles, isLoading: isProfilesLoading } = useProfiles(canReadCases)
  const {
    toolTypes,
    isLoading: isToolTypesLoading,
    fetchToolTypes,
    getToolTypeById,
  } = useToolTypes(canReadTools)
  const hasFetched = useRef(false)
  const [searchQuery, setSearchQuery] = useState("")
  const [filterCase, setFilterCase] = useState("")
  const [filterType, setFilterType] = useState<string>("all")
  const [filterStatus, setFilterStatus] = useState<AssignmentStatus | "all">(
    "all"
  )

  useEffect(() => {
    if (!canReadTools) {
      hasFetched.current = false
      return
    }
    if (hasFetched.current) return
    hasFetched.current = true
    void fetchToolTypes()
  }, [fetchToolTypes, canReadTools])

  const getCaseName = (caseId: string) => {
    const profile = profiles.find((p) => p.id === caseId)
    return profile?.name || caseId
  }

  const getToolTypeName = (typeId: string) => {
    const toolType = getToolTypeById(typeId)
    return toolType?.key || "Unknown"
  }

  const expertCaseIds = isExpert ? profiles.map((p) => p.id) : []

  const filteredAssignments = assignments.filter((assignment) => {
    // Filter by expert's assigned cases
    if (isExpert && !expertCaseIds.includes(assignment.case)) return false

    // Filter by search query
    if (searchQuery) {
      const caseName = getCaseName(assignment.case).toLowerCase()
      const assignmentName = (assignment.name_en || "").toLowerCase()
      if (
        !caseName.includes(searchQuery.toLowerCase()) &&
        !assignmentName.includes(searchQuery.toLowerCase())
      ) {
        return false
      }
    }

    // Filter by case
    if (filterCase && assignment.case !== filterCase) {
      return false
    }

    // Filter by type
    if (filterType !== "all" && assignment.type !== filterType) {
      return false
    }

    // Filter by status
    if (filterStatus !== "all" && assignment.status !== filterStatus) {
      return false
    }

    return true
  })

  // Get unique tool types for filter dropdown
  const uniqueToolTypes = Array.from(
    new Set(assignments.map((a) => a.type))
  ).filter(Boolean)

  const isLoading =
    isAssignmentsLoading || isProfilesLoading || isToolTypesLoading

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="icon" onClick={() => router.back()}>
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold text-primary">
                {lang === "ar" ? "التكليفات" : "Assignments"}
              </h1>
              <p className="text-muted-foreground">
                {lang === "ar"
                  ? "إدارة تكليفات الأدوات للحالات"
                  : "Manage tool assignments to cases"}
              </p>
            </div>
          </div>
        </div>
        <SkeletonTable rows={6} />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {(!canReadCases || !canReadTools) && (
        <p
          role="status"
          className="rounded-lg border bg-white p-4 text-sm text-muted-foreground"
        >
          {lang === "ar"
            ? "تظهر معرفات الحالات عند عدم توفر صلاحية قراءتها. بعض تفاصيل الأنواع تتطلب صلاحية قراءة الأدوات."
            : "Case IDs are shown when case access is unavailable. Some type details require Tools read access."}
        </p>
      )}
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "التكليفات" : "Assignments"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "إدارة تكليفات الأدوات للحالات"
                : "Manage tool assignments to cases"}
            </p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col gap-4 sm:flex-row">
            <div className="relative flex-1">
              <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder={
                  lang === "ar"
                    ? "ابحث باسم التكليف..."
                    : "Search by assignment name..."
                }
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <CaseSearchCombobox
              enabled={canReadCases}
              value={filterCase}
              onChange={setFilterCase}
              placeholder={
                lang === "ar" ? "تصفية حسب الحالة..." : "Filter by case..."
              }
              className="w-[250px]"
            />
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-[200px]">
                <SelectValue
                  placeholder={
                    lang === "ar" ? "تصفية حسب النوع" : "Filter by Type"
                  }
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">
                  {lang === "ar" ? "جميع الأنواع" : "All Types"}
                </SelectItem>
                {uniqueToolTypes.map((typeId) => {
                  const toolType = getToolTypeById(typeId)
                  return (
                    <SelectItem key={typeId} value={typeId}>
                      {getToolTypeLabel(toolType, lang)}
                    </SelectItem>
                  )
                })}
              </SelectContent>
            </Select>
            <Select
              value={filterStatus}
              onValueChange={(v) =>
                setFilterStatus(v as AssignmentStatus | "all")
              }
            >
              <SelectTrigger className="w-[180px]">
                <SelectValue
                  placeholder={
                    lang === "ar" ? "تصفية حسب الحالة" : "Filter by Status"
                  }
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">
                  {lang === "ar" ? "جميع الحالات" : "All Status"}
                </SelectItem>
                <SelectItem value="pending">
                  {lang === "ar" ? "قيد الانتظار" : "Pending"}
                </SelectItem>
                <SelectItem value="assigned">
                  {lang === "ar" ? "تم التكليف" : "Assigned"}
                </SelectItem>
                <SelectItem value="in_progress">
                  {lang === "ar" ? "قيد التنفيذ" : "In Progress"}
                </SelectItem>
                <SelectItem value="completed">
                  {lang === "ar" ? "مكتمل" : "Completed"}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Assignments Table */}
      <Card>
        <CardHeader>
          <CardTitle>
            {lang === "ar" ? "جميع التكليفات" : "All Assignments"}
          </CardTitle>
          <CardDescription>
            {lang === "ar"
              ? `تم العثور على ${filteredAssignments.length} تكليف`
              : `${filteredAssignments.length} assignment(s) found`}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {filteredAssignments.length === 0 ? (
            <div className="py-12 text-center">
              <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
              <h3 className="mb-2 text-lg font-medium">
                {lang === "ar" ? "لا توجد تكليفات" : "No assignments found"}
              </h3>
              <p className="text-muted-foreground">
                {assignments.length === 0
                  ? lang === "ar"
                    ? "لم يتم تكليف أي أدوات للحالات بعد. افتح الحالة ثم تبويب التكليفات لإضافة أداة أو مقياس."
                    : "No tools have been assigned yet. Open a case and its Assignments tab to add a tool or assessment."
                  : lang === "ar"
                    ? "لا توجد تكليفات تطابق عوامل التصفية."
                    : "No assignments match your filters."}
              </p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{lang === "ar" ? "الحالة" : "Case"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "التكليف" : "Assignment"}
                  </TableHead>
                  <TableHead>{lang === "ar" ? "النوع" : "Type"}</TableHead>
                  <TableHead>{lang === "ar" ? "الحالة" : "Status"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "مرئي للمستخدم" : "Visible to User"}
                  </TableHead>
                  <TableHead>
                    {lang === "ar" ? "تاريخ التكليف" : "Assigned Date"}
                  </TableHead>
                  <TableHead className="text-right">
                    {lang === "ar" ? "الإجراءات" : "Actions"}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredAssignments.map((assignment) => {
                  const toolType = getToolTypeById(assignment.type)
                  const typeName = getToolTypeName(assignment.type)
                  const Icon = getToolTypeMeta(typeName)?.icon || FileText
                  return (
                    <TableRow key={assignment.id}>
                      <TableCell className="font-medium">
                        <SmartLink
                          href={`/dashboard/cases/${assignment.case}`}
                          className="hover:text-primary hover:underline"
                        >
                          {(() => { const profile = profiles.find(p => p.id === assignment.case); return profile ? <CaseName profile={profile} /> : assignment.case })()}
                        </SmartLink>
                      </TableCell>
                      <TableCell>
                        <SmartLink
                          href={`/dashboard/admin/assignments/${assignment.id}`}
                          className="hover:text-primary hover:underline"
                        >
                          {assignment.name_en ||
                            (lang === "ar"
                              ? "تكليف بدون اسم"
                              : "Unnamed Assignment")}
                        </SmartLink>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 text-muted-foreground">
                          <Icon className="h-3 w-3" />
                          <span className="text-xs">
                            {getToolTypeLabel(toolType, lang)}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge className={statusColors[assignment.status]}>
                          {statusLabels[assignment.status]?.[lang] ||
                            (lang === "ar"
                              ? "حالة غير معروفة"
                              : "Unknown status")}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Switch
                          checked={assignment.is_visible_to_user}
                          onCheckedChange={(checked) =>
                            updateAssignment(assignment.id, {
                              is_visible_to_user: checked,
                            })
                          }
                        />
                      </TableCell>
                      <TableCell>
                        {formatDate(
                          assignment.assigned_at || assignment.created
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          <SmartLink
                            href={`/dashboard/admin/assignments/${assignment.id}`}
                          >
                            <Button variant="ghost" size="sm">
                              <Eye className="h-4 w-4" />
                            </Button>
                          </SmartLink>
                          <Button
                            variant="ghost"
                            size="sm"
                            disabled={!access.can("assignments.delete")}
                            onClick={() => deleteAssignment(assignment.id)}
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { Archive, DatabaseBackup, Download, Loader2, RefreshCw, ShieldCheck } from "lucide-react"
import { Button } from "@/components/ui/button"
import { useLang } from "@/lib/lang-context"
import pb, { getErrorMessage } from "@/lib/pb"

type Backup = { name: string; size: number; modified: string }

export default function BackupsPage() {
  const { lang } = useLang()
  const ar = lang === "ar"
  const [backups, setBackups] = useState<Backup[]>([])
  const [loading, setLoading] = useState(true)
  const [creating, setCreating] = useState(false)
  const [downloading, setDownloading] = useState<string | null>(null)
  const [error, setError] = useState("")
  const [notice, setNotice] = useState("")
  const load = useCallback(async () => {
    setLoading(true)
    setError("")
    try {
      const result = await pb.send<Backup[]>("/api/dsc/backups", { method: "GET", requestKey: null })
      setBackups(result)
    } catch (err) {
      setError(getErrorMessage(err, lang))
    } finally {
      setLoading(false)
    }
  }, [lang])
  useEffect(() => { void load() }, [load])

  async function createBackup() {
    setCreating(true)
    setError("")
    setNotice("")
    try {
      await pb.send<{ name: string }>("/api/dsc/backups", { method: "POST", body: {}, requestKey: null })
      setNotice(ar ? "تم إنشاء النسخة الاحتياطية. يمكنك تنزيلها الآن." : "Backup created. You can download it now.")
      await load()
    } catch (err) {
      setError(getErrorMessage(err, lang))
    } finally {
      setCreating(false)
    }
  }

  async function downloadBackup(name: string) {
    setDownloading(name)
    setError("")
    try {
      const response = await fetch(`${pb.baseURL}/api/dsc/backups/download`, {
        method: "POST",
        headers: { Authorization: pb.authStore.token, "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      })
      if (!response.ok) {
        const failure = await response.json().catch(() => null)
        throw new Error(failure?.message || (ar ? "تعذّر تنزيل النسخة الاحتياطية." : "Unable to download backup."))
      }
      const url = URL.createObjectURL(await response.blob())
      const anchor = document.createElement("a")
      anchor.href = url
      anchor.download = name
      document.body.appendChild(anchor)
      anchor.click()
      anchor.remove()
      window.setTimeout(() => URL.revokeObjectURL(url), 1000)
      setNotice(ar ? "بدأ تنزيل النسخة الاحتياطية." : "Backup download started.")
    } catch (err) {
      setError(getErrorMessage(err, lang))
    } finally {
      setDownloading(null)
    }
  }

  function formatSize(size: number) {
    return new Intl.NumberFormat(ar ? "ar" : "en", { maximumFractionDigits: 1 }).format(size / 1024 / 1024) + " MB"
  }

  return (
    <section className="mx-auto max-w-5xl space-y-6" dir={ar ? "rtl" : "ltr"}>
      <header className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <p className="mb-2 text-xs font-semibold uppercase tracking-widest text-[#927013]">{ar ? "إدارة البيانات" : "Data management"}</p>
          <h1 className="text-3xl font-bold text-[#0b3d60]">{ar ? "النسخ الاحتياطية لقاعدة البيانات" : "Database backups"}</h1>
          <p className="mt-2 max-w-xl text-sm leading-6 text-slate-600">{ar ? "احفظ نسخة من بيانات النظام والملفات المرفوعة، ثم نزّلها للاحتفاظ بها في مكان آمن." : "Create a snapshot of your system data and uploaded files, then download it for safekeeping."}</p>
        </div>
        <Button onClick={createBackup} disabled={creating || loading || downloading !== null} className="min-h-11 gap-2 bg-[#0b3d60]">
          {creating ? <Loader2 className="size-4 animate-spin" /> : <DatabaseBackup className="size-4" />}
          {creating ? (ar ? "جارٍ إنشاء النسخة…" : "Creating backup…") : (ar ? "إنشاء نسخة احتياطية" : "Create backup")}
        </Button>
      </header>

      <aside className="flex gap-3 border-s-4 border-[#caa522] bg-[#fffaf0] p-4 text-sm leading-6 text-[#4c421f]">
        <ShieldCheck className="mt-1 size-5 shrink-0" />
        <p>{ar ? "تتضمن النسخة قاعدة البيانات والملفات المحلية المرفوعة. لا يؤدي إنشاؤها أو تنزيلها إلى تغيير البيانات الحالية. احتفظ بالملف بشكل خاص لأنه قد يحتوي على معلومات شخصية. الاستعادة غير متاحة من هذه الصفحة." : "Backups include the database and local uploaded files. Creating or downloading one does not change current data. Keep the file private because it may contain personal information. This page does not restore backups."}</p>
      </aside>

      {error && <div role="alert" className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}</div>}
      {notice && <div role="status" className="rounded-lg border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800">{notice}</div>}
      <div className="overflow-hidden rounded-xl border border-slate-200 bg-white">
        <div className="flex items-center justify-between gap-3 border-b border-slate-200 px-5 py-4">
          <h2 className="font-semibold text-[#0b3d60]">{ar ? "النسخ المحفوظة" : "Saved backups"}</h2>
          <Button variant="ghost" onClick={() => void load()} disabled={loading || creating || downloading !== null} className="gap-2">
            <RefreshCw className={`size-4 ${loading ? "animate-spin" : ""}`} />{ar ? "تحديث" : "Refresh"}
          </Button>
        </div>
        {loading ? <div role="status" className="flex items-center justify-center gap-2 py-14 text-sm text-slate-600"><Loader2 className="size-5 animate-spin" />{ar ? "جارٍ تحميل النسخ…" : "Loading backups…"}</div> : backups.length === 0 ? (
          <div className="px-5 py-14 text-center"><Archive className="mx-auto mb-4 size-9 text-[#927013]" /><h3 className="font-semibold text-[#0b3d60]">{ar ? "لا توجد نسخ احتياطية بعد" : "No backups yet"}</h3><p className="mt-2 text-sm text-slate-600">{ar ? "أنشئ النسخة الأولى باستخدام الزر أعلاه." : "Create your first snapshot using the button above."}</p></div>
        ) : <ul className="divide-y divide-slate-200">{backups.map((backup) => (
          <li key={backup.name} className="flex flex-col gap-4 px-5 py-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="min-w-0"><p className="break-all font-medium text-[#0b3d60]" dir="ltr">{backup.name}</p><p className="mt-1 text-sm text-slate-600">{Number.isNaN(Date.parse(backup.modified)) ? backup.modified : new Date(backup.modified).toLocaleString(ar ? "ar" : "en")} · <span dir="ltr">{formatSize(backup.size)}</span></p></div>
            <Button variant="outline" className="min-h-11 shrink-0 gap-2" disabled={downloading !== null || creating} onClick={() => void downloadBackup(backup.name)}>
              {downloading === backup.name ? <Loader2 className="size-4 animate-spin" /> : <Download className="size-4" />}{downloading === backup.name ? (ar ? "جارٍ التنزيل…" : "Downloading…") : (ar ? "تنزيل ZIP" : "Download ZIP")}
            </Button>
          </li>
        ))}</ul>}
      </div>
    </section>
  )
}

"use client"
import { TemplateWorkspace } from "@/components/tools/TemplateWorkspace"
import { CaseDocuments } from "@/components/cases/CaseDocuments"
import { CaseMessages } from "@/components/cases/CaseMessages"
import { CaseName } from "@/components/cases/CaseName"
import { usePermissions } from "@/hooks/usePermissions"
import { ProtectedFileLink } from "@/components/ProtectedFileLink"
import { CaseAssessments } from "@/components/assessments/CaseAssessments"
import { CaseAllocations } from "@/components/cases/CaseAllocations"
import { CaseFeedback } from "@/components/cases/CaseFeedback"

import { use, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useUsers } from "@/hooks/useUsers"
import { useLang } from "@/lib/lang-context"
import { t } from "@/lib/i18n"
import { useAuth } from "@/hooks/useAuth"
import { usePaymentSettings } from "@/hooks/usePaymentSettings"
import pb, { getErrorMessage } from "@/lib/pb"
import {
  EMAIL_INVALID_MESSAGE,
  isValidEmail,
  normalizeEmail,
} from "@/lib/validators"
import { toast } from "sonner"
import { sendCredentialsEmail } from "@/lib/send-credentials-email"
import { formatDate } from "@/lib/format-date"

import { CaseStatusBadge } from "@/components/cases/status-badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { EmailInput } from "@/components/ui/email-input"
import { PasswordInput } from "@/components/ui/password-input"
import { Label } from "@/components/ui/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { TableCell, TableRow } from "@/components/ui/table"
import { ArrowLeft, User, ClipboardList, History, Eye, Trash2, FileText, Plus, Link2, UserX, UserPlus, KeyRound, Wallet, Save, CheckCircle2, XCircle, Loader2 } from "lucide-react"
import Link from "next/link"
import type { AssignmentStatus } from "@/types/assignment"
import {
  getToolTypeLabel,
  getToolTypeMeta,
} from "@/lib/tool-types"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التكليف" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function AdminCaseDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id: caseId } = use(params)
  const [activeTab, setActiveTab] = useState("overview")
  useEffect(() => {
    const openTab = () => {
      if (window.location.hash === "#case-assignments") setActiveTab("assigned")
      if (window.location.hash === "#case-allocations")
        setActiveTab("allocations")
    }
    openTab()
    window.addEventListener("hashchange", openTab)
    return () => window.removeEventListener("hashchange", openTab)
  }, [caseId])
  const access = usePermissions()
  const router = useRouter()
  const { lang } = useLang()
  const { currentUser, isAdmin } = useAuth()
  const {
    getProfileById,
    updateProfile,
    setPaymentAmount,
    approveCase,
    rejectPayment,
  } = useProfiles()
  const { assignments, deleteAssignment, refresh: refreshAssignments } = useAssignments()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const { users } = useUsers()
  const { bankDetails } = usePaymentSettings()

  const [showAssignModal, setShowAssignModal] = useState(false)
  const [assignKind, setAssignKind] = useState<"tool" | "assessment">("tool")
  const [assessmentReload, setAssessmentReload] = useState(0)
  const [assessmentCount, setAssessmentCount] = useState(0)
  const [linkMode, setLinkMode] = useState<"existing" | "new">("existing")
  const [linkUserId, setLinkUserId] = useState("")
  const [newUser, setNewUser] = useState({ name: "", email: "", password: "" })
  const [isLinking, setIsLinking] = useState(false)
  const [linkError, setLinkError] = useState<string | null>(null)
  const [linkSuccess, setLinkSuccess] = useState<string | null>(null)
  const [amountInput, setAmountInput] = useState<string | null>(null)
  const [rejectInput, setRejectInput] = useState("")
  const [isPaymentBusy, setIsPaymentBusy] = useState(false)
  const [paymentError, setPaymentError] = useState<string | null>(null)
  const [paymentSuccess, setPaymentSuccess] = useState<string | null>(null)

  const profile = getProfileById(caseId)
  const caseAssignments = assignments.filter((a) => a.case === caseId)
  const owner = profile ? users.find((u) => u.id === profile.user) : undefined
  const linkableUsers = users.filter(
    (u) => !["admin", "super_admin", "expert"].includes(u.role)
  )

  const handleLinkExisting = async () => {
    if (!linkUserId) return
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      await updateProfile(caseId, { user: linkUserId })
      setLinkSuccess(
        lang === "ar" ? "تم ربط الحالة بالمستخدم." : "Case linked to user."
      )
      setLinkUserId("")
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل ربط المستخدم." : "Failed to link user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleCreateAndLink = async () => {
    if (!newUser.name || !newUser.email || !newUser.password) {
      setLinkError(
        lang === "ar"
          ? "يرجى ملء جميع الحقول المطلوبة."
          : "Please fill in all required fields."
      )
      return
    }
    if (!isValidEmail(newUser.email)) {
      setLinkError(t(EMAIL_INVALID_MESSAGE, lang))
      return
    }
    if (newUser.password.length < 8) {
      setLinkError(
        lang === "ar"
          ? "يجب أن تكون كلمة المرور 8 أحرف على الأقل."
          : "Password must be at least 8 characters."
      )
      return
    }
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      const cleanName = newUser.name.trim()
      const cleanEmail = normalizeEmail(newUser.email)

      const record = await pb.collection("users").create({
        email: cleanEmail,
        password: newUser.password,
        passwordConfirm: newUser.password,
        name: cleanName,
        role: "individual",
        contact_number: "",
        is_active: true,
        emailVisibility: true,
      })
      await updateProfile(caseId, { user: record.id })
      try {
        await sendCredentialsEmail({
          email: cleanEmail,
          name: cleanName,
          password: newUser.password,
          caseName: profile?.name,
          caseUrl: `${window.location.origin}/dashboard/cases/${caseId}`,
        })
        setLinkSuccess(
          lang === "ar"
            ? "تم إنشاء المستخدم وربط الحالة وإرسال بيانات الدخول بالبريد."
            : "User created, case linked, and credentials emailed."
        )
      } catch (err) {
        setLinkSuccess(
          lang === "ar"
            ? "تم إنشاء المستخدم وربط الحالة، لكن تعذر إرسال البريد الإلكتروني."
            : "User created and case linked, but the credentials email could not be sent."
        )
        toast.error(getErrorMessage(err))
      }
      setNewUser({ name: "", email: "", password: "" })
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل إنشاء المستخدم." : "Failed to create user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleUnlink = async () => {
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      await updateProfile(caseId, { user: "" })
      setLinkSuccess(lang === "ar" ? "تم فك ربط الحالة." : "Case unlinked.")
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل فك ربط المستخدم." : "Failed to unlink user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleSetAmount = async () => {
    if (!access.can("payments.update")) return
    if (
      amountInput === null ||
      !amountInput.trim() ||
      !Number.isFinite(Number(amountInput)) ||
      Number(amountInput) <= 0
    )
      return
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      if (profile?.status === "pending")
        await setPaymentAmount(caseId, Number(amountInput))
      else await updateProfile(caseId, { payment_amount: Number(amountInput) })
      setPaymentSuccess(
        lang === "ar" ? "تم حفظ رسوم الحالة." : "Case fee saved."
      )
      setAmountInput(null)
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل تحديد المبلغ." : "Failed to set amount.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  const handleApprove = async () => {
    if (!access.can("payments.update")) return
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      await approveCase(caseId)
      setPaymentSuccess(
        lang === "ar"
          ? "تم تفعيل الحالة. يمكن للمستخدم الوصول إليها الآن."
          : "Case enabled. The user can now access it."
      )
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل تفعيل الحالة." : "Failed to enable case.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  const handleReject = async () => {
    if (!access.can("payments.update")) return
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      await rejectPayment(caseId, rejectInput)
      setPaymentSuccess(
        lang === "ar"
          ? "تم رفض الإيصال. سيعاد طلب الدفع للمستخدم."
          : "Receipt rejected. The user will be asked to pay again."
      )
      setRejectInput("")
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل رفض الدفع." : "Failed to reject payment.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الحالة غير موجودة" : "Case not found"}
        </h2>
        <Link href="/dashboard/admin/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary"><CaseName profile={profile} /></h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? `أنشئت في ${formatDate(profile.created)}`
              : `Created ${formatDate(profile.created)}`}
          </p>
        </div>
      </div>

      <Tabs
        value={activeTab}
        onValueChange={setActiveTab}
        className="space-y-4"
      >
        <TabsList className="h-auto flex-wrap">
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="assigned">
            {lang === "ar" ? "الأدوات والمقاييس" : "Tools & assessments"}
            <Badge variant="secondary" className="ms-2">
              {caseAssignments.length + assessmentCount}
            </Badge>
          </TabsTrigger>
          {access.can("allocations.read") && (
            <TabsTrigger value="allocations">
              {lang === "ar" ? "تخصيص الخبراء" : "Expert allocation"}
            </TabsTrigger>
          )}
          <TabsTrigger value="documents">{lang === "ar" ? "المستندات" : "Documents"}</TabsTrigger>
          <TabsTrigger value="case-file">
            {lang === "ar" ? "ملف الحالة" : "Case File"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="dsc-detail-cards">
          {isAdmin && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Link2 className="h-5 w-5" />
                  {lang === "ar" ? "المستخدم المرتبط" : "Linked User"}
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "اربط هذه الحالة بمستخدم ليتمكن من الوصول إليها"
                    : "Link this case to a user so they can access it"}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {linkError && (
                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                    {linkError}
                  </div>
                )}
                {linkSuccess && (
                  <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                    {linkSuccess}
                  </div>
                )}

                {owner ? (
                  <div className="dsc-inline-summary rounded-lg border p-4">
                    <div className="flex items-center gap-3">
                      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10">
                        <User className="h-5 w-5 text-primary" />
                      </div>
                      <div>
                        <p className="font-medium">{owner.name}</p>
                        <p className="text-sm text-muted-foreground">
                          {owner.email}
                        </p>
                      </div>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleUnlink}
                      disabled={isLinking}
                    >
                      <UserX className="me-1 h-4 w-4" />
                      {lang === "ar" ? "فك الربط" : "Unlink"}
                    </Button>
                  </div>
                ) : (
                  <div className="rounded-lg border p-4">
                    <p className="mb-3 text-sm text-muted-foreground">
                      {lang === "ar"
                        ? "لا يوجد مستخدم مرتبط بهذه الحالة بعد."
                        : "No user linked to this case yet."}
                    </p>
                    <div className="grid grid-cols-2 gap-3">
                      <Button
                        type="button"
                        variant={
                          linkMode === "existing" ? "default" : "outline"
                        }
                        size="sm"
                        onClick={() => setLinkMode("existing")}
                      >
                        <Link2 className="me-1 h-4 w-4" />
                        {lang === "ar" ? "مستخدم مسجل" : "Existing User"}
                      </Button>
                      <Button
                        type="button"
                        variant={linkMode === "new" ? "default" : "outline"}
                        size="sm"
                        onClick={() => setLinkMode("new")}
                      >
                        <UserPlus className="me-1 h-4 w-4" />
                        {lang === "ar" ? "مستخدم جديد" : "New User"}
                      </Button>
                    </div>

                    {linkMode === "existing" ? (
                      <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-end">
                        <div className="flex-1 space-y-2">
                          <Label>{lang === "ar" ? "المستخدم" : "User"}</Label>
                          <Select
                            value={linkUserId}
                            onValueChange={setLinkUserId}
                          >
                            <SelectTrigger>
                              <SelectValue
                                placeholder={
                                  lang === "ar"
                                    ? "اختر مستخدمًا"
                                    : "Select a user"
                                }
                              />
                            </SelectTrigger>
                            <SelectContent>
                              {linkableUsers.length === 0 ? (
                                <SelectItem value="__none__" disabled>
                                  {lang === "ar"
                                    ? "لا يوجد مستخدمون"
                                    : "No users available"}
                                </SelectItem>
                              ) : (
                                linkableUsers.map((user) => (
                                  <SelectItem key={user.id} value={user.id}>
                                    {user.name} ({user.email})
                                  </SelectItem>
                                ))
                              )}
                            </SelectContent>
                          </Select>
                        </div>
                        <Button
                          onClick={handleLinkExisting}
                          disabled={isLinking || !linkUserId}
                        >
                          <Link2 className="me-1 h-4 w-4" />
                          {lang === "ar" ? "ربط" : "Link"}
                        </Button>
                      </div>
                    ) : (
                      <div className="mt-4 space-y-3 rounded-lg bg-muted/50 p-4">
                        <div className="space-y-2">
                          <Label htmlFor="link_user_name">
                            {lang === "ar" ? "الاسم الكامل" : "Full Name"}
                          </Label>
                          <Input
                            id="link_user_name"
                            value={newUser.name}
                            onChange={(e) =>
                              setNewUser({ ...newUser, name: e.target.value })
                            }
                            placeholder={
                              lang === "ar"
                                ? "أدخل الاسم الكامل"
                                : "Enter full name"
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="link_user_email">
                            {lang === "ar" ? "البريد الإلكتروني" : "Email"}
                          </Label>
                          <EmailInput
                            id="link_user_email"
                            value={newUser.email}
                            onChange={(value) =>
                              setNewUser({ ...newUser, email: value })
                            }
                            placeholder={
                              lang === "ar"
                                ? "أدخل عنوان البريد الإلكتروني"
                                : "Enter email address"
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="link_user_password">
                            {lang === "ar" ? "كلمة المرور" : "Password"}
                          </Label>
                          <PasswordInput
                            id="link_user_password"
                            value={newUser.password}
                            onChange={(e) =>
                              setNewUser({
                                ...newUser,
                                password: e.target.value,
                              })
                            }
                            placeholder={
                              lang === "ar"
                                ? "8 أحرف على الأقل"
                                : "Min 8 characters"
                            }
                          />
                        </div>
                        <Button
                          onClick={handleCreateAndLink}
                          disabled={isLinking}
                          className="w-full"
                        >
                          <KeyRound className="me-1 h-4 w-4" />
                          {isLinking
                            ? lang === "ar"
                              ? "جارٍ الإنشاء..."
                              : "Creating..."
                            : lang === "ar"
                              ? "إنشاء مستخدم وربط"
                              : "Create User & Link"}
                        </Button>
                        <p className="text-xs text-muted-foreground">
                          {lang === "ar"
                            ? "سيتم إنشاء حساب جديد وسيتم إرسال بيانات الدخول إلى بريد المستخدم."
                            : "A new account will be created and the login credentials will be emailed to the user."}
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </CardContent>
            </Card>
          )}
          {isAdmin && access.can("payments.read") && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Wallet className="h-5 w-5" />
                  {lang === "ar" ? "الدفع" : "Payment"}
                  <CaseStatusBadge status={profile.status} />
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "حدد المبلغ، راجع الإيصال، وفعّل الحالة"
                    : "Set the amount, review the receipt, and enable the case"}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {paymentError && (
                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                    {paymentError}
                  </div>
                )}
                {paymentSuccess && (
                  <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                    {paymentSuccess}
                  </div>
                )}

                <div className="dsc-inline-summary rounded-lg border p-4">
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
                    <div className="flex-1 space-y-2">
                      <Label htmlFor="payment_amount">
                        {lang === "ar" ? "رسوم الحالة" : "Case fee"}
                      </Label>
                      <Input
                        id="payment_amount"
                        fieldWidth="short"
                        type="number"
                        min="0"
                        step="0.01"
                        aria-describedby="case-fee-help"
                        value={
                          amountInput ?? String(profile.payment_amount ?? 0)
                        }
                        onChange={(e) => setAmountInput(e.target.value)}
                        placeholder={
                          lang === "ar" ? "أدخل المبلغ" : "Enter amount"
                        }
                      />
                      <p
                        id="case-fee-help"
                        className="text-xs text-muted-foreground"
                      >
                        {lang === "ar"
                          ? `الرسوم الحالية بعملة ${bankDetails.currency}. عدّل القيمة ثم اضغط حفظ الرسوم.`
                          : `Current fee in ${bankDetails.currency}. Edit the value, then click Save fee.`}
                      </p>
                    </div>
                    <Button
                      onClick={handleSetAmount}
                      disabled={
                        isPaymentBusy ||
                        !access.can("payments.update") ||
                        amountInput === null ||
                        !amountInput.trim() ||
                        !Number.isFinite(Number(amountInput)) ||
                        Number(amountInput) <= 0 ||
                        Number(amountInput) ===
                          Number(profile.payment_amount ?? 0)
                      }
                    >
                      {isPaymentBusy ? (
                        <Loader2 className="me-1 h-4 w-4 animate-spin" />
                      ) : (
                        <Save className="me-1 h-4 w-4" />
                      )}
                      {lang === "ar" ? "حفظ الرسوم" : "Save fee"}
                    </Button>
                  </div>
                  {profile.payment_slip && (
                    <ProtectedFileLink
                      href={pb.files.getURL(
                        { collectionId: "cases", id: caseId },
                        profile.payment_slip
                      )}
                      target="_blank"
                      rel="noreferrer"
                    >
                      <Button variant="outline" size="sm">
                        <FileText className="me-1 h-4 w-4" />
                        {lang === "ar" ? "عرض الإيصال" : "View Receipt"}
                      </Button>
                    </ProtectedFileLink>
                  )}
                </div>

                {profile.status === "awaiting_payment" && (
                  <p className="text-sm text-muted-foreground">
                    {lang === "ar"
                      ? "بانتظار رفع إيصال التحويل من المستخدم."
                      : "Waiting for the user to upload the transfer receipt."}
                    {profile.payment_reject_reason && (
                      <span className="ms-1 text-red-600">
                        {lang === "ar"
                          ? `الرفض: ${profile.payment_reject_reason}`
                          : `Rejected: ${profile.payment_reject_reason}`}
                      </span>
                    )}
                  </p>
                )}

                {profile.status === "under_review" && (
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
                    <div className="flex-1 space-y-2">
                      <Label htmlFor="reject_reason">
                        {lang === "ar"
                          ? "سبب الرفض (اختياري)"
                          : "Reject reason (optional)"}
                      </Label>
                      <Input
                        id="reject_reason"
                        value={rejectInput}
                        onChange={(e) => setRejectInput(e.target.value)}
                        placeholder={
                          lang === "ar"
                            ? "مثال: المبلغ غير مطابق"
                            : "e.g. Amount does not match"
                        }
                      />
                    </div>
                    <Button
                      onClick={handleApprove}
                      disabled={isPaymentBusy || !access.can("payments.update")}
                    >
                      {isPaymentBusy ? (
                        <Loader2 className="me-1 h-4 w-4 animate-spin" />
                      ) : (
                        <CheckCircle2 className="me-1 h-4 w-4" />
                      )}
                      {lang === "ar" ? "تفعيل الحالة" : "Enable Case"}
                    </Button>
                    <Button
                      variant="destructive"
                      onClick={handleReject}
                      disabled={isPaymentBusy || !access.can("payments.update")}
                    >
                      <XCircle className="me-1 h-4 w-4" />
                      {lang === "ar" ? "رفض" : "Reject"}
                    </Button>
                  </div>
                )}

                {profile.status === "active" && (
                  <p className="text-sm text-green-700">
                    {lang === "ar"
                      ? "الحالة مفعلة والدفع مكتمل."
                      : "Case is active and paid."}
                  </p>
                )}
              </CardContent>
            </Card>
          )}
          <div className="dsc-detail-grid">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="h-5 w-5" />
                  {lang === "ar" ? "معلومات الطفل" : "Child Information"}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="dsc-detail-row">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                  </span>
                  <span className="font-medium">
                    {profile.date_of_birth
                      ? formatDate(profile.date_of_birth)
                      : "—"}
                  </span>
                </div>
                <div className="dsc-detail-row">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "الجنس" : "Gender"}
                  </span>
                  <span className="font-medium capitalize">
                    {profile.gender === "male"
                      ? lang === "ar"
                        ? "ذكر"
                        : "male"
                      : profile.gender === "female"
                        ? lang === "ar"
                          ? "أنثى"
                          : "female"
                        : profile.gender}
                  </span>
                </div>
                <div className="dsc-detail-row">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "الصف الدراسي" : "Grade"}
                  </span>
                  <span className="font-medium capitalize">
                    {profile.grade}
                  </span>
                </div>
                {profile.notes && (
                  <div className="pt-2">
                    <span className="mb-2 block text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </span>
                    <p className="text-sm text-muted-foreground">
                      {profile.notes}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>

            {profile.notes && (
              <Card className="lg:col-span-2">
                <CardHeader>
                  <CardTitle>{lang === "ar" ? "ملاحظات" : "Notes"}</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-muted-foreground">{profile.notes}</p>
                </CardContent>
              </Card>
            )}
          </div>
        </TabsContent>

        <TabsContent value="assigned" id="case-assignments">
          <CaseMessages key={caseId} caseId={caseId} />
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <ClipboardList className="h-5 w-5" />
                  {lang === "ar" ? "التكليفات" : "Assignments"}
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "إدارة التكليفات لهذه الحالة"
                    : "Manage assignments for this case"}
                </CardDescription>
              </div>
              <Button
                onClick={() => {
                  setAssignKind("tool")
                  setShowAssignModal(true)
                }}
              >
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar"
                  ? "تكليف أداة أو مقياس"
                  : "Assign tool or assessment"}
              </Button>
            </CardHeader>
            <CardContent>
              <CaseAssessments
                key={`${profile.id}-${assessmentReload}`}
                caseId={profile.id}
                mode="list"
                onCountChange={setAssessmentCount}
                assignmentRows={
                  caseAssignments.length ? (
                    <>
                      {caseAssignments.map((assignment) => {
                        const toolType = toolTypes.find(
                          (t) => t.id === assignment.type
                        )
                        const toolTypeName = toolType?.key || "custom"
                        const Icon =
                          getToolTypeMeta(toolTypeName)?.icon || FileText

                        return (
                          <TableRow key={assignment.id}>
                            <TableCell className="font-medium">
                              {assignment.name_en ||
                                (lang === "ar"
                                  ? "تكليف بدون اسم"
                                  : "Unnamed Assignment")}
                            </TableCell>
                            <TableCell>
                              <div className="flex items-center gap-1">
                                <Icon className="h-3 w-3 text-muted-foreground" />
                                <span className="text-xs">
                                  {getToolTypeLabel(toolType, lang)}
                                </span>
                              </div>
                            </TableCell>
                            <TableCell>
                              <Badge
                                className={statusColors[assignment.status]}
                              >
                                {statusLabels[assignment.status]?.[lang] ||
                                  (lang === "ar"
                                    ? "حالة غير معروفة"
                                    : "Unknown status")}
                              </Badge>
                            </TableCell>
                            <TableCell>
                              {assignment.is_visible_to_user
                                ? lang === "ar"
                                  ? "نعم"
                                  : "Yes"
                                : lang === "ar"
                                  ? "لا"
                                  : "No"}
                            </TableCell>
                            <TableCell>
                              {formatDate(
                                assignment.assigned_at || assignment.created
                              )}
                            </TableCell>
                            <TableCell className="text-right">
                              <div className="flex items-center justify-end gap-1">
                                <Link
                                  href={`/dashboard/admin/cases/${profile.id}/tasks/${assignment.id}`}
                                >
                                  <Button variant="ghost" size="sm">
                                    <Eye className="h-4 w-4" />
                                  </Button>
                                </Link>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    deleteAssignment(assignment.id)
                                  }
                                >
                                  <Trash2 className="h-4 w-4 text-destructive" />
                                </Button>
                              </div>
                            </TableCell>
                          </TableRow>
                        )
                      })}
                    </>
                  ) : undefined
                }
              />
            </CardContent>
          </Card>
        </TabsContent>

        {access.can("allocations.read") && (
          <TabsContent value="allocations" id="case-allocations">
            <CaseAllocations
              key={profile.id}
              caseId={profile.id}
            />
          </TabsContent>
        )}
        <TabsContent value="documents"><CaseDocuments key={caseId} caseId={caseId} mode="list" basePath={`/dashboard/admin/cases/${encodeURIComponent(caseId)}/files`} /></TabsContent>
        <TabsContent value="case-file">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <History className="h-5 w-5" />
                {lang === "ar" ? "ملف الحالة" : "Case File"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "سجل جميع التفاعلات بين الحالة والخبير"
                  : "History of all interactions between the case and the expert"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {caseAssignments.filter((a) => a.status === "completed")
                .length === 0 ? (
                <div className="py-8 text-center">
                  <History className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا يوجد سجل بعد" : "No history yet"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر التكليفات المكتملة هنا"
                      : "Completed assignments will appear here"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {caseAssignments
                    .filter((a) => a.status === "completed")
                    .map((assignment) => (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4"
                      >
                        <div>
                          <p className="font-medium">
                            {lang === "ar"
                              ? assignment.name_ar || assignment.name_en
                              : assignment.name_en}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {lang === "ar" ? "أكملت في" : "Completed"}{" "}
                            {assignment.updated &&
                              formatDate(assignment.updated)}
                          </p>
                        </div>
                        <Badge variant="default">
                          {lang === "ar" ? "مكتمل" : "Completed"}
                        </Badge>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      <CaseFeedback caseId={profile.id} ownerId={profile.user} />

      {showAssignModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <Card className="mx-4 w-full max-w-2xl">
            <CardHeader>
              <CardTitle>
                {lang === "ar"
                  ? "تكليف أداة أو مقياس"
                  : "Assign tool or assessment"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "اختر أداة أو أنشئ أداة جديدة لهذه الحالة"
                  : "Choose a tool or create a new tool for this case"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="mb-4 flex gap-2">
                <Button
                  variant={assignKind === "tool" ? "default" : "outline"}
                  onClick={() => setAssignKind("tool")}
                >
                  {lang === "ar" ? "أداة" : "Tool"}
                </Button>
                <Button
                  variant={assignKind === "assessment" ? "default" : "outline"}
                  onClick={() => setAssignKind("assessment")}
                >
                  {lang === "ar" ? "مقياس / تقييم" : "Assessment"}
                </Button>
              </div>
              {assignKind === "assessment" ? (
                <CaseAssessments
                  caseId={profile.id}
                  mode="assign"
                  onAssigned={() => {
                    setAssessmentReload((v) => v + 1)
                    setShowAssignModal(false)
                  }}
                />
              ) : (
                <TemplateWorkspace caseId={caseId} onSent={() => { void refreshAssignments(); setAssessmentReload(v => v + 1); setShowAssignModal(false) }} />
              )}
            </CardContent>
            <CardContent className="flex justify-end pt-0">
              <Button
                variant="outline"
                onClick={() => {
                  setShowAssignModal(false)
                }}
              >
                {lang === "ar" ? "إلغاء" : "Cancel"}
              </Button>
            </CardContent>
          </Card>
        </div>
      )}


    </div>
  )
}

"use client"
import { useUiTranslation } from "@/hooks/useUiTranslation"
import { usePermissions } from "@/hooks/usePermissions"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"

import { useLang } from "@/lib/lang-context"
import { usePaymentSettings } from "@/hooks/usePaymentSettings"
import type { PaymentBankDetails } from "@/lib/payment"
import { getErrorMessage } from "@/lib/pb"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { ArrowLeft, Landmark, Loader2 } from "lucide-react"

export default function PaymentSettingsPage() {
  const ui = useUiTranslation()

  const access = usePermissions()
  const router = useRouter()
  const canReadSettings = access.can("settings.read")
  const isAuthLoading = access.isLoading
  const { lang } = useLang()
  const {
    bankDetails,
    isLoading: isSettingsLoading,
    saveBankDetails,
  } = usePaymentSettings()

  const [formData, setFormData] = useState<PaymentBankDetails>(bankDetails)
  const [isSaving, setIsSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (isAuthLoading) return
    if (!canReadSettings) {
      router.push("/dashboard")
    }
  }, [isAuthLoading, canReadSettings, router])

  useEffect(() => {
    setFormData(bankDetails)
  }, [bankDetails])

  if (isAuthLoading || isSettingsLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!canReadSettings) {
    return null
  }

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!access.can("settings.update")) return
    setIsSaving(true)
    setSaved(false)
    setError(null)
    try {
      await saveBankDetails(formData)
      setSaved(true)
    } catch (err) {
      setError(
        getErrorMessage(err) ||
          (lang === "ar" ? "فشل حفظ الإعدادات." : "Failed to save settings.")
      )
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "إعدادات الدفع" : "Payment Settings"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "بيانات التحويل البنكي المعروضة للمستخدمين عند الدفع"
              : "Bank transfer details shown to users when paying for a case"}
          </p>
        </div>
      </div>

      <form onSubmit={handleSave}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Landmark className="h-5 w-5" />
              {lang === "ar"
                ? "بيانات التحويل البنكي"
                : "Bank Transfer Details"}
            </CardTitle>
            <CardDescription>
              {lang === "ar"
                ? "ستظهر هذه البيانات للمستخدمين في صفحة الدفع."
                : "These details will be shown to users on the payment page."}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {error && (
              <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                {error}
              </div>
            )}
            {saved && (
              <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                {lang === "ar"
                  ? "تم حفظ الإعدادات بنجاح."
                  : "Settings saved successfully."}
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="currency">
                {lang === "ar" ? "العملة" : "Currency"}
              </Label>
              <Input
                id="currency"
                value={formData.currency}
                onChange={(e) =>
                  setFormData({ ...formData, currency: e.target.value })
                }
                placeholder="SAR"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="bank_name">
                {lang === "ar" ? "اسم البنك" : "Bank Name"}
              </Label>
              <Input
                id="bank_name"
                value={formData.bank_name}
                onChange={(e) =>
                  setFormData({ ...formData, bank_name: e.target.value })
                }
                placeholder={
                  lang === "ar"
                    ? "مثال: البنك الأهلي السعودي"
                    : "e.g. National Commercial Bank"
                }
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="beneficiary">
                {lang === "ar" ? "اسم المستفيد" : "Beneficiary Name"}
              </Label>
              <Input
                id="beneficiary"
                value={formData.beneficiary}
                onChange={(e) =>
                  setFormData({ ...formData, beneficiary: e.target.value })
                }
                placeholder={
                  lang === "ar" ? "اسم صاحب الحساب" : "Account holder name"
                }
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="account_number">
                {lang === "ar" ? "رقم الحساب" : "Account Number"}
              </Label>
              <Input
                id="account_number"
                value={formData.account_number}
                onChange={(e) =>
                  setFormData({ ...formData, account_number: e.target.value })
                }
                placeholder={
                  lang === "ar" ? "أدخل رقم الحساب" : "Enter account number"
                }
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="iban">{ui("IBAN")}</Label>
              <Input
                id="iban"
                dir="ltr"
                value={formData.iban}
                onChange={(e) =>
                  setFormData({ ...formData, iban: e.target.value })
                }
                placeholder="SA0000000000000000000000"
              />
            </div>

            <div className="flex justify-end pt-2">
              <Button
                type="submit"
                disabled={isSaving || !access.can("settings.update")}
              >
                {isSaving ? (
                  <Loader2 className="me-1 h-4 w-4 animate-spin" />
                ) : null}
                {isSaving
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "حفظ"
                    : "Save"}
              </Button>
            </div>
          </CardContent>
        </Card>
      </form>
    </div>
  )
}

"use client"
