  { value: "opt5", label: "Option 5", isCorrect: false },
]

interface MultipleChoiceBuilderPageProps {
  params?: Promise<{ id?: string }>
  searchParams?: Promise<{ caseId?: string }>
}

export default function MultipleChoiceBuilderPage({
  params,
  searchParams,
}: MultipleChoiceBuilderPageProps = {}) {
  const router = useRouter()
  const { lang } = useLang()
  const {
    updateTool,
    getToolById,
    isLoading: isToolsLoading,
    loadError: toolsLoadError,
    refresh: retryTools,
  } = useTools()
  const { assignTool } = useAssignments()
  const { getProfileById } = useProfiles()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState("")
  const createdTemplateId = useRef<string | null>(null)
  const submitting = useRef(false)
  const [isLoading, setIsLoading] = useState(false)

  // Edit mode detection
  const resolvedParams = params ? use(params) : undefined
  const resolvedSearchParams = searchParams ? use(searchParams) : undefined
  const editId = resolvedParams?.id
  const caseId = resolvedSearchParams?.caseId
  const isEditMode = !!editId

  const { currentUser } = useAuth()
  const isExpert = currentUser?.role === "expert"
  const [templateSelected, setIsTemplate] = useState(true)
  const isTemplate = isExpert ? false : templateSelected
  const selectedCase = caseId ? getProfileById(caseId) : null

  const [formData, setFormData] = useState({
    nameEn: "",
    nameAr: "",
  })

  const [questions, setQuestions] = useState<MCQuestion[]>([])
  const [pendingFiles, setPendingFiles] = useState<Map<string, File>>(new Map())
  const filePreviewUrls = useFilePreviewUrls(pendingFiles)
  const [uploadOpen, setUploadOpen] = useState(false)
  const [currentMediaQuestionId, setCurrentMediaQuestionId] = useState<
    string | null
  >(null)

  // Load existing data in edit mode
  useEffect(() => {
    if (isEditMode && editId && !isToolsLoading) {
      // Initialize the editable draft once the asynchronous tool data is available.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsLoading(true)
      const tool = getToolById(editId)
      if (tool && tool.config) {
        const config = tool.config as MultipleChoiceConfig
        setFormData({
          nameEn: tool.name.ar || tool.name.en,
          nameAr: tool.name.ar || tool.name.en,
        })
        setQuestions(config.questions || [])
      }
      setIsLoading(false)
    }
  }, [isEditMode, editId, isToolsLoading, getToolById])

  const addQuestion = () => {
    const newQuestion: MCQuestion = {
      id: generateId(),
      text: "",
      answerType: "single_choice",
      options: [...DEFAULT_OPTIONS],
      required: false,
      order: questions.length,
    }
    setQuestions([...questions, newQuestion])
  }

  const updateQuestion = (id: string, updates: Partial<MCQuestion>) => {
    setQuestions(questions.map((q) => (q.id === id ? { ...q, ...updates } : q)))
  }

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter((q) => q.id !== id))
  }

  const handleReorder = (reordered: MCQuestion[]) => {
    setQuestions(reordered)
  }

  const handleSubmit = async () => {
    if (submitting.current || !formData.nameEn || questions.length === 0) return
    submitting.current = true
    setIsSubmitting(true)
    setSubmitError("")
    try {

    const toolTypes = await fetchToolTypes()
    const type = toolTypes.find((t) => t.key === "multiple_answer")?.id
    if (!type) {
      throw new Error(lang === "ar" ? "نوع الأداة multiple_answer مفقود. صحح إعدادات أنواع الأدوات على الخادم." : "The multiple_answer tool type is missing. Correct the server tool type settings.")
    }

    const mediaUrls = (record: {media?: unknown;[key:string]:unknown}) => {
      if (!Array.isArray(record.media) || record.media.some(name => typeof name !== "string")) throw new Error(lang === "ar" ? "تعذر إكمال الحفظ: حقل ملفات الأداة media مفقود أو غير صحيح على الخادم. يلزم تطبيق تحديث قاعدة البيانات." : "Cannot complete saving: the tool media file field is missing or invalid on the server. Apply the database update.")
      return (record.media as string[]).map(filename => pb.files.getURL(record as never, filename))
    }
    const baseQuestions = questions.map((q, idx) => ({ ...q, order: idx }))
    const pendingEntries = Array.from(pendingFiles.entries())

    const baseConfig: MultipleChoiceConfig = {
      title: { en: formData.nameEn, ar: formData.nameEn },
      questions: baseQuestions,
      media: [],
    }

    let finalConfig: MultipleChoiceConfig

    // Helper: build finalConfig from uploaded URLs
    const buildFinalConfig = (uploadedUrls: string[]): MultipleChoiceConfig => {
      const finalQuestions = baseQuestions.map((q) => {
        const pendingIndex = pendingEntries.findIndex(([id]) => id === q.id)
        if (pendingIndex >= 0 && uploadedUrls[pendingIndex]) {
          return { ...q, mediaUrl: uploadedUrls[pendingIndex] }
        }
        return q
      })
      return {
        title: { en: formData.nameEn, ar: formData.nameEn },
        questions: finalQuestions,
        media: uploadedUrls,
      }
    }

    if (isEditMode && editId) {
      const mediaFormData = new FormData()
      for (const [, file] of pendingEntries) {
        mediaFormData.append("media", file)
      }
      mediaFormData.append("config", JSON.stringify(baseConfig))

      const record = await pb.collection("tools").update(editId, mediaFormData)
      const uploadedUrls = mediaUrls(record)

      finalConfig = buildFinalConfig(uploadedUrls)

      await updateTool(editId, {
        name: { en: formData.nameEn, ar: formData.nameEn },
        config: finalConfig,
      })
      router.push(`/dashboard/admin/tools/multiple-choice/${editId}`)
      return
    }

    // Create mode: only 2 paths
    if (!isTemplate && caseId) {
      // Assignment: create in case_tools, upload media there
      const assignment = await caseToolsCollection.create({
        case: caseId,
        type: type,
        name_en: formData.nameEn,
        name_ar: formData.nameEn,
        is_not_template: true,
        config: baseConfig,
        status: "pending",
        is_visible_to_user: true,
        responses: {},
        media: [],
      })

      if (pendingEntries.length > 0) {
        const files = pendingEntries.map(([, file]) => file)
        const updated = await caseToolsCollection.updateWithFiles(
          assignment.id,
          {},
          files
        )
        const uploadedUrls = (updated.media as string[]).map((filename) =>
          pb.files.getURL(updated, filename)
        )
        finalConfig = buildFinalConfig(uploadedUrls)
        await caseToolsCollection.update(assignment.id, { config: finalConfig })
      } else {
        finalConfig = baseConfig
      }

      router.push(caseTaskPath(caseId))
    } else {
      // Template (with or without case): create in tools, upload media there
      const mediaFormData = new FormData()
      mediaFormData.append("name_en", formData.nameEn)
      mediaFormData.append("name_ar", formData.nameEn)
      mediaFormData.append("type", type)
      mediaFormData.append("serviceType", "individual")
      mediaFormData.append("status", "active")
      mediaFormData.append("config", JSON.stringify(baseConfig))
      for (const [, file] of pendingEntries) {
        mediaFormData.append("media", file)
      }

      const record = createdTemplateId.current
        ? await pb.collection("tools").update(createdTemplateId.current, mediaFormData)
        : await pb.collection("tools").create(mediaFormData)
      createdTemplateId.current = record.id
      const uploadedUrls = mediaUrls(record)

      finalConfig = buildFinalConfig(uploadedUrls)

      await updateTool(record.id, {
        name: { en: formData.nameEn, ar: formData.nameEn },
        config: finalConfig,
      })

      if (caseId) {
        await caseToolsCollection.create({
          case: caseId,
          type: type,
          name_en: formData.nameEn,
          name_ar: formData.nameEn,
          is_not_template: false,
          config: finalConfig,
          is_visible_to_user: true,
          status: "pending",
          responses: {},
          media: [],
        })
      }

      router.push(`/dashboard/admin/tools`)
    }
    } catch (error) {
      setSubmitError(getErrorMessage(error, lang))
    } finally {
      submitting.current = false
      setIsSubmitting(false)
    }
  }

  const getMediaIcon = (type?: MediaType) => {
    switch (type) {
      case "image":
        return Image
      case "video":
        return Video
      case "audio":
        return Music
      default:
        return Image
    }
  }

  const handleMediaUpload = (data: {
    file: File
    mediaType: MediaType
    responseType: ResponseType
  }) => {
    if (!currentMediaQuestionId) return
    updateQuestion(currentMediaQuestionId, {
      mediaType: data.mediaType,
      mediaUrl: "",
      responseType: data.responseType,
    })
    setPendingFiles((prev) =>
      new Map(prev).set(currentMediaQuestionId, data.file)
    )
    setCurrentMediaQuestionId(null)
  }

  const handleRemoveMedia = (questionId: string) => {
    updateQuestion(questionId, {
      mediaType: undefined,
      mediaUrl: undefined,
      responseType: undefined,
    })
    setPendingFiles((prev) => {
      const next = new Map(prev)
      next.delete(questionId)
      return next
    })
  }

  const renderQuestionItem = (question: MCQuestion, index: number) => {
    const showOptions =
      question.answerType === "single_choice" ||
      question.answerType === "multiple_choice"
    const isMedia = question.answerType === "media"
    const mediaPreviewSrc = filePreviewUrls.get(question.id) || question.mediaUrl

    return (
      <div className="flex-1 space-y-3">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium">
            {lang === "ar" ? "سؤال" : "Question"} {index + 1}
          </span>
          <div className="flex items-center gap-2">
            <Checkbox
              id={`req-${question.id}`}
              checked={question.required}
              onCheckedChange={(checked) =>
                updateQuestion(question.id, { required: !!checked })
              }
            />
            <Label htmlFor={`req-${question.id}`} className="text-xs">
              {lang === "ar" ? "إجباري" : "Required"}
            </Label>
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => {
                removeQuestion(question.id)
                setPendingFiles((prev) => {
                  const next = new Map(prev)
                  next.delete(question.id)
                  return next
                })
              }}
            >
              <Trash2 className="h-4 w-4 text-destructive" />
            </Button>
          </div>
        </div>

        <Input
          placeholder={lang === "ar" ? "سؤال" : "Question"}
          value={question.text}
          onChange={(e) =>
            updateQuestion(question.id, { text: e.target.value })
          }
        />

        <Select
          value={question.answerType}
          onValueChange={(v) =>
            updateQuestion(question.id, { answerType: v as MCAnswerType })
          }
        >
          <SelectTrigger className="w-56">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ANSWER_TYPES.map((type) => (
              <SelectItem key={type.value} value={type.value}>
                {type.label[lang]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {isMedia && (
          <div className="space-y-3 rounded-md border p-3">
            <Label className="text-xs">
              {lang === "ar" ? "وسائط السؤال" : "Media Prompt"}
            </Label>
            {!question.mediaType ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  setCurrentMediaQuestionId(question.id)
                  setUploadOpen(true)
                }}
              >
                <Plus className="me-1 h-3 w-3" />
                {lang === "ar" ? "اختر الوسائط" : "Select Media"}
              </Button>
            ) : (
              <div className="space-y-3">
                <div className="rounded-lg border bg-muted/30 p-2">
                  {question.mediaType === "image" && mediaPreviewSrc && (
                    <img
                      src={mediaPreviewSrc}
                      alt={lang === "ar" ? "معاينة" : "Preview"}
                      className="h-32 w-full rounded object-cover"
                    />
                  )}
                  {question.mediaType === "video" && mediaPreviewSrc && (
                    <video
                      controls
                      playsInline
                      src={mediaPreviewSrc}
                      className="h-32 w-full rounded object-cover"
                    />
                  )}
                  {question.mediaType === "audio" && (
                    <div className="flex h-12 items-center justify-center rounded bg-muted">
                      <Music className="h-6 w-6" />
                    </div>
                  )}
                  {question.mediaType === "audio" && mediaPreviewSrc && (
                    <audio
                      src={mediaPreviewSrc}
                      controls
                      className="mt-2 w-full"
                    />
                  )}
                  {!mediaPreviewSrc && (
                    <div className="flex h-32 items-center justify-center text-muted-foreground">
                      {lang === "ar" ? "لا توجد معاينة" : "No preview"}
                    </div>
                  )}
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    {(() => {
                      const Icon = getMediaIcon(question.mediaType)
                      return <Icon className="h-4 w-4" />
                    })()}
                    <span className="capitalize">{question.mediaType}</span>
                    <span className="text-muted-foreground">•</span>
                    <span className="capitalize">
                      {question.responseType}{" "}
                      {lang === "ar" ? "استجابة" : "response"}
                    </span>
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveMedia(question.id)}
                  >
                    <X className="me-1 h-3 w-3" />
                    {lang === "ar" ? "إزالة" : "Remove"}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}

        {showOptions && (
          <div className="space-y-2 rounded-md border p-3">
            <Label className="text-xs">
              {lang === "ar"
                ? "الخيارات - حدد الإجابة الصحيحة"
                : "Options - check correct answer(s)"}
            </Label>
            {question.options.map((opt, optIdx) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`correct-${question.id}-${optIdx}`}
                  checked={opt.isCorrect}
                  onCheckedChange={(checked) => {
                    const newOptions = question.options.map((o, i) =>
                      i === optIdx ? { ...o, isCorrect: !!checked } : o
                    )
                    updateQuestion(question.id, { options: newOptions })
                  }}
                />
                <Input
                  placeholder={lang === "ar" ? "خيار" : "Option"}
                  value={opt.label}
                  onChange={(e) => {
                    const newOptions = question.options.map((o, i) =>
                      i === optIdx ? { ...o, label: e.target.value } : o
                    )
                    updateQuestion(question.id, { options: newOptions })
                  }}
                  className="flex-1"
                />
                {opt.isCorrect && (
                  <CheckCircle className="h-4 w-4 text-green-600" />
                )}
              </div>
            ))}
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => {
                const newOptions = [
                  ...question.options,
                  {
                    value: generateId(),
                    label: `Option ${question.options.length + 1}`,
                    isCorrect: false,
                  },
                ]
                updateQuestion(question.id, { options: newOptions })
              }}
            >
              <Plus className="me-1 h-3 w-3" />
              {lang === "ar" ? "إضافة خيار" : "Add Option"}
            </Button>
          </div>
        )}
      </div>
    )
  }

  if (toolsLoadError)
    return <DataError message={toolsLoadError} onRetry={retryTools} />

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {isEditMode
                ? lang === "ar"
                  ? "تعديل"
                  : "Edit"
                : lang === "ar"
                  ? "إنشاء"
                  : "Create"}{" "}
              {lang === "ar"
                ? "منشئ الإجابة المتعددة"
                : "Multiple Answer Builder"}
            </h1>
            <p className="text-muted-foreground">
              {isEditMode
                ? lang === "ar"
                  ? "تحديث أسئلة وإجابات الاختبار"
                  : "Update quiz questions and answers"
                : lang === "ar"
                  ? "أنشئ اختباراً بالإجابات الصحيحة"
                  : "Build quiz with correct answer(s)"}
            </p>
          </div>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات أساسية" : "Basic Info"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label>
                    {lang === "ar" ? "الاسم" : "Name"}
                  </Label>
                  <Input
                    value={formData.nameEn || formData.nameAr}
                    onChange={(e) =>
                      setFormData({ ...formData, nameEn: e.target.value, nameAr: e.target.value })
                    }
                    placeholder={
                      lang === "ar" ? "عنوان الاختبار" : "Quiz title"
                    }
                  />
                </div>

              </div>
            </CardContent>
          </Card>

          {caseId && selectedCase && (
            <Card>
              <CardHeader>
                <CardTitle>
                  {lang === "ar" ? "معلومات الحالة" : "Case Information"}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-2 text-sm">
                  <span className="font-medium">
                    {lang === "ar" ? "الحالة:" : "Case:"}
                  </span>
                  <span><CaseName profile={selectedCase} /></span>
                </div>
              </CardContent>
            </Card>
          )}

          {!isExpert && (caseId || !isEditMode) && (
            <Card>
              <CardContent className="pt-6">
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="isTemplate"
                    checked={isTemplate}
                    onCheckedChange={(checked) =>
                      setIsTemplate(checked === true)
                    }
                  />
                  <label
                    htmlFor="isTemplate"
                    className="text-sm leading-none font-medium peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                  >
                    {lang === "ar"
                      ? "حفظ كقالب (متاح للاستخدام المستقبلي)"
                      : "Save as template (available for future use)"}
                  </label>
                </div>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الأسئلة" : "Questions"}</CardTitle>
              <Button size="sm" onClick={addQuestion}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة سؤال" : "Add Question"}
              </Button>
            </CardHeader>
            <CardContent>
              {questions.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar" ? "لا توجد أسئلة بعد." : "No questions yet."}
                </p>
              ) : (
                <DragList
                  items={questions}
                  onReorder={handleReorder}
                  renderItem={renderQuestionItem}
                  keyExtractor={(q) => q.id}
                />
              )}
            </CardContent>
          </Card>

          {submitError && <p role="alert" className="rounded-md bg-red-50 p-3 text-red-800">{submitError}</p>}
          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={() => router.back()}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={
                !formData.nameEn || questions.length === 0 || isSubmitting
              }
            >
              {isSubmitting
                ? isEditMode
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : isEditMode
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء"
                    : "Create"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <MultipleChoicePreview
              config={{
                title: { en: formData.nameEn, ar: formData.nameEn },
                questions,
                media: [],
              }}
            />
          </div>
        )}
      </div>

      <MediaUpload
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        onUpload={handleMediaUpload}
      />
    </div>
  )
}

"use client"
import { caseTaskPath } from "@/lib/case-task-path"

import { useEffect, useState, useRef, useCallback } from "react"
import { useRouter } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { toolTypesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import { DragList } from "@/components/ui/drag-list"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import { PlanPreview } from "@/components/tool-renderers/PlanPreview"
import { Plus, Trash2, Eye, EyeOff } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import type { PlanConfig } from "@/types/tool"

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

// Simple interfaces for admin form (non-bilingual except plan name)
interface SimplePlanGoal {
  id: string
  title: string
  description: string
  order: number
}

interface SimplePlanStep {
  id: string
  goalId?: string
  title: string
  description: string
  notes: string
  comments: string
  dateOfAchievement: string
  evaluation: string
  completed: boolean
  order: number
}

export default function PlanBuilderPage({
  searchParams,
}: {
  searchParams: Promise<{ caseId?: string; edit?: string }>
}) {
  const router = useRouter()
  const { lang } = useLang()
  const { assignTool, updateAssignment, assignments, isLoading: isAssignmentsLoading } = useAssignments()
  const { getProfileById, isLoading: isProfilesLoading } = useProfiles()
  const { currentUser } = useAuth()
  const [editAssignmentId, setEditAssignmentId] = useState<string>("")
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const submitting = useRef(false)
  const [saveError, setSaveError] = useState("")
  const [planTypeId, setPlanTypeId] = useState<string>("")
  const [typeError, setTypeError] = useState<string>("")

  const [selectedCaseId, setSelectedCaseId] = useState("")
  const [hasCaseContext, setHasCaseContext] = useState(false)
  const [isInitializing, setIsInitializing] = useState(true)
  const hasInitialized = useRef(false)

  // Name for this specific plan instance
  const [toolName, setToolName] = useState("")

  const [formData, setFormData] = useState({
    childName: "",
    expertName: "",
    startDate: "",
    endDate: "",
  })

  const [goals, setGoals] = useState<SimplePlanGoal[]>([])
  const [steps, setSteps] = useState<SimplePlanStep[]>([])
  const childName = formData.childName.trim() || getProfileById(selectedCaseId)?.name || ""

  // Fetch plan type ID on mount
  useEffect(() => {
    let active = true
    const fetchPlanType = async () => {
      try {
        const planType = await toolTypesCollection.getByName("plan")
        if (!active) return
        setPlanTypeId(planType.id)
        setTypeError("")
      } catch (error) {
        if (!active) return
        setTypeError(
          getErrorMessage(error) ||
            (lang === "ar"
              ? 'نوع الأداة "plan" غير موجود. يرجى الاتصال بالمسؤول.'
              : 'Tool type "plan" not found. Please contact admin.')
        )
        console.error("Failed to fetch plan type:", error)
      }
    }
    void fetchPlanType()
    return () => { active = false }
  }, [lang])

  // Update expert name when currentUser loads
  useEffect(() => {
    if (currentUser?.name) {
      setFormData((prev) => ({
        ...prev,
        expertName: currentUser.name,
      }))
    }
  }, [currentUser])

  const handleCaseSelect = useCallback((caseId: string) => {
    setSelectedCaseId(caseId)
    if (caseId) {
      const caseProfile = getProfileById(caseId)
      if (caseProfile) {
        setFormData((prev) => ({
          ...prev,
          childName: caseProfile.name,
        }))
        // Auto-generate tool name if empty
        setToolName((prev) => prev || caseProfile.name)
      }
    } else {
      // Reset fields when case is cleared
      setFormData((prev) => ({
        ...prev,
        childName: "",
      }))
    }
  }, [getProfileById])

  // Initialize from URL caseId - runs once after assignments load
  useEffect(() => {
    if (isAssignmentsLoading || isProfilesLoading) return
    if (hasInitialized.current) return

    const initFromUrl = async () => {
      try {
        const params = await searchParams
        const editId = params?.edit
        const caseIdFromUrl = params?.caseId
        setHasCaseContext(Boolean(caseIdFromUrl || editId))

        // Edit mode - load existing assignment
        if (editId) {
          setEditAssignmentId(editId)
          const existingAssignment = assignments.find((a) => a.id === editId)
          if (existingAssignment) {
            const config = existingAssignment.config as PlanConfig
            setSelectedCaseId(existingAssignment.case)
            setToolName(existingAssignment.name_ar || existingAssignment.name_en || "")
            setFormData({
              childName: config?.childName || "",
              expertName: config?.expertName || "",
              startDate: config?.startDate || "",
              endDate: config?.endDate || "",
            })
            setGoals(
              (config?.goals || []).map((g) => ({
                id: g.id,
                title: g.title,
                description: g.description || "",
                order: g.order,
              }))
            )
            setSteps(
              (config?.steps || []).map((s, idx) => ({
                id: s.id,
                title: s.title,
                description: s.description || "",
                notes: s.notes || "",
                comments: s.comments || "",
                dateOfAchievement: s.dateOfAchievement || "",
                evaluation: s.evaluation || "",
                completed: s.completed,
                order: idx,
              }))
            )
          }
        } else if (caseIdFromUrl) {
          handleCaseSelect(caseIdFromUrl)
        }
      } catch (e) {
        console.error("Failed to read searchParams:", e)
        toast.error(getErrorMessage(e))
      } finally {
        setIsInitializing(false)
        hasInitialized.current = true
      }
    }
    initFromUrl()
  }, [isAssignmentsLoading, isProfilesLoading, assignments, searchParams, handleCaseSelect])

  const addGoal = () => {
    setGoals([
      ...goals,
      {
        id: generateId(),
        title: "",
        description: "",
        order: goals.length,
      },
    ])
  }

  const updateGoal = (id: string, updates: Partial<SimplePlanGoal>) => {
    setGoals(goals.map((g) => (g.id === id ? { ...g, ...updates } : g)))
  }

  const removeGoal = (id: string) => {
    setGoals(goals.filter((g) => g.id !== id))
  }

  const handleGoalReorder = (reordered: SimplePlanGoal[]) => {
    setGoals(reordered.map((g, idx) => ({ ...g, order: idx })))
  }

  const addStep = () => {
    setSteps([
      ...steps,
      {
        id: generateId(),
        title: "",
        description: "",
        notes: "",
        comments: "",
        dateOfAchievement: "",
        evaluation: "",
        completed: false,
        order: steps.length,
      },
    ])
  }

  const updateStep = (id: string, updates: Partial<SimplePlanStep>) => {
    setSteps(steps.map((s) => (s.id === id ? { ...s, ...updates } : s)))
  }

  const removeStep = (id: string) => {
    setSteps(steps.filter((s) => s.id !== id))
  }

  const handleStepReorder = (reordered: SimplePlanStep[]) => {
    setSteps(reordered.map((s, idx) => ({ ...s, order: idx })))
  }

  const handleSubmit = async () => {
    if (submitting.current) return
    const missing = [
      [!selectedCaseId, lang === "ar" ? "الحالة" : "case"],
      [!toolName.trim(), lang === "ar" ? "اسم الخطة" : "plan name"],
      [!childName, lang === "ar" ? "اسم الطفل" : "child name"],
      [!formData.expertName.trim(), lang === "ar" ? "اسم الخبير" : "expert name"],
      [!formData.startDate, lang === "ar" ? "تاريخ البداية" : "start date"],
      [!formData.endDate, lang === "ar" ? "تاريخ النهاية" : "end date"],
    ].filter(([required]) => required).map(([, label]) => label)
    if (missing.length || !planTypeId) {
      setSaveError(missing.length
        ? (lang === "ar" ? "أكمل الحقول المطلوبة: " : "Complete the required fields: ") + missing.join("، ")
        : (lang === "ar" ? "نوع الخطة غير متاح. أعد تحميل الصفحة." : "Plan type is unavailable. Reload the page."))
      return
    }
    submitting.current = true
    setSaveError("")
    setIsSubmitting(true)

    try {
      // Convert simple form data to bilingual config for storage
      const config: PlanConfig = {
        childName,
        expertName: formData.expertName,
        startDate: formData.startDate,
        endDate: formData.endDate,
        goals: goals.map((g, idx) => ({
          id: g.id,
          title: g.title,
          description: g.description,
          order: idx,
        })),
        steps: steps.map((s) => ({
          id: s.id,
          title: s.title,
          description: s.description,
          notes: s.notes,
          comments: s.comments,
          dateOfAchievement: s.dateOfAchievement || undefined,
          evaluation: s.evaluation,
          completed: s.completed,
        })),
        media: [],
      }

      // Edit mode - update existing assignment
      if (editAssignmentId) {
        await updateAssignment(editAssignmentId, {
          name_en: toolName.trim(),
          name_ar: toolName.trim(),
          config,
        })
        router.push(caseTaskPath(selectedCaseId, editAssignmentId))
      } else {
        // Create case document directly in case_tools (no tool template)
        await assignTool({
          case: selectedCaseId,
          type: planTypeId,
          name_en: toolName.trim(),
          name_ar: toolName.trim(),
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "pending",
        })

        router.push(caseTaskPath(selectedCaseId))
      }
      toast.success(lang === "ar" ? "تم حفظ الخطة ضمن تكليفات الحالة." : "Plan saved to the case assignments.")
    } catch (error) {
      console.error(editAssignmentId ? "Failed to update plan:" : "Failed to create plan:", error)
      const message = getErrorMessage(error, lang)
      setSaveError(message)
      toast.error(message)
    } finally {
      submitting.current = false
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    if (editAssignmentId) {
      router.push(caseTaskPath(selectedCaseId, editAssignmentId))
    } else {
      // Reset form
      setSelectedCaseId("")
      setToolName("")
      setFormData({
        childName: "",
        expertName: currentUser?.name || "",
        startDate: "",
        endDate: "",
      })
      setGoals([])
      setSteps([])
      setShowPreview(false)
    }
  }

  const renderGoalItem = (goal: SimplePlanGoal, index: number) => (
    <div className="flex-1 space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium">
          {lang === "ar" ? "هدف" : "Goal"} {index + 1}
        </span>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={() => removeGoal(goal.id)}
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      </div>
      <div className="space-y-2">
        <Input
          placeholder={lang === "ar" ? "عنوان الهدف" : "Goal Title"}
          value={goal.title}
          onChange={(e) => updateGoal(goal.id, { title: e.target.value })}
        />
        <Input
          placeholder={lang === "ar" ? "الوصف" : "Description"}
          value={goal.description}
          onChange={(e) => updateGoal(goal.id, { description: e.target.value })}
        />
      </div>
    </div>
  )

  const renderStepItem = (step: SimplePlanStep, index: number) => (
    <div className="flex-1 space-y-3 rounded border p-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Checkbox
            checked={step.completed}
            onCheckedChange={(checked) =>
              updateStep(step.id, { completed: !!checked })
            }
          />
          <span className="font-medium">
            {lang === "ar" ? "خطوة" : "Step"} {index + 1}
          </span>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={() => removeStep(step.id)}
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      </div>

      <div className="space-y-3">
        <Input
          placeholder={lang === "ar" ? "عنوان الخطوة" : "Step Title"}
          value={step.title}
          onChange={(e) => updateStep(step.id, { title: e.target.value })}
        />
        <Input
          placeholder={lang === "ar" ? "الوصف" : "Description"}
          value={step.description}
          onChange={(e) => updateStep(step.id, { description: e.target.value })}
        />

        {/* Fields matching preview layout */}
        <div className="grid gap-2 sm:grid-cols-2">
          <Input
            placeholder={lang === "ar" ? "ملاحظات" : "Notes"}
            value={step.notes}
            onChange={(e) => updateStep(step.id, { notes: e.target.value })}
          />
          <Input
            placeholder={lang === "ar" ? "تعليقات" : "Comments"}
            value={step.comments}
            onChange={(e) => updateStep(step.id, { comments: e.target.value })}
          />
        </div>
        <div className="grid gap-2 sm:grid-cols-2">
          <DateInput
            placeholder={
              lang === "ar" ? "تاريخ الإنجاز" : "Date of Achievement"
            }
            value={step.dateOfAchievement}
            onChange={(v) =>
              updateStep(step.id, { dateOfAchievement: v })
            }
          />
          <Input
            placeholder={lang === "ar" ? "التقييم" : "Evaluation"}
            value={step.evaluation}
            onChange={(e) =>
              updateStep(step.id, { evaluation: e.target.value })
            }
          />
        </div>
      </div>
    </div>
  )

  if (typeError) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-destructive">{typeError}</p>
      </div>
    )
  }

  if (isInitializing) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {editAssignmentId
              ? lang === "ar"
                ? "تعديل الخطة"
                : "Edit Plan"
              : lang === "ar"
                ? "إنشاء خطة"
                : "Create Plan"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "إنشاء خطة لحالة محددة"
              : "Create a plan for a specific case"}
          </p>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      {typeError && (
        <div className="rounded-lg border border-destructive bg-destructive/10 p-4 text-destructive">
          {typeError}
        </div>
      )}

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          {/* Case Selection */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختيار الحالة *" : "Case Selection *"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <CaseSearchCombobox
                readOnly={hasCaseContext}
                value={selectedCaseId}
                onChange={handleCaseSelect}
                placeholder={lang === "ar" ? "اختر حالة..." : "Select a case..."}
                disabled={!!editAssignmentId}
              />
            </CardContent>
          </Card>

          {/* Plan name */}
          <Card>
            <CardHeader>
              <CardTitle>{lang === "ar" ? "اسم الخطة *" : "Plan Name *"}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <Label htmlFor="plan-name">{lang === "ar" ? "اسم الخطة" : "Plan name"}</Label>
              <Input
                id="plan-name"
                dir="auto"
                value={toolName}
                onChange={(e) => setToolName(e.target.value)}
                placeholder={lang === "ar" ? "مثال: خطة تطوير مهارات التواصل" : "e.g., Communication skills plan"}
              />
            </CardContent>
          </Card>

          {/* Child & Expert Info - Single fields */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar"
                  ? "معلومات الطفل والخبير"
                  : "Child & Expert Information"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label htmlFor="plan-child-name">{lang === "ar" ? "اسم الطفل" : "Child Name"}</Label>
                  <Input
                    id="plan-child-name"
                    value={formData.childName || childName}
                    onChange={(e) =>
                      setFormData({ ...formData, childName: e.target.value })
                    }
                    placeholder={lang === "ar" ? "اسم الطفل" : "Child name"}
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الخبير" : "Expert Name"}</Label>
                  <Input
                    value={formData.expertName}
                    onChange={(e) =>
                      setFormData({ ...formData, expertName: e.target.value })
                    }
                    placeholder={lang === "ar" ? "اسم الخبير" : "Expert name"}
                  />
                </div>
              </div>
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "تاريخ البداية" : "Start Date"}</Label>
                  <DateInput
                    value={formData.startDate}
                    onChange={(v) =>
                      setFormData({ ...formData, startDate: v })
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "تاريخ النهاية" : "End Date"}</Label>
                  <DateInput
                    value={formData.endDate}
                    onChange={(v) =>
                      setFormData({ ...formData, endDate: v })
                    }
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Goals - Single fields */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الأهداف" : "Goals"}</CardTitle>
              <Button size="sm" onClick={addGoal}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة هدف" : "Add Goal"}
              </Button>
            </CardHeader>
            <CardContent>
              {goals.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar"
                    ? "لا توجد أهداف بعد. انقر على إضافة هدف لإنشاء واحد."
                    : "No goals yet. Click Add Goal to create one."}
                </p>
              ) : (
                <DragList
                  items={goals}
                  onReorder={handleGoalReorder}
                  renderItem={renderGoalItem}
                  keyExtractor={(g) => g.id}
                />
              )}
            </CardContent>
          </Card>

          {/* Steps - With all fields matching preview */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الخطوات" : "Steps"}</CardTitle>
              <Button size="sm" onClick={addStep}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة خطوة" : "Add Step"}
              </Button>
            </CardHeader>
            <CardContent>
              {steps.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar"
                    ? "لا توجد خطوات بعد. انقر على إضافة خطوة لإنشاء واحدة."
                    : "No steps yet. Click Add Step to create one."}
                </p>
              ) : (
                <DragList
                  items={steps}
                  onReorder={handleStepReorder}
                  renderItem={renderStepItem}
                  keyExtractor={(s) => s.id}
                />
              )}
            </CardContent>
          </Card>

          {saveError && <p role="alert" className="text-destructive">{saveError}</p>}
          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={handleCancel}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={
                isInitializing ||
                isSubmitting
              }
            >
              {isSubmitting
                ? editAssignmentId
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : editAssignmentId
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء خطة"
                    : "Create Plan"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <PlanPreview
              config={{
                childName,
                expertName: formData.expertName,
                startDate: formData.startDate,
                endDate: formData.endDate,
                goals: goals.map((g) => ({
                  id: g.id,
                  title: g.title,
                  description: g.description,
                  order: g.order,
                })),
                steps: steps.map((s) => ({
                  id: s.id,
                  title: s.title,
                  description: s.description,
                  notes: s.notes,
                  comments: s.comments,
                  dateOfAchievement: s.dateOfAchievement || undefined,
                  evaluation: s.evaluation,
                  completed: s.completed,
                })),
                media: [],
              }}
            />
          </div>
        )}
      </div>
    </div>
  )
}

"use client"
import { caseTaskPath } from "@/lib/case-task-path"

import { useState, useEffect, useRef, useCallback } from "react"
import { useRouter } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { toolTypesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import { ReportPreview } from "@/components/tool-renderers/ReportPreview"
import { Eye, EyeOff } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import type { ReportConfig } from "@/types/tool"

export default function ReportBuilderPage({
  searchParams,
}: {
  searchParams: Promise<{ caseId?: string; edit?: string }>
}) {
  const router = useRouter()
  const { lang } = useLang()
  const { assignTool, updateAssignment, assignments, isLoading: isAssignmentsLoading } = useAssignments()
  const { getProfileById } = useProfiles()
  const { currentUser } = useAuth()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [reportTypeId, setReportTypeId] = useState<string>("")
  const [typeError, setTypeError] = useState<string>("")
  const [editAssignmentId, setEditAssignmentId] = useState<string>("")

  const [selectedCaseId, setSelectedCaseId] = useState("")
  const [hasCaseContext, setHasCaseContext] = useState(false)
  const [isInitializing, setIsInitializing] = useState(true)
  const hasInitialized = useRef(false)

  // Child name - from case selection
  const [childName, setChildName] = useState("")

  // Report name - goes directly to name_en/name_ar
  const [reportName, setReportName] = useState({
    en: "",
    ar: "",
  })

  // Expert name - single field, auto-filled from auth
  const [expertName, setExpertName] = useState("")

  // Fixed fields - stored in config
  const [fixedFields, setFixedFields] = useState({
    date: "",
    assessment: "",
    suggestions: "",
  })

  // Fetch report type ID on mount
  useEffect(() => {
    let active = true
    const fetchReportType = async () => {
      try {
        const reportType = await toolTypesCollection.getByName("report")
        if (!active) return
        setReportTypeId(reportType.id)
        setTypeError("")
      } catch (error) {
        if (!active) return
        setTypeError(
          getErrorMessage(error) ||
            (lang === "ar"
              ? 'نوع الأداة "report" غير موجود. يرجى الاتصال بالمسؤول.'
              : 'Tool type "report" not found. Please contact admin.')
        )
        console.error("Failed to fetch report type:", error)
      }
    }
    void fetchReportType()
    return () => { active = false }
  }, [lang])

  // Auto-fill expert name when currentUser loads
  useEffect(() => {
    if (currentUser?.name) {
      setExpertName(currentUser.name)
    }
  }, [currentUser])

  const handleCaseSelect = useCallback((caseId: string) => {
    setSelectedCaseId(caseId)
    if (caseId) {
      const caseProfile = getProfileById(caseId)
      if (caseProfile) {
        // Auto-populate child name and report name
        setChildName(caseProfile.name)
        setReportName({
          en: `${caseProfile.name} - Report`,
          ar: `${caseProfile.name} - تقرير`,
        })
      }
    } else {
      // Reset name fields when case is cleared
      setChildName("")
      setReportName({ en: "", ar: "" })
    }
  }, [getProfileById])

  // Initialize from URL caseId - runs once after assignments load
  useEffect(() => {
    if (isAssignmentsLoading) return
    if (hasInitialized.current) return

    const initFromUrl = async () => {
      try {
        const params = await searchParams
        const editId = params?.edit
        const caseIdFromUrl = params?.caseId
        setHasCaseContext(Boolean(caseIdFromUrl || editId))

        // Edit mode - load existing assignment
        if (editId) {
          setEditAssignmentId(editId)
          const existingAssignment = assignments.find((a) => a.id === editId)
          if (existingAssignment) {
            const config = existingAssignment.config as ReportConfig
            setSelectedCaseId(existingAssignment.case)
            setReportName({
              en: existingAssignment.name_ar || existingAssignment.name_en || "",
              ar: existingAssignment.name_ar || "",
            })
            setChildName(config?.childName || "")
            setExpertName(config?.expertName || "")
            setFixedFields({
              date: config?.date || "",
              assessment: config?.assessment || "",
              suggestions: config?.suggestions || "",
            })
          }
        } else if (caseIdFromUrl) {
          handleCaseSelect(caseIdFromUrl)
        }
      } catch (e) {
        console.error("Failed to read searchParams:", e)
        toast.error(getErrorMessage(e))
      } finally {
        setIsInitializing(false)
        hasInitialized.current = true
      }
    }
    initFromUrl()
  }, [isAssignmentsLoading, assignments, searchParams, handleCaseSelect])

  const handleSubmit = async () => {
    if (!selectedCaseId || !reportName.en || !expertName || !reportTypeId)
      return
    setIsSubmitting(true)

    try {
      // Store fixed fields in config
      const config: ReportConfig = {
        title: { en: reportName.en, ar: reportName.en },
        childName: childName,
        expertName: expertName,
        customFields: [],
        media: [],
        date: fixedFields.date || undefined,
        assessment: fixedFields.assessment,
        suggestions: fixedFields.suggestions,
      }

      // Edit mode - update existing assignment
      if (editAssignmentId) {
        await updateAssignment(editAssignmentId, {
          name_en: reportName.en,
          name_ar: reportName.en,
          config,
        })
        router.push(caseTaskPath(selectedCaseId, editAssignmentId))
      } else {
        // Create case document directly in case_tools (no tool template)
        await assignTool({
          case: selectedCaseId,
          type: reportTypeId,
          name_en: reportName.en,
          name_ar: reportName.en,
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "completed",
        })

        // Redirect to assignments page
        router.push(caseTaskPath(selectedCaseId))
      }
    } catch (error) {
      console.error(editAssignmentId ? "Failed to update report:" : "Failed to create report:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    if (editAssignmentId) {
      router.push(caseTaskPath(selectedCaseId, editAssignmentId))
    } else {
      // Reset form
      setSelectedCaseId("")
      setReportName({ en: "", ar: "" })
      setExpertName(currentUser?.name || "")
      setChildName("")
      setFixedFields({
        date: "",
        assessment: "",
        suggestions: "",
      })
      setShowPreview(false)
    }
  }

  const isFormValid =
    selectedCaseId && reportName.en && expertName && reportTypeId

  if (typeError) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-destructive">{typeError}</p>
      </div>
    )
  }

  if (isInitializing) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {editAssignmentId
              ? lang === "ar"
                ? "تعديل التقرير"
                : "Edit Report"
              : lang === "ar"
                ? "إنشاء تقرير"
                : "Create Report"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "إنشاء تقرير لحالة محددة"
              : "Create a report for a specific case"}
          </p>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      {typeError && (
        <div className="rounded-lg border border-destructive bg-destructive/10 p-4 text-destructive">
          {typeError}
        </div>
      )}

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          {/* Case Selection */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختر حالة *" : "Select Case *"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <CaseSearchCombobox
                readOnly={hasCaseContext}
                value={selectedCaseId}
                onChange={handleCaseSelect}
                placeholder={lang === "ar" ? "اختر حالة..." : "Select a case..."}
                disabled={!!editAssignmentId}
              />
              {!selectedCaseId && (
                <p className="mt-2 text-sm text-destructive">
                  {lang === "ar"
                    ? "يرجى اختيار حالة للمتابعة"
                    : "Please select a case to continue"}
                </p>
              )}
            </CardContent>
          </Card>

          {/* Report Name (goes to name_en/name_ar) */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اسم التقرير *" : "Report Name *"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم التقرير" : "Report name"}</Label>
                  <Input
                    value={reportName.en}
                    onChange={(e) =>
                      setReportName({ en: e.target.value, ar: e.target.value })
                    }
                    placeholder={
                      lang === "ar" ? "عنوان التقرير" : "Report title"
                    }
                  />
                </div>

              </div>
            </CardContent>
          </Card>

          {/* Basic Info - Child Name from Case + Expert Name */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات أساسية" : "Basic Information"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الطفل" : "Child Name"}</Label>
                  <Input
                    value={childName}
                    onChange={(e) => setChildName(e.target.value)}
                    placeholder={lang === "ar" ? "اسم الطفل" : "Child name"}
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الخبير" : "Expert Name"}</Label>
                  <Input
                    value={expertName}
                    onChange={(e) => setExpertName(e.target.value)}
                    placeholder={lang === "ar" ? "اسم الخبير" : "Expert name"}
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Fixed Fields - Date, Assessment, Suggestions */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "تفاصيل التقرير" : "Report Details"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label>{lang === "ar" ? "التاريخ" : "Date"}</Label>
                <DateInput
                  value={fixedFields.date}
                  onChange={(v) =>
                    setFixedFields({ ...fixedFields, date: v })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>{lang === "ar" ? "التقييم" : "Assessment"}</Label>
                <Textarea
                  value={fixedFields.assessment}
                  onChange={(e) =>
                    setFixedFields({
                      ...fixedFields,
                      assessment: e.target.value,
                    })
                  }
                  placeholder={
                    lang === "ar" ? "أدخل التقييم..." : "Enter assessment..."
                  }
                  rows={4}
                />
              </div>
              <div className="space-y-2">
                <Label>{lang === "ar" ? "الاقتراحات" : "Suggestions"}</Label>
                <Textarea
                  value={fixedFields.suggestions}
                  onChange={(e) =>
                    setFixedFields({
                      ...fixedFields,
                      suggestions: e.target.value,
                    })
                  }
                  placeholder={
                    lang === "ar"
                      ? "أدخل الاقتراحات..."
                      : "Enter suggestions..."
                  }
                  rows={4}
                />
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={handleCancel}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={!isFormValid || isSubmitting}
            >
              {isSubmitting
                ? editAssignmentId
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : editAssignmentId
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء تقرير"
                    : "Create Report"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <ReportPreview
              config={{
                title: { en: reportName.en, ar: reportName.en },
                childName: childName,
                expertName: expertName,
                customFields: [],
                media: [],
                date: fixedFields.date,
                assessment: fixedFields.assessment,
                suggestions: fixedFields.suggestions,
              }}
            />
          </div>
        )}
      </div>
    </div>
  )
}

"use client"
import { useAuth } from "@/hooks/useAuth"
import { caseTaskPath } from "@/lib/case-task-path"
import { CaseName } from "@/components/cases/CaseName"
import { DataError } from "@/components/ui/data-error"
import { useUiTranslation } from "@/hooks/useUiTranslation"

import { use, useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useTools } from "@/hooks/useTools"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useLang } from "@/lib/lang-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { DragList } from "@/components/ui/drag-list"
import { SurveyPreview } from "@/components/tool-renderers/SurveyPreview"
import {
  ArrowLeft,
  Plus,
  Trash2,
  Eye,
  EyeOff,
  GripVertical,
} from "lucide-react"
import type {
  SurveyConfig,
  SurveyQuestion,
  SurveyOption,
  SurveyAnswerType,
} from "@/types/tool"
import { useToolTypes } from "@/hooks/useToolTypes"

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

const ANSWER_TYPES: {
  value: SurveyAnswerType
  label: { en: string; ar: string }
}[] = [
  {
    value: "single_choice",
    label: { en: "Single Choice (Radio)", ar: "اختيار واحد (أزرار اختيار)" },
  },
  {
    value: "multiple_choice",
    label: { en: "Multiple Choice (Checkbox)", ar: "اختيار من متعدد (خانات)" },
  },
]

interface SurveyBuilderPageProps {
  params?: Promise<{ id?: string }>
  searchParams?: Promise<{ caseId?: string }>
}

export default function SurveyBuilderPage({
  params,
  searchParams,
}: SurveyBuilderPageProps = {}) {
  const ui = useUiTranslation()

  const router = useRouter()
  const { lang } = useLang()
  const {
    addTool,
    updateTool,
    getToolById,
    isLoading: isToolsLoading,
    loadError: toolsLoadError,
    refresh: retryTools,
  } = useTools()
  const { assignTool } = useAssignments()
  const { getProfileById } = useProfiles()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const hasInitialized = useRef(false)
  const resolvedParams = params ? use(params) : undefined
  const resolvedSearchParams = searchParams ? use(searchParams) : undefined
  const editId = resolvedParams?.id
  const caseId = resolvedSearchParams?.caseId
  const isEditMode = !!editId

  const { currentUser } = useAuth()
  const isExpert = currentUser?.role === "expert"
  const [templateSelected, setIsTemplate] = useState(true)
  const isTemplate = isExpert ? false : templateSelected

  const selectedCase = caseId ? getProfileById(caseId) : null

  const [formData, setFormData] = useState({
    nameEn: "",
    nameAr: "",
    answerType: "single_choice" as SurveyAnswerType,
  })

  const [options, setOptions] = useState<SurveyOption[]>([
    {
      id: generateId(),
      value: "very_satisfied",
      label: "Very Satisfied",
      labelAr: "راضٍ جدًا",
      order: 0,
    },
    {
      id: generateId(),
      value: "satisfied",
      label: "Satisfied",
      labelAr: "راضٍ",
      order: 1,
    },
    {
      id: generateId(),
      value: "neutral",
      label: "Neutral",
      labelAr: "محايد",
      order: 2,
    },
    {
      id: generateId(),
      value: "unsatisfied",
      label: "Unsatisfied",
      labelAr: "غير راضٍ",
      order: 3,
    },
    {
      id: generateId(),
      value: "very_unsatisfied",
      label: "Very Unsatisfied",
      labelAr: "غير راضٍ جدًا",
      order: 4,
    },
  ])

  const [questions, setQuestions] = useState<SurveyQuestion[]>([])

  useEffect(() => {
    if (!isEditMode || !editId || isToolsLoading) return
    if (hasInitialized.current) return

    // Initialize the editable draft once the asynchronous tool data is available.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsLoading(true)
    const tool = getToolById(editId)
    if (tool && tool.config) {
      const config = tool.config as SurveyConfig
      setFormData({
        nameEn: tool.name.ar || tool.name.en,
        nameAr: tool.name.ar || tool.name.en,
        answerType: config.answerType || "single_choice",
      })
      setOptions(config.options || [])
      setQuestions(config.questions || [])
    }
    setIsLoading(false)
    hasInitialized.current = true
  }, [isEditMode, editId, isToolsLoading, getToolById])

  const addOption = () => {
    const newOption: SurveyOption = {
      id: generateId(),
      value: `option_${options.length + 1}`,
      label: `Option ${options.length + 1}`,
      labelAr: `خيار ${options.length + 1}`,
      order: options.length,
    }
    setOptions([...options, newOption])
  }

  const updateOption = (
    id: string,
    field: "label" | "labelAr",
    value: string
  ) => {
    setOptions(options.map((o) => (o.id === id ? { ...o, [field]: value } : o)))
  }

  const removeOption = (id: string) => {
    if (options.length <= 2) return
    setOptions(options.filter((o) => o.id !== id))
  }

  const addQuestion = () => {
    const newQuestion: SurveyQuestion = {
      id: generateId(),
      text: "",
      required: false,
      order: questions.length,
    }
    setQuestions([...questions, newQuestion])
  }

  const updateQuestion = (id: string, updates: Partial<SurveyQuestion>) => {
    setQuestions(questions.map((q) => (q.id === id ? { ...q, ...updates } : q)))
  }

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter((q) => q.id !== id))
  }

  const handleReorder = (reordered: SurveyQuestion[]) => {
    setQuestions(reordered)
  }

  const handleSubmit = async () => {
    if (!formData.nameEn || options.length < 2 || questions.length === 0) return
    setIsSubmitting(true)

    const config: SurveyConfig = {
      title: { en: formData.nameEn, ar: formData.nameEn },
      answerType: formData.answerType,
      options: options.map((o, idx) => ({ ...o, order: idx })),
      questions: questions.map((q, idx) => ({ ...q, order: idx })),
      media: [],
    }

    if (isEditMode && editId) {
      await updateTool(editId, {
        name: { en: formData.nameEn, ar: formData.nameEn },
        config,
      })
      router.push(`/dashboard/admin/tools/survey/${editId}`)
    } else {
      const toolTypes = await fetchToolTypes()
      const type = toolTypes.find((t) => t.key === "survey")?.id
      if (!type) {
        setIsSubmitting(false)
        return
      }

      if (!isTemplate && caseId) {
        await assignTool({
          case: caseId,
          type: type,
          name_en: formData.nameEn,
          name_ar: formData.nameEn,
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "pending",
        })
        router.push(caseTaskPath(caseId))
      } else {
        await addTool({
          name: { en: formData.nameEn, ar: formData.nameEn },
          type: type,
          serviceType: "individual",
          status: "active",
          config,
        })
        router.push(`/dashboard/admin/tools`)
      }
    }
  }

  const renderQuestionItem = (question: SurveyQuestion, index: number) => {
    return (
      <div className="flex items-start gap-3">
        <div className="mt-3 cursor-grab">
          <GripVertical className="h-4 w-4 text-muted-foreground" />
        </div>
        <div className="flex-1 space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">
              {lang === "ar" ? "سؤال" : "Question"} {index + 1}
            </span>
            <div className="flex items-center gap-2">
              <Checkbox
                id={`req-${question.id}`}
                checked={question.required}
                onCheckedChange={(checked) =>
                  updateQuestion(question.id, { required: !!checked })
                }
              />
              <Label htmlFor={`req-${question.id}`} className="text-xs">
                {lang === "ar" ? "إجباري" : "Required"}
              </Label>
              <Button
                variant="ghost"
                size="icon-xs"
                onClick={() => removeQuestion(question.id)}
              >
                <Trash2 className="h-4 w-4 text-destructive" />
              </Button>
            </div>
          </div>
          <Input
            placeholder={
              lang === "ar" ? "أدخل نص السؤال" : "Enter question text"
            }
            value={question.text}
            onChange={(e) =>
              updateQuestion(question.id, {
                text: e.target.value,
              })
            }
          />
        </div>
      </div>
    )
  }

  const renderOptionItem = (option: SurveyOption, index: number) => {
    return (
      <div key={option.id} className="flex items-center gap-2">
        <div className="grid flex-1 gap-2 sm:grid-cols-2">
          <div className="space-y-1">
            <Label htmlFor={`option-${option.id}-en`}>
              {ui("Option (EN)")}
            </Label>
            <Input
              id={`option-${option.id}-en`}
              dir="ltr"
              placeholder={ui("English option")}
              value={option.label}
              onChange={(e) => updateOption(option.id, "label", e.target.value)}
            />
          </div>
          <div className="space-y-1">
            <Label htmlFor={`option-${option.id}-ar`}>الخيار (AR)</Label>
            <Input
              id={`option-${option.id}-ar`}
              dir="rtl"
              placeholder="نص الخيار بالعربية"
              value={option.labelAr || ""}
              onChange={(e) =>
                updateOption(option.id, "labelAr", e.target.value)
              }
            />
          </div>
        </div>
        <Button
          variant="ghost"
          size="icon-xs"
          onClick={() => removeOption(option.id)}
          disabled={options.length <= 2}
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      </div>
    )
  }

  if (toolsLoadError)
    return <DataError message={toolsLoadError} onRetry={retryTools} />

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {isEditMode
                ? lang === "ar"
                  ? "تعديل الاستبيان"
                  : "Edit Survey"
                : lang === "ar"
                  ? "إنشاء استبيان"
                  : "Create Survey"}
            </h1>
            <p className="text-muted-foreground">
              {isEditMode
                ? lang === "ar"
                  ? "تحديث أسئلة وخيارات الاستبيان"
                  : "Update survey questions and options"
                : lang === "ar"
                  ? "أنشئ استبياناً بخيارات مشتركة لجميع الأسئلة"
                  : "Build a survey with shared options for all questions"}
            </p>
          </div>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات أساسية" : "Basic Info"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="dsc-form-grid">
                <div className="space-y-2">
                  <Label>
                    {lang === "ar"
                      ? "اسم الاستبيان"
                      : "Survey Name"}
                  </Label>
                  <Input
                    value={formData.nameEn || formData.nameAr}
                    onChange={(e) =>
                      setFormData({ ...formData, nameEn: e.target.value, nameAr: e.target.value })
                    }
                    placeholder={
                      lang === "ar" ? "عنوان الاستبيان" : "Survey title"
                    }
                  />
                </div>

              </div>
            </CardContent>
          </Card>

          {caseId && selectedCase && (
            <Card>
              <CardHeader>
                <CardTitle>
                  {lang === "ar" ? "معلومات الحالة" : "Case Information"}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-2 text-sm">
                  <span className="font-medium">
                    {lang === "ar" ? "الحالة:" : "Case:"}
                  </span>
                  <span><CaseName profile={selectedCase} /></span>
                </div>
              </CardContent>
            </Card>
          )}

          {!isExpert && (caseId || !isEditMode) && (
            <Card>
              <CardContent className="pt-6">
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="isTemplate"
                    checked={isTemplate}
                    onCheckedChange={(checked) =>
                      setIsTemplate(checked === true)
                    }
                  />
                  <label
                    htmlFor="isTemplate"
                    className="text-sm leading-none font-medium peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                  >
                    {lang === "ar"
                      ? "حفظ كقالب (متاح للاستخدام المستقبلي)"
                      : "Save as template (available for future use)"}
                  </label>
                </div>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "نوع الإجابة" : "Answer Type"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <Select
                value={formData.answerType}
                onValueChange={(v) =>
                  setFormData({
                    ...formData,
                    answerType: v as SurveyAnswerType,
                  })
                }
              >
                <SelectTrigger className="w-64">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ANSWER_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {type.label[lang]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>
                {lang === "ar"
                  ? "الخيارات (مشتركة لجميع الأسئلة)"
                  : "Options (Shared for all questions)"}
              </CardTitle>
              <Button size="sm" onClick={addOption}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة خيار" : "Add Option"}
              </Button>
            </CardHeader>
            <CardContent>
              <p className="mb-4 text-sm text-muted-foreground">
                {lang === "ar"
                  ? "مطلوب 2 خيارات كحد أدنى. ستستخدم جميع الأسئلة هذه الخيارات."
                  : "Minimum 2 options required. All questions will use these options."}
              </p>
              <div className="space-y-2">
                {options.map((opt, idx) => renderOptionItem(opt, idx))}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الأسئلة" : "Questions"}</CardTitle>
              <Button size="sm" onClick={addQuestion}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة سؤال" : "Add Question"}
              </Button>
            </CardHeader>
            <CardContent>
              {questions.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar"
                    ? "لا توجد أسئلة بعد. أضف واحداً للبدء."
                    : "No questions yet. Add one to start."}
                </p>
              ) : (
                <DragList
                  items={questions}
                  onReorder={handleReorder}
                  renderItem={renderQuestionItem}
                  keyExtractor={(q) => q.id}
                />
              )}
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={() => router.back()}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={
                !formData.nameEn ||
                options.length < 2 ||
                questions.length === 0 ||
                isSubmitting
              }
            >
              {isSubmitting
                ? isEditMode
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : isEditMode
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء استبيان"
                    : "Create Survey"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <SurveyPreview
              config={{
                title: { en: formData.nameEn, ar: formData.nameEn },
                answerType: formData.answerType,
                options: options,
                questions: questions,
                media: [],
              }}
            />
          </div>
        )}
      </div>
    </div>
  )
}

"use client"
import { useRequestGuard } from "@/hooks/useRequestGuard"
import { useUiTranslation } from "@/hooks/useUiTranslation"
import { openProtectedFile } from "@/components/ProtectedFileLink"

import { use, useState, useEffect, useCallback } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import Image from "next/image"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Separator } from "@/components/ui/separator"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useTraining } from "@/hooks/useTraining"
import { ProgramForm, ProgramReportCard } from "@/components/training"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import { casesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import type { Profile } from "@/types/profile"
import {
  ArrowLeft,
  Calendar,
  Clock,
  MapPin,
  Users,
  Edit,
  Trash2,
  CheckCircle,
  XCircle,
  ExternalLink,
  User,
  BookOpen,
  Award,
  Plus,
  Download,
} from "lucide-react"
import type { ProgramStatus } from "@/types/training"

type EnrollmentStatus = "enrolled" | "attended" | "absent"

const statusLabels: Record<ProgramStatus, { en: string; ar: string }> = {
  draft: { en: "Draft", ar: "مسودة" },
  published: { en: "Published", ar: "منشور" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
  cancelled: { en: "Cancelled", ar: "ملغي" },
}

const statusColors: Record<ProgramStatus, string> = {
  draft: "bg-gray-100 text-gray-800",
  published: "bg-green-100 text-green-800",
  in_progress: "bg-blue-100 text-blue-800",
  completed: "bg-blue-100 text-blue-800",
  cancelled: "bg-red-100 text-red-800",
}

const typeLabels = {
  online: { en: "Online", ar: "عبر الشبكة" },
  in_person: { en: "In-Person", ar: "حضوري" },
  hybrid: { en: "Hybrid", ar: "حضوري وعبر الشبكة" },
}

const registrationLabels: Record<
  EnrollmentStatus,
  { en: string; ar: string }
> = {
  enrolled: { en: "Enrolled", ar: "مسجل" },
  attended: { en: "Attended", ar: "حضر" },
  absent: { en: "Absent", ar: "غائب" },
}

const registrationVariants: Record<EnrollmentStatus, "default" | "secondary" | "destructive" | "outline"> = {
  enrolled: "secondary",
  attended: "default",
  absent: "destructive",
}

const enrollmentStatusToCaseStatus = (status: EnrollmentStatus) => status

const caseStatusToEnrollmentStatus = (
  status?: string
): EnrollmentStatus => {
  if (status === "enrolled" || status === "attended" || status === "absent") {
    return status
  }
  return "enrolled"
}

export default function AdminTrainingProgramDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const ui = useUiTranslation()

  const { id } = use(params)
  const router = useRouter()
  const searchParams = useSearchParams()
  const { lang } = useLang()
  const {
    getProgramById,
    updateProgram,
    deleteProgram,
    getProgramStats,
    certificates,
    addCertificate,
    deleteCertificate,
    isLoading,
  } = useTraining()

  const beginEnrollmentRequest = useRequestGuard("training-enrollments:" + id)
  const [enrollments, setEnrollments] = useState<Profile[]>([])
  const [enrollmentsLoading, setEnrollmentsLoading] = useState(true)

  const [activeTab, setActiveTab] = useState("overview")
  const [isEditing, setIsEditing] = useState(
    searchParams.get("edit") === "true"
  )
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [certDialogOpen, setCertDialogOpen] = useState(false)
  const [certRegistrationId, setCertRegistrationId] = useState<string>("")
  const [certForm, setCertForm] = useState({
    certificateNumber: "",
    issueDate: new Date().toISOString().split("T")[0],
    notes: "",
  })
  const [certFile, setCertFile] = useState<File | undefined>()
  const [isCertSubmitting, setIsCertSubmitting] = useState(false)

  const program = getProgramById(id)
  const stats = program ? getProgramStats(program.id) : null
  const programCertificates = program
    ? certificates.filter((c) => c.programId === program.id)
    : []

  const fetchEnrollments = useCallback(async () => {
    const isCurrent = beginEnrollmentRequest()
    setEnrollmentsLoading(true)
    setEnrollments([])
    try {
      const data = await casesCollection.getByProgramAndPortalType(
        id,
        "Attending Training"
      )
      if (isCurrent()) setEnrollments(data)
    } catch (err) {
      if (!isCurrent()) return
      console.error("Failed to load enrollments:", err)
      toast.error(getErrorMessage(err))
      setEnrollments([])
    } finally {
      if (isCurrent()) setEnrollmentsLoading(false)
    }
  }, [id, beginEnrollmentRequest])

  useEffect(() => {
    void fetchEnrollments()
  }, [fetchEnrollments])

  const eligibleRegistrations = enrollments.filter((e) => {
    const status = caseStatusToEnrollmentStatus(e.program_status)
    return status === "attended"
  })

  const registrationsWithoutCert = eligibleRegistrations.filter(
    (e) => !programCertificates.some((c) => c.userId === e.user)
  )

  const resetCertForm = () => {
    setCertRegistrationId("")
    setCertForm({
      certificateNumber: "",
      issueDate: new Date().toISOString().split("T")[0],
      notes: "",
    })
    setCertFile(undefined)
  }

  const handleIssueCertificate = async () => {
    if (!program || !certRegistrationId || !certForm.certificateNumber) return

    const enrollee = enrollments.find((e) => e.id === certRegistrationId)
    if (!enrollee) return

    setIsCertSubmitting(true)
    try {
      await addCertificate(
        {
          userId: enrollee.user,
          userName: enrollee.name,
          programId: program.id,
          programName: program.title,
          issueDate: certForm.issueDate,
          certificateNumber: certForm.certificateNumber,
          notes: certForm.notes || undefined,
        },
        certFile
      )
      await casesCollection.update(enrollee.id, {
        program_status: "attended",
      })
      await fetchEnrollments()
      setCertDialogOpen(false)
      resetCertForm()
    } catch (error) {
      console.error("Failed to issue certificate:", error)
      toast.error(
        lang === "ar" ? "فشل إصدار الشهادة" : "Failed to issue certificate",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsCertSubmitting(false)
    }
  }

  const handleDeleteCertificate = async (id: string) => {
    if (
      window.confirm(
        lang === "ar" ? "هل أنت متأكد من حذف هذه الشهادة؟" : "Are you sure?"
      )
    ) {
      await deleteCertificate(id)
    }
  }

  useEffect(() => {
    if (!isLoading && !program) {
      router.push("/dashboard/admin/training")
    }
  }, [isLoading, program, router])

  if (isLoading || !program) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  const handleUpdate = async (
    data: Parameters<typeof updateProgram>[1]
  ) => {
    setIsSubmitting(true)
    try {
      await updateProgram(id, data)
      setIsEditing(false)
    } catch (error) {
      console.error("Failed to update program:", error)
      toast.error(
        lang === "ar" ? "فشل تحديث البرنامج" : "Failed to update program",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleDelete = async () => {
    if (
      window.confirm(
        lang === "ar"
          ? "هل أنت متأكد من حذف هذا البرنامج؟"
          : "Are you sure you want to delete this program?"
      )
    ) {
      await deleteProgram(id)
      router.push("/dashboard/admin/training")
    }
  }

  const handleStatusChange = async (
    enrollmentId: string,
    newStatus: EnrollmentStatus
  ) => {
    try {
      await casesCollection.update(enrollmentId, {
        program_status: enrollmentStatusToCaseStatus(newStatus),
      })
      await fetchEnrollments()
    } catch (error) {
      console.error("Failed to update enrollment status:", error)
      toast.error(getErrorMessage(error))
    }
  }

  const registrations = enrollments.map((e) => {
    return {
      id: e.id,
      userId: e.user,
      userName: e.user_details?.name ?? "",
      email: e.user_details?.email ?? "",
      contact: e.user_details?.contact ?? "",
      registeredAt: e.created,
      status: caseStatusToEnrollmentStatus(e.program_status),
    }
  })

  const activeRegistrations = registrations.filter(
    (r) => r.status === "enrolled" || r.status === "attended"
  )
  const attendedCount = registrations.filter(
    (r) => r.status === "attended"
  ).length
  const registrationsTotal = registrations.length

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.push("/dashboard/admin/training")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-primary">
                {program.title[lang]}
              </h1>
              <Badge className={statusColors[program.status]}>
                {statusLabels[program.status][lang]}
              </Badge>
            </div>
            <p className="text-muted-foreground">
              {program.trainer.name[lang]}
            </p>
          </div>
        </div>
        {!isEditing && (
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setIsEditing(true)}>
              <Edit className="me-2 h-4 w-4" />
              {lang === "ar" ? "تعديل" : "Edit"}
            </Button>
            <Button variant="destructive" onClick={handleDelete}>
              <Trash2 className="me-2 h-4 w-4" />
              {lang === "ar" ? "حذف" : "Delete"}
            </Button>
          </div>
        )}
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="registrations">
            {lang === "ar" ? "التسجيلات" : "Registrations"}
          </TabsTrigger>
          <TabsTrigger value="attendance">
            {lang === "ar" ? "الحضور" : "Attendance"}
          </TabsTrigger>
          <TabsTrigger value="certificates">
            {lang === "ar" ? "الشهادات" : "Certificates"}
            {programCertificates.length > 0 && (
              <Badge variant="secondary" className="ms-2">
                {programCertificates.length}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="report">
            {lang === "ar" ? "التقرير" : "Report"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-6">
          {isEditing ? (
            <ProgramForm
              initialData={program}
              onSubmit={handleUpdate}
              onCancel={() => setIsEditing(false)}
              isSubmitting={isSubmitting}
              submitLabel={lang === "ar" ? "حفظ التغييرات" : "Save Changes"}
            />
          ) : (
            <>
              {program.thumbnail && (
                <div className="relative h-64 w-full overflow-hidden rounded-lg bg-muted md:h-80">
                  <Image
                    src={program.thumbnail}
                    alt={program.title[lang]}
                    fill
                    className="object-cover"
                    priority
                  />
                </div>
              )}

              <div className="grid gap-6 md:grid-cols-2">
                <Card>
                  <CardHeader>
                    <CardTitle>
                      {lang === "ar" ? "معلومات البرنامج" : "Program Details"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="flex items-center gap-2">
                      <Calendar className="h-4 w-4 text-muted-foreground" />
                      <span>
                        {formatDate(program.schedule.startDate)} -{" "}
                        {formatDate(program.schedule.endDate)}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Clock className="h-4 w-4 text-muted-foreground" />
                      <span>
                        {program.duration}{" "}
                        {lang === "ar" ? "أيام" : "days"}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <MapPin className="h-4 w-4 text-muted-foreground" />
                      <span>
                        {program.location} ({typeLabels[program.type][lang]})
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <BookOpen className="h-4 w-4 text-muted-foreground" />
                      <span>{program.category[lang]}</span>
                    </div>
                    {program.maxParticipants && (
                    <div className="flex items-center gap-2">
                      <Users className="h-4 w-4 text-muted-foreground" />
                      <span>
                        {registrationsTotal} / {program.maxParticipants}{" "}
                        {lang === "ar" ? "مسجلين" : "enrolled"}
                      </span>
                    </div>
                    )}
                    {program.coordinator && (
                      <div className="flex items-center gap-2">
                        <User className="h-4 w-4 text-muted-foreground" />
                        <span>
                          {lang === "ar" ? "المنسق:" : "Coordinator:"}{" "}
                          {program.coordinator}
                        </span>
                      </div>
                    )}
                    {program.meetingLink && (
                      <div className="flex items-center gap-2">
                        <ExternalLink className="h-4 w-4 text-muted-foreground" />
                        <a
                          href={program.meetingLink}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-primary hover:underline"
                        >
                          {lang === "ar" ? "رابط الاجتماع" : "Meeting Link"}
                        </a>
                      </div>
                    )}
                    {program.recordingUrl && (
                      <div className="flex items-center gap-2">
                        <ExternalLink className="h-4 w-4 text-muted-foreground" />
                        <a
                          href={program.recordingUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-primary hover:underline"
                        >
                          {lang === "ar" ? "رابط التسجيل" : "Recording Link"}
                        </a>
                      </div>
                    )}
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle>
                      {lang === "ar" ? "المدرب" : "Trainer"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div>
                      <p className="font-medium">
                        {program.trainer.name[lang]}
                      </p>
                      {program.trainer.role[lang] && (
                        <p className="text-muted-foreground">
                          {program.trainer.role[lang]}
                        </p>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </div>

              {program.schedule.sessions.length > 0 && (
                <Card>
                  <CardHeader>
                    <CardTitle>
                      {lang === "ar" ? "الجلسات" : "Sessions"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3">
                      {program.schedule.sessions.map((session, index) => (
                        <div
                          key={index}
                          className="flex items-start gap-4 rounded-md border p-3"
                        >
                          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10">
                            <span className="text-sm font-semibold">
                              {index + 1}
                            </span>
                          </div>
                          <div className="flex-1 space-y-1">
                            <div className="flex items-center gap-2">
                              <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                              <span className="text-sm font-medium">
                                {formatDate(session.date)}
                              </span>
                            </div>
                            <div className="flex items-center gap-2">
                              <Clock className="h-3.5 w-3.5 text-muted-foreground" />
                              <span className="text-sm text-muted-foreground">
                                {session.timeFrom} - {session.timeTo}
                              </span>
                            </div>
                            {session.location && (
                              <div className="flex items-center gap-2">
                                <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
                                <span className="text-sm text-muted-foreground">
                                  {session.location}
                                </span>
                              </div>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}

              {program.goals && (program.goals.en || program.goals.ar) && (
                <Card>
                  <CardHeader>
                    <CardTitle>
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid gap-4 md:grid-cols-2">
                      {program.goals.en && (
                        <div>
                          <h4 className="mb-2 font-medium">{ui("English")}</h4>
                          <p className="text-muted-foreground">
                            {program.goals.en}
                          </p>
                        </div>
                      )}
                      {program.goals.ar && (
                        <div className="text-right" dir="rtl">
                          <h4 className="mb-2 font-medium">العربية</h4>
                          <p className="text-muted-foreground">
                            {program.goals.ar}
                          </p>
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              )}

              {program.notes && (
                <Card>
                  <CardHeader>
                    <CardTitle>
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-muted-foreground">{program.notes}</p>
                  </CardContent>
                </Card>
              )}
            </>
          )}
        </TabsContent>

        <TabsContent value="registrations">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "المسجلون" : "Enrollments"} (
                {registrationsTotal})
              </CardTitle>
              <p className="text-sm text-muted-foreground">
                {lang === "ar"
                  ? "تستند هذه القائمة إلى سجلات الحالات المرتبطة بهذا البرنامج."
                  : "This list is based on case records linked to this program."}
              </p>
            </CardHeader>
            <CardContent>
              {enrollmentsLoading ? (
                <div className="py-8 text-center text-muted-foreground">
                  {lang === "ar" ? "جاري التحميل..." : "Loading..."}
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{lang === "ar" ? "الاسم" : "Name"}</TableHead>
                      <TableHead>
                        {lang === "ar" ? "البريد الإلكتروني" : "Email"}
                      </TableHead>
                      <TableHead>
                        {lang === "ar" ? "الاتصال" : "Contact"}
                      </TableHead>
                      <TableHead>{lang === "ar" ? "الحالة" : "Status"}</TableHead>
                      <TableHead className="text-right">
                        {lang === "ar" ? "الإجراءات" : "Actions"}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {registrations.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={5} className="py-8 text-center">
                          {lang === "ar"
                            ? "لا توجد تسجيلات بعد"
                            : "No enrollments yet"}
                        </TableCell>
                      </TableRow>
                    ) : (
                      registrations.map((reg) => (
                        <TableRow key={reg.id}>
                          <TableCell>{reg.userName}</TableCell>
                          <TableCell>{reg.email || "—"}</TableCell>
                          <TableCell>{reg.contact || "—"}</TableCell>
                          <TableCell>
                            <Badge variant={registrationVariants[reg.status]}>
                              {registrationLabels[reg.status][lang]}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex justify-end gap-1">
                              {reg.status !== "attended" && (
                                <Button
                                  variant="ghost"
                                  size="icon-xs"
                                  onClick={() =>
                                    handleStatusChange(reg.id, "attended")
                                  }
                                  title={
                                    lang === "ar"
                                      ? "تحديد كحاضر"
                                      : "Mark attended"
                                  }
                                >
                                  <CheckCircle className="h-4 w-4 text-green-600" />
                                </Button>
                              )}
                              {reg.status !== "absent" && (
                                <Button
                                  variant="ghost"
                                  size="icon-xs"
                                  onClick={() =>
                                    handleStatusChange(reg.id, "absent")
                                  }
                                  title={
                                    lang === "ar"
                                      ? "تحديد كغائب"
                                      : "Mark absent"
                                  }
                                >
                                  <XCircle className="h-4 w-4 text-destructive" />
                                </Button>
                              )}
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="attendance">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "إدارة الحضور" : "Attendance Management"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="mb-4 text-sm text-muted-foreground">
                {lang === "ar"
                  ? "استخدم علامة الصح بجانب التسجيل لتحديد الحضور، أو العلامة الحمراء للغياب."
                  : "Use the checkmark next to an enrollment to mark attendance, or the cross for absent."}
              </p>
              {activeRegistrations.length === 0 ? (
                <div className="py-12 text-center">
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "لا توجد تسجيلات نشطة"
                      : "No active enrollments"}
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="grid gap-4 sm:grid-cols-3">
                    <Card>
                      <CardHeader className="pb-2">
                        <CardTitle className="text-sm font-medium">
                          {lang === "ar" ? "إجمالي النشطين" : "Total Active"}
                        </CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="text-2xl font-bold">
                          {activeRegistrations.length}
                        </div>
                      </CardContent>
                    </Card>
                    <Card>
                      <CardHeader className="pb-2">
                        <CardTitle className="text-sm font-medium">
                          {lang === "ar" ? "حضر" : "Attended"}
                        </CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="text-2xl font-bold text-green-600">
                          {attendedCount}
                        </div>
                      </CardContent>
                    </Card>
                    <Card>
                      <CardHeader className="pb-2">
                        <CardTitle className="text-sm font-medium">
                          {lang === "ar" ? "نسبة الحضور" : "Attendance Rate"}
                        </CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="text-2xl font-bold">
                          {activeRegistrations.length > 0
                            ? Math.round(
                                (attendedCount / activeRegistrations.length) * 100
                              )
                            : 0}
                          %
                        </div>
                      </CardContent>
                    </Card>
                  </div>

                  <Separator />

                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>
                          {lang === "ar" ? "الاسم" : "Name"}
                        </TableHead>
                        <TableHead>
                          {lang === "ar" ? "البريد الإلكتروني" : "Email"}
                        </TableHead>
                        <TableHead>
                          {lang === "ar" ? "الحضور" : "Attendance"}
                        </TableHead>
                        <TableHead className="text-right">
                          {lang === "ar" ? "الإجراء" : "Action"}
                        </TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {activeRegistrations.map((reg) => {
                        const isAttended = reg.status === "attended"
                        return (
                          <TableRow key={reg.id}>
                            <TableCell>{reg.userName}</TableCell>
                            <TableCell>{reg.email || "—"}</TableCell>
                            <TableCell>
                              {isAttended ? (
                                <span className="inline-flex items-center gap-1 text-sm text-green-600">
                                  <CheckCircle className="h-4 w-4" />
                                  {lang === "ar" ? "حاضر" : "Present"}
                                </span>
                              ) : reg.status === "absent" ? (
                                <span className="inline-flex items-center gap-1 text-sm text-red-600">
                                  <XCircle className="h-4 w-4" />
                                  {lang === "ar" ? "غائب" : "Absent"}
                                </span>
                              ) : (
                                <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
                                  {lang === "ar" ? "مسجل" : "Enrolled"}
                                </span>
                              )}
                            </TableCell>
                            <TableCell className="text-right">
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() =>
                                  handleStatusChange(
                                    reg.id,
                                    isAttended ? "enrolled" : "attended"
                                  )
                                }
                              >
                                {isAttended
                                  ? lang === "ar"
                                    ? "إلغاء الحضور"
                                    : "Mark Absent"
                                  : lang === "ar"
                                    ? "تسجيل الحضور"
                                    : "Mark Present"}
                              </Button>
                            </TableCell>
                          </TableRow>
                        )
                      })}
                    </TableBody>
                  </Table>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="certificates">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>
                  {lang === "ar" ? "الشهادات" : "Certificates"} (
                  {programCertificates.length})
                </CardTitle>
                <p className="text-sm text-muted-foreground">
                  {lang === "ar"
                    ? "إصدار وإدارة شهادات البرنامج"
                    : "Issue and manage certificates for this program"}
                </p>
              </div>
              <Dialog
                open={certDialogOpen}
                onOpenChange={(open) => {
                  setCertDialogOpen(open)
                  if (!open) resetCertForm()
                }}
              >
                <DialogTrigger asChild>
                  <Button disabled={registrationsWithoutCert.length === 0}>
                    <Plus className="me-2 h-4 w-4" />
                    {lang === "ar" ? "إصدار شهادة" : "Issue Certificate"}
                  </Button>
                </DialogTrigger>
                <DialogContent className="max-w-xl">
                  <DialogHeader>
                    <DialogTitle>
                      {lang === "ar" ? "إصدار شهادة جديدة" : "Issue New Certificate"}
                    </DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="cert-participant">
                        {lang === "ar" ? "المشارك *" : "Participant *"}
                      </Label>
                      <Select
                        value={certRegistrationId}
                        onValueChange={setCertRegistrationId}
                      >
                        <SelectTrigger id="cert-participant">
                          <SelectValue
                            placeholder={
                              lang === "ar"
                                ? "اختر مشاركاً..."
                                : "Select a participant..."
                            }
                          />
                        </SelectTrigger>
                        <SelectContent>
                          {registrationsWithoutCert.length === 0 ? (
                            <SelectItem value="__none__" disabled>
                              {lang === "ar"
                                ? "لا يوجد مشاركون مؤهلون"
                                : "No eligible participants"}
                            </SelectItem>
                          ) : (
                            registrationsWithoutCert.map((reg) => (
                              <SelectItem key={reg.id} value={reg.id}>
                                {reg.name}
                              </SelectItem>
                            ))
                          )}
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="cert-program-name">
                        {lang === "ar" ? "البرنامج" : "Program"}
                      </Label>
                      <Input
                        id="cert-program-name"
                        value={program.title[lang]}
                        disabled
                      />
                    </div>

                    <div className="grid gap-4 md:grid-cols-2">
                      <div className="space-y-2">
                        <Label htmlFor="cert-number">
                          {lang === "ar" ? "رقم الشهادة *" : "Certificate Number *"}
                        </Label>
                        <Input
                          id="cert-number"
                          value={certForm.certificateNumber}
                          onChange={(e) =>
                            setCertForm({
                              ...certForm,
                              certificateNumber: e.target.value,
                            })
                          }
                          placeholder={lang === "ar" ? "مثال: TR-2024-001" : "e.g., TR-2024-001"}
                          required
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="cert-issue-date">
                          {lang === "ar" ? "تاريخ الإصدار" : "Issue Date"}
                        </Label>
                        <DateInput
                          id="cert-issue-date"
                          value={certForm.issueDate}
                          onChange={(v) =>
                            setCertForm({
                              ...certForm,
                              issueDate: v,
                            })
                          }
                        />
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="cert-file">
                        {lang === "ar" ? "ملف الشهادة (PDF)" : "Certificate File (PDF)"}
                      </Label>
                      <Input
                        id="cert-file"
                        type="file"
                        accept=".pdf,.png,.jpg,.jpeg"
                        onChange={(e) =>
                          setCertFile(e.target.files?.[0] || undefined)
                        }
                      />
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="cert-notes">
                        {lang === "ar" ? "ملاحظات" : "Notes"}
                      </Label>
                      <Textarea
                        id="cert-notes"
                        value={certForm.notes}
                        onChange={(e) =>
                          setCertForm({ ...certForm, notes: e.target.value })
                        }
                        rows={2}
                      />
                    </div>
                  </div>
                  <DialogFooter>
                    <Button
                      variant="outline"
                      onClick={() => {
                        setCertDialogOpen(false)
                        resetCertForm()
                      }}
                    >
                      {lang === "ar" ? "إلغاء" : "Cancel"}
                    </Button>
                    <Button
                      onClick={handleIssueCertificate}
                      disabled={
                        isCertSubmitting ||
                        !certRegistrationId ||
                        !certForm.certificateNumber
                      }
                    >
                      {isCertSubmitting
                        ? lang === "ar"
                          ? "جاري الحفظ..."
                          : "Saving..."
                        : lang === "ar"
                          ? "إصدار الشهادة"
                          : "Issue Certificate"}
                    </Button>
                  </DialogFooter>
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              {programCertificates.length === 0 ? (
                <div className="py-12 text-center">
                  <Award className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar"
                      ? "لا توجد شهادات بعد"
                      : "No certificates issued yet"}
                  </h3>
                  <p className="text-sm text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر الشهادات هنا بعد إصدارها."
                      : "Issued certificates will appear here."}
                  </p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>
                        {lang === "ar" ? "المشارك" : "Participant"}
                      </TableHead>
                      <TableHead>
                        {lang === "ar" ? "رقم الشهادة" : "Certificate No."}
                      </TableHead>
                      <TableHead>
                        {lang === "ar" ? "تاريخ الإصدار" : "Issue Date"}
                      </TableHead>
                      <TableHead className="text-right">
                        {lang === "ar" ? "الإجراءات" : "Actions"}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {programCertificates.map((cert) => (
                      <TableRow key={cert.id}>
                        <TableCell className="font-medium">
                          {cert.userName}
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className="font-mono text-xs">
                            {cert.certificateNumber}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          {cert.issueDate
                            ? formatDate(cert.issueDate)
                            : "—"}
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-1">
                            {cert.file && (
                              <Button
                                variant="ghost"
                                size="icon-xs"
                                onClick={() =>
                                  cert.file && void openProtectedFile(cert.file)
                                }
                                title={
                                  lang === "ar" ? "تحميل" : "Download"
                                }
                              >
                                <Download className="h-4 w-4" />
                              </Button>
                            )}
                            <Button
                              variant="ghost"
                              size="icon-xs"
                              onClick={() => handleDeleteCertificate(cert.id)}
                              title={lang === "ar" ? "حذف" : "Delete"}
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="report">
          <div className="space-y-6">
            {stats && <ProgramReportCard stats={stats} />}

            <Card>
              <CardHeader>
                <CardTitle>
                  {lang === "ar" ? "ملخص مفصل" : "Detailed Summary"}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid gap-4 md:grid-cols-2">
                  <div>
                    <h4 className="mb-2 font-medium">
                      {lang === "ar" ? "الإحصائيات" : "Analytics"}
                    </h4>
                    <ul className="space-y-2 text-sm">
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "إجمالي التسجيلات:" : "Total registrations:"}
                        </span>
                        <span className="font-medium">
                          {stats?.totalRegistered ?? 0}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المكتملون:" : "Total completed:"}
                        </span>
                        <span className="font-medium">
                          {stats?.totalCompleted ?? 0}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "نسبة الإكمال:" : "Completion rate:"}
                        </span>
                        <span className="font-medium">
                          {stats?.attendanceRate ?? 0}%
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "عدد الجلسات:" : "Sessions:"}
                        </span>
                        <span className="font-medium">
                          {program.schedule.sessions.length}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "الحد الأقصى:" : "Max participants:"}
                        </span>
                        <span className="font-medium">
                          {program.maxParticipants ?? "—"}
                        </span>
                      </li>
                    </ul>
                  </div>
                  <div>
                    <h4 className="mb-2 font-medium">
                      {lang === "ar" ? "معلومات البرنامج" : "Program Info"}
                    </h4>
                    <ul className="space-y-2 text-sm">
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "العنوان:" : "Title:"}
                        </span>
                        <span className="font-medium">
                          {program.title[lang]}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المدرب:" : "Trainer:"}
                        </span>
                        <span className="font-medium">
                          {program.trainer.name[lang]}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "تاريخ البدء:" : "Start date:"}
                        </span>
                        <span className="font-medium">
                          {formatDate(program.schedule.startDate)}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المدة:" : "Duration:"}
                        </span>
                        <span className="font-medium">
                          {program.duration}{" "}
                          {lang === "ar" ? "أيام" : "days"}
                        </span>
                      </li>
                      <li className="dsc-detail-row">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "الموقع:" : "Location:"}
                        </span>
                        <span className="font-medium">{program.location}</span>
                      </li>
                    </ul>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}

"use client"
import { TemplateResponse } from "@/components/tools/TemplateResponse"
import { CaseName } from "@/components/cases/CaseName"
import { useProtectedFileToken } from "@/hooks/useProtectedFileToken"
import { surveyOptionLabel } from "@/lib/survey-options"

import { use, useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import { ArrowLeft, AlertCircle, Upload, X, FileText, Image as ImageIcon, Video, Music, Play, Trash2, File } from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"

import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const fileToken = useProtectedFileToken(!!assignmentId)
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/cases/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <ImageIcon aria-hidden="true" className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    if (!fileToken) return undefined
    return pb.files.getURL(
      { collectionId: "case_tools", id: assignmentId },
      filename,
      { token: fileToken }
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{surveyOptionLabel(opt, lang)}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{surveyOptionLabel(opt, lang)}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {question.mediaType === "image" && (
              <img
                src={question.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "video" && (
              <video
                src={question.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "audio" && (
              <div className="p-4">
                <audio src={question.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {question.answerType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {question.answerType === "number" && (
          <Input
            fieldWidth="short" type="number"
            placeholder="0"
            value={value as string | number | undefined}
            onChange={(e) => handleAnswer(question.id, Number(e.target.value))}
          />
        )}
        {question.answerType === "single_choice" && (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`mc-${question.id}-${opt.value}`}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {surveyOptionLabel(opt, lang)}
                </Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {question.answerType === "multiple_choice" && (
          <div className="space-y-2">
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`mc-${question.id}-${opt.value}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {surveyOptionLabel(opt, lang)}
                </Label>
              </div>
            ))}
          </div>
        )}

        {/* Media question response */}
        {isMedia && question.responseType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {isMedia &&
          (question.responseType === "video" ||
            question.responseType === "audio") && (
            <div className="space-y-3">
              {(() => {
                const hasNewUpload = uploadedFiles[question.id]
                const hasExistingFile =
                  existingFiles[question.id] &&
                  existingFiles[question.id].length > 0 &&
                  !filesToRemove.includes(existingFiles[question.id][0])

                return (
                  <>
                    {/* Show existing uploaded file */}
                    {hasExistingFile && !hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {existingFiles[question.id][0].split("_").pop()}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(existingFiles[question.id][0]),
                                  "_blank"
                                )
                              }
                            >
                              <Play className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleRemoveExistingFile(
                                  existingFiles[question.id][0]
                                )
                              }
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </div>
                        <div className="mt-2">
                          {question.responseType === "video" ? (
                            <video
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full rounded"
                              style={{ maxHeight: "200px" }}
                            />
                          ) : (
                            <audio
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full"
                            />
                          )}
                        </div>
                      </div>
                    )}

                    {/* Show new file being uploaded */}
                    {hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {uploadedFiles[question.id].file.name}
                            </span>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRemoveFile(question.id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                        {uploadedFiles[question.id].preview && (
                          <div className="mt-2">
                            {question.responseType === "video" ? (
                              <video
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full rounded"
                                style={{ maxHeight: "200px" }}
                              />
                            ) : (
                              <audio
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full"
                              />
                            )}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Upload button */}
                    {!hasExistingFile && !hasNewUpload && (
                      <div className="flex items-center gap-2">
                        <Input
                          type="file"
                          accept={
                            question.responseType === "video"
                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
                            document
                              .getElementById(`media-upload-${question.id}`)
                              ?.click()
                          }
                        >
                          <Upload className="me-2 h-4 w-4" />
                          {lang === "ar" ? "اختيار ملف" : "Choose File"}
                        </Button>
                      </div>
                    )}
                  </>
                )
              })()}
            </div>
          )}

        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMediaItem = (item: MediaItem) => {
    const hasNewUpload = uploadedFiles[item.id]
    const hasExistingFile =
      existingFiles[item.id] &&
      existingFiles[item.id].length > 0 &&
      !filesToRemove.includes(existingFiles[item.id][0])
    const hasError = errors.includes(item.id)

    return (
      <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
        <Label className="text-base font-medium">{item.question}</Label>

        {/* Display existing media (question media) */}
        {item.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {item.mediaType === "image" && (
              <img
                src={item.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "video" && (
              <video
                src={item.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "audio" && (
              <div className="p-4">
                <audio src={item.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {/* Response section */}
        {item.responseType === "text" && (
          <div>
            <Label className="text-sm text-muted-foreground">
              {lang === "ar" ? "إجابتك:" : "Your response:"}
            </Label>
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={mediaResponses[item.id] || ""}
              onChange={(e) => {
                setMediaResponses((prev) => ({
                  ...prev,
                  [item.id]: e.target.value,
                }))
                setErrors((prev) => prev.filter((e) => e !== item.id))
              }}
              className="mt-2"
            />
            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
              </div>
            )}
          </div>
        )}

        {/* Video/Audio response upload */}
        {(item.responseType === "video" || item.responseType === "audio") && (
          <div className="space-y-3">
            <Label className="text-sm text-muted-foreground">
              {lang === "ar"
                ? item.responseType === "video"
                  ? "رفع فيديو الرد:"
                  : "رفع صوت الرد:"
                : item.responseType === "video"
                  ? "Upload video response:"
                  : "Upload audio response:"}
            </Label>

            {/* Show existing uploaded file */}
            {hasExistingFile && !hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {existingFiles[item.id][0].split("_").pop()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(
                          getFileUrl(existingFiles[item.id][0]),
                          "_blank"
                        )
                      }
                    >
                      <Play className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        handleRemoveExistingFile(existingFiles[item.id][0])
                      }
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
                {/* Preview player */}
                <div className="mt-2">
                  {item.responseType === "video" ? (
                    <video
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full rounded"
                      style={{ maxHeight: "200px" }}
                    />
                  ) : (
                    <audio
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full"
                    />
                  )}
                </div>
              </div>
            )}

            {/* Show new file being uploaded */}
            {hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {/* Preview player for new upload */}
                {uploadedFiles[item.id].preview && (
                  <div className="mt-2">
                    {item.responseType === "video" ? (
                      <video
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full rounded"
                        style={{ maxHeight: "200px" }}
                      />
                    ) : (
                      <audio
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full"
                      />
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Upload button */}
            {!hasExistingFile && !hasNewUpload && (
              <div className="flex items-center gap-2">
                <Input
                  type="file"
                  accept={item.responseType === "video" ? "video/*" : "audio/*"}
                  onChange={(e) => handleFileSelect(item.id, e)}
                  className="hidden"
                  id={`media-upload-${item.id}`}
                />
                <Button
                  variant="outline"
                  onClick={() =>
                    document.getElementById(`media-upload-${item.id}`)?.click()
                  }
                >
                  <Upload className="me-2 h-4 w-4" />
                  {lang === "ar" ? "اختيار ملف" : "Choose File"}
                </Button>
              </div>
            )}

            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "الرد مطلوب" : "Response is required"}
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if ((isPlanTool || isReportTool) && (assignment.config as unknown as Record<string, unknown>)?.templateWorkflow === true) return <TemplateResponse key={assignment.id} task={assignment} kind={toolTypeName} readOnly={isAdminOrExpert} save={updateAssignment} />

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground"><CaseName profile={profile} /></p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {surveyOptionLabel(opt, lang)}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                  </p>
                </div>
                {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الرابط" : "Meeting Link"}
                    </Label>
                    <div className="mt-1">
                      <a
                        href={meetingConfig.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button variant="default" size="sm">
                          {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                        </Button>
                      </a>
                    </div>
                  </div>
                )}
                {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الموقع" : "Location"}
                    </Label>
                    <p className="font-medium">{meetingConfig.location}</p>
                  </div>
                )}

                {isAdminOrExpert ? (
                  <div className="space-y-2 rounded-lg border p-3">
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                    </Label>
                    <textarea
                      value={localNotes}
                      onChange={(e) => setLocalNotes(e.target.value)}
                      placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                      className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      rows={3}
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          id="notes-visible-completed"
                          checked={localNotesVisible}
                          onChange={(e) => setLocalNotesVisible(e.target.checked)}
                          className="h-4 w-4 rounded border-gray-300"
                        />
                        <Label htmlFor="notes-visible-completed" className="text-sm text-muted-foreground">
                          {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                        </Label>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={saveNotes}
                        disabled={isSavingNotes}
                      >
                        {isSavingNotes
                          ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                          : lang === "ar" ? "حفظ" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                  </div>
                ) : null}
              </div>
            )}

            {isReportTool && reportConfig && (
              <div className="space-y-3">
                {reportConfig.date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{formatDate(reportConfig.date)}</p>
                  </div>
                )}
                {reportConfig.assessment && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التقييم" : "Assessment"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                  </div>
                )}
                {reportConfig.suggestions && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                  </div>
                )}
              </div>
            )}

            {isPlanTool && planConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                    </Label>
                    <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                    </Label>
                    <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                  </div>
                </div>
                {planConfig.goals?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.goals.map((goal) => (
                        <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                          <p className="font-medium">{goal.title}</p>
                          {goal.description && (
                            <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {planConfig.steps?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الخطوات" : "Steps"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.steps.map((step) => (
                        <div key={step.id} className="rounded-lg border p-3">
                          <div className="flex items-start gap-2">
                            <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                            <div className="flex-1">
                              <p className="font-medium">{step.title}</p>
                              {step.description && (
                                <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {(isMeetingTool || isReportTool || isPlanTool) && (
              <div className="flex gap-2 pt-4">
                <Button
                  onClick={() => router.push(`/dashboard/cases/${profile.id}`)}
                >
                  {lang === "ar" ? "العودة" : "Back"}
                </Button>
              </div>
            )}

            {!isMeetingTool && !isReportTool && !isPlanTool && (
            <div className="flex gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() =>
                  updateAssignment(assignmentId, { status: "in_progress" })
                }
              >
                {lang === "ar" ? "تعديل الإجابات" : "Edit Answers"}
              </Button>
              <Button
                onClick={() => router.push(`/dashboard/cases/${profile.id}`)}
              >
                {lang === "ar" ? "العودة" : "Back"}
              </Button>
            </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
          <p className="text-muted-foreground"><CaseName profile={profile} /></p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{assignment.name_en}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {isSurveyTool &&
            (() => {
              const sortedOptions = [...(surveyConfig?.options || [])].sort(
                (a, b) => a.order - b.order
              )
              const isMultiple = surveyConfig?.answerType === "multiple_choice"
              return (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                        <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                          {lang === "ar" ? "الأسئلة" : "Questions"}
                        </th>
                        {sortedOptions.map((opt) => (
                          <th
                            key={opt.id}
                            className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                          >
                            {surveyOptionLabel(opt, lang)}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {surveyConfig?.questions.map((question) => {
                        const value = answers[question.id] as
                          | string
                          | string[]
                          | undefined
                        const hasError = errors.includes(question.id)
                        return (
                          <tr key={question.id}>
                            <td className="py-3 pe-4 align-top">
                              <Label className="text-base font-medium">
                                {question.text}
                                {question.required && (
                                  <span className="ms-1 text-destructive">
                                    *
                                  </span>
                                )}
                              </Label>
                            </td>
                            {sortedOptions.map((opt) => (
                              <td
                                key={opt.id}
                                className="px-2 py-3 text-center"
                              >
                                {isMultiple ? (
                                  <Checkbox
                                    id={`${question.id}-${opt.id}`}
                                    checked={(
                                      (value as string[]) || []
                                    ).includes(opt.value)}
                                    onCheckedChange={(checked) => {
                                      if (checked) {
                                        handleAnswer(question.id, [
                                          ...((value as string[]) || []),
                                          opt.value,
                                        ])
                                      } else {
                                        handleAnswer(
                                          question.id,
                                          ((value as string[]) || []).filter(
                                            (v) => v !== opt.value
                                          )
                                        )
                                      }
                                    }}
                                    className="mx-auto"
                                  />
                                ) : (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      handleAnswer(question.id, opt.value)
                                    }
                                    className={`mx-auto h-5 w-5 rounded-full border-2 transition-colors ${
                                      (value as string) === opt.value
                                        ? "border-primary bg-primary"
                                        : "border-muted-foreground hover:border-primary"
                                    }`}
                                  />
                                )}
                              </td>
                            ))}
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                  {errors.some((errId) =>
                    surveyConfig?.questions.find((q) => q.id === errId)
                  ) && (
                    <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
                      <AlertCircle className="h-4 w-4" />
                      {lang === "ar"
                        ? "يرجى الإجابة على جميع الأسئلة المطلوبة"
                        : "Please answer all required questions"}
                    </div>
                  )}
                </div>
              )
            })()}

          {isMultipleChoiceTool &&
            mcConfig?.questions.map((question) => (
              <div key={question.id}>{renderMCQuestion(question)}</div>
            ))}

          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import pb from "@/lib/pb"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { DateInput } from "@/components/ui/date-input"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useLang } from "@/lib/lang-context"
import { t } from "@/lib/i18n"
import { usePortals } from "@/hooks/usePortals"
import { trainingProgramsCollection } from "@/lib/pb-training"
import type { TrainingProgram } from "@/types/training"
import { type PortalServiceValue } from "@/components/register/PortalServiceSelector"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

const OTHER_VALUE = "other"
const TRAINING_SERVICE_ID = "attending-training"

const GRADES = [
  { value: "kg1", label: { en: "KG 1", ar: "روضة 1" } },
  { value: "kg2", label: { en: "KG 2", ar: "روضة 2" } },
  { value: "grade1", label: { en: "Grade 1", ar: "الصف الأول" } },
  { value: "grade2", label: { en: "Grade 2", ar: "الصف الثاني" } },
  { value: "grade3", label: { en: "Grade 3", ar: "الصف الثالث" } },
  { value: "grade4", label: { en: "Grade 4", ar: "الصف الرابع" } },
  { value: "grade5", label: { en: "Grade 5", ar: "الصف الخامس" } },
  { value: "grade6", label: { en: "Grade 6", ar: "الصف السادس" } },
  { value: "grade7", label: { en: "Grade 7", ar: "الصف السابع" } },
  { value: "grade8", label: { en: "Grade 8", ar: "الصف الثامن" } },
  { value: "grade9", label: { en: "Grade 9", ar: "الصف التاسع" } },
  { value: "grade10", label: { en: "Grade 10", ar: "الصف العاشر" } },
  { value: "grade11", label: { en: "Grade 11", ar: "الصف الحادي عشر" } },
  { value: "grade12", label: { en: "Grade 12", ar: "الصف الثاني عشر" } },
  { value: "university", label: { en: "University", ar: "الجامعة" } },
]

export default function NewProfilePage() {
  const router = useRouter()
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const { portals: PORTALS } = usePortals()
  const { addProfile } = useProfiles()
  const [isSubmitting, setIsSubmitting] = useState(false)

  const [formData, setFormData] = useState({
    name: "",
    date_of_birth: "",
    gender: "",
    grade: "",
    notes: "",
  })

  const [portalService, setPortalService] = useState<PortalServiceValue>({
    categoryId: "",
    subCategoryId: "",
    customCategory: "",
    customSubCategory: "",
  })

  const [trainingPrograms, setTrainingPrograms] = useState<TrainingProgram[]>(
    []
  )
  const [trainingProgramsLoading, setTrainingProgramsLoading] = useState(false)
  const [selectedProgramId, setSelectedProgramId] = useState("")

  const isTrainingSelected =
    portalService.categoryId === TRAINING_SERVICE_ID ||
    portalService.subCategoryId === TRAINING_SERVICE_ID

  const isIndividual = currentUser?.role === "individual"
  const showBasicDetails = !isIndividual

  useEffect(() => {
    if (!isTrainingSelected) {
      setSelectedProgramId("")
      setTrainingPrograms([])
      return
    }
    let cancelled = false
    setTrainingProgramsLoading(true)
    trainingProgramsCollection
      .getPublished()
      .then((data) => {
        if (cancelled) return
        const today = new Date().toISOString().slice(0, 10)
        const running = data
          .filter((p) => today <= p.schedule.endDate)
          .sort((a, b) => (a.schedule.endDate < b.schedule.endDate ? -1 : 1))
        setTrainingPrograms(running)
      })
      .catch((err) => {
        console.error("Failed to load training programs:", err)
      })
      .finally(() => {
        if (!cancelled) setTrainingProgramsLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [isTrainingSelected])

  const handleServiceTypeChange = (value: string) => {
    if (value === TRAINING_SERVICE_ID) {
      setPortalService({
        categoryId: TRAINING_SERVICE_ID,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    } else {
      setPortalService({
        categoryId: value,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    }
  }

  const handleCaseTypeChange = (value: string) => {
    if (isTrainingSelected) {
      setSelectedProgramId(value)
    } else {
      setPortalService({
        ...portalService,
        subCategoryId: value,
      })
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentUser) return

    if (
      ["parent", "care_foundation"].includes(currentUser.role) &&
      (!formData.name.trim() ||
        !formData.date_of_birth ||
        !["male", "female"].includes(formData.gender))
    ) {
      toast.error(
        lang === "ar"
          ? "اسم الطفل وتاريخ الميلاد والجنس حقول مطلوبة."
          : "Child name, date of birth and gender are required."
      )
      return
    }
    setIsSubmitting(true)

    try {
      const isTraining = isTrainingSelected && selectedProgramId
      const selectedProgram = isTraining
        ? trainingPrograms.find((p) => p.id === selectedProgramId)
        : null

      const profileId = await addProfile({
        user: currentUser.id,
        name:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? selectedProgram?.title[lang] ||
              (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
            : formData.name,
        date_of_birth:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? ""
            : formData.date_of_birth,
        gender:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? undefined
            : (formData.gender as "male" | "female"),
        grade: isTraining ? "" : formData.grade,
        notes: formData.notes,
        portal_type: isTraining ? "Attending Training" : undefined,
        service_type: isTraining
          ? selectedProgram?.title[lang]
          : portalService.subCategoryId.trim() || undefined,
        program_id: isTraining ? selectedProgramId : undefined,
        training_link: isTraining
          ? selectedProgram?.meetingLink ||
            `/programmes/training_programmes/${selectedProgramId}`
          : undefined,
        program_status: isTraining ? "enrolled" : undefined,
        status: "pending",
        user_details: isTraining
          ? {
              name: currentUser.name,
              email: currentUser.email,
              contact: currentUser.contact_number,
            }
          : undefined,
        case_details: isTraining
          ? undefined
          : {
              custom_category:
                portalService.categoryId === OTHER_VALUE
                  ? portalService.customCategory
                  : undefined,
              custom_sub_category:
                portalService.subCategoryId.trim() || undefined,
            },
      })

      const caseName = isTraining
        ? selectedProgram?.title[lang] ||
          (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
        : formData.name

      fetch("/api/telegram-notify", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${pb.authStore.token}`,
        },
        body: JSON.stringify({
          text: [
            "*New Case Needs Payment Amount*",
            "",
            `*Case:* ${caseName}`,
            `*User:* ${currentUser.name} (${currentUser.email})`,
            `*Service:* ${portalService.subCategoryId || portalService.categoryId || "-"}`,
          ].join("\n"),
        }),
      }).catch(() => {})

      router.push(`/dashboard/cases/${profileId}`)
    } catch (error) {
      console.error("Failed to create profile:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-primary">
          {lang === "ar" ? "إنشاء حالة جديدة" : "Create New Case"}
        </h1>
        <p className="text-muted-foreground">
          {lang === "ar" ? "املأ تفاصيل الحالة" : "Fill in the case details"}
        </p>
      </div>

      <form onSubmit={handleSubmit}>
        {showBasicDetails && (
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات الحالة" : "Case Information"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "التفاصيل الأساسية حول الحالة"
                  : "Basic details about the case"}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="name">
                  {lang === "ar" ? "اسم الطفل *" : "Child Name *"}
                </Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  required
                />
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="date_of_birth">
                    {lang === "ar" ? "تاريخ الميلاد *" : "Date of Birth *"}
                  </Label>
                  <DateInput
                    id="date_of_birth"
                    value={formData.date_of_birth}
                    onChange={(v) =>
                      setFormData({ ...formData, date_of_birth: v })
                    }
                    maxDate={new Date()}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="gender">
                    {lang === "ar" ? "الجنس *" : "Gender *"}
                  </Label>
                  <Select
                    required
                    value={formData.gender}
                    onValueChange={(value) =>
                      setFormData({ ...formData, gender: value })
                    }
                  >
                    <SelectTrigger id="gender" aria-required="true">
                      <SelectValue
                        placeholder={
                          lang === "ar" ? "اختر الجنس" : "Select gender"
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="male">
                        {lang === "ar" ? "ذكر" : "Male"}
                      </SelectItem>
                      <SelectItem value="female">
                        {lang === "ar" ? "أنثى" : "Female"}
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="grade">
                  {lang === "ar" ? "الصف الدراسي" : "Grade"}
                </Label>
                <Select
                  value={formData.grade}
                  onValueChange={(value) =>
                    setFormData({ ...formData, grade: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={lang === "ar" ? "اختر الصف" : "Select grade"}
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {GRADES.map((grade) => (
                      <SelectItem key={grade.value} value={grade.value}>
                        {grade.label[lang]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>
        )}

        <Card className={showBasicDetails ? "mt-6" : ""}>
          <CardHeader>
            <CardTitle>
              {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Select the service this case belongs to",
                  ar: "اختر الخدمة التي تنتمي إليها هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>
                {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
                <span className="ms-1 text-red-500">*</span>
              </Label>
              <Select
                value={portalService.categoryId}
                onValueChange={handleServiceTypeChange}
              >
                <SelectTrigger>
                  <SelectValue
                    placeholder={t(
                      { en: "Select service type", ar: "اختر نوع الخدمة" },
                      lang
                    )}
                  />
                </SelectTrigger>
                <SelectContent>
                  {PORTALS.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {lang === "ar"
                        ? p.portalName.ar.replace(/^بوابة /, "")
                        : p.title.en}
                    </SelectItem>
                  ))}
                  <SelectItem value={TRAINING_SERVICE_ID}>
                    {t({ en: "Attending Training", ar: "حضور تدريب" }, lang)}
                  </SelectItem>
                  <SelectItem value={OTHER_VALUE}>
                    {t({ en: "Other", ar: "أخرى" }, lang)}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {isTrainingSelected ? (
              <div className="space-y-2">
                <Label>
                  {t({ en: "Case Type", ar: "نوع الحالة" }, lang)}
                  <span className="ms-1 text-red-500">*</span>
                </Label>
                <Select
                  value={selectedProgramId}
                  onValueChange={handleCaseTypeChange}
                  disabled={trainingProgramsLoading}
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={
                        trainingProgramsLoading
                          ? t({ en: "Loading...", ar: "جاري التحميل..." }, lang)
                          : t(
                              {
                                en: "Select a training program",
                                ar: "اختر برنامج تدريبي",
                              },
                              lang
                            )
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {trainingPrograms.length === 0 ? (
                      <SelectItem value="__none__" disabled>
                        {t(
                          {
                            en: "No programs with open enrollment",
                            ar: "لا توجد برامج مفتوحة للتسجيل",
                          },
                          lang
                        )}
                      </SelectItem>
                    ) : (
                      trainingPrograms.map((p) => (
                        <SelectItem key={p.id} value={p.id}>
                          {p.title[lang]}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <>
                {portalService.categoryId === OTHER_VALUE && (
                  <div className="space-y-2">
                    <Label>
                      {t(
                        {
                          en: "Custom service type",
                          ar: "اسم نوع الخدمة المخصص",
                        },
                        lang
                      )}
                      <span className="ms-1 text-red-500">*</span>
                    </Label>
                    <Input
                      value={portalService.customCategory}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          customCategory: e.target.value,
                        })
                      }
                      placeholder={t(
                        { en: "Enter service type", ar: "أدخل اسم نوع الخدمة" },
                        lang
                      )}
                    />
                  </div>
                )}

                {portalService.categoryId && (
                  <div className="space-y-2">
                    <Label>
                      {t({ en: "Issue Type", ar: "نوع المشكلة" }, lang)}
                      <span className="ms-1 text-red-500">*</span>
                    </Label>
                    <Input
                      value={portalService.subCategoryId}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          subCategoryId: e.target.value,
                          customSubCategory: "",
                        })
                      }
                      placeholder={t(
                        { en: "Enter issue type", ar: "أدخل اسم نوع المشكلة" },
                        lang
                      )}
                    />
                  </div>
                )}
              </>
            )}
          </CardContent>
        </Card>

        <Card className="mt-6">
          <CardHeader>
            <CardTitle>
              {t({ en: "Explain more", ar: "اشرح أكثر" }, lang)}{" "}
              <span className="ms-1 text-red-500">*</span>
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Add any extra context that will help us handle this case",
                  ar: "أضف أي سياق إضافي يساعدنا في التعامل مع هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Textarea
                id="notes"
                value={formData.notes}
                required
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
                placeholder={t(
                  {
                    en: "Provide more details about the case...",
                    ar: "قدم مزيداً من التفاصيل حول الحالة...",
                  },
                  lang
                )}
                rows={4}
              />
            </div>
          </CardContent>
        </Card>

        <div className="mt-6 flex justify-end gap-4">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            {lang === "ar" ? "إلغاء" : "Cancel"}
          </Button>
          <Button
            type="submit"
            disabled={
              isSubmitting || (isTrainingSelected && !selectedProgramId)
            }
          >
            {isSubmitting
              ? lang === "ar"
                ? "جارٍ الإنشاء..."
                : "Creating..."
              : lang === "ar"
                ? "إنشاء الحالة"
                : "Create Case"}
          </Button>
        </div>
      </form>
    </div>
  )
}

"use client"
import { TemplateResponse } from "@/components/tools/TemplateResponse"
import { CaseName } from "@/components/cases/CaseName"
import { useProtectedFileToken } from "@/hooks/useProtectedFileToken"
import { surveyOptionLabel } from "@/lib/survey-options"

import { use, useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import { ArrowLeft, AlertCircle, Upload, X, FileText, Image as ImageIcon, Video, Music, Play, Trash2, File } from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"

import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const fileToken = useProtectedFileToken(!!assignmentId)
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/individual/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/individual/cases/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <ImageIcon aria-hidden="true" className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    if (!fileToken) return undefined
    return pb.files.getURL(
      { collectionId: "case_tools", id: assignmentId },
      filename,
      { token: fileToken }
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{surveyOptionLabel(opt, lang)}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{surveyOptionLabel(opt, lang)}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {question.mediaType === "image" && (
              <img
                src={question.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "video" && (
              <video
                src={question.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "audio" && (
              <div className="p-4">
                <audio src={question.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {question.answerType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {question.answerType === "number" && (
          <Input
            fieldWidth="short" type="number"
            placeholder="0"
            value={value as string | number | undefined}
            onChange={(e) => handleAnswer(question.id, Number(e.target.value))}
          />
        )}
        {question.answerType === "single_choice" && (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`mc-${question.id}-${opt.value}`}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {surveyOptionLabel(opt, lang)}
                </Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {question.answerType === "multiple_choice" && (
          <div className="space-y-2">
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`mc-${question.id}-${opt.value}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {surveyOptionLabel(opt, lang)}
                </Label>
              </div>
            ))}
          </div>
        )}

        {/* Media question response */}
        {isMedia && question.responseType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {isMedia &&
          (question.responseType === "video" ||
            question.responseType === "audio") && (
            <div className="space-y-3">
              {(() => {
                const hasNewUpload = uploadedFiles[question.id]
                const hasExistingFile =
                  existingFiles[question.id] &&
                  existingFiles[question.id].length > 0 &&
                  !filesToRemove.includes(existingFiles[question.id][0])

                return (
                  <>
                    {/* Show existing uploaded file */}
                    {hasExistingFile && !hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {existingFiles[question.id][0].split("_").pop()}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(existingFiles[question.id][0]),
                                  "_blank"
                                )
                              }
                            >
                              <Play className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleRemoveExistingFile(
                                  existingFiles[question.id][0]
                                )
                              }
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </div>
                        <div className="mt-2">
                          {question.responseType === "video" ? (
                            <video
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full rounded"
                              style={{ maxHeight: "200px" }}
                            />
                          ) : (
                            <audio
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full"
                            />
                          )}
                        </div>
                      </div>
                    )}

                    {/* Show new file being uploaded */}
                    {hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {uploadedFiles[question.id].file.name}
                            </span>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRemoveFile(question.id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                        {uploadedFiles[question.id].preview && (
                          <div className="mt-2">
                            {question.responseType === "video" ? (
                              <video
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full rounded"
                                style={{ maxHeight: "200px" }}
                              />
                            ) : (
                              <audio
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full"
                              />
                            )}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Upload button */}
                    {!hasExistingFile && !hasNewUpload && (
                      <div className="flex items-center gap-2">
                        <Input
                          type="file"
                          accept={
                            question.responseType === "video"
                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
                            document
                              .getElementById(`media-upload-${question.id}`)
                              ?.click()
                          }
                        >
                          <Upload className="me-2 h-4 w-4" />
                          {lang === "ar" ? "اختيار ملف" : "Choose File"}
                        </Button>
                      </div>
                    )}
                  </>
                )
              })()}
            </div>
          )}

        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMediaItem = (item: MediaItem) => {
    const hasNewUpload = uploadedFiles[item.id]
    const hasExistingFile =
      existingFiles[item.id] &&
      existingFiles[item.id].length > 0 &&
      !filesToRemove.includes(existingFiles[item.id][0])
    const hasError = errors.includes(item.id)

    return (
      <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
        <Label className="text-base font-medium">{item.question}</Label>

        {/* Display existing media (question media) */}
        {item.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {item.mediaType === "image" && (
              <img
                src={item.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "video" && (
              <video
                src={item.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "audio" && (
              <div className="p-4">
                <audio src={item.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {/* Response section */}
        {item.responseType === "text" && (
          <div>
            <Label className="text-sm text-muted-foreground">
              {lang === "ar" ? "إجابتك:" : "Your response:"}
            </Label>
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={mediaResponses[item.id] || ""}
              onChange={(e) => {
                setMediaResponses((prev) => ({
                  ...prev,
                  [item.id]: e.target.value,
                }))
                setErrors((prev) => prev.filter((e) => e !== item.id))
              }}
              className="mt-2"
            />
            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
              </div>
            )}
          </div>
        )}

        {/* Video/Audio response upload */}
        {(item.responseType === "video" || item.responseType === "audio") && (
          <div className="space-y-3">
            <Label className="text-sm text-muted-foreground">
              {lang === "ar"
                ? item.responseType === "video"
                  ? "رفع فيديو الرد:"
                  : "رفع صوت الرد:"
                : item.responseType === "video"
                  ? "Upload video response:"
                  : "Upload audio response:"}
            </Label>

            {/* Show existing uploaded file */}
            {hasExistingFile && !hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {existingFiles[item.id][0].split("_").pop()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(
                          getFileUrl(existingFiles[item.id][0]),
                          "_blank"
                        )
                      }
                    >
                      <Play className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        handleRemoveExistingFile(existingFiles[item.id][0])
                      }
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
                {/* Preview player */}
                <div className="mt-2">
                  {item.responseType === "video" ? (
                    <video
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full rounded"
                      style={{ maxHeight: "200px" }}
                    />
                  ) : (
                    <audio
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full"
                    />
                  )}
                </div>
              </div>
            )}

            {/* Show new file being uploaded */}
            {hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {/* Preview player for new upload */}
                {uploadedFiles[item.id].preview && (
                  <div className="mt-2">
                    {item.responseType === "video" ? (
                      <video
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full rounded"
                        style={{ maxHeight: "200px" }}
                      />
                    ) : (
                      <audio
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full"
                      />
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Upload button */}
            {!hasExistingFile && !hasNewUpload && (
              <div className="flex items-center gap-2">
                <Input
                  type="file"
                  accept={item.responseType === "video" ? "video/*" : "audio/*"}
                  onChange={(e) => handleFileSelect(item.id, e)}
                  className="hidden"
                  id={`media-upload-${item.id}`}
                />
                <Button
                  variant="outline"
                  onClick={() =>
                    document.getElementById(`media-upload-${item.id}`)?.click()
                  }
                >
                  <Upload className="me-2 h-4 w-4" />
                  {lang === "ar" ? "اختيار ملف" : "Choose File"}
                </Button>
              </div>
            )}

            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "الرد مطلوب" : "Response is required"}
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if ((isPlanTool || isReportTool) && (assignment.config as unknown as Record<string, unknown>)?.templateWorkflow === true) return <TemplateResponse key={assignment.id} task={assignment} kind={toolTypeName} readOnly={isAdminOrExpert} save={updateAssignment} />

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground"><CaseName profile={profile} /></p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {surveyOptionLabel(opt, lang)}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                  </p>
                </div>
                {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الرابط" : "Meeting Link"}
                    </Label>
                    <div className="mt-1">
                      <a
                        href={meetingConfig.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button variant="default" size="sm">
                          {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                        </Button>
                      </a>
                    </div>
                  </div>
                )}
                {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الموقع" : "Location"}
                    </Label>
                    <p className="font-medium">{meetingConfig.location}</p>
                  </div>
                )}

                {isAdminOrExpert ? (
                  <div className="space-y-2 rounded-lg border p-3">
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                    </Label>
                    <textarea
                      value={localNotes}
                      onChange={(e) => setLocalNotes(e.target.value)}
                      placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                      className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      rows={3}
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          id="notes-visible-completed"
                          checked={localNotesVisible}
                          onChange={(e) => setLocalNotesVisible(e.target.checked)}
                          className="h-4 w-4 rounded border-gray-300"
                        />
                        <Label htmlFor="notes-visible-completed" className="text-sm text-muted-foreground">
                          {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                        </Label>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={saveNotes}
                        disabled={isSavingNotes}
                      >
                        {isSavingNotes
                          ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                          : lang === "ar" ? "حفظ" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                  </div>
                ) : null}
              </div>
            )}

            {isReportTool && reportConfig && (
              <div className="space-y-3">
                {reportConfig.date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{formatDate(reportConfig.date)}</p>
                  </div>
                )}
                {reportConfig.assessment && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التقييم" : "Assessment"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                  </div>
                )}
                {reportConfig.suggestions && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                  </div>
                )}
              </div>
            )}

            {isPlanTool && planConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                    </Label>
                    <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                    </Label>
                    <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                  </div>
                </div>
                {planConfig.goals?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.goals.map((goal) => (
                        <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                          <p className="font-medium">{goal.title}</p>
                          {goal.description && (
                            <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {planConfig.steps?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الخطوات" : "Steps"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.steps.map((step) => (
                        <div key={step.id} className="rounded-lg border p-3">
                          <div className="flex items-start gap-2">
                            <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                            <div className="flex-1">
                              <p className="font-medium">{step.title}</p>
                              {step.description && (
                                <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {(isMeetingTool || isReportTool || isPlanTool) && (
              <div className="flex gap-2 pt-4">
                <Button
                  onClick={() => router.push(`/dashboard/individual/cases/${profile.id}`)}
                >
                  {lang === "ar" ? "العودة" : "Back"}
                </Button>
              </div>
            )}

            {!isMeetingTool && !isReportTool && !isPlanTool && (
            <div className="flex gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() =>
                  updateAssignment(assignmentId, { status: "in_progress" })
                }
              >
                {lang === "ar" ? "تعديل الإجابات" : "Edit Answers"}
              </Button>
              <Button
                onClick={() => router.push(`/dashboard/individual/cases/${profile.id}`)}
              >
                {lang === "ar" ? "العودة" : "Back"}
              </Button>
            </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
          <p className="text-muted-foreground"><CaseName profile={profile} /></p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{assignment.name_en}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {isSurveyTool &&
            (() => {
              const sortedOptions = [...(surveyConfig?.options || [])].sort(
                (a, b) => a.order - b.order
              )
              const isMultiple = surveyConfig?.answerType === "multiple_choice"
              return (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                        <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                          {lang === "ar" ? "الأسئلة" : "Questions"}
                        </th>
                        {sortedOptions.map((opt) => (
                          <th
                            key={opt.id}
                            className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                          >
                            {surveyOptionLabel(opt, lang)}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {surveyConfig?.questions.map((question) => {
                        const value = answers[question.id] as
                          | string
                          | string[]
                          | undefined
                        const hasError = errors.includes(question.id)
                        return (
                          <tr key={question.id}>
                            <td className="py-3 pe-4 align-top">
                              <Label className="text-base font-medium">
                                {question.text}
                                {question.required && (
                                  <span className="ms-1 text-destructive">
                                    *
                                  </span>
                                )}
                              </Label>
                            </td>
                            {sortedOptions.map((opt) => (
                              <td
                                key={opt.id}
                                className="px-2 py-3 text-center"
                              >
                                {isMultiple ? (
                                  <Checkbox
                                    id={`${question.id}-${opt.id}`}
                                    checked={(
                                      (value as string[]) || []
                                    ).includes(opt.value)}
                                    onCheckedChange={(checked) => {
                                      if (checked) {
                                        handleAnswer(question.id, [
                                          ...((value as string[]) || []),
                                          opt.value,
                                        ])
                                      } else {
                                        handleAnswer(
                                          question.id,
                                          ((value as string[]) || []).filter(
                                            (v) => v !== opt.value
                                          )
                                        )
                                      }
                                    }}
                                    className="mx-auto"
                                  />
                                ) : (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      handleAnswer(question.id, opt.value)
                                    }
                                    className={`mx-auto h-5 w-5 rounded-full border-2 transition-colors ${
                                      (value as string) === opt.value
                                        ? "border-primary bg-primary"
                                        : "border-muted-foreground hover:border-primary"
                                    }`}
                                  />
                                )}
                              </td>
                            ))}
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                  {errors.some((errId) =>
                    surveyConfig?.questions.find((q) => q.id === errId)
                  ) && (
                    <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
                      <AlertCircle className="h-4 w-4" />
                      {lang === "ar"
                        ? "يرجى الإجابة على جميع الأسئلة المطلوبة"
                        : "Please answer all required questions"}
                    </div>
                  )}
                </div>
              )
            })()}

          {isMultipleChoiceTool &&
            mcConfig?.questions.map((question) => (
              <div key={question.id}>{renderMCQuestion(question)}</div>
            ))}

          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { DateInput } from "@/components/ui/date-input"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useLang } from "@/lib/lang-context"
import { t } from "@/lib/i18n"
import { usePortals } from "@/hooks/usePortals"
import { trainingProgramsCollection } from "@/lib/pb-training"
import type { TrainingProgram } from "@/types/training"
import { type PortalServiceValue } from "@/components/register/PortalServiceSelector"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"

const OTHER_VALUE = "other"
const TRAINING_SERVICE_ID = "attending-training"

const GRADES = [
  { value: "kg1", label: { en: "KG 1", ar: "روضة 1" } },
  { value: "kg2", label: { en: "KG 2", ar: "روضة 2" } },
  { value: "grade1", label: { en: "Grade 1", ar: "الصف الأول" } },
  { value: "grade2", label: { en: "Grade 2", ar: "الصف الثاني" } },
  { value: "grade3", label: { en: "Grade 3", ar: "الصف الثالث" } },
  { value: "grade4", label: { en: "Grade 4", ar: "الصف الرابع" } },
  { value: "grade5", label: { en: "Grade 5", ar: "الصف الخامس" } },
  { value: "grade6", label: { en: "Grade 6", ar: "الصف السادس" } },
  { value: "grade7", label: { en: "Grade 7", ar: "الصف السابع" } },
  { value: "grade8", label: { en: "Grade 8", ar: "الصف الثامن" } },
  { value: "grade9", label: { en: "Grade 9", ar: "الصف التاسع" } },
  { value: "grade10", label: { en: "Grade 10", ar: "الصف العاشر" } },
  { value: "grade11", label: { en: "Grade 11", ar: "الصف الحادي عشر" } },
  { value: "grade12", label: { en: "Grade 12", ar: "الصف الثاني عشر" } },
  { value: "university", label: { en: "University", ar: "الجامعة" } },
]

export default function NewProfilePage() {
  const router = useRouter()
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const { portals: PORTALS } = usePortals()
  const getPortalById = (id: string) => PORTALS.find((portal) => portal.id === id)
  const { addProfile } = useProfiles()
  const [isSubmitting, setIsSubmitting] = useState(false)

  const [formData, setFormData] = useState({
    name: "",
    date_of_birth: "",
    gender: "",
    grade: "",
    notes: "",
  })

  const [portalService, setPortalService] = useState<PortalServiceValue>({
    categoryId: "",
    subCategoryId: "",
    customCategory: "",
    customSubCategory: "",
  })

  const [trainingPrograms, setTrainingPrograms] = useState<TrainingProgram[]>(
    []
  )
  const [trainingProgramsLoading, setTrainingProgramsLoading] = useState(false)
  const [selectedProgramId, setSelectedProgramId] = useState("")

  const isTrainingSelected =
    portalService.categoryId === TRAINING_SERVICE_ID ||
    portalService.subCategoryId === TRAINING_SERVICE_ID

  const isIndividual = currentUser?.role === "individual"
  const showBasicDetails = !isIndividual

  useEffect(() => {
    if (!isTrainingSelected) {
      setSelectedProgramId("")
      setTrainingPrograms([])
      return
    }
    let cancelled = false
    setTrainingProgramsLoading(true)
    trainingProgramsCollection
      .getPublished()
      .then((data) => {
        if (cancelled) return
        const today = new Date().toISOString().slice(0, 10)
        const running = data
          .filter((p) => today <= p.schedule.endDate)
          .sort((a, b) =>
            a.schedule.endDate < b.schedule.endDate ? -1 : 1
          )
        setTrainingPrograms(running)
      })
      .catch((err) => {
        console.error("Failed to load training programs:", err)
      })
      .finally(() => {
        if (!cancelled) setTrainingProgramsLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [isTrainingSelected])

  const handleServiceTypeChange = (value: string) => {
    if (value === TRAINING_SERVICE_ID) {
      setPortalService({
        categoryId: TRAINING_SERVICE_ID,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    } else {
      setPortalService({
        categoryId: value,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    }
  }

  const handleCaseTypeChange = (value: string) => {
    if (isTrainingSelected) {
      setSelectedProgramId(value)
    } else {
      setPortalService({
        ...portalService,
        subCategoryId: value,
      })
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentUser) return

    setIsSubmitting(true)

    try {
      const isTraining = isTrainingSelected && selectedProgramId
      const selectedProgram = isTraining
        ? trainingPrograms.find((p) => p.id === selectedProgramId)
        : null

      const portal = getPortalById(portalService.categoryId)
      const portalLabel =
        portalService.categoryId === OTHER_VALUE
          ? portalService.customCategory
          : portal?.title[lang]
      const serviceLabel = portalService.subCategoryId.trim()

      let profileDob = ""
      let profileGender: "male" | "female" | undefined
      if (!isTraining) {
        try {
          const individualProfile = await pb
            .collection("individual_profiles")
            .getFirstListItem(pb.filter("user = {:value0}", { value0: currentUser.id }))
          profileDob = (individualProfile.date_of_birth as string) || ""
          profileGender =
            (individualProfile.gender as "male" | "female" | undefined) ||
            undefined
        } catch {
          // profile record not found — create case without personal details
        }
      }

      const derivedName =
        [currentUser.name, portalLabel, serviceLabel]
          .filter(Boolean)
          .join(" - ") || currentUser.name

      const profileId = await addProfile({
        user: currentUser.id,
        name: isTraining
          ? selectedProgram?.title[lang] ||
            (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
          : derivedName,
        date_of_birth: isTraining ? "" : profileDob,
        gender: isTraining ? undefined : profileGender,
        grade: "",
        notes: formData.notes,
        portal_type: isTraining ? "Attending Training" : portalService.categoryId,
        service_type: isTraining
          ? selectedProgram?.title[lang]
          : portalService.subCategoryId.trim(),
        program_id: isTraining ? selectedProgramId : undefined,
        training_link: isTraining
          ? selectedProgram?.meetingLink ||
            `/programmes/training_programmes/${selectedProgramId}`
          : undefined,
        program_status: isTraining ? "enrolled" : undefined,
        status: "pending",
        user_details: isTraining
          ? {
              name: currentUser.name,
              email: currentUser.email,
              contact: currentUser.contact_number,
            }
          : undefined,
        case_details: isTraining
          ? undefined
          : {
              custom_category:
                portalService.categoryId === OTHER_VALUE
                  ? portalService.customCategory
                  : undefined,
              custom_sub_category:
                portalService.subCategoryId.trim() || undefined,
            },
      })

      const caseName = isTraining
        ? selectedProgram?.title[lang] ||
          (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
        : derivedName

      fetch("/api/telegram-notify", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${pb.authStore.token}` },
        body: JSON.stringify({
          text: [
            "*New Case Needs Payment Amount*",
            "",
            `*Case:* ${caseName}`,
            `*User:* ${currentUser.name} (${currentUser.email})`,
            `*Service:* ${portalService.subCategoryId || portalService.categoryId || "-"}`,
          ].join("\n"),
        }),
      }).catch(() => {})

      router.push(`/dashboard/individual/cases/${profileId}`)
    } catch (error) {
      console.error("Failed to create profile:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-primary">
          {lang === "ar" ? "إنشاء حالة جديدة" : "Create New Case"}
        </h1>
        <p className="text-muted-foreground">
          {lang === "ar" ? "املأ تفاصيل الحالة" : "Fill in the case details"}
        </p>
      </div>

      <form onSubmit={handleSubmit}>
        {showBasicDetails && (
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات الحالة" : "Case Information"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "التفاصيل الأساسية حول الحالة"
                  : "Basic details about the case"}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="name">
                  {lang === "ar" ? "اسم الحالة" : "Case Name"}
                </Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  required
                />
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="date_of_birth">
                    {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                  </Label>
                  <DateInput
                    id="date_of_birth"
                    value={formData.date_of_birth}
                    onChange={(v) =>
                      setFormData({ ...formData, date_of_birth: v })
                    }
                    maxDate={new Date()}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="gender">
                    {lang === "ar" ? "الجنس" : "Gender"}
                  </Label>
                  <Select
                    value={formData.gender}
                    onValueChange={(value) =>
                      setFormData({ ...formData, gender: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue
                        placeholder={
                          lang === "ar" ? "اختر الجنس" : "Select gender"
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="male">
                        {lang === "ar" ? "ذكر" : "Male"}
                      </SelectItem>
                      <SelectItem value="female">
                        {lang === "ar" ? "أنثى" : "Female"}
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="grade">
                  {lang === "ar" ? "الصف الدراسي" : "Grade"}
                </Label>
                <Select
                  value={formData.grade}
                  onValueChange={(value) =>
                    setFormData({ ...formData, grade: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={lang === "ar" ? "اختر الصف" : "Select grade"}
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {GRADES.map((grade) => (
                      <SelectItem key={grade.value} value={grade.value}>
                        {grade.label[lang]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>
        )}

        <Card className={showBasicDetails ? "mt-6" : ""}>
          <CardHeader>
            <CardTitle>
              {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Select the service this case belongs to",
                  ar: "اختر الخدمة التي تنتمي إليها هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>
                {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
                <span className="text-red-500 ms-1">*</span>
              </Label>
              <Select
                value={portalService.categoryId}
                onValueChange={handleServiceTypeChange}
              >
                <SelectTrigger>
                  <SelectValue
                    placeholder={t(
                      { en: "Select service type", ar: "اختر نوع الخدمة" },
                      lang
                    )}
                  />
                </SelectTrigger>
                <SelectContent>
                  {PORTALS.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {lang === "ar"
                        ? p.portalName.ar.replace(/^بوابة /, "")
                        : p.title.en}
                    </SelectItem>
                  ))}
                  <SelectItem value={TRAINING_SERVICE_ID}>
                    {t(
                      { en: "Attending Training", ar: "حضور تدريب" },
                      lang
                    )}
                  </SelectItem>
                  <SelectItem value={OTHER_VALUE}>
                    {t({ en: "Other", ar: "أخرى" }, lang)}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {isTrainingSelected ? (
              <div className="space-y-2">
                <Label>
                  {t({ en: "Case Type", ar: "نوع الحالة" }, lang)}
                  <span className="text-red-500 ms-1">*</span>
                </Label>
                <Select
                  value={selectedProgramId}
                  onValueChange={handleCaseTypeChange}
                  disabled={trainingProgramsLoading}
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={
                        trainingProgramsLoading
                          ? t(
                              { en: "Loading...", ar: "جاري التحميل..." },
                              lang
                            )
                          : t(
                              {
                                en: "Select a training program",
                                ar: "اختر برنامج تدريبي",
                              },
                              lang
                            )
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {trainingPrograms.length === 0 ? (
                      <SelectItem value="__none__" disabled>
                        {t(
                          {
                            en: "No programs with open enrollment",
                            ar: "لا توجد برامج مفتوحة للتسجيل",
                          },
                          lang
                        )}
                      </SelectItem>
                    ) : (
                      trainingPrograms.map((p) => (
                        <SelectItem key={p.id} value={p.id}>
                          {p.title[lang]}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <>
                {portalService.categoryId === OTHER_VALUE && (
                  <div className="space-y-2">
                    <Label>
                      {t(
                        {
                          en: "Custom service type",
                          ar: "اسم نوع الخدمة المخصص",
                        },
                        lang
                      )}
                      <span className="text-red-500 ms-1">*</span>
                    </Label>
                    <Input
                      value={portalService.customCategory}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          customCategory: e.target.value,
                        })
                      }
                      placeholder={t(
                        { en: "Enter service type", ar: "أدخل اسم نوع الخدمة" },
                        lang
                      )}
                    />
                  </div>
                )}

                {portalService.categoryId && (
                  <div className="space-y-2">
                    <Label>
                      {t({ en: "Issue Type", ar: "نوع المشكلة" }, lang)}
                      <span className="text-red-500 ms-1">*</span>
                    </Label>
                    <Input
                      value={portalService.subCategoryId}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          subCategoryId: e.target.value,
                          customSubCategory: "",
                        })
                      }
                      placeholder={t(
                        { en: "Enter issue type", ar: "أدخل اسم نوع المشكلة" },
                        lang
                      )}
                    />
                  </div>
                )}
              </>
            )}
          </CardContent>
        </Card>

        <Card className="mt-6">
          <CardHeader>
            <CardTitle>
              {t({ en: "Explain more", ar: "اشرح أكثر" }, lang)}  <span className="text-red-500 ms-1">*</span>
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Add any extra context that will help us handle this case",
                  ar: "أضف أي سياق إضافي يساعدنا في التعامل مع هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Textarea
                id="notes"
                value={formData.notes}
                required
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
                placeholder={t(
                  {
                    en: "Provide more details about the case...",
                    ar: "قدم مزيداً من التفاصيل حول الحالة...",
                  },
                  lang
                )}
                rows={4}
              />
            </div>
          </CardContent>
        </Card>

        <div className="mt-6 flex justify-end gap-4">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            {lang === "ar" ? "إلغاء" : "Cancel"}
          </Button>
          <Button
            type="submit"
            disabled={
              isSubmitting ||
              (isTrainingSelected && !selectedProgramId)
            }
          >
            {isSubmitting
              ? lang === "ar"
                ? "جارٍ الإنشاء..."
                : "Creating..."
              : lang === "ar"
                ? "إنشاء الحالة"
                : "Create Case"}
          </Button>
        </div>
      </form>
    </div>
  )
}

