                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
