                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
