  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if ((isPlanTool || isReportTool) && (assignment.config as unknown as Record<string, unknown>)?.templateWorkflow === true) return <TemplateResponse key={assignment.id} task={assignment} kind={toolTypeName} readOnly={isAdminOrExpert} save={updateAssignment} />

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground"><CaseName profile={profile} /></p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {surveyOptionLabel(opt, lang)}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                  </p>
                </div>
                {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الرابط" : "Meeting Link"}
                    </Label>
                    <div className="mt-1">
                      <a
                        href={meetingConfig.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button variant="default" size="sm">
                          {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                        </Button>
                      </a>
                    </div>
                  </div>
                )}
                {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الموقع" : "Location"}
                    </Label>
                    <p className="font-medium">{meetingConfig.location}</p>
                  </div>
                )}

                {isAdminOrExpert ? (
                  <div className="space-y-2 rounded-lg border p-3">
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                    </Label>
                    <textarea
                      value={localNotes}
                      onChange={(e) => setLocalNotes(e.target.value)}
                      placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                      className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      rows={3}
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          id="notes-visible-completed"
                          checked={localNotesVisible}
                          onChange={(e) => setLocalNotesVisible(e.target.checked)}
                          className="h-4 w-4 rounded border-gray-300"
                        />
                        <Label htmlFor="notes-visible-completed" className="text-sm text-muted-foreground">
                          {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                        </Label>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={saveNotes}
                        disabled={isSavingNotes}
                      >
                        {isSavingNotes
                          ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                          : lang === "ar" ? "حفظ" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                  </div>
                ) : null}
              </div>
            )}

            {isReportTool && reportConfig && (
              <div className="space-y-3">
                {reportConfig.date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{formatDate(reportConfig.date)}</p>
                  </div>
                )}
                {reportConfig.assessment && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التقييم" : "Assessment"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                  </div>
                )}
                {reportConfig.suggestions && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                  </div>
                )}
              </div>
            )}

            {isPlanTool && planConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                    </Label>
                    <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                    </Label>
                    <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                  </div>
                </div>
                {planConfig.goals?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.goals.map((goal) => (
                        <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                          <p className="font-medium">{goal.title}</p>
                          {goal.description && (
                            <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {planConfig.steps?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الخطوات" : "Steps"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.steps.map((step) => (
                        <div key={step.id} className="rounded-lg border p-3">
                          <div className="flex items-start gap-2">
                            <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                            <div className="flex-1">
                              <p className="font-medium">{step.title}</p>
                              {step.description && (
                                <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {(isMeetingTool || isReportTool || isPlanTool) && (
              <div className="flex gap-2 pt-4">
                <Button
                  onClick={() => router.push(`/dashboard/parent/cases/${profile.id}`)}
                >
                  {lang === "ar" ? "العودة" : "Back"}
                </Button>
              </div>
            )}

            {!isMeetingTool && !isReportTool && !isPlanTool && (
            <div className="flex gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() =>
                  updateAssignment(assignmentId, { status: "in_progress" })
                }
              >
                {lang === "ar" ? "تعديل الإجابات" : "Edit Answers"}
              </Button>
              <Button
                onClick={() => router.push(`/dashboard/parent/cases/${profile.id}`)}
              >
                {lang === "ar" ? "العودة" : "Back"}
              </Button>
            </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
          <p className="text-muted-foreground"><CaseName profile={profile} /></p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{assignment.name_en}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {isSurveyTool &&
            (() => {
              const sortedOptions = [...(surveyConfig?.options || [])].sort(
                (a, b) => a.order - b.order
              )
              const isMultiple = surveyConfig?.answerType === "multiple_choice"
              return (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                        <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                          {lang === "ar" ? "الأسئلة" : "Questions"}
                        </th>
                        {sortedOptions.map((opt) => (
                          <th
                            key={opt.id}
                            className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                          >
                            {surveyOptionLabel(opt, lang)}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {surveyConfig?.questions.map((question) => {
                        const value = answers[question.id] as
                          | string
                          | string[]
                          | undefined
                        const hasError = errors.includes(question.id)
                        return (
                          <tr key={question.id}>
                            <td className="py-3 pe-4 align-top">
                              <Label className="text-base font-medium">
                                {question.text}
                                {question.required && (
                                  <span className="ms-1 text-destructive">
                                    *
                                  </span>
                                )}
                              </Label>
                            </td>
                            {sortedOptions.map((opt) => (
                              <td
                                key={opt.id}
                                className="px-2 py-3 text-center"
                              >
                                {isMultiple ? (
                                  <Checkbox
                                    id={`${question.id}-${opt.id}`}
                                    checked={(
                                      (value as string[]) || []
                                    ).includes(opt.value)}
                                    onCheckedChange={(checked) => {
                                      if (checked) {
                                        handleAnswer(question.id, [
                                          ...((value as string[]) || []),
                                          opt.value,
                                        ])
                                      } else {
                                        handleAnswer(
                                          question.id,
                                          ((value as string[]) || []).filter(
                                            (v) => v !== opt.value
                                          )
                                        )
                                      }
                                    }}
                                    className="mx-auto"
                                  />
                                ) : (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      handleAnswer(question.id, opt.value)
                                    }
                                    className={`mx-auto h-5 w-5 rounded-full border-2 transition-colors ${
                                      (value as string) === opt.value
                                        ? "border-primary bg-primary"
                                        : "border-muted-foreground hover:border-primary"
                                    }`}
                                  />
                                )}
                              </td>
                            ))}
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                  {errors.some((errId) =>
                    surveyConfig?.questions.find((q) => q.id === errId)
                  ) && (
                    <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
                      <AlertCircle className="h-4 w-4" />
                      {lang === "ar"
                        ? "يرجى الإجابة على جميع الأسئلة المطلوبة"
                        : "Please answer all required questions"}
                    </div>
                  )}
                </div>
              )
            })()}

          {isMultipleChoiceTool &&
            mcConfig?.questions.map((question) => (
              <div key={question.id}>{renderMCQuestion(question)}</div>
            ))}

          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import pb from "@/lib/pb"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { DateInput } from "@/components/ui/date-input"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useLang } from "@/lib/lang-context"
import { t } from "@/lib/i18n"
import { usePortals } from "@/hooks/usePortals"
import { trainingProgramsCollection } from "@/lib/pb-training"
import type { TrainingProgram } from "@/types/training"
import { type PortalServiceValue } from "@/components/register/PortalServiceSelector"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

const OTHER_VALUE = "other"
const TRAINING_SERVICE_ID = "attending-training"
const PARENT_SERVICE_IDS = new Set(["1", "2", "4"])

const GRADES = [
  { value: "kg1", label: { en: "KG 1", ar: "روضة 1" } },
  { value: "kg2", label: { en: "KG 2", ar: "روضة 2" } },
  { value: "grade1", label: { en: "Grade 1", ar: "الصف الأول" } },
  { value: "grade2", label: { en: "Grade 2", ar: "الصف الثاني" } },
  { value: "grade3", label: { en: "Grade 3", ar: "الصف الثالث" } },
  { value: "grade4", label: { en: "Grade 4", ar: "الصف الرابع" } },
  { value: "grade5", label: { en: "Grade 5", ar: "الصف الخامس" } },
  { value: "grade6", label: { en: "Grade 6", ar: "الصف السادس" } },
  { value: "grade7", label: { en: "Grade 7", ar: "الصف السابع" } },
  { value: "grade8", label: { en: "Grade 8", ar: "الصف الثامن" } },
  { value: "grade9", label: { en: "Grade 9", ar: "الصف التاسع" } },
  { value: "grade10", label: { en: "Grade 10", ar: "الصف العاشر" } },
  { value: "grade11", label: { en: "Grade 11", ar: "الصف الحادي عشر" } },
  { value: "grade12", label: { en: "Grade 12", ar: "الصف الثاني عشر" } },
  { value: "university", label: { en: "University", ar: "الجامعة" } },
]

export default function NewProfilePage() {
  const router = useRouter()
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const { portals: PORTALS } = usePortals()
  const { addProfile } = useProfiles()
  const isParent = currentUser?.role === "parent"
  const servicePortals = isParent ? PORTALS.filter(portal => PARENT_SERVICE_IDS.has(portal.id)) : PORTALS
  const [isSubmitting, setIsSubmitting] = useState(false)

  const [formData, setFormData] = useState({
    name: "",
    date_of_birth: "",
    gender: "",
    grade: "",
    relationship: "",
    notes: "",
  })

  const [portalService, setPortalService] = useState<PortalServiceValue>({
    categoryId: "",
    subCategoryId: "",
    customCategory: "",
    customSubCategory: "",
  })

  const [trainingPrograms, setTrainingPrograms] = useState<TrainingProgram[]>(
    []
  )
  const [trainingProgramsLoading, setTrainingProgramsLoading] = useState(false)
  const [selectedProgramId, setSelectedProgramId] = useState("")

  const isTrainingSelected =
    portalService.categoryId === TRAINING_SERVICE_ID ||
    portalService.subCategoryId === TRAINING_SERVICE_ID

  const isIndividual = currentUser?.role === "individual"
  const showBasicDetails = !isIndividual

  useEffect(() => {
    if (!isTrainingSelected) {
      setSelectedProgramId("")
      setTrainingPrograms([])
      return
    }
    let cancelled = false
    setTrainingProgramsLoading(true)
    trainingProgramsCollection
      .getPublished()
      .then((data) => {
        if (cancelled) return
        const today = new Date().toISOString().slice(0, 10)
        const running = data
          .filter((p) => today <= p.schedule.endDate)
          .sort((a, b) => (a.schedule.endDate < b.schedule.endDate ? -1 : 1))
        setTrainingPrograms(running)
      })
      .catch((err) => {
        console.error("Failed to load training programs:", err)
      })
      .finally(() => {
        if (!cancelled) setTrainingProgramsLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [isTrainingSelected])

  const handleServiceTypeChange = (value: string) => {
    if (value === TRAINING_SERVICE_ID) {
      setPortalService({
        categoryId: TRAINING_SERVICE_ID,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    } else {
      setPortalService({
        categoryId: value,
        subCategoryId: "",
        customCategory: "",
        customSubCategory: "",
      })
    }
  }

  const handleCaseTypeChange = (value: string) => {
    if (isTrainingSelected) {
      setSelectedProgramId(value)
    } else {
      setPortalService({
        ...portalService,
        subCategoryId: value,
      })
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentUser) return
    if (isParent && !PARENT_SERVICE_IDS.has(portalService.categoryId)) {
      toast.error(lang === "ar"
        ? "اختر الاحتياجات الخاصة أو الصحة النفسية أو التعليم والابتكار."
        : "Choose Special Needs, Mental Health, or Education and Innovation.")
      return
    }

    if (
      ["parent", "care_foundation"].includes(currentUser.role) &&
      (!formData.name.trim() ||
        !formData.date_of_birth ||
        !["male", "female"].includes(formData.gender))
    ) {
      toast.error(
        lang === "ar"
          ? "اسم الطفل وتاريخ الميلاد والجنس حقول مطلوبة."
          : "Child name, date of birth and gender are required."
      )
      return
    }
    setIsSubmitting(true)

    try {
      const isTraining = isTrainingSelected && selectedProgramId
      const selectedProgram = isTraining
        ? trainingPrograms.find((p) => p.id === selectedProgramId)
        : null

      const profileId = await addProfile({
        user: currentUser.id,
        name:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? selectedProgram?.title[lang] ||
              (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
            : formData.name,
        date_of_birth:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? ""
            : formData.date_of_birth,
        gender:
          isTraining && !["parent", "care_foundation"].includes(currentUser.role)
            ? undefined
            : (formData.gender as "male" | "female"),
        grade: isTraining ? "" : formData.grade,
        relationship: isTraining ? undefined : formData.relationship,
        notes: formData.notes,
        portal_type: isTraining
          ? "Attending Training"
          : portalService.categoryId,
        service_type: isTraining
          ? selectedProgram?.title[lang]
          : portalService.subCategoryId.trim(),
        program_id: isTraining ? selectedProgramId : undefined,
        training_link: isTraining
          ? selectedProgram?.meetingLink ||
            `/programmes/training_programmes/${selectedProgramId}`
          : undefined,
        program_status: isTraining ? "enrolled" : undefined,
        status: "pending",
        user_details: isTraining
          ? {
              name: currentUser.name,
              email: currentUser.email,
              contact: currentUser.contact_number,
            }
          : undefined,
        case_details: isTraining
          ? undefined
          : {
              custom_category:
                portalService.categoryId === OTHER_VALUE
                  ? portalService.customCategory
                  : undefined,
              custom_sub_category:
                portalService.subCategoryId.trim() || undefined,
            },
      })

      const caseName = isTraining
        ? selectedProgram?.title[lang] ||
          (lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment")
        : formData.name

      fetch("/api/telegram-notify", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${pb.authStore.token}`,
        },
        body: JSON.stringify({
          text: [
            "*New Case Needs Payment Amount*",
            "",
            `*Case:* ${caseName}`,
            `*User:* ${currentUser.name} (${currentUser.email})`,
            `*Service:* ${portalService.subCategoryId || portalService.categoryId || "-"}`,
          ].join("\n"),
        }),
      }).catch(() => {})

      router.push(`/dashboard/parent/cases/${profileId}`)
    } catch (error) {
      console.error("Failed to create profile:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-primary">
          {lang === "ar" ? "إنشاء حالة جديدة" : "Create New Case"}
        </h1>
        <p className="text-muted-foreground">
          {lang === "ar" ? "املأ تفاصيل الحالة" : "Fill in the case details"}
        </p>
      </div>

      <form onSubmit={handleSubmit}>
        {showBasicDetails && (
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات الحالة" : "Case Information"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "التفاصيل الأساسية حول الحالة"
                  : "Basic details about the case"}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="name">
                  {lang === "ar" ? "اسم الطفل *" : "Child Name *"}
                </Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  required
                />
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="date_of_birth">
                    {lang === "ar" ? "تاريخ الميلاد *" : "Date of Birth *"}
                  </Label>
                  <DateInput
                    id="date_of_birth"
                    value={formData.date_of_birth}
                    onChange={(v) =>
                      setFormData({ ...formData, date_of_birth: v })
                    }
                    maxDate={new Date()}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="gender">
                    {lang === "ar" ? "الجنس *" : "Gender *"}
                  </Label>
                  <Select
                    required
                    value={formData.gender}
                    onValueChange={(value) =>
                      setFormData({ ...formData, gender: value })
                    }
                  >
                    <SelectTrigger id="gender" aria-required="true">
                      <SelectValue
                        placeholder={
                          lang === "ar" ? "اختر الجنس" : "Select gender"
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="male">
                        {lang === "ar" ? "ذكر" : "Male"}
                      </SelectItem>
                      <SelectItem value="female">
                        {lang === "ar" ? "أنثى" : "Female"}
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="grade">
                  {lang === "ar" ? "الصف الدراسي" : "Grade"}
                </Label>
                <Select
                  value={formData.grade}
                  onValueChange={(value) =>
                    setFormData({ ...formData, grade: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={lang === "ar" ? "اختر الصف" : "Select grade"}
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {GRADES.map((grade) => (
                      <SelectItem key={grade.value} value={grade.value}>
                        {grade.label[lang]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="relationship">
                  {lang === "ar"
                    ? (currentUser?.role === "care_foundation" ? "صفة الإشراف على الطفل" : "صلة القرابة بالطفل")
                    : (currentUser?.role === "care_foundation" ? "Supervisory Relationship" : "Relationship to Child")}
                  <span className="ml-1 text-red-500">*</span>
                </Label>
                <Input
                  id="relationship"
                  value={formData.relationship}
                  onChange={(e) =>
                    setFormData({ ...formData, relationship: e.target.value })
                  }
                  placeholder={currentUser?.role === "care_foundation" ? (lang === "ar" ? "مثال: مؤسسة مشرفة" : "e.g. Supervising foundation") : (lang === "ar" ? "مثال: أب" : "e.g. Father")}
                  required
                />
              </div>
            </CardContent>
          </Card>
        )}

        <Card className={showBasicDetails ? "mt-6" : ""}>
          <CardHeader>
            <CardTitle>
              {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Select the service this case belongs to",
                  ar: "اختر الخدمة التي تنتمي إليها هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>
                {t({ en: "Service Type", ar: "نوع الخدمة" }, lang)}
                <span className="ms-1 text-red-500">*</span>
              </Label>
              <Select
                value={portalService.categoryId}
                onValueChange={handleServiceTypeChange}
              >
                <SelectTrigger>
                  <SelectValue
                    placeholder={t(
                      { en: "Select service type", ar: "اختر نوع الخدمة" },
                      lang
                    )}
                  />
                </SelectTrigger>
                <SelectContent>
                  {servicePortals.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {lang === "ar"
                        ? p.portalName.ar.replace(/^بوابة /, "")
                        : p.title.en}
                    </SelectItem>
                  ))}
                  {!isParent && (<>
                  <SelectItem value={TRAINING_SERVICE_ID}>
                    {t({ en: "Attending Training", ar: "حضور تدريب" }, lang)}
                  </SelectItem>
                  <SelectItem value={OTHER_VALUE}>
                    {t({ en: "Other", ar: "أخرى" }, lang)}
                  </SelectItem>
                  </>)}
                </SelectContent>
              </Select>
            </div>

            {isTrainingSelected ? (
              <div className="space-y-2">
                <Label>
                  {t({ en: "Case Type", ar: "نوع الحالة" }, lang)}
                  <span className="ms-1 text-red-500">*</span>
                </Label>
                <Select
                  value={selectedProgramId}
                  onValueChange={handleCaseTypeChange}
                  disabled={trainingProgramsLoading}
                >
                  <SelectTrigger>
                    <SelectValue
                      placeholder={
                        trainingProgramsLoading
                          ? t({ en: "Loading...", ar: "جاري التحميل..." }, lang)
                          : t(
                              {
                                en: "Select a training program",
                                ar: "اختر برنامج تدريبي",
                              },
                              lang
                            )
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {trainingPrograms.length === 0 ? (
                      <SelectItem value="__none__" disabled>
                        {t(
                          {
                            en: "No programs with open enrollment",
                            ar: "لا توجد برامج مفتوحة للتسجيل",
                          },
                          lang
                        )}
                      </SelectItem>
                    ) : (
                      trainingPrograms.map((p) => (
                        <SelectItem key={p.id} value={p.id}>
                          {p.title[lang]}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <>
                {portalService.categoryId === OTHER_VALUE && (
                  <div className="space-y-2">
                    <Label>
                      {t(
                        {
                          en: "Custom service type",
                          ar: "اسم نوع الخدمة المخصص",
                        },
                        lang
                      )}
                      <span className="ms-1 text-red-500">*</span>
                    </Label>
                    <Input
                      value={portalService.customCategory}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          customCategory: e.target.value,
                        })
                      }
                      placeholder={t(
                        { en: "Enter service type", ar: "أدخل اسم نوع الخدمة" },
                        lang
                      )}
                    />
                  </div>
                )}

                {portalService.categoryId && (
                  <div className="space-y-2">
                    <Label>
                      {t({ en: "Issue Type", ar: "نوع المشكلة" }, lang)}
                      <span className="ms-1 text-red-500">*</span>
                    </Label>
                    <Input
                      value={portalService.subCategoryId}
                      onChange={(e) =>
                        setPortalService({
                          ...portalService,
                          subCategoryId: e.target.value,
                          customSubCategory: "",
                        })
                      }
                      placeholder={t(
                        { en: "Enter issue type", ar: "أدخل اسم نوع المشكلة" },
                        lang
                      )}
                    />
                  </div>
                )}
              </>
            )}
          </CardContent>
        </Card>

        <Card className="mt-6">
          <CardHeader>
            <CardTitle>
              {t({ en: "Explain more", ar: "اشرح أكثر" }, lang)}{" "}
              <span className="ms-1 text-red-500">*</span>
            </CardTitle>
            <CardDescription>
              {t(
                {
                  en: "Add any extra context that will help us handle this case",
                  ar: "أضف أي سياق إضافي يساعدنا في التعامل مع هذه الحالة",
                },
                lang
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Textarea
                id="notes"
                value={formData.notes}
                required
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
                placeholder={t(
                  {
                    en: "Provide more details about the case...",
                    ar: "قدم مزيداً من التفاصيل حول الحالة...",
                  },
                  lang
                )}
                rows={4}
              />
            </div>
          </CardContent>
        </Card>

        <div className="mt-6 flex justify-end gap-4">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            {lang === "ar" ? "إلغاء" : "Cancel"}
          </Button>
          <Button
            type="submit"
            disabled={
              isSubmitting || (isTrainingSelected && !selectedProgramId)
            }
          >
            {isSubmitting
              ? lang === "ar"
                ? "جارٍ الإنشاء..."
                : "Creating..."
              : lang === "ar"
                ? "إنشاء الحالة"
                : "Create Case"}
          </Button>
        </div>
      </form>
    </div>
  )
}

"use client"


import Link from "next/link"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { ProfileCard } from "@/components/profiles/ProfileCard"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { PageLoader } from "@/components/ui/page-loader"
import { FolderKanban, Plus } from "lucide-react"

export default function ProfilesPage() {
  const router = useRouter()
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const { profiles, isLoading } = useProfiles()

  if (isLoading) {
    return <PageLoader text={lang === "ar" ? "جارٍ تحميل الحالات..." : "Loading cases..."} />
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "الحالات" : "Cases"}
          </h1>
          <p className="text-muted-foreground">
            {currentUser?.role === "care_foundation"
              ? (lang === "ar" ? "إدارة الحالات تحت رعاية المؤسسة" : "Manage cases under the foundation’s care")
              : (lang === "ar" ? "إدارة حالاتك" : "Manage your cases")}
          </p>
        </div>
        <Link href="/dashboard/parent/cases/new">
          <Button>
            <Plus className="me-2 h-4 w-4" />
            {lang === "ar" ? "إضافة حالة" : "Add Case"}
          </Button>
        </Link>
      </div>

      {profiles.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <FolderKanban className="mb-4 h-12 w-12 text-muted-foreground" />
            <h3 className="mb-2 text-lg font-medium">
              {lang === "ar" ? "لا توجد حالات بعد" : "No cases yet"}
            </h3>
            <p className="mb-4 text-center text-muted-foreground">
              {lang === "ar"
                ? "أضف أول حالة للبدء"
                : "Add the first case to get started"}
            </p>
            <Link href="/dashboard/parent/cases/new">
              <Button>{lang === "ar" ? "إضافة حالة" : "Add Case"}</Button>
            </Link>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {profiles.map((profile) => (
            <ProfileCard
              key={profile.id}
              profile={profile}
              hrefPrefix="/dashboard/parent/cases"
            />
          ))}
        </div>
      )}
    </div>
  )
}

