"use client"

import { useState, useEffect, useRef, use } from "react"
import { useRouter } from "next/navigation"
import Image from "next/image"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { EmailInput } from "@/components/ui/email-input"
import { PasswordInput } from "@/components/ui/password-input"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import { PageNotFound } from "@/components/PageNotFound"
import { trainingProgramsCollection } from "@/lib/pb-training"
import { casesCollection } from "@/lib/pb-collections"
import pb, { authWithPassword, getErrorMessage } from "@/lib/pb"
import { useAuth } from "@/hooks/useAuth"
import type { TrainingProgram } from "@/types/training"
import {
  EMAIL_INVALID_MESSAGE,
  isValidEmail,
  normalizeEmail,
} from "@/lib/validators"
import {
  ArrowLeft,
  Calendar,
  Clock,
  MapPin,
  Users,
  ExternalLink,
  User,
  BookOpen,
  AlertCircle,
  CheckCircle,
} from "lucide-react"
import { toast } from "sonner"

const typeLabels = {
  online: { en: "Online", ar: "عبر الشبكة" },
  in_person: { en: "In-Person", ar: "حضوري" },
  hybrid: { en: "Hybrid", ar: "حضوري وعبر الشبكة" },
}

const statusLabels = {
  draft: { en: "Draft", ar: "مسودة" },
  published: { en: "Published", ar: "منشور" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
  cancelled: { en: "Cancelled", ar: "ملغي" },
}

interface EnrollmentFormState {
  name: string
  email: string
  password: string
  confirmPassword: string
  contactNumber: string
  dateOfBirth: string
  gender: "male" | "female"
  grade: string
  notes: string
}

const initialEnrollmentForm: EnrollmentFormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  contactNumber: "",
  dateOfBirth: "",
  gender: "male",
  grade: "",
  notes: "",
}

export default function TrainingProgrammeDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const router = useRouter()
  const submissionKey = useRef(crypto.randomUUID())
  const { lang } = useLang()
  const { currentUser } = useAuth()
  const [program, setProgram] = useState<TrainingProgram | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  const [enrolledCaseId, setEnrolledCaseId] = useState<string | null>(null)
  const [enrollError, setEnrollError] = useState<string>("")
  const [enrollSuccess, setEnrollSuccess] = useState<string>("")
  const [isEnrolleeChecking, setIsEnrolleeChecking] = useState(true)
  const [isEnrolling, setIsEnrolling] = useState(false)
  const [enrollForm, setEnrollForm] = useState<EnrollmentFormState>(
    initialEnrollmentForm
  )

  useEffect(() => {
    const load = async () => {
      try {
        const data = await trainingProgramsCollection.getById(id)
        setProgram(data)
      } catch (err) {
        console.error("Failed to load programme:", err)
        toast.error(getErrorMessage(err))
      } finally {
        setIsLoading(false)
      }
    }
    load()
  }, [id])

  useEffect(() => {
    if (!currentUser) {
      setIsEnrolleeChecking(false)
      return
    }
    const checkExisting = async () => {
      try {
        const mine = await casesCollection.getByUser(currentUser.id)
        const existing = mine.find(
          (c) => c.program_id === id && c.portal_type === "Attending Training"
        )
        if (existing) {
          setEnrolledCaseId(existing.id)
        }
      } catch (err) {
        console.error("Failed to check existing enrollment:", err)
        toast.error(getErrorMessage(err))
      } finally {
        setIsEnrolleeChecking(false)
      }
    }
    checkExisting()
  }, [currentUser, id])

  const validateEnrollmentForm = (): string | null => {
    if (!enrollForm.name.trim()) {
      return lang === "ar" ? "الاسم مطلوب" : "Name is required"
    }
    if (!enrollForm.email.trim()) {
      return lang === "ar" ? "البريد الإلكتروني مطلوب" : "Email is required"
    }
    if (!isValidEmail(enrollForm.email)) {
      return lang === "ar"
        ? "يرجى إدخال بريد إلكتروني صحيح"
        : EMAIL_INVALID_MESSAGE.en
    }
    if (!enrollForm.password) {
      return lang === "ar" ? "كلمة المرور مطلوبة" : "Password is required"
    }
    if (enrollForm.password !== enrollForm.confirmPassword) {
      return lang === "ar"
        ? "كلمات المرور غير متطابقة"
        : "Passwords do not match"
    }
    if (enrollForm.password.length < 8) {
      return lang === "ar"
        ? "كلمة المرور قصيرة جداً (8 أحرف على الأقل)"
        : "Password is too short (min 8 characters)"
    }
    return null
  }

  const handleEnrollAsGuest = async () => {
    setEnrollError("")
    setEnrollSuccess("")

    const validationError = validateEnrollmentForm()
    if (validationError) {
      setEnrollError(validationError)
      return
    }

    if (!program) return

    setIsEnrolling(true)
    try {
      const cleanName = enrollForm.name.trim()
      const cleanEmail = normalizeEmail(enrollForm.email)
      const cleanContact = enrollForm.contactNumber.trim()

      await pb.send("/api/dsc/register", {
        method: "POST",
        body: {
          submission_key: submissionKey.current,
          program_id: id,
          user: {
            email: cleanEmail,
            password: enrollForm.password,
            passwordConfirm: enrollForm.confirmPassword,
            name: cleanName,
            contact_number: cleanContact,
            role: "individual",
          },
          profile: {
            collection: "individual_profiles",
            gender: enrollForm.gender,
            date_of_birth: enrollForm.dateOfBirth,
            notes: enrollForm.notes,
          },
          cases: [],
        },
      })

      await authWithPassword(cleanEmail, enrollForm.password)

      setEnrollSuccess(
        lang === "ar"
          ? "تم التسجيل بنجاح! مرحباً بك."
          : "Enrollment successful! Welcome."
      )
      setEnrollForm(initialEnrollmentForm)
    } catch (err) {
      setEnrollError(getErrorMessage(err))
    } finally {
      setIsEnrolling(false)
    }
  }

  const handleEnrollAsUser = async () => {
    if (!currentUser) return
    if (!program) return
    setEnrollError("")
    setEnrollSuccess("")
    setIsEnrolling(true)
    try {
      const created = await pb.send<{ id: string }>(
        `/api/dsc/programs/${id}/enroll`,
        { method: "POST" }
      )
      setEnrolledCaseId(created.id)
      setEnrollSuccess(
        lang === "ar"
          ? "تم التسجيل بنجاح!"
          : "You have been enrolled successfully!"
      )
    } catch (err) {
      setEnrollError(getErrorMessage(err))
    } finally {
      setIsEnrolling(false)
    }
  }

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-center py-12">
          <p className="text-muted-foreground">
            {lang === "ar" ? "جاري التحميل..." : "Loading..."}
          </p>
        </div>
      </div>
    )
  }

  if (!program) {
    return <PageNotFound lang={lang} />
  }

  const isPast = new Date(program.schedule.endDate) < new Date()
  const isFull = !!(
    program.maxParticipants &&
    program.currentRegistrations >= program.maxParticipants
  )

  const renderEnrollmentCard = () => {
    if (isPast) {
      return (
        <Card>
          <CardContent className="pt-6">
            <Badge variant="secondary" className="w-full justify-center py-2">
              {lang === "ar"
                ? "انتهى هذا البرنامج"
                : "This programme has ended"}
            </Badge>
          </CardContent>
        </Card>
      )
    }

    if (isFull) {
      return (
        <Card>
          <CardHeader>
            <CardTitle>{lang === "ar" ? "التسجيل" : "Enrollment"}</CardTitle>
          </CardHeader>
          <CardContent>
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                {lang === "ar"
                  ? "عذراً، هذا البرنامج ممتلئ."
                  : "Sorry, this programme is full."}
              </AlertDescription>
            </Alert>
          </CardContent>
        </Card>
      )
    }

    if (isEnrolleeChecking) {
      return (
        <Card>
          <CardContent className="pt-6">
            <p className="text-sm text-muted-foreground">
              {lang === "ar" ? "جاري التحقق..." : "Checking..."}
            </p>
          </CardContent>
        </Card>
      )
    }

    if (enrolledCaseId || enrollSuccess) {
      return (
        <Card>
          <CardHeader>
            <CardTitle>
              {lang === "ar" ? "حالة التسجيل" : "Enrollment Status"}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Alert>
              <CheckCircle className="h-4 w-4" />
              <AlertDescription>
                {enrollSuccess ||
                  (lang === "ar"
                    ? "أنت مسجل في هذا البرنامج."
                    : "You are enrolled in this programme.")}
              </AlertDescription>
            </Alert>
          </CardContent>
        </Card>
      )
    }

    if (currentUser) {
      return (
        <Card>
          <CardHeader>
            <CardTitle>
              {lang === "ar"
                ? "التسجيل في البرنامج"
                : "Enroll in this programme"}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              {lang === "ar"
                ? `مرحباً ${currentUser.name}، انقر أدناه للتسجيل في هذا البرنامج.`
                : `Hi ${currentUser.name}, click below to enroll in this programme.`}
            </p>
            {enrollError && (
              <Alert variant="destructive">
                <AlertCircle className="h-4 w-4" />
                <AlertDescription>{enrollError}</AlertDescription>
              </Alert>
            )}
            <Button
              className="w-full"
              disabled={isEnrolling}
              onClick={handleEnrollAsUser}
            >
              {isEnrolling
                ? lang === "ar"
                  ? "جاري التسجيل..."
                  : "Enrolling..."
                : lang === "ar"
                  ? "تأكيد التسجيل"
                  : "Confirm Enrollment"}
            </Button>
          </CardContent>
        </Card>
      )
    }

    return (
      <Card>
        <CardHeader>
          <CardTitle>
            {lang === "ar" ? "التسجيل في البرنامج" : "Enroll in this programme"}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? "سيتم إنشاء حساب لك تلقائياً عند التسجيل."
              : "An account will be created for you upon enrollment."}
          </p>
          {enrollError && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>{enrollError}</AlertDescription>
            </Alert>
          )}
          <div className="space-y-2">
            <Label htmlFor="enroll-name">
              {lang === "ar" ? "الاسم الكامل *" : "Full Name *"}
            </Label>
            <Input
              id="enroll-name"
              value={enrollForm.name}
              onChange={(e) =>
                setEnrollForm({ ...enrollForm, name: e.target.value })
              }
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="enroll-email">
              {lang === "ar" ? "البريد الإلكتروني *" : "Email *"}
            </Label>
            <EmailInput
              id="enroll-email"
              value={enrollForm.email}
              onChange={(value) =>
                setEnrollForm({ ...enrollForm, email: value })
              }
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="enroll-contact">
              {lang === "ar" ? "رقم الهاتف" : "Phone Number"}
            </Label>
            <Input
              id="enroll-contact"
              type="tel"
              value={enrollForm.contactNumber}
              onChange={(e) =>
                setEnrollForm({
                  ...enrollForm,
                  contactNumber: e.target.value,
                })
              }
              placeholder={
                lang === "ar" ? "أدخل رقم هاتفك" : "Enter your phone number"
              }
            />
          </div>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="enroll-password">
                {lang === "ar" ? "كلمة المرور *" : "Password *"}
              </Label>
              <PasswordInput
                id="enroll-password"
                value={enrollForm.password}
                onChange={(e) =>
                  setEnrollForm({ ...enrollForm, password: e.target.value })
                }
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="enroll-confirm">
                {lang === "ar" ? "تأكيد كلمة المرور *" : "Confirm Password *"}
              </Label>
              <PasswordInput
                id="enroll-confirm"
                value={enrollForm.confirmPassword}
                onChange={(e) =>
                  setEnrollForm({
                    ...enrollForm,
                    confirmPassword: e.target.value,
                  })
                }
                required
              />
            </div>
          </div>

          <Button
            className="w-full"
            disabled={isEnrolling}
            onClick={handleEnrollAsGuest}
          >
            {isEnrolling
              ? lang === "ar"
                ? "جاري التسجيل..."
                : "Enrolling..."
              : lang === "ar"
                ? "إنشاء حساب والتسجيل"
                : "Create Account & Enroll"}
          </Button>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="container mx-auto space-y-6 px-4 py-8">
      <Button
        variant="ghost"
        className="mb-4"
        onClick={() => router.push("/programmes/training_programmes")}
      >
        <ArrowLeft className="me-2 h-4 w-4" />
        {lang === "ar"
          ? "العودة إلى البرامج التدريبية"
          : "Back to training programmes"}
      </Button>

      {program.thumbnail && (
        <div className="relative h-64 w-full overflow-hidden rounded-lg bg-muted md:h-80">
          <Image
            src={program.thumbnail}
            alt={program.title[lang]}
            fill
            className="object-cover"
            priority
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
          <div className="absolute right-0 bottom-0 left-0 p-6 text-white">
            <h1 className="mb-2 text-3xl font-bold">{program.title[lang]}</h1>
            <p className="text-lg text-white/90">
              {program.trainer.name[lang]}
            </p>
          </div>
        </div>
      )}

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="space-y-6 lg:col-span-2">
          {!program.thumbnail && (
            <Card>
              <CardHeader>
                <h1 className="text-3xl font-bold">{program.title[lang]}</h1>
                <p className="text-lg text-muted-foreground">
                  {program.trainer.name[lang]}
                </p>
              </CardHeader>
            </Card>
          )}

          {program.goals && (
            <Card>
              <CardHeader>
                <CardTitle>
                  {lang === "ar" ? "عن هذا البرنامج" : "About this programme"}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="leading-relaxed text-muted-foreground">
                  {program.goals[lang]}
                </p>
              </CardContent>
            </Card>
          )}

          {program.notes && (
            <Card>
              <CardHeader>
