// Copies expert users + expert_profiles (and their files) from a source
// PocketBase to a target PocketBase.
//

//
// Add-only and idempotent:
//   - users are matched by email (existing emails are skipped)
//   - profiles are matched by the linked user id
//
// Flags:
//   --dry-run   print what would happen without writing anything
//
// Notes:
//   - Password hashes cannot be exported; copied users get TEMP_PASSWORD.
//   - The orphan prod profile (user="") is skipped.
//   - age_group (array) -> json field; client_type (array) -> ", "-joined text.

import { fileURLToPath } from "node:url"

const args = process.argv.slice(2)
const DRY_RUN = args.includes("--dry-run") || process.env.DRY_RUN === "1"

const PROD_URL = (process.env.PROD_URL )
const DEV_URL = (process.env.DEV_URL )
const EMAIL = process.env.PB_ADMIN_EMAIL
const PASSWORD = process.env.PB_ADMIN_PASSWORD
const TEMP_PASSWORD = process.env.TEMP_PASSWORD || "ProdCopy123!"

if (!EMAIL || !PASSWORD) {
  console.error("Set PB_ADMIN_EMAIL and PB_ADMIN_PASSWORD")
  process.exit(1)
}

const stats = {
  usersCreated: 0,
  usersSkipped: 0,
  profilesCreated: 0,
  profilesUpdated: 0,
  profilesSkipped: 0,
  filesUploaded: 0,
  errors: [],
}

async function auth(base) {
  const res = await fetch(`${base}/api/collections/_superusers/auth-with-password`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ identity: EMAIL, password: PASSWORD }),
  })
  const data = await res.json()
  if (!data.token) throw new Error(`auth failed for ${base}: ${JSON.stringify(data)}`)
  return data.token
}

function h(token, json = true) {
  return json
    ? { "Content-Type": "application/json", Authorization: token }
    : { Authorization: token }
}

async function listAll(base, token, collection, filter) {
  const out = []
  let page = 1
  for (;;) {
    const q = new URLSearchParams({ page: String(page), perPage: "200" })
    if (filter) q.set("filter", filter)
    const res = await fetch(`${base}/api/collections/${collection}/records?${q}`, {
      headers: h(token, false),
    })
    if (!res.ok) throw new Error(`list ${collection} failed: ${res.status} ${await res.text()}`)
    const data = await res.json()
    out.push(...data.items)
    if (page >= data.totalPages || data.items.length === 0) break
    page++
  }
  return out
}

async function downloadFile(base, token, collection, recordId, filename) {
  const url = `${base}/api/files/${collection}/${recordId}/${encodeURIComponent(filename)}`
  const res = await fetch(url, { headers: h(token, false) })
  if (!res.ok) return null
  return Buffer.from(await res.arrayBuffer())
}

function joinList(value) {
  if (Array.isArray(value)) return value.filter((v) => typeof v === "string" && v).join(", ")
  return typeof value === "string" ? value : ""
}

async function main() {
  console.log(`source: ${PROD_URL}`)
  console.log(`target: ${DEV_URL}`)
  if (DRY_RUN) console.log("mode:   DRY RUN (no writes)")

  const prodToken = await auth(PROD_URL)
  const devToken = await auth(DEV_URL)

  const prodUsers = await listAll(PROD_URL, prodToken, "users", 'role = "expert"')
  const prodProfiles = await listAll(PROD_URL, prodToken, "expert_profiles")
  console.log(`\nprod expert users: ${prodUsers.length}`)
  console.log(`prod expert profiles: ${prodProfiles.length}`)

  const devUsers = await listAll(DEV_URL, devToken, "users", 'role = "expert"')
  const devByEmail = new Map(devUsers.map((u) => [u.email.toLowerCase(), u]))

  // ------------------------------------------------------------------ users
  const devUserIdByProdId = new Map()
  for (const pu of prodUsers) {
    const key = (pu.email || "").toLowerCase()
    const existing = devByEmail.get(key)
    if (existing) {
      devUserIdByProdId.set(pu.id, existing.id)
      stats.usersSkipped++
      console.log(`  = user ${pu.email} (exists)`)
      continue
    }
    if (DRY_RUN) {
      stats.usersCreated++
      devUserIdByProdId.set(pu.id, `dry-run:${pu.id}`)
      console.log(`  + user ${pu.email} (would create)`)
      continue
    }
    try {
      const fd = new FormData()
      fd.set("email", pu.email)
      fd.set("password", TEMP_PASSWORD)
      fd.set("passwordConfirm", TEMP_PASSWORD)
      fd.set("emailVisibility", "true")
      fd.set("verified", "true")
      fd.set("name", pu.name || "")
      fd.set("role", "expert")
      fd.set("is_active", String(pu.is_active === true))
      fd.set("contact_number", pu.contact_number || "")
      if (pu.avatar) {
        const buf = await downloadFile(PROD_URL, prodToken, "users", pu.id, pu.avatar)
        if (buf) {
          fd.set("avatar", new Blob([buf]), pu.avatar)
          stats.filesUploaded++
        }
      }
      const res = await fetch(`${DEV_URL}/api/collections/users/records`, {
        method: "POST",
        headers: h(devToken, false),
        body: fd,
      })
      if (!res.ok) throw new Error(`${res.status} ${(await res.text()).slice(0, 300)}`)
      const created = await res.json()
      devUserIdByProdId.set(pu.id, created.id)
      stats.usersCreated++
      console.log(`  + user ${pu.email}`)
    } catch (err) {
      stats.errors.push(`user ${pu.email}: ${err.message}`)
      console.log(`  ! user ${pu.email}: ${err.message}`)
    }
  }

  // --------------------------------------------------------------- profiles
  const devProfiles = await listAll(DEV_URL, devToken, "expert_profiles")
  const devProfileByUser = new Map(devProfiles.map((p) => [p.user, p]))

  for (const pp of prodProfiles) {
    if (!pp.user) {
      stats.profilesSkipped++
      console.log(`  ~ profile ${pp.id} (orphan, skipped)`)
      continue
    }
    const devUserId = devUserIdByProdId.get(pp.user)
    if (!devUserId) {
      stats.profilesSkipped++
      console.log(`  ~ profile ${pp.id} (no matching dev user, skipped)`)
      continue
    }

    const fields = {
      user: devUserId,
      full_legal_name: pp.full_legal_name || "",
      nationality: pp.nationality || "",
      country_of_residence: pp.country_of_residence || "",
      city: pp.city || "",
      whatsapp_country_code: pp.whatsapp_country_code || "",
      whatsapp_number: pp.whatsapp_number || "",
      highest_academic_degree: pp.highest_academic_degree || "",
      degree_title: pp.degree_title || "",
      field_of_study: pp.field_of_study || "",
      consultation_mode: pp.consultation_mode || "",
      status: pp.status || "",
      specialization_type: pp.specialization_type || "",
      fee: pp.fee || "",
      availability: pp.availability || "",
      bio: pp.bio || "",
      preferred_languages: pp.preferred_languages || "",
      age_group: JSON.stringify(Array.isArray(pp.age_group) ? pp.age_group : []),
      client_type: joinList(pp.client_type),
    }

    const existing = devProfileByUser.get(devUserId)

    if (existing) {
      stats.profilesSkipped++
      console.log(`  = profile ${existing.id} (exists)`)
      continue
    }

    if (DRY_RUN) {
      stats.profilesCreated++
      console.log(`  + profile for user ${devUserId} (would create)`)
      continue
    }

    try {
      const fd = new FormData()
      for (const [k, v] of Object.entries(fields)) fd.set(k, v)
      for (const field of ["profile_photo", "cv"]) {
        const filename = pp[field]
        if (!filename) continue
        const buf = await downloadFile(PROD_URL, prodToken, "expert_profiles", pp.id, filename)
        if (buf) {
          fd.set(field, new Blob([buf]), filename)
          stats.filesUploaded++
        }
      }
      const res = await fetch(`${DEV_URL}/api/collections/expert_profiles/records`, {
        method: "POST",
        headers: h(devToken, false),
        body: fd,
      })
      if (!res.ok) throw new Error(`${res.status} ${(await res.text()).slice(0, 300)}`)
      const saved = await res.json()
      stats.profilesCreated++
      devProfileByUser.set(devUserId, saved)
      console.log(`  + profile ${saved.id}`)
    } catch (err) {
      stats.errors.push(`profile ${pp.id}: ${err.message}`)
      console.log(`  ! profile ${pp.id}: ${err.message}`)
    }
  }

  console.log("\n===== summary =====")
  console.log(`users   created=${stats.usersCreated} skipped=${stats.usersSkipped}`)
  console.log(`profiles created=${stats.profilesCreated} updated=${stats.profilesUpdated} skipped=${stats.profilesSkipped}`)
  console.log(`files   uploaded=${stats.filesUploaded}`)
  if (stats.errors.length) {
    console.log(`errors  ${stats.errors.length}`)
    for (const e of stats.errors) console.log(`   - ${e}`)
    process.exitCode = 1
  }
}

main().catch((err) => {
  console.error("FATAL", err.message)
  process.exit(1)
})

const h=require(__hooks+'/lib/assessments-api.js').helpers
const policy=require(__hooks+'/lib/security-policy.js')
const engine=require(__hooks+'/lib/assessment-engine.js')
function clientSession(app,u,id){
 const s=app.findRecordById('assessment_sessions',id)
 if(s.getString('recipient')!==u.id)throw new ForbiddenError('Assessment access denied')
 const c=app.findRecordById('cases',s.getString('case'))
 if(c.getString('user')!==u.id)throw new ForbiddenError('Case ownership changed')
 return s
}
function clientDto(app,s,full=true){
 const d=h.json(s,'snapshot',{}),c=app.findRecordById('cases',s.getString('case'))
 const out={id:s.id,case:c.id,caseName:c.getString('name'),owner_display:require(__hooks+'/lib/case-owner-display.js')(app,c),name:d.name,version:d.version,language:d.language,instructions:d.instructions,referencePeriod:d.referencePeriod||"",respondentNotice:d.respondentNotice||"",status:s.getString('status'),created:s.getString('created'),submitted_at:s.getString('submitted_at'),questions:[],answers:{},minAnswered:d.minAnswered,requireAll:d.missingPolicy==='reject'}
 if(full){
  out.questions=d.questions.map(q=>({id:q.id,order:q.order,text:q.text,options:d.answerSets.find(a=>a.id===q.answerSet).options.map(o=>({id:o.id,label:o.label}))})).sort((a,b)=>a.order-b.order)
  const response=h.find(app,'assessment_responses','session = {:id}',{id:s.id})[0];out.answers=response?h.json(response,'answers',{}):{}
 }
 return out
}
function validateAnswers(d,answers){
 if(!answers||typeof answers!=='object'||Array.isArray(answers)||JSON.stringify(answers).length>300000)throw new BadRequestError('Invalid responses / إجابات غير صالحة')
 for(const key of Object.keys(answers)){
  const q=d.questions.find(q=>q.id===key)
  if(!q||typeof answers[key]!=='string'||(answers[key]!==''&&!d.answerSets.find(s=>s.id===q.answerSet).options.some(o=>o.id===answers[key])))throw new BadRequestError('Invalid answer / إجابة غير صالحة')
 }
}
module.exports=(e,action)=>{
 const u=policy.freshUser(e.app,e.auth),b=e.requestInfo().body||{},id=e.request.pathValue('id')
 if(action==='case'){
  h.actor(e);h.allowedCase(e.app,u,id)
  const sessions=h.find(e.app,'assessment_sessions','case = {:id}',{id}).map(s=>h.sessionDto(e.app,s,false))
  const assessments=h.find(e.app,'assessments','status = "published"',{}).map(r=>({id:r.id,name:r.getString('name'),version:r.getString('version')}))
  return e.json(200,{sessions,assessments,canAssign:u.getString('role')==='expert'||h.permit(e.app,u,'tools.create')})
 }
 if(action==='assign'){
  h.actor(e)
  if(u.getString('role')!=='expert'&&!h.permit(e.app,u,'tools.create'))throw new ForbiddenError('Assignment access denied')
  let saved
  e.app.runInTransaction(app=>{
   const c=h.allowedCase(app,u,b.case),recipient=app.findRecordById('users',c.getString('user'))
   if(!recipient.getBool('is_active'))throw new BadRequestError('The case owner must have an active account / يلزم حساب نشط للعميل المرتبط بالحالة')
   const assessment=h.row(app,b.assessment)
   if(assessment.getString('status')!=='published')throw new BadRequestError('Publish an approved assessment first / يجب نشر المقياس المعتمد أولًا')
   const existing=h.find(app,'assessment_sessions','assessment = {:assessment} && case = {:case} && recipient = {:recipient} && submitted_at = ""',{assessment:assessment.id,case:c.id,recipient:recipient.id})[0]
   if(existing){saved=h.sessionDto(app,existing);return}
   const d=h.definition(app,assessment).definition;engine.validateDefinition(d)
   const s=new Record(app.findCollectionByNameOrId('assessment_sessions'))
   s.set('assessment',assessment.id);s.set('case',c.id);s.set('operator',u.id);s.set('recipient',recipient.id);s.set('assigned_at',new Date().toISOString());s.set('status','assigned');s.set('snapshot',d);s.set('population',h.population(b.population));app.save(s)
   saved=h.sessionDto(app,s)
  })
  return e.json(200,saved)
 }
 if(action==='mine'){
  const sessions=h.find(e.app,'assessment_sessions','recipient = {:user}',{user:u.id}).filter(s=>{
   try{return e.app.findRecordById('cases',s.getString('case')).getString('user')===u.id}catch{return false}
  }).map(s=>clientDto(e.app,s,false))
  return e.json(200,{sessions})
 }
 if(action==='client')return e.json(200,clientDto(e.app,clientSession(e.app,u,id)))
 if(action==='respond'){
  let saved
  e.app.runInTransaction(app=>{
   const s=clientSession(app,u,id)
   if(s.getString('submitted_at')||s.getString('status')==='completed')throw new BadRequestError('Assessment already submitted / تم إرسال التقييم بالفعل')
   const d=h.json(s,'snapshot',{}),answers=b.answers||{};validateAnswers(d,answers)
   const count=d.questions.filter(q=>typeof answers[q.id]==='string'&&answers[q.id]!=='').length
   if(b.finalize===true&&(count<d.minAnswered||(d.missingPolicy==='reject'&&count!==d.questions.length)))throw new BadRequestError('Complete the required answers before submitting / أكمل الإجابات المطلوبة قبل الإرسال')
   const previous=h.find(app,'assessment_responses','session = {:id}',{id:s.id})[0],response=previous||new Record(app.findCollectionByNameOrId('assessment_responses'))
   response.set('session',s.id);response.set('answers',answers);app.save(response)
   if(b.finalize===true){
    let result
    try{result=engine.calculate(d,answers,h.json(s,'population',{}))}catch(error){throw new BadRequestError('Unable to submit the assessment. Contact the specialist / تعذر إرسال التقييم، يرجى مراجعة المختص')}
    const record=new Record(app.findCollectionByNameOrId('assessment_results'));record.set('session',s.id);record.set('result',result);app.save(record)
    s.set('status',result.complete?'completed':'incomplete');s.set('submitted_at',new Date().toISOString())
   }else s.set('status','in_progress')
   app.save(s);saved=clientDto(app,s)
  })
  return e.json(200,saved)
 }
 throw new BadRequestError('Unknown assessment delivery action')
}

