                      />
                    </Field>
                    <Field label={t("وصف البعد", "Description")}>
                      <Input
                        value={d.description ?? ""}
                        onChange={(e) =>
                          change({
                            ...definition,
                            dimensions: definition.dimensions.map((r, j) =>
                              j === i
                                ? { ...r, description: e.target.value }
                                : r
                            ),
