                  <Field label={t("اسم مجموعة الإجابات", "Answer-set name")}>
                    <Input
                      value={set.name}
                      onChange={(e) =>
                        change({
                          ...definition,
                          answerSets: definition.answerSets.map((r, j) =>
                            i === j ? { ...r, name: e.target.value } : r
                          ),
                        })
                      }
                    />
                  </Field>
                  <p className="text-xs text-slate-600" dir="ltr">
