                      className="grid gap-2 sm:grid-cols-[1fr_100px_auto]"
                    >
                      <Input
                        aria-label={t("بديل الإجابة", "Answer label")}
                        value={o.label}
                        onChange={(e) =>
                          change({
                            ...definition,
                            answerSets: definition.answerSets.map((r, j) =>
                              i === j
                                ? {
                                    ...r,
                                    options: r.options.map((v, k) =>
                                      k === oi
                                        ? { ...v, label: e.target.value }
                                        : v
                                    ),
                                  }
                                : r
                            ),
                          })
                        }
                      />
                      <Field label={t("الدرجة", "Score")}>
                        <Num
                          value={o.score}
                          onChange={(score) =>
                            change({
                              ...definition,
                              answerSets: definition.answerSets.map((r, j) =>
                                i === j
                                  ? {
                                      ...r,
                                      options: r.options.map((v, k) =>
                                        k === oi ? { ...v, score } : v
                                      ),
                                    }
                                  : r
                              ),
                            })
                          }
                        />
