                          <Field key={k} label={displayLabel(k, t)}>
                            <Select
                              value={mapping[k] ?? ""}
                              onChange={(v) => {
                                setMapping({ ...mapping, [k]: v })
                                setImportPreview([])
                              }}
                              options={[
                                {
                                  value: "",
                                  label: t("اختر عمودًا", "Choose column"),
                                },
                                ...Object.keys(sheets[sheet]?.[0] ?? {}).map(
                                  (v) => ({ value: v, label: v })
                                ),
                              ]}
                            />
                          </Field>
                        ))}
                      </div>
                      <Button
