                                    <td>
                                      {q.critical ? t("حرج", "Critical") : "—"}
                                    </td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                          <Button
                            onClick={() => {
                              change({
                                ...definition,
                                questions: [
                                  ...definition.questions,
                                  ...importPreview,
                                ],
                              })
                              setImportPreview([])
                            }}
                          >
                            {t(
                              "إضافة الأسئلة المعاينة",
                              "Append previewed questions"
                            )}
                          </Button>
                        </>
