                              change({
                                ...definition,
                                questions: definition.questions.map((r, j) =>
                                  i === j
                                    ? {
                                        ...r,
                                        dimensions: r.dimensions.map((x) =>
                                          x.id === d.id
                                            ? {
                                                ...x,
                                                weight: Number(e.target.value),
                                              }
                                            : x
                                        ),
                                      }
                                    : r
                                ),
                              })
                            }
                          />
                        )}
                      </label>
                    ))}
                  </div>
                  <Button
                    variant="outline"
                    onClick={() =>
                      change({
                        ...definition,
                        questions: definition.questions.filter(
                          (r) => r.id !== q.id
