                      value={r.name}
                      onChange={(e) =>
                        change({
                          ...definition,
                          indicators: definition.indicators.map((x, j) =>
                            i === j ? { ...x, name: e.target.value } : x
                          ),
                        })
                      }
                    />
                  </Field>
                  <p className="text-xs text-slate-500" dir="ltr">
                    ID: {r.id}
                  </p>
                  <RuleEditor
                    value={r.rule}
                    onChange={(rule) =>
                      change({
                        ...definition,
                        indicators: definition.indicators.map((x, j) =>
                          i === j ? { ...x, rule } : x
                        ),
                      })
                    }
                    t={t}
                  />
                  <Button
                    variant="outline"
                    onClick={() =>
                      change({
                        ...definition,
                        indicators: definition.indicators.filter(
                          (x) => x.id !== r.id
