                  <label className="flex gap-2">
                    <input
                      type="checkbox"
                      checked={!!b.includeMax}
                      onChange={(e) =>
                        change({
                          ...definition,
                          bands: definition.bands.map((r, j) =>
                            i === j ? { ...r, includeMax: e.target.checked } : r
                          ),
                        })
                      }
                    />
                    {t("يشمل الحد الأعلى", "Include upper bound")}
                  </label>
                  <Field label={t("التفسير", "Interpretation")}>
                    <Input
                      value={b.label}
                      onChange={(e) =>
                        change({
                          ...definition,
                          bands: definition.bands.map((r, j) =>
                            i === j ? { ...r, label: e.target.value } : r
                          ),
                        })
                      }
                    />
                  </Field>
                  <Field label={t("التوصية", "Recommendation")}>
                    <Input
                      value={b.recommendation ?? ""}
                      onChange={(e) =>
                        change({
                          ...definition,
                          bands: definition.bands.map((r, j) =>
                            i === j
                              ? { ...r, recommendation: e.target.value }
                              : r
                          ),
                        })
                      }
                    />
                  </Field>
                  <PopulationFields
                    value={b.population ?? {}}
                    onChange={(population) =>
                      change({
                        ...definition,
                        bands: definition.bands.map((r, j) =>
                          i === j ? { ...r, population } : r
                        ),
                      })
                    }
                    t={t}
                  />
                  <Button
                    variant="outline"
                    onClick={() =>
                      change({
                        ...definition,
                        bands: definition.bands.filter((r) => r.id !== b.id),
                      })
                    }
                  >
                    {t("حذف النطاق", "Remove band")}
                  </Button>
                </article>
              ))}
              <Button
                variant="outline"
                onClick={() =>
                  change({
                    ...definition,
                    bands: [
                      ...definition.bands,
                      {
                        id: id(),
                        target: "overall",
                        min: 0,
                        max: 0,
                        label: "",
                      },
                    ],
                  })
                }
              >
                {t("إضافة نطاق", "Add band")}
              </Button>
              <h3 className="font-bold">{t("التنبيهات", "Alerts")}</h3>
              {definition.alerts.map((a, i) => (
                <article key={a.id} className="space-y-3 border p-4">
                  <div className="grid gap-3 sm:grid-cols-3">
                    <Field label={t("السؤال أو الدرجة", "Question or score")}>
                      <Select
                        value={a.target}
                        onChange={(target) =>
                          change({
                            ...definition,
                            alerts: definition.alerts.map((r, j) =>
                              i === j ? { ...r, target } : r
                            ),
                          })
                        }
                        options={[
                          ...targets,
                          ...definition.questions.map((q) => ({
                            value: `question:${q.id}`,
                            label: `${q.order}. ${q.text}`,
                          })),
                        ]}
                      />
                    </Field>
                    <Field label={t("المقارنة", "Operator")}>
                      <Select
                        value={a.operator}
                        onChange={(operator) =>
                          change({
                            ...definition,
                            alerts: definition.alerts.map((r, j) =>
                              i === j
                                ? {
                                    ...r,
                                    operator: operator as typeof a.operator,
                                  }
                                : r
                            ),
                          })
                        }
                        options={["gt", "gte", "lt", "lte", "eq"].map((v) => ({
                          value: v,
                          label: displayLabel(v, t),
                        }))}
                      />
                    </Field>
                    <Field label={t("الحد", "Threshold")}>
                      <Num
                        value={a.threshold}
                        onChange={(threshold) =>
                          change({
                            ...definition,
                            alerts: definition.alerts.map((r, j) =>
                              i === j ? { ...r, threshold } : r
                            ),
                          })
                        }
                      />
                    </Field>
                  </div>
                  {(["message", "recommendation"] as const).map((k) => (
                    <Field
                      key={k}
                      label={
                        k === "message"
                          ? t("رسالة التنبيه", "Alert message")
                          : t("التوصية", "Recommendation")
                      }
                    >
                      <Input
                        value={a[k] ?? ""}
                        onChange={(e) =>
                          change({
                            ...definition,
                            alerts: definition.alerts.map((r, j) =>
                              i === j ? { ...r, [k]: e.target.value } : r
                            ),
                          })
                        }
                      />
                    </Field>
                  ))}
                  <Button
                    variant="outline"
                    onClick={() =>
                      change({
                        ...definition,
                        alerts: definition.alerts.filter((r) => r.id !== a.id),
                      })
                    }
                  >
                    {t("حذف التنبيه", "Remove alert")}
                  </Button>
                </article>
              ))}
              <Button
                variant="outline"
                onClick={() =>
                  change({
                    ...definition,
                    alerts: [
                      ...definition.alerts,
                      {
                        id: id(),
                        target: "overall",
                        operator: "gte",
                        threshold: 0,
                        message: "",
                      },
                    ],
                  })
                }
              >
                {t("إضافة تنبيه", "Add alert")}
              </Button>
            </fieldset>
          )}
          {(tab === 6 || tab === 7) && (
            <div className="space-y-5">
              {tab === 6 && (
                <div className="space-y-3 rounded border border-amber-300 bg-amber-50 p-4">
                  <p>
                    {t(
                      "احفظ المسودة ثم جرّب إجاباتها قبل النشر. الإصدار المنشور لا يُعدّل؛ أنشئ إصدارًا جديدًا لتغييره.",
                      "Save and test your draft before publishing. Published definitions are immutable; clone a new version to change them."
                    )}
                  </p>
                  {record?.status === "draft" && data.canManage && (
                    <Button
                      disabled={busy || dirty || !record.tested}
                      onClick={() =>
                        run(async () => {
                          const r = await pb.send<AssessmentRecord>(
                            `/api/dsc/assessments/${record.id}/publish`,
                            { method: "POST" }
                          )
                          setRecord(r)
                          setDefinition(r.definition)
                          setData((d) =>
                            d
                              ? {
                                  ...d,
                                  assessments: d.assessments.map((a) =>
                                    a.id === r.id ? r : a
                                  ),
                                }
                              : d
                          )
                        })
                      }
                    >
                      {t("نشر الإصدار المختبَر", "Publish tested version")}
                    </Button>
                  )}
                  {record?.status === "published" && data.canCreate && (
                    <div className="flex gap-2">
                      <Input
                        aria-label={t("رقم الإصدار الجديد", "New version")}
                        value={version}
                        onChange={(e) => setVersion(e.target.value)}
                      />
                      <Button
                        disabled={busy || !version.trim()}
                        onClick={() =>
                          run(async () => {
                            const r = await pb.send<AssessmentRecord>(
                              `/api/dsc/assessments/${record.id}/clone`,
                              { method: "POST", body: { version } }
                            )
                            setRecord(r)
                            setDefinition(r.definition)
                            setImportPreview([])
                            setAnswers({})
                            setResult(null)
                            setData((d) =>
                              d
                                ? { ...d, assessments: [...d.assessments, r] }
                                : d
                            )
                            setTab(0)
                          })
                        }
                      >
                        {t("نسخ لإصدار جديد", "Clone new version")}
                      </Button>
                    </div>
                  )}
                </div>
              )}
              {tab === 7 && !templateOnly && (
                <div className="space-y-3 print:hidden">
                  <h3 className="font-bold">
                    {t("التطبيقات المحفوظة", "Saved sessions")}
                  </h3>
                  <Select
                    value={session?.id ?? ""}
                    onChange={(v) => {
                      if (!v) return
                      void run(async () => {
                        const s = await pb.send<SessionRecord>(
                          `/api/dsc/assessment-sessions/${v}`,
                          { method: "GET" }
                        )
                        setSession(s)
                        setAnswers(s.answers ?? {})
                        setPopulation(s.population)
                        setResult(s.result ?? null)
                      })
                    }}
                    options={[
                      { value: "", label: t("اختر تطبيقًا", "Choose session") },
                      ...data.sessions.map((s) => ({
                        value: s.id,
                        label: `${data.assessments.find((a) => a.id === s.assessment)?.name ?? s.assessment} · ${data.cases.find((c) => c.id === s.case)?.name ?? s.case} · ${s.status}`,
                      })),
                    ]}
                  />
                  <div className="flex flex-wrap gap-2">
                    <div className="min-w-48 flex-1">
                      <Select
                        value={caseId}
                        onChange={setCaseId}
                        options={[
                          { value: "", label: t("اختر الحالة", "Choose case") },
                          ...data.cases.map((c) => ({
                            value: c.id,
                            label: c.name,
                          })),
                        ]}
                      />
                    </div>
                    <Button
                      disabled={
                        busy || !caseId || record?.status !== "published"
                      }
                      onClick={() =>
                        run(async () => {
                          const s = await pb.send<SessionRecord>(
                            "/api/dsc/assessment-sessions",
                            {
                              method: "POST",
                              body: {
                                assessment: record!.id,
                                case: caseId,
                                population,
                              },
                            }
                          )
                          setSession(s)
                          setAnswers(s.answers ?? {})
                          setResult(null)
                          setData((d) =>
                            d ? { ...d, sessions: [s, ...d.sessions] } : d
                          )
                        })
                      }
                    >
                      {t("بدء تطبيق على الحالة", "Start case session")}
                    </Button>
                  </div>
                </div>
              )}
              <AssessmentInstructions
                lang={lang}
                instructions={
                  (tab === 7 ? session?.snapshot : definition)?.instructions
                }
                referencePeriod={
                  (tab === 7 ? session?.snapshot : definition)?.referencePeriod
                }
                respondentNotice={
                  (tab === 7 ? session?.snapshot : definition)?.respondentNotice
                }
              />
              <fieldset
                disabled={
                  busy ||
                  session?.status === "completed" ||
                  !!session?.recipient
                }
                className="space-y-4"
              >
                <legend className="font-bold">
                  {t("بيانات المفحوص", "Respondent population")}
                </legend>
                <div className="grid gap-3 sm:grid-cols-4">
                  <Field label={t("العمر", "Age")}>
                    <Input
                      fieldWidth="short" type="number"
                      min="0"
                      disabled={tab === 7 && !!session}
                      value={population.age ?? ""}
                      onChange={(e) => {
                        setResult(null)
                        setPopulation({
                          ...population,
                          age: e.target.value
                            ? Number(e.target.value)
                            : undefined,
                        })
                      }}
                    />
                  </Field>
                  {(["sex", "language", "group"] as const).map((k) => (
                    <Field key={k} label={displayLabel(k, t)}>
                      <Input
                        disabled={tab === 7 && !!session}
                        value={population[k] ?? ""}
                        onChange={(e) => {
                          setResult(null)
                          setPopulation({ ...population, [k]: e.target.value })
                        }}
                      />
                    </Field>
                  ))}
                </div>
                <AnswerMatrix
                  lang={lang}
                  disabled={
                    busy ||
                    session?.status === "completed" ||
                    !!session?.recipient
                  }
                  questions={(tab === 7
                    ? (session?.snapshot.questions ?? [])
                    : definition.questions
                  ).map((q) => ({
                    ...q,
                    options:
                      (tab === 7 ? session?.snapshot : definition)?.answerSets
                        .find((set) => set.id === q.answerSet)
                        ?.options.map((o) => ({ id: o.id, label: o.label })) ??
                      [],
                  }))}
                  answers={answers}
                  onChange={(question, option) => {
                    setAnswers((a) => {
                      const next = { ...a }
                      if (option) next[question] = option
                      else delete next[question]
                      return next
                    })
                    setResult(null)
                  }}
                />
              </fieldset>
              {tab === 6 && (
                <Button
                  disabled={busy || dirty || !record}
                  onClick={() =>
                    run(async () => {
                      const r = await pb.send<Result>(
                        `/api/dsc/assessments/${record!.id}/preview`,
                        { method: "POST", body: { answers, population } }
                      )
                      setResult(r)
                      setRecord((a) => (a ? { ...a, tested: true } : a))
                    })
                  }
                >
                  {t("حساب التجربة على الخادم", "Calculate preview on server")}
                </Button>
              )}
              {tab === 7 &&
                session &&
                !session.recipient &&
                session.status !== "completed" && (
                  <div className="flex gap-2 print:hidden">
                    {[false, true].map((finalize) => (
                      <Button
                        key={String(finalize)}
                        variant={finalize ? "default" : "outline"}
                        disabled={busy}
                        onClick={() =>
                          run(async () => {
                            const s = await pb.send<SessionRecord>(
                              `/api/dsc/assessment-sessions/${session.id}/submit`,
                              { method: "POST", body: { answers, finalize } }
                            )
                            setSession(s)
                            setResult(s.result ?? null)
                            setData((d) =>
                              d
                                ? {
                                    ...d,
                                    sessions: d.sessions.map((x) =>
                                      x.id === s.id ? s : x
                                    ),
                                  }
                                : d
                            )
                          })
                        }
                      >
                        {finalize
                          ? t(
                              "إنهاء التطبيق وحساب التقرير",
                              "Finalize & calculate report"
                            )
                          : t("حفظ الإجابات", "Save answers")}
                      </Button>
                    ))}
                  </div>
                )}
              {result && (tab === 6 || !!session) && (
                <section className="assessment-report space-y-4">
                  <header className="border-b pb-3">
                    <h2 className="text-2xl font-bold">
                      {session?.snapshot.name ?? definition.name}
                    </h2>
                    <p>
                      {t("الإصدار", "Version")}:{" "}
                      {session?.snapshot.version ?? definition.version} ·{" "}
                      {session
                        ? t("تقرير حالة", "Case report")
                        : t("تجربة", "Preview")}
                    </p>
                    {session && (
                      <>
                        <p>
                          {t("الحالة", "Case")}:{" "}
                          {data.cases.find((c) => c.id === session.case)
                            ?.name ?? session.case}
                        </p>
                        <p>
                          {t("رقم التطبيق", "Session")}: {session.id} ·{" "}
                          {session.created} · {session.status} ·{" "}
                          {t("المنفذ", "Operator")}: {session.operator}
                        </p>
                      </>
                    )}
                  </header>
                  <Results
                    result={result}
                    t={t}
                    questions={(session?.snapshot ?? definition).questions}
                  />
                  <div className="flex flex-wrap gap-2 print:hidden">
                    <Button variant="outline" onClick={() => window.print()}>
                      {t("طباعة / PDF", "Print / PDF")}
                    </Button>
                    <Button
                      variant="outline"
                      onClick={() => exportResult("json")}
                    >
                      JSON
                    </Button>
                    <Button
                      variant="outline"
                      onClick={() => exportResult("csv")}
                    >
                      CSV
                    </Button>
                  </div>
                </section>
              )}
            </div>
          )}
        </section>
      </div>
      <style jsx global>{`
        @media print {
          body * {
            visibility: hidden;
          }
          .assessment-report,
          .assessment-report * {
            visibility: visible;
          }
          .assessment-report {
            position: absolute;
            inset: 0;
            background: white;
            padding: 20px;
            overflow: visible;
          }
          .assessment-report details {
            display: block;
          }
          .assessment-report article {
            break-inside: avoid;
          }
        }
      `}</style>
    </main>
  )
}

"use client"
import { useEffect, useRef, useState, type ReactNode } from "react"
import pb, { getErrorMessage } from "@/lib/pb"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ClientAssessmentList } from "./ClientAssessments"
import type { SessionRecord } from "@/lib/assessments/types"

type CaseData = {
  sessions: SessionRecord[]
  assessments: { id: string; name: string; version: string }[]
  canAssign: boolean
}
const selectStyle =
  "h-10 w-full rounded-md border border-slate-300 bg-white px-2 text-sm"
type CaseAssessmentProps = { caseId: string; mode?: "all" | "assign" | "list"; assignmentRows?: ReactNode; onAssigned?: () => void; onCountChange?: (count: number) => void }
export function CaseAssessments(props: CaseAssessmentProps) {
  const { caseId } = props
  const { currentUser, isLoading } = useAuth()
  if (isLoading) return null
  const professional =
    currentUser && ["admin", "super_admin", "expert"].includes(currentUser.role)
  return professional ? (
    <ProfessionalCaseAssessments key={caseId} {...props} />
  ) : (
    <ClientAssessmentList caseId={caseId} />
  )
}
function ProfessionalCaseAssessments({ caseId, mode = "all", assignmentRows, onAssigned, onCountChange }: CaseAssessmentProps) {
  const { lang } = useLang()
  const t = (ar: string, en: string) => (lang === "ar" ? ar : en)
  const [data, setData] = useState<CaseData | null>(null),
    [error, setError] = useState(""),
    [reload, setReload] = useState(0),
    [assessment, setAssessment] = useState(""),
    [busy, setBusy] = useState(false),
    [notice, setNotice] = useState(""),
    [session, setSession] = useState<SessionRecord | null>(null),
    [loadingReport, setLoadingReport] = useState(false),
    [reportError, setReportError] = useState("")
  const [person, setPerson] = useState<{
    age?: number
    sex?: string
    language?: string
    group?: string
  }>({})
  const assigning = useRef(false),
    reportToken = useRef(0)
  useEffect(() => {
    let active = true
    const controller = new AbortController()
    setError("")
    pb.send<CaseData>(`/api/dsc/cases/${caseId}/assessments`, {
      method: "GET",
      signal: controller.signal,
    })
      .then((r) => {
        if (active) { setData(r); onCountChange?.(r.sessions.length) }
      })
      .catch((e) => {
        if (active) setError(getErrorMessage(e))
      })
    return () => {
      active = false
      controller.abort()
    }
  }, [caseId, reload, onCountChange])
  useEffect(
    () => () => {
      // Invalidate in-flight report requests when this case panel unmounts.
      reportToken.current++
    },
    []
  )
  async function assign() {
    if (!assessment || assigning.current) return
    assigning.current = true
    setBusy(true)
    setNotice("")
    setError("")
    try {
      const s = await pb.send<SessionRecord>(
        "/api/dsc/assessment-sessions/assign",
        {
          method: "POST",
          body: { assessment, case: caseId, population: person },
        }
      )
      setData((d) =>
        d
          ? {
              ...d,
              sessions: [s, ...d.sessions.filter((item) => item.id !== s.id)],
            }
          : d
      )
      onAssigned?.()
      setNotice(
        t(
          "تم إرسال المقياس إلى حساب العميل داخل الموقع.",
          "Assessment assigned to the client's account in this website."
        )
      )
    } catch (e) {
      setError(getErrorMessage(e))
    } finally {
      assigning.current = false
      setBusy(false)
    }
  }
  async function viewReport(id: string) {
    const token = ++reportToken.current
    setSession(null)
    setLoadingReport(true)
    setReportError("")
    try {
      const s = await pb.send<SessionRecord>(
        `/api/dsc/assessment-sessions/${id}`,
        { method: "GET" }
      )
      if (token === reportToken.current) setSession(s)
    } catch (e) {
      if (token === reportToken.current) setReportError(getErrorMessage(e))
    } finally {
      if (token === reportToken.current) setLoadingReport(false)
    }
  }
  function status(s: SessionRecord) {
    if (s.status === "completed") return t("مكتمل", "Completed")
    if (s.submitted_at)
      return t("مرسل ويحتاج مراجعة", "Submitted — review needed")
    return s.status === "assigned"
      ? t("بانتظار العميل", "Awaiting client")
      : t("بدأ العميل الإجابة", "Client draft")
  }
  return (
    <section
      className="space-y-4"
      dir={lang === "ar" ? "rtl" : "ltr"}
    >
      {mode === "all" && <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-xl font-bold text-primary">
            {t("المقاييس والتقييمات", "Assessments")}
          </h2>
          <p className="mt-1 text-sm text-slate-600">
            {t(
              "أرسل مقياسًا منشورًا للعميل، ثم راجع إجابات وتقرير الإصدار نفسه.",
              "Assign a published assessment to the client, then review that version's answers and report."
            )}
          </p>
        </div>
        <Button variant="outline" onClick={() => setReload((v) => v + 1)}>
          {t("تحديث الحالة", "Refresh status")}
        </Button>
      </header>}
      {error && (
        <p role="alert" className="rounded bg-red-50 p-3 text-red-800">
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="rounded bg-green-50 p-3 text-green-900">
          {notice}
        </p>
      )}
      {!data && !error && (
        <p role="status">{t("جارٍ تحميل المقاييس…", "Loading assessments…")}</p>
      )}
      {mode !== "list" && data?.canAssign && (
        <fieldset
          disabled={busy}
          className="space-y-3 border-s-4 border-primary bg-slate-50 p-4"
        >
          <legend className="sr-only">
            {t("إرسال تقييم", "Assign assessment")}
          </legend>
          {!data.assessments.length ? (
            <p>
              {t(
                "لا توجد مقاييس منشورة. احفظ المقياس واختبره ثم انشره أولًا.",
                "No published assessments are available. Save, test and publish an assessment first."
              )}
            </p>
          ) : (
            <>
              <label className="grid gap-1 text-sm font-medium">
                {t("المقياس والإصدار", "Assessment and version")}
                <select
                  className={selectStyle}
                  value={assessment}
                  onChange={(e) => setAssessment(e.target.value)}
                >
                  <option value="">
                    {t("اختر مقياسًا منشورًا", "Choose a published assessment")}
                  </option>
                  {data.assessments.map((a) => (
                    <option value={a.id} key={a.id}>
                      {a.name} · {a.version}
                    </option>
                  ))}
                </select>
              </label>
              <div className="grid gap-3 sm:grid-cols-4">
                <label className="grid gap-1 text-sm">
                  {t("العمر (اختياري)", "Age (optional)")}
                  <Input
                    fieldWidth="short" type="number"
                    min="0"
                    max="150"
                    value={person.age ?? ""}
                    onChange={(e) =>
                      setPerson({
                        ...person,
                        age: e.target.value
                          ? Number(e.target.value)
                          : undefined,
                      })
                    }
                  />
                </label>
                {(["sex", "language", "group"] as const).map((k, i) => (
                  <label key={k} className="grid gap-1 text-sm">
                    {
                      [
                        t("الجنس (اختياري)", "Sex (optional)"),
                        t("اللغة (اختياري)", "Language (optional)"),
                        t("المجموعة (اختياري)", "Group (optional)"),
                      ][i]
                    }
                    <Input
                      value={person[k] ?? ""}
                      onChange={(e) =>
                        setPerson({ ...person, [k]: e.target.value })
                      }
                    />
                  </label>
                ))}
              </div>
              <Button disabled={busy || !assessment} onClick={assign}>
                {busy
                  ? t("جارٍ الإرسال…", "Assigning…")
                  : t("إرسال للعميل", "Send to client")}
              </Button>
              <p className="text-xs text-slate-600">
                {t(
                  "يظهر في قائمة «تكليفاتي» لدى مالك الحالة. لا يرسل بريدًا أو رسالة خارجية.",
                  "Appears in the case owner's My Assignments list. No external email or message is sent."
                )}
              </p>
            </>
          )}
        </fieldset>
      )}
      {mode !== "assign" && (data || assignmentRows) &&
        (!data?.sessions.length && !assignmentRows ? (
          <p className="rounded border border-dashed p-4 text-slate-600">
            {t(
              "لا توجد تكليفات لهذه الحالة بعد.",
              "No assignments have been added to this case."
            )}
          </p>
        ) : (
          <div className="overflow-auto">
            <table className="w-full text-start text-sm">
              <thead>
                <tr>
                  {[
                    t("التكليف", "Assignment"),
                    t("النوع", "Type"),
                    t("الحالة", "Status"),
                    t("مرئي للمستخدم", "Visible to user"),
                    t("تاريخ التكليف", "Assigned date"),
                    t("التقرير", "Report"),
                  ].map((h) => (
                    <th key={h} className="p-2 text-start">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {assignmentRows}
                {data?.sessions.map((s) => (
                  <tr key={s.id} className="border-t">
                    <td className="p-2 font-medium">{s.snapshot.name} · {s.snapshot.version}</td>
                    <td className="p-2">{t("مقياس / تقييم", "Assessment")}</td>
                    <td className="p-2">{status(s)}</td>
                    <td className="p-2">{s.recipient ? t("نعم", "Yes") : t("لا", "No")}</td>
                    <td className="p-2">{s.assigned_at || s.created}</td>
                    <td className="p-2">
                      <Button
                        variant="outline"
                        onClick={() => viewReport(s.id)}
                      >
                        {t("عرض الإجابات والتقرير", "View answers & report")}
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}
      {loadingReport && (
        <p role="status">{t("جارٍ تحميل التقرير…", "Loading report…")}</p>
      )}
      {reportError && (
        <p role="alert" className="text-red-700">
          {reportError}
        </p>
      )}
      {session && (
        <section className="case-assessment-report space-y-4 border-t pt-5">
          <header>
            <h3 className="text-xl font-bold">{session.snapshot.name}</h3>
            <p className="text-sm text-slate-600">
              {t("الحالة", "Case")}: {caseId} · {t("الإصدار", "Version")}:{" "}
              {session.snapshot.version} · {t("التطبيق", "Session")}:{" "}
              {session.id}
            </p>
            <p className="text-sm text-slate-600">
              {t("المنفذ", "Operator")}: {session.operator} ·{" "}
              {session.submitted_at || session.created} · {status(session)}
            </p>
          </header>
          {!session.result ? (
            <p className="rounded bg-slate-50 p-3">
              {t(
                "لم يُحسب تقرير نهائي بعد. يمكن للعميل متابعة الإجابات حتى يرسلها نهائيًا.",
                "No final report has been calculated yet. The client can resume answers until final submission."
              )}
            </p>
          ) : (
            <>
              <p className="rounded bg-slate-50 p-3">
                {t("المجاب", "Answered")}: {session.result.answered}/
                {session.result.total} · {t("الناقص", "Missing")}:{" "}
                {session.result.total - session.result.answered} ·{" "}
                {session.result.complete
                  ? t("مكتمل", "Complete")
                  : t("غير مكتمل", "Incomplete")}
              </p>
              {session.result.scores.map((s) => (
                <article key={s.id} className="rounded border p-4">
                  <div className="flex justify-between gap-3">
                    <h4 className="font-bold">{s.name}</h4>
                    <strong>
                      {s.value === null
                        ? s.notApplicable
                          ? t("غير منطبق", "Not applicable")
                          : t("بيانات غير كافية", "Insufficient data")
                        : Number(s.value.toFixed(3))}
                    </strong>
                  </div>
                  {s.value !== null && (
                    <div className="my-3 h-2 bg-slate-100">
                      <div
                        className="h-2 bg-primary"
                        style={{
                          width: `${Math.min(100, Math.max(0, s.max === s.min ? 0 : ((s.value - s.min) / (s.max - s.min)) * 100))}%`,
                        }}
                      />
                    </div>
                  )}
                  <p>{s.interpretation}</p>
                  <p className="text-sm text-slate-700">{s.recommendation}</p>
                </article>
              ))}
              {session.result.alerts.map((a, i) => (
                <aside
                  key={i}
                  className="rounded border border-amber-200 bg-amber-50 p-3"
                >
                  <strong>{a.message}</strong>
                  <p>{a.recommendation}</p>
                </aside>
              ))}
            </>
          )}
          <details className="space-y-2">
            <summary className="font-bold">
              {t("إجابات العميل", "Client answers")}
            </summary>
            <ol className="divide-y">
              {session.snapshot.questions
                .slice()
                .sort((a, b) => a.order - b.order)
                .map((q) => (
                  <li key={q.id} className="py-2">
                    <strong>
                      {q.order}. {q.text}
                    </strong>
                    <p>
                      {session.snapshot.answerSets
                        .find((s) => s.id === q.answerSet)
                        ?.options.find((o) => o.id === session.answers[q.id])
                        ?.label ?? t("لم يُجب", "Not answered")}
                    </p>
                  </li>
                ))}
            </ol>
          </details>
          <Button
            className="print:hidden"
            variant="outline"
            onClick={() => window.print()}
          >
            {t("طباعة التقرير / PDF", "Print report / PDF")}
          </Button>
        </section>
      )}
      {session && (
        <style jsx global>{`
          @media print {
            body * {
              visibility: hidden;
            }
            .case-assessment-report,
            .case-assessment-report * {
              visibility: visible;
            }
            .case-assessment-report {
              position: absolute;
              inset: 0;
              padding: 20px;
              background: white;
            }
            .case-assessment-report article {
              break-inside: avoid;
            }
          }
        `}</style>
      )}
    </section>
  )
}

"use client"
import { CaseName } from "@/components/cases/CaseName"
import { useCallback, useEffect, useRef, useState } from "react"
import Link from "next/link"
import AnswerMatrix from "./AnswerMatrix"
import AssessmentInstructions from "./AssessmentInstructions"
import pb, { getErrorMessage } from "@/lib/pb"
import { useLang } from "@/lib/lang-context"
import { Button } from "@/components/ui/button"
import type { Answers, ClientAssessment } from "@/lib/assessments/types"

export function assessmentStatus(
  status: ClientAssessment["status"],
  submitted: boolean,
  ar: boolean
) {
  if (submitted) return ar ? "تم الإرسال" : "Submitted"
  return {
    assigned: ar ? "بانتظار إجابتك" : "Awaiting your answers",
    in_progress: ar ? "مسودة محفوظة" : "Saved draft",
    incomplete: ar ? "غير مكتمل" : "Incomplete",
    completed: ar ? "مكتمل" : "Completed",
  }[status]
}
export function ClientAssessmentList({ caseId }: { caseId?: string }) {
  const { lang } = useLang()
  const t = (ar: string, en: string) => (lang === "ar" ? ar : en)
  const [sessions, setSessions] = useState<ClientAssessment[] | null>(null),
    [error, setError] = useState(""),
    [reload, setReload] = useState(0)
  useEffect(() => {
    const controller = new AbortController()
    let current = true
    queueMicrotask(() => {
      if (current) {
        setSessions(null)
        setError("")
      }
    })
    pb.send<{ sessions: ClientAssessment[] }>("/api/dsc/my-assessments", {
      method: "GET",
      signal: controller.signal,
    })
      .then((r) => {
        if (current)
          setSessions(r.sessions.filter((s) => !caseId || s.case === caseId))
      })
      .catch((e) => {
        if (current) setError(getErrorMessage(e))
      })
    return () => {
      current = false
      controller.abort()
    }
  }, [caseId, reload])
  return (
    <section className="space-y-4 rounded-lg border bg-white p-5">
      <header className="flex items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-primary">
          {t("تكليفاتي", "My Assignments")}
        </h2>
        <Button variant="outline" onClick={() => setReload((v) => v + 1)}>
          {t("تحديث", "Refresh")}
        </Button>
      </header>
      <p className="text-sm text-slate-600">
        {t(
          "المقاييس التي أرسلها إليك المختص. يمكنك حفظ الإجابات والعودة إليها قبل الإرسال النهائي.",
          "Assessments assigned by your practitioner. Save your answers and return before final submission."
        )}
      </p>
      {error ? (
        <p role="alert" className="text-red-700">
          {error}
        </p>
      ) : sessions === null ? (
        <p role="status">
          {t("جارٍ تحميل التقييمات…", "Loading assessments…")}
        </p>
      ) : !sessions.length ? (
        <p className="rounded bg-slate-50 p-4">
          {t(
            "لا توجد تقييمات مرسلة إليك حاليًا.",
            "You have no assigned assessments yet."
          )}
        </p>
      ) : (
        <ul className="divide-y">
          {sessions.map((s) => (
            <li
              key={s.id}
              className="flex flex-wrap items-center justify-between gap-3 py-4"
            >
              <div>
                <h3 className="font-bold">{s.name}</h3>
                <p className="text-sm text-slate-600">
                  <CaseName profile={{name:s.caseName,owner_display:s.owner_display}} /> · {t("الإصدار", "Version")} {s.version} ·{" "}
                  {assessmentStatus(s.status, !!s.submitted_at, lang === "ar")}
                </p>
              </div>
              <Link
                href={`/dashboard/assessments/${s.id}`}
                className="rounded-md bg-primary px-4 py-2 text-sm text-primary-foreground"
              >
                {s.submitted_at
                  ? t("عرض الإجابات المرسلة", "View submitted answers")
                  : t("فتح التقييم", "Open assessment")}
              </Link>
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}
export default function ClientAssessments({
  sessionId,
}: {
  sessionId: string
}) {
  const { lang } = useLang()
  const t = (ar: string, en: string) => (lang === "ar" ? ar : en)
  const [session, setSession] = useState<ClientAssessment | null>(null),
    [answers, setAnswers] = useState<Answers>({}),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(""),
    [notice, setNotice] = useState(""),
    [reload, setReload] = useState(0),
    [dirty, setDirty] = useState(false)
  const submitting = useRef(false),
    generation = useRef(0)
  const load = useCallback(() => {
    setReload((v) => v + 1)
  }, [])
  useEffect(() => {
    const controller = new AbortController()
    const token = ++generation.current
    setSession(null)
    setBusy(false)
    setAnswers({})
    setError("")
    setNotice("")
    setDirty(false)
    pb.send<ClientAssessment>(`/api/dsc/my-assessments/${sessionId}`, {
      method: "GET",
      signal: controller.signal,
    })
      .then((s) => {
        if (generation.current === token) {
          setSession(s)
          setAnswers(s.answers ?? {})
        }
      })
      .catch((e) => {
        if (generation.current === token) setError(getErrorMessage(e))
      })
    return () => {
      // Request generation counters must advance on cleanup; this is not a DOM ref.
      // eslint-disable-next-line react-hooks/exhaustive-deps
      generation.current++
      controller.abort()
    }
  }, [sessionId, reload])
  useEffect(() => {
    if (!dirty) return
    const warn = (e: BeforeUnloadEvent) => {
      e.preventDefault()
      e.returnValue = ""
    }
    window.addEventListener("beforeunload", warn)
    return () => window.removeEventListener("beforeunload", warn)
  }, [dirty])
  const answered = session?.questions.filter((q) => !!answers[q.id]).length ?? 0
  const locked = !!session?.submitted_at
  async function submit(finalize: boolean) {
    if (!session || submitting.current || locked) return
    if (
      finalize &&
      (answered < session.minAnswered ||
        (session.requireAll && answered < session.questions.length))
    ) {
      setError(
        t(
          "أكمل الإجابات المطلوبة قبل الإرسال النهائي.",
          "Complete the required answers before final submission."
        )
      )
      return
    }
    if (
      finalize &&
      !window.confirm(
        t(
          "إرسال الإجابات نهائيًا؟ لن تتمكن من تعديلها بعد الإرسال.",
          "Submit your answers? You cannot edit them after submission."
        )
      )
    )
      return
    submitting.current = true
    setBusy(true)
    setError("")
    setNotice("")
    const token = generation.current
    try {
      const s = await pb.send<ClientAssessment>(
        `/api/dsc/my-assessments/${session.id}/submit`,
        { method: "POST", body: { answers, finalize } }
      )
      if (token !== generation.current) return
      setSession(s)
      setAnswers(s.answers ?? {})
      setDirty(false)
      setNotice(
        finalize
          ? t(
              "تم إرسال إجاباتك إلى المختص بنجاح.",
              "Your answers have been submitted to your practitioner."
            )
          : t(
              "تم حفظ المسودة. يمكنك العودة لإكمالها.",
              "Draft saved. You can return to finish it."
            )
      )
    } catch (e) {
      if (token === generation.current) setError(getErrorMessage(e))
    } finally {
      submitting.current = false
      if (token === generation.current) setBusy(false)
    }
  }
  return (
    <main
      dir={lang === "ar" ? "rtl" : "ltr"}
      className="mx-auto max-w-3xl space-y-5 p-4 md:p-7"
    >
      <Link className="text-sm text-primary" href="/dashboard/assessments">
        {t("← تكليفاتي", "← My Assignments")}
      </Link>
      {!session ? (
        <section className="rounded-lg border bg-white p-6">
          {error ? (
            <>
              <p role="alert" className="mb-3 text-red-700">
                {error}
              </p>
              <Button onClick={load}>{t("إعادة المحاولة", "Retry")}</Button>
            </>
          ) : (
            <p role="status">
              {t("جارٍ تحميل التقييم…", "Loading assessment…")}
            </p>
          )}
        </section>
      ) : (
        <>
          <header className="border-b pb-5">
            <p className="text-sm text-slate-600">
              <CaseName profile={{name:session.caseName,owner_display:session.owner_display}} /> · {t("الإصدار", "Version")} {session.version}
            </p>
            <h1 className="my-2 text-3xl font-bold text-primary">
              {session.name}
            </h1>
          </header>
          <AssessmentInstructions
            lang={lang}
            instructions={session.instructions}
            referencePeriod={session.referencePeriod}
            respondentNotice={session.respondentNotice}
          />
          {locked ? (
            <p
              role="status"
              className="rounded border border-green-200 bg-green-50 p-4 text-green-900"
            >
              {t(
                "تم إرسال هذا التقييم. الإجابات متاحة للقراءة، وسيقوم المختص بمراجعتها.",
                "This assessment has been submitted. Your answers are read-only and will be reviewed by your practitioner."
              )}
            </p>
          ) : (
            <div className="rounded border bg-white p-4">
              <div className="flex justify-between gap-3 text-sm">
                <span>{t("الأسئلة المجابة", "Answered questions")}</span>
                <span>
                  {answered}/{session.questions.length}
                </span>
              </div>
              <progress
                aria-label={t("تقدم الإجابة", "Answer progress")}
                className="mt-2 h-2 w-full accent-primary"
                max={Math.max(1, session.questions.length)}
                value={answered}
              />
              <p className="mt-2 text-sm text-slate-600">
                {session.requireAll
                  ? t(
                      "يجب الإجابة عن جميع الأسئلة.",
                      "All questions require an answer."
                    )
                  : t(
                      `الحد الأدنى للإرسال: ${session.minAnswered} إجابة.`,
                      `Minimum required: ${session.minAnswered} answers.`
                    )}
              </p>
            </div>
          )}
          {error && (
            <p
              role="alert"
              className="rounded border border-red-200 bg-red-50 p-3 text-red-800"
            >
              {error}
            </p>
          )}
          {notice && (
            <p role="status" className="rounded bg-green-50 p-3 text-green-900">
              {notice}
            </p>
          )}
          <form
            onSubmit={(e) => {
              e.preventDefault()
              void submit(true)
            }}
            className="space-y-4"
          >
            <AnswerMatrix
              questions={session.questions}
              answers={answers}
              disabled={busy || locked}
              lang={lang}
              onChange={(question, option) => {
                setAnswers((a) => {
                  const next = { ...a }
                  if (option) next[question] = option
                  else delete next[question]
                  return next
                })
                setDirty(true)
                setNotice("")
                setError("")
              }}
            />
            {!locked && (
              <footer className="flex flex-wrap gap-3 border-t pt-4">
                <Button
                  type="button"
                  variant="outline"
                  disabled={busy}
                  onClick={() => submit(false)}
                >
                  {busy
                    ? t("جارٍ الحفظ…", "Saving…")
                    : t("حفظ المسودة", "Save draft")}
                </Button>
                <Button disabled={busy} type="submit">
                  {t("إرسال الإجابات نهائيًا", "Submit final answers")}
                </Button>
                <p className="w-full text-sm text-slate-600">
                  {t(
                    "الإرسال من داخل الموقع فقط. لا تُرسل رسائل خارجية.",
                    "Delivery takes place within this website."
                  )}
                </p>
              </footer>
            )}
          </form>
        </>
      )}
    </main>
  )
}

"use client"
import { useCallback, useEffect, useState } from "react"
import { Star, MessageSquare } from "lucide-react"
import pb, { getErrorMessage } from "@/lib/pb"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { DataError } from "@/components/ui/data-error"
import type { RecordModel } from "pocketbase"
export function CaseFeedback({ caseId, ownerId }: { caseId: string; ownerId: string }) {
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const ar = lang === "ar"
  const [items, setItems] = useState<RecordModel[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")
  const [rating, setRating] = useState(5)
  const [comment, setComment] = useState("")
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const mine = items.find(item => item.author === currentUser?.id)
  const load = useCallback(async () => {
    setLoading(true); setError("")
    try {
      const records = await pb.collection("case_feedback").getFullList({ filter: pb.filter("case = {:id}", { id: caseId }), sort: "-created", requestKey: null })
      setItems(records)
      const own = records.find(item => item.author === currentUser?.id)
      if (own) { setRating(own.rating); setComment(own.comment || "") }
      return true
    } catch (e) { setError(getErrorMessage(e, lang)); return false }
    finally { setLoading(false) }
  }, [caseId, currentUser?.id, lang])
  useEffect(() => { void load() }, [load])
  async function save() {
    if (!currentUser || saving) return
    setSaving(true); setError(""); setSaved(false)
    try {
      const data = { rating, comment: comment.trim() }
      if (mine) await pb.collection("case_feedback").update(mine.id, data)
      else await pb.collection("case_feedback").create({ ...data, case: caseId, author: currentUser.id })
      setSaved(await load())
    } catch (e) { setError(getErrorMessage(e, lang)) }
    finally { setSaving(false) }
  }
  return <Card><CardHeader><CardTitle className="flex items-center gap-2"><MessageSquare className="h-5 w-5" />{ar ? "تقييم الحالة" : "Case feedback"}</CardTitle><p className="text-sm text-muted-foreground">{ar ? "شارك تجربتك لمساعدتنا على تحسين الدعم." : "Share your experience to help us improve your support."}</p></CardHeader><CardContent className="space-y-4">
    {error && <DataError message={error} onRetry={load} />}
    {loading ? <p role="status">{ar ? "جارٍ تحميل التقييم…" : "Loading feedback…"}</p> : error ? null : currentUser?.id === ownerId ? <div className="space-y-3">
      <fieldset><legend className="mb-2 text-sm font-medium">{ar ? "التقييم من ٥" : "Rating out of 5"}</legend><div className="flex flex-wrap gap-2">{[1,2,3,4,5].map(n => <button key={n} type="button" disabled={saving} onClick={() => { setRating(n); setSaved(false) }} aria-label={ar ? `${n} من ٥` : `${n} out of 5`} aria-pressed={rating === n} className="flex h-11 w-11 items-center justify-center rounded-lg border focus-visible:outline-2 focus-visible:outline-primary"><Star className={n <= rating ? "h-6 w-6 fill-amber-400 text-amber-600" : "h-6 w-6 text-muted-foreground"} /></button>)}</div></fieldset>
      <Label htmlFor={`feedback-${caseId}`}>{ar ? "ملاحظاتك (اختياري)" : "Your comments (optional)"}</Label><Textarea id={`feedback-${caseId}`} value={comment} maxLength={2000} disabled={saving} onChange={e => { setComment(e.target.value); setSaved(false) }} rows={4}/><p className="text-xs text-muted-foreground">{comment.length}/2000</p><Button disabled={saving} onClick={save}>{saving ? (ar ? "جارٍ الحفظ…" : "Saving…") : (ar ? "حفظ التقييم" : "Save feedback")}</Button>{saved && <p role="status" className="text-sm text-green-700">{ar ? "تم حفظ تقييمك. شكرًا لك." : "Your feedback was saved. Thank you."}</p>}
    </div> : items.length ? items.map(item => <article key={item.id} className="space-y-2 border-b pb-4 last:border-0"><p className="font-semibold">{item.rating}/5 <span className="text-sm font-normal text-muted-foreground">{ar ? "تقييم صاحب الحالة" : "Case owner feedback"}</span></p><p className="whitespace-pre-wrap [overflow-wrap:anywhere]">{item.comment}</p><time className="text-xs text-muted-foreground">{new Date(item.updated || item.created).toLocaleDateString(ar ? "ar" : "en")}</time></article>) : <p className="text-sm text-muted-foreground">{ar ? "لم يرسل صاحب الحالة تقييمًا بعد." : "The case owner has not submitted feedback yet."}</p>}
  </CardContent></Card>
}

"use client"

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react"
import { Button } from "@/components/ui/button"
import { Loader2, Save, RotateCcw, Code2, Pencil } from "lucide-react"
import { Textarea } from "@/components/ui/textarea"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"
import { UI_STRINGS, t } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"
import {
  cmsLayoutSource,
  isCustomCmsLayout,
  storeCmsLayout,
} from "@/lib/cms-layout"
import { CustomLayoutFrame } from "./CustomLayoutFrame"
import { sanitizeCmsContent } from "@/lib/sanitize"

import "suneditor/css/editor"
import "suneditor/css/contents"
import "codemirror/lib/codemirror.css"

interface RichTextEditorProps {
  initialContent: string
  onSave: (html: string) => Promise<void>
  isSaving: boolean
  title?: string
  onDiscard?: () => void
  onImageUpload?: (file: File) => Promise<string>
  onChange?: (html: string) => void
  maxMediaSizeMB?: number
  direction?: "ltr" | "rtl"
}

export function RichTextEditor({
  initialContent,
  onSave,
  isSaving,
  title,
  onImageUpload,
  onDiscard,
  onChange,
  maxMediaSizeMB,
  direction = "ltr",
}: RichTextEditorProps) {
  const { lang } = useLang()
  const containerRef = useRef<HTMLDivElement>(null)
  const editorRef = useRef<SunEditor.Instance | null>(null)
  const onImageUploadRef = useRef(onImageUpload)
  const onChangeRef = useRef(onChange)
  const mediaLimitRef = useRef({ maxMediaSizeMB, lang })
  const initialEditorRef = useRef({ initialContent, direction })
  useLayoutEffect(() => {
    initialEditorRef.current = { initialContent, direction }
  }, [initialContent, direction])
  useEffect(() => { mediaLimitRef.current = { maxMediaSizeMB, lang } }, [maxMediaSizeMB, lang])
  const exceedsMediaLimit = (file: File) => {
    const { maxMediaSizeMB: limit, lang: currentLang } = mediaLimitRef.current
    if (!limit || file.size <= limit * 1024 * 1024) return false
    toast.error(currentLang === "ar"
      ? `الحد الأعلى لحجم الملف هو ${limit} ميجابايت. اختر ملفًا أصغر.`
      : `The maximum file size is ${limit} MB. Choose a smaller file.`)
    return true
  }
  const lastSyncedInitialContent = useRef<string>("")
  const [content, setContent] = useState(() => cmsLayoutSource(initialContent))
  const [mode, setMode] = useState<"visual" | "html" | "custom">(() =>
    isCustomCmsLayout(initialContent) ? "custom" : "visual"
  )
  const modeRef = useRef(mode)
  const [editorReady, setEditorReady] = useState(false)

  // Keep callback refs up-to-date without re-creating the editor
  useEffect(() => {
    onImageUploadRef.current = onImageUpload
  }, [onImageUpload])
  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  // Create editor once on mount
  useEffect(() => {
    let instance: SunEditor.Instance | undefined
    let cancelled = false

    const init = async () => {
      if (!containerRef.current) return

      containerRef.current.innerHTML = ""
      const textarea = document.createElement("textarea")
      containerRef.current.appendChild(textarea)

      const [{ default: suneditor, plugins }, { default: CodeMirror }] =
        await Promise.all([import("suneditor"), import("codemirror")])

      if (cancelled || !textarea.isConnected) return

      // Imports may finish after the caller switches to another language or page.
      const { initialContent: startingContent, direction: startingDirection } = initialEditorRef.current

      instance = suneditor.create(textarea, {
        plugins,
        externalLibs: {
          codeMirror: { src: CodeMirror },
        },
        textDirection: startingDirection,
        toolbar_sticky: 93,
        value: isCustomCmsLayout(startingContent) ? "" : startingContent,
        height: "600px",
        minHeight: "400px",
        buttonList: [
          ["undo", "redo"],
          "|",
          ["blockStyle", "font", "fontSize"],
          "|",
          ["bold", "italic", "underline", "strike", "subscript", "superscript"],
          "|",
          ["fontColor", "backgroundColor"],
          "|",
          ["textStyle"],
          "|",
          ["removeFormat"],
          "/",
          ["outdent", "indent", "align", "list"],
          "|",
          ["hr", "table", "link", "image", "video"],
          "|",
          ["fullScreen", "showBlocks"],
        ],
        events: {
          onChange: (params: { data: string }) => {
            if (modeRef.current === "custom") return
            setContent(params.data)
            lastSyncedInitialContent.current = params.data
            onChangeRef.current?.(params.data)
          },
          onVideoUploadBefore: async ({ info }) => {
            if (!(info.files instanceof FileList)) return true
            const file = info.files[0]
            if (file && exceedsMediaLimit(file)) return false
            const upload = onImageUploadRef.current
            if (!file || !upload) {
              toast.error(mediaLimitRef.current.lang === "ar" ? "أدخل رابط فيديو منشورًا على الإنترنت." : "Enter an online video URL.")
              return false
            }
            try {
              const url = await upload(file)
              const video = instance!.$.plugins.video
              const element = document.createElement("video")
              element.controls = true
              element.playsInline = true
              video.create(element, url, info.inputWidth, info.inputHeight, info.align, info.isUpdate, { name: file.name, size: file.size }, true)
              video.modal.close()
            } catch (error) {
              toast.error(getErrorMessage(error))
            }
            return false
          },
          onImageUploadBefore: async (params) => {
            const { info } = params
            const uploadHandler = onImageUploadRef.current

            // URL upload (not a file) – let v3 handle it normally
            if (!(info.files instanceof FileList)) {
              return true
            }

            // No custom uploader – let v3 fall back to base64/default behaviour
            if (!uploadHandler || !info.files || info.files.length === 0) {
              return true
            }

            if (exceedsMediaLimit(info.files[0])) return false
            try {
              const url = await uploadHandler(info.files[0])
              const imagePlugin = instance!.$.plugins.image
              imagePlugin.create(
                url,
                null,
                "auto",
                "auto",
                "",
                { name: info.files[0].name, size: info.files[0].size },
                "",
                true
              )
              imagePlugin.modal.close()
              return false
            } catch (error) {
              console.error("Image upload failed:", error)
              toast.error(getErrorMessage(error))
              return false
            }
          },
        },
      })

      editorRef.current = instance
      setEditorReady(true)

      if (startingDirection === "rtl") {
        containerRef.current
          ?.querySelector(".sun-editor-editable")
          ?.setAttribute("lang", "ar")
      }
    }

    init()

    return () => {
      cancelled = true
      // Fallback: destroy if useLayoutEffect hasn't already (e.g. effect re-run)
      if (instance && editorRef.current === instance) {
        try {
          instance.destroy()
        } catch {
          // DOM already detached; manual cleanup not critical here because
          // useLayoutEffect's cleanup will run after this with full fallback.
        }
        editorRef.current = null
      }
    }
  }, []) // run once

  useEffect(() => {
    const instance = editorRef.current
    if (!instance) return
    if (instance.$.options.get("textDirection") !== direction) {
      instance.resetOptions({ textDirection: direction })
    }
    containerRef.current?.querySelector(".sun-editor-editable")?.setAttribute("lang", direction === "rtl" ? "ar" : "en")
  }, [direction, editorReady])

  // Update editor content when initialContent prop changes
  useEffect(() => {
    if (
      editorRef.current &&
      initialContent !== lastSyncedInitialContent.current
    ) {
      if (isCustomCmsLayout(initialContent)) {
        modeRef.current = "custom"
        setMode("custom")
        setContent(cmsLayoutSource(initialContent))
        lastSyncedInitialContent.current = initialContent
        return
      }
      if (modeRef.current === "custom") {
        modeRef.current = "visual"
        setMode("visual")
      }
      const current = editorRef.current.$.html.get()
      if (current === initialContent) {
        lastSyncedInitialContent.current = initialContent
        return
      }
      editorRef.current.$.html.set(initialContent)
      setContent(initialContent)
      lastSyncedInitialContent.current = initialContent
    }
  }, [initialContent, editorReady])

  // Destroy editor BEFORE React removes the DOM.
  // useLayoutEffect cleanup runs synchronously before DOM mutations,
  // so the textarea and editor DOM are still attached when destroy() runs.
  useLayoutEffect(() => {
    return () => {
      const instance = editorRef.current
      if (!instance) return

      try {
        // Pre-emptively handle CodeMirror to prevent the toTextArea error.
        // If the wrapper is already detached, we skip CM cleanup (React will
        // remove it anyway) so destroy() can proceed past step 1.
        try {
          const hasCM = instance.$.options?.get?.("hasCodeMirror")
          if (hasCM && instance.$.contextProvider?.applyToRoots) {
            instance.$.contextProvider.applyToRoots((e) => {
              const cm = e.get("options").get("codeMirrorEditor")
              if (cm?.display?.wrapper?.isConnected) {
                cm.toTextArea()
              }
            })
          }
        } catch {
          console.warn(
            "Editor cleanup could not finish; continuing fallback cleanup"
          )
        }

        instance.destroy()
      } catch {
        // destroy() still hit an error.  Perform critical memory cleanup manually.
        if (instance.events) {
          for (const k in instance.events) instance.events[k] = null
          instance.events = null
        }
        try {
          ;(
            instance.$ as SunEditor.Deps & {
              kernel?: { _destroy?: () => void }
            }
          ).kernel?._destroy?.()
        } catch {
          console.warn("Editor kernel cleanup failed")
        }
      }

      editorRef.current = null
    }
  }, [])

  const handleSave = useCallback(async () => {
    const currentContent =
      mode === "visual" && editorRef.current
        ? editorRef.current.$.html.get()
        : mode === "custom"
          ? storeCmsLayout(content)
          : content
    if (/(?:src|href)\s*=\s*["']\/?(?:[a-z]:[\\/]|file:)/i.test(currentContent)) {
      toast.error(lang === "ar" ? "يوجد ملف مرتبط بمسار على جهازك. ارفع الملف أو استخدم رابطًا منشورًا قبل الحفظ." : "A file uses a local computer path. Upload it or use an online URL before saving.")
      return
    }
    try {
      await onSave(currentContent)
    } catch (error) {
      toast.error(getErrorMessage(error))
    }
  }, [content, mode, onSave, lang])

  const switchMode = (next: "visual" | "html" | "custom") => {
    if (next === mode) return
    if (next === "custom") {
      const source =
        mode === "visual" && editorRef.current
          ? editorRef.current.$.html.get()
          : content
      modeRef.current = "custom"
      setContent(cmsLayoutSource(source))
      const stored = storeCmsLayout(source)
      lastSyncedInitialContent.current = stored
      onChangeRef.current?.(stored)
      setMode("custom")
      return
    }
    if (!editorRef.current) return
    if (mode === "custom") {
      if (
        !window.confirm(
          lang === "ar"
            ? "التحويل إلى النص المنسق يزيل CSS والتخطيط المخصص. هل تريد المتابعة؟"
            : "Converting to rich text removes custom CSS and layout formatting. Continue?"
        )
      )
        return
      modeRef.current = next
      editorRef.current.$.html.set(
        sanitizeCmsContent(content, direction === "rtl" ? "ar" : "en")
      )
      const html = editorRef.current.$.html.get()
      setContent(html)
      lastSyncedInitialContent.current = html
      onChangeRef.current?.(html)
      setMode(next)
      return
    }
    modeRef.current = next
    if (next === "html") {
      const html = editorRef.current.$.html.get()
      setContent(html)
      lastSyncedInitialContent.current = html
      onChangeRef.current?.(html)
    } else {
      editorRef.current.$.html.set(content)
      const html = editorRef.current.$.html.get()
      setContent(html)
      lastSyncedInitialContent.current = html
      onChangeRef.current?.(html)
    }
    setMode(next)
  }

  return (
    <div className="flex flex-col gap-4">
      {onImageUpload && maxMediaSizeMB && (
        <p className="text-sm text-muted-foreground" role="note">
          {lang === "ar"
            ? `الحد الأعلى لحجم كل صورة أو فيديو مرفوع: ${maxMediaSizeMB} ميجابايت.`
            : `Maximum upload size per image or video: ${maxMediaSizeMB} MB.`}
        </p>
      )}
      {title && (
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">{title}</h2>
          <div className="flex items-center gap-2">
            {onDiscard && (
              <Button variant="outline" onClick={onDiscard} disabled={isSaving}>
                <RotateCcw className="mr-2 h-4 w-4" />
                {t(UI_STRINGS.discard_changes, lang)}
              </Button>
            )}
            <Button onClick={handleSave} disabled={isSaving}>
              {isSaving ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Save className="mr-2 h-4 w-4" />
              )}
              {isSaving ? t(UI_STRINGS.saving, lang) : t(UI_STRINGS.save, lang)}
            </Button>
          </div>
        </div>
      )}
      <div
        className="flex flex-wrap items-center gap-2"
        role="group"
        aria-label={t({ en: "Editor mode", ar: "وضع التحرير" }, lang)}
      >
        <Button
          type="button"
          variant={mode === "visual" ? "default" : "outline"}
          aria-pressed={mode === "visual"}
          disabled={!editorReady || isSaving}
          onClick={() => switchMode("visual")}
        >
          <Pencil className="h-4 w-4" />{" "}
          {t({ en: "Visual (WYSIWYG)", ar: "المحرر المرئي" }, lang)}
        </Button>
        <Button
          type="button"
          variant={mode === "html" ? "default" : "outline"}
          aria-pressed={mode === "html"}
          disabled={!editorReady || isSaving}
          onClick={() => switchMode("html")}
        >
          <Code2 className="h-4 w-4" /> HTML
        </Button>
        <Button
          type="button"
          variant={mode === "custom" ? "default" : "outline"}
          aria-pressed={mode === "custom"}
          disabled={isSaving}
          onClick={() => switchMode("custom")}
        >
          <Code2 className="h-4 w-4" />
          {lang === "ar" ? "تخطيط HTML/CSS مخصص" : "Custom HTML/CSS layout"}
        </Button>
      </div>
      <div
        ref={containerRef}
        className="rounded-md border"
        hidden={mode !== "visual"}
        inert={isSaving}
      />
      {(mode === "html" || mode === "custom") && (
        <div className="space-y-2">
          <p className="text-sm text-muted-foreground">
            {mode === "custom"
              ? lang === "ar"
                ? "الصق مستند HTML كاملًا أو محتوى مع CSS داخل وسم style. تُحفظ التنسيقات وتظهر في المعاينة أدناه. JavaScript وملفات CSS الخارجية غير مدعومة."
                : "Paste a complete HTML document or content with a style block. CSS is preserved in the preview below. JavaScript and external stylesheets are not supported."
              : t(
                  {
                    en: "Copy, paste, or edit HTML here. Switch to Visual to view the formatted content.",
                    ar: "انسخ أو الصق أو عدّل HTML هنا. انتقل إلى المحرر المرئي لعرض المحتوى المنسّق.",
                  },
                  lang
                )}
          </p>
          <Textarea
            disabled={isSaving}
            aria-label={t({ en: "HTML source", ar: "مصدر HTML" }, lang)}
            dir="ltr"
            spellCheck={false}
            className="[field-sizing:fixed] h-[400px] max-h-[600px] min-h-[300px] resize-y overflow-y-auto font-mono text-sm"
            value={content}
            onChange={(event) => {
              const html = event.target.value
              const custom = mode === "custom" || isCustomCmsLayout(html)
              if (custom) {
                modeRef.current = "custom"
                setMode("custom")
              }
              setContent(custom ? cmsLayoutSource(html) : html)
              const stored = custom ? storeCmsLayout(html) : html
              lastSyncedInitialContent.current = stored
              onChangeRef.current?.(stored)
            }}
          />
          {mode === "custom" && (
            <div className="overflow-hidden rounded-md border">
              <h3 className="border-b bg-muted/30 p-3 text-sm font-medium">
                {lang === "ar"
                  ? "معاينة التخطيط المخصص"
                  : "Custom layout preview"}
              </h3>
              <CustomLayoutFrame
                html={content}
                lang={direction === "rtl" ? "ar" : "en"}
              />
            </div>
          )}
        </div>
      )}
      {!title && (
        <div className="flex justify-end gap-2">
          {onDiscard && (
            <Button variant="outline" onClick={onDiscard} disabled={isSaving}>
              <RotateCcw className="mr-2 h-4 w-4" />
              {t(UI_STRINGS.discard_changes, lang)}
            </Button>
          )}
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Save className="mr-2 h-4 w-4" />
            )}
            {isSaving ? t(UI_STRINGS.saving, lang) : t(UI_STRINGS.save, lang)}
          </Button>
        </div>
      )}
    </div>
  )
}

