    void boundedFullList(pb.collection("expert_profiles"), {fields:"id,user,review_status", requestKey:null})
      .then(profiles => { if (active) {setSubmittedUsers(new Set(profiles.filter(p => p.review_status !== "rejected").map(p => String(p.user)))); setSubmissionError("")} })
      .catch(error => { if (active) setSubmissionError(getErrorMessage(error, lang)) })
    return () => {active = false}
  }, [users, lang, access.isLoading]) // eslint-disable-line react-hooks/exhaustive-deps


  useEffect(() => {
    let cancelled = false
    pb.files
      .getToken()
      .then((token) => {
        if (!cancelled) setFileToken(token)
      })
      .catch(() => {
        if (!cancelled) setFileToken("")
      })
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!selectedUser) {
      return
    }
    let cancelled = false
    // Loading flags are intentionally reset when selecting a new application.
    setProfileLoading(true)
    pb.collection("expert_profiles")
      .getFirstListItem(
        pb.filter("user = {:value0}", { value0: selectedUser.id })
      )
      .then((record) => {
        if (!cancelled) setSelectedProfile(record)
      })
      .catch(() => {
        if (!cancelled) setSelectedProfile(null)
      })
      .finally(() => {
        if (!cancelled) setProfileLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [selectedUser])

  const pendingExperts = users.filter(
    (u) => u.role === "expert" && !u.is_active && submittedUsers?.has(u.id)
  )

  const getFileUrl = (record: RecordModel, filename: string) => {
    return pb.files.getURL(
      record,
      filename,
      fileToken ? { token: fileToken } : {}
    )
  }

  const handleReviewAction = async (user: User, action: "reject" | "delete") => {
    if (actingId || approvingId) return
    const message = action === "delete"
      ? (lang === "ar" ? "حذف حساب هذا الخبير وطلبه نهائياً؟ لا يمكن التراجع عن الحذف." : "Permanently delete this expert account and application? This cannot be undone.")
      : (lang === "ar" ? "رفض هذا الطلب؟ سيبقى الحساب غير نشط." : "Reject this application? The account will remain inactive.")
    if (!window.confirm(message)) return
    setActingId(user.id)
    setActionError("")
    try {
      if (action === "delete") await deleteUser(user.id)
      else await pb.send(`/api/dsc/security/experts/${user.id}/reject`, { method: "POST" })
      setSelectedUser(null)
      await refresh()
    } catch (error) { setActionError(getErrorMessage(error, lang)) }
    finally { setActingId(null) }
  }

  const handleApprove = async (user: (typeof users)[number]) => {
    setApprovingId(user.id)
    setActionError("")
    let stage: "profile" | "approval" | "email" | "refresh" = "profile"
    let approved = false
    try {
      // Recheck before approval so a stale list cannot approve a failed attempt.
      await pb.collection("expert_profiles").getFirstListItem(pb.filter("user = {:id}", {id:user.id}), {requestKey:null})
      stage = "approval"
      await updateUser(user.id, { is_active: true })
      approved = true
      stage = "email"

      const loginUrl = `${window.location.origin}/login`
      const approvalEmailTitle =
        lang === "ar"
          ? "تم اعتماد حسابك كخبير"
          : "Your Expert Account Has Been Approved"
      const html = [
        `<h2>${approvalEmailTitle}</h2>`,
        `<p>${
          lang === "ar" ? `مرحباً ${user.name}،` : `Dear ${user.name},`
        }</p>`,
        `<p>${
          lang === "ar"
            ? "تهانينا! تم اعتماد حسابك كخبير لدى <strong>DSC</strong>."
