      <Dialog
        open={!!selectedUser}
        onOpenChange={(open) => {
          if (!open) setSelectedUser(null)
        }}
      >
        <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-3xl">
          {selectedUser && (
            <>
              {access.can("payments.read") && (
                <ExpertBankDetails
                  key={selectedUser.id}
