                  )}
                  <span className="flex items-center gap-2">
                    {selectedUser.name}
                    <Badge
                      variant="outline"
                      className="bg-amber-50 text-amber-700"
                    >
                      {ui("Pending")}
                    </Badge>
                  </span>
                </DialogTitle>
                <DialogDescription>
                  {ui("Expert application submitted on")}{" "}
