import { t } from "@/lib/i18n"
import { usePortals } from "@/hooks/usePortals"
import { ArrowRight } from "lucide-react"
import { PortalIcon } from "@/components/portal/PortalIcon"
import { ServiceSearch } from "./ServiceSearch"
const SERVICE_DESCRIPTIONS: Record<string, { en: string; ar: string }> = {
  "anxiety-support": {
    en: "Professional guidance for anxiety management",
    ar: "إرشاد متخصص لإدارة القلق",
  },
  "autism-spectrum-disorder": {
    en: "Comprehensive evaluation and personalized support plan",
    ar: "تقييم شامل وخطط دعم مخصصة",
  },
  "curriculum-design": {
    en: "Build modern, effective learning curricula",
    ar: "بناء منهج تعليمي حديث وفعّال",
  },
  "strategic-planning": {
    en: "Organizational strategy and goal alignment",
    ar: "استراتيجية مؤسسية ومواءمة الأهداف",
  },
}

const POPULAR_SERVICES = [
  { portalId: "1", serviceId: "autism-spectrum-disorder" },
  { portalId: "2", serviceId: "anxiety-support" },
  { portalId: "4", serviceId: "curriculum-design" },
  { portalId: "5", serviceId: "strategic-planning" },
]

export function PortalDiscovery() {
  const { lang } = useLang()
  const { portals: PORTALS, isLoading, error, reload } = usePortals()
  const ar = lang === "ar"
  return (
    <section id="support" className={styles.discovery} dir={ar ? "rtl" : "ltr"}>
      <div className={styles.container}>
        <header className={styles.header}>
          <div>
            <p className={styles.eyebrow}>
              {ar ? "الدعم المناسب لك" : "A path for every possibility"}
            </p>
            <h2>
              {ar
                ? "اختر مجال الدعم الذي تحتاجه"
                : "Choose the support you need."}
            </h2>
          </div>
          <p className={styles.intro}>
            {ar
              ? "خبرة متخصصة للأفراد والأسر والمؤسسات، في كل خطوة من رحلة التطور."
              : "Specialist guidance for individuals, families and organizations. Wherever your journey begins."}
          </p>
        </header>
        <ServiceSearch portals={PORTALS} />
        {isLoading && <p role="status">{ar ? "جارٍ تحميل البوابات…" : "Loading portals…"}</p>}
        {error && <div role="alert"><p>{ar ? "تعذر تحميل البوابات" : "Unable to load portals."}</p><button onClick={() => void reload()}>{ar ? "إعادة المحاولة" : "Retry"}</button></div>}
        {!isLoading && !error && PORTALS.length === 0 && <p>{ar ? "لا توجد بوابات متاحة حالياً." : "No portals are currently available."}</p>}
        <div className={styles.portalGrid}>
          {PORTALS.map((portal, index) => {

            return (
              <article
                key={portal.id}
                className={`${styles.portal} ${portal.picture ? styles.portalWithPicture : ""}`}
                style={{ "--portal-color": portal.accent } as CSSProperties}
              >
                <div className={portal.picture ? styles.pictureTop : styles.portalTop}>
                  {portal.picture ? (
                    <img src={portal.picture} alt="" className={styles.portalPicture} />
                  ) : (
                    <span className={styles.icon}><PortalIcon name={portal.icon} /></span>
                  )}
                  <span className={styles.number}>0{index + 1}</span>
                </div>
                <h3>{t(portal.title, lang)}</h3>
                <p>{t(portal.tagline, lang)}</p>
                <div className={styles.portalActions}>
                <Link href={`/portal/${portal.id}`} className={styles.explore}>
                  {ar ? "استكشف المجال" : "Explore support"}
                  <ArrowRight size={16} />
                </Link>
                </div>
              </article>
            )
          })}
        </div>
        <div className={styles.services}>
          <div className={styles.servicesHeading}>
            <h3>{ar ? "الخدمات الأكثر طلباً" : "Popular services"}</h3>
            <span>{ar ? "ابدأ بما يهمك" : "A good place to start"}</span>
          </div>
          <div className={styles.serviceGrid}>
            {POPULAR_SERVICES.map((item) => {
              const portal = PORTALS.find((p) => p.id === item.portalId)
              const service = portal?.services.find(
                (s) => s.id === item.serviceId
              )
              const desc = SERVICE_DESCRIPTIONS[item.serviceId]
              if (!portal || !service) return null

              return (
                <Link
                  key={item.serviceId}
                  href={`/portal/${portal.id}`}
                  className={styles.service}
                  style={{ "--portal-color": portal.accent } as CSSProperties}
                >
                  <span className={styles.serviceIcon}>
                    <PortalIcon name={portal.icon} size={19} />
                  </span>
                  <h4>{t(service.name, lang)}</h4>
                  <p>{desc ? t(desc, lang) : ""}</p>
                  <span className={styles.book}>
                    {ar ? "احجز الآن" : "Book now"}
                    <ArrowRight size={14} />
                  </span>
                </Link>
              )
            })}
          </div>
        </div>
      </div>
    </section>
  )
}

"use client"

import Link from "next/link"
import { useRouter } from "next/navigation"
import { useCallback } from "react"
import { useLoading } from "@/components/loading-provider"
import { cn } from "@/lib/utils"

interface SmartLinkProps {
  href: string
  children: React.ReactNode
  className?: string
  title?: string
  onClick?: () => void
  disabled?: boolean
  prefetch?: boolean
}

export function SmartLink({
  href,
  children,
  className,
  title,
  onClick,
  disabled,
  prefetch,
}: SmartLinkProps) {
  const { startLoading, stopLoading } = useLoading()
  const router = useRouter()

  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      if (disabled) {
        e.preventDefault()
        return
      }
      startLoading()
      onClick?.()
      // Stop loading after a short delay to simulate navigation complete
      // In Next.js App Router, we can't easily detect when a page finishes loading
      // So we use a timeout based approach
      const stop = () => stopLoading()
      window.addEventListener("popstate", stop, { once: true })
      setTimeout(stop, 800)
    },
    [startLoading, stopLoading, onClick, disabled]
  )

  if (disabled) {
    return (
      <span className={cn("pointer-events-none opacity-50", className)}>
        {children}
      </span>
    )
  }

  return (
    <Link
      href={href}
      className={className}
      title={title}
      onClick={handleClick}
      prefetch={prefetch}
    >
      {children}
    </Link>
  )
}

// Also export a SmartButton that navigates and shows loading
interface SmartButtonProps {
  href: string
  children: React.ReactNode
  className?: string
  variant?: "default" | "outline" | "ghost"
  size?: "default" | "sm" | "lg" | "icon"
  disabled?: boolean
}

export function SmartButton({
  href,
  children,
  className,
  disabled,
}: SmartButtonProps) {
  const { startLoading, stopLoading } = useLoading()
  const router = useRouter()

  const handleClick = useCallback(() => {
    if (disabled) return
    startLoading()
    router.push(href)
    setTimeout(() => stopLoading(), 800)
  }, [startLoading, stopLoading, router, href, disabled])

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      className={cn(
        "inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-50",
        className
      )}
    >
      {children}
    </button>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { useClassifications } from "@/hooks/useClassifications"
import { useLang } from "@/lib/lang-context"
import pb, { getErrorMessage } from "@/lib/pb"
import { boundedFullList } from "@/lib/bounded-records"
import { normalizeAllocationRole } from "@/lib/allocation-role-groups"
import type { RolesManagement } from "@/types/expert-role"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"

export function SpecialistSelector({ value, onChange, disabled = false }: {
  value: string[]
  onChange: (ids: string[]) => void
  disabled?: boolean
}) {
  const { lang } = useLang()
  const { groups: ALLOCATION_ROLE_GROUPS, isLoading: groupsLoading, error: groupsError, refresh: refreshGroups } = useClassifications()
  const ar = lang === "ar"
  const [roles, setRoles] = useState<RolesManagement[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")
  const [selectedGroups, setSelectedGroups] = useState<string[]>([])
  const [search, setSearch] = useState("")
  const refresh = useCallback(async () => {
    setLoading(true)
    setError("")
    try {
      const data = await boundedFullList<RolesManagement>(pb.collection("expert_roles_public"), { requestKey: null })
      setRoles(data.map(normalizeAllocationRole).sort((a, b) => (a.role_order || 0) - (b.role_order || 0)))
    } catch (err) {
      setError(`Public role catalog unavailable or requires correction. ${getErrorMessage(err)}`)
    } finally {
      setLoading(false)
    }
  }, [])
  useEffect(() => { void refresh() }, [refresh])
  const groupIds = new Set([...selectedGroups, ...roles.filter(role => value.includes(role.id)).map(role => role.role_group!)])
  const available = roles.filter(role => !role.is_retired || value.includes(role.id))
  const visibleRoles = available.filter(role => groupIds.has(role.role_group!) && `${role.role_name_en} ${role.role_name_ar}`.toLowerCase().includes(search.toLowerCase()))

  if (loading || groupsLoading) return <p role="status">{ar ? "جارٍ تحميل الأدوار..." : "Loading roles..."}</p>
  if (error || groupsError) return <div role="alert" className="space-y-2"><p>{error || groupsError}</p><Button type="button" variant="outline" onClick={() => { refreshGroups(); void refresh() }}>{ar ? "إعادة المحاولة" : "Retry"}</Button></div>
  const missingGroups = available.filter(role => !ALLOCATION_ROLE_GROUPS.some(group => group.id === role.role_group))
  if (missingGroups.length) return <div role="alert">{ar ? "يلزم تصحيح مجموعات الأدوار في قاعدة البيانات:" : "Role groups need correction in the database:"} {missingGroups.map(role => `${role.id}: ${role.role_group}`).join(", ")}</div>
  return <div className="dsc-form-grid" dir={ar ? "rtl" : "ltr"}>
    <fieldset disabled={disabled} className="space-y-3 rounded-lg border p-4">
      <legend className="px-2 font-semibold">{ar ? "مجموعة الأدوار" : "Role Group"}</legend>
      {ALLOCATION_ROLE_GROUPS.filter(group => available.some(role => role.role_group === group.id)).map(group => (
        <label key={group.id} className="flex items-center gap-2">
          <input type="checkbox" checked={groupIds.has(group.id)} onChange={() => {
            if (groupIds.has(group.id)) {
              setSelectedGroups(selectedGroups.filter(id => id !== group.id))
              onChange(value.filter(id => !roles.some(role => role.id === id && role.role_group === group.id)))
            } else setSelectedGroups([...selectedGroups, group.id])
          }} />
          {ar ? group.ar : group.en}
        </label>
      ))}
      {!available.length && <p className="text-sm text-muted-foreground">{ar ? "لا توجد أدوار متاحة حالياً." : "No roles are available yet."}</p>}
    </fieldset>
    <fieldset disabled={disabled} className="space-y-3 rounded-lg border p-4">
      <legend className="px-2 font-semibold">{ar ? "الدور (اختيار متعدد)" : "Role (multiple selection)"}</legend>
      <Input aria-label={ar ? "البحث في الأدوار" : "Search roles"} placeholder={ar ? "البحث في الأدوار..." : "Search roles..."} value={search} onChange={event => setSearch(event.target.value)} />
      <div className="max-h-64 space-y-3 overflow-y-auto">
        {visibleRoles.map(role => <label key={role.id} className="flex items-center gap-2">
          <input type="checkbox" checked={value.includes(role.id)} onChange={() => onChange(value.includes(role.id) ? value.filter(id => id !== role.id) : [...value, role.id])} />
          {(ar ? role.role_name_ar : role.role_name_en) || role.role_name_en || role.role_name_ar}
        </label>)}
      </div>
      {!groupIds.size && <p className="text-sm text-muted-foreground">{ar ? "اختر مجموعة أولاً." : "Choose a role group first."}</p>}
      {!!groupIds.size && !visibleRoles.length && <p className="text-sm text-muted-foreground">{ar ? "لا توجد أدوار مطابقة." : "No matching roles."}</p>}
    </fieldset>
  </div>
}

