"use client"
import { useUiTranslation } from "@/hooks/useUiTranslation"

import { useState } from "react"
import { useLang } from "@/lib/lang-context"
import type { MediaConfig, MediaItem } from "@/types/tool"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"


interface MediaPreviewProps {
  config: MediaConfig
  responses?: Record<string, string>
  readOnly?: boolean
}

export function MediaPreview({ config, responses = {}, readOnly = false }: MediaPreviewProps) {
  const ui = useUiTranslation()

  const { lang } = useLang()
  const [localResponses, setLocalResponses] = useState<Record<string, string>>(responses)

  const sortedItems = [...config.items].sort((a, b) => a.order - b.order)

  const handleResponse = (itemId: string, value: string) => {
    setLocalResponses((prev) => ({ ...prev, [itemId]: value }))
  }

  const currentResponses = readOnly ? responses : localResponses

  const renderMedia = (item: MediaItem) => {
    if (item.mediaType === "image") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
          <img
            src={item.mediaUrl}
            alt={ui("Media")}
            className="h-full w-full object-contain"
          />
        </div>
      )
    }
    if (item.mediaType === "video") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
          <video src={item.mediaUrl} controls playsInline className="h-full w-full object-contain" />
        </div>
      )
    }
    if (item.mediaType === "audio") {
      return (
        <div className="flex items-center justify-center rounded-lg border bg-muted/30 p-4">
          <audio src={item.mediaUrl} controls className="w-full" />
        </div>
      )
    }
    return null
  }

  if (sortedItems.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          {ui("No media items yet")}
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold">{config.title[lang]}</h3>
      {sortedItems.map((item) => (
        <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
          <div className="flex items-start gap-2">
            <Label className="font-medium">
              {item.question || ui("No question text")}
            </Label>
          </div>
          {renderMedia(item)}
          <div>
            <Label className="text-sm text-muted-foreground">
              {ui("Response Type:")}{" "}
              <span className="capitalize">{ui(item.responseType)}</span>
            </Label>
            {item.responseType === "text" && (
              <Input
                placeholder={
                  lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
                }
                value={currentResponses[item.id] || ""}
                onChange={readOnly ? undefined : (e) => handleResponse(item.id, e.target.value)}
                className="mt-2"
                readOnly={readOnly}
              />
            )}
          </div>
</div>
        ))}
      {!readOnly && (
        <div className="rounded-lg bg-muted/30 p-4">
          <p className="mb-2 text-sm font-medium">{ui("Responses:")}</p>
          <pre className="overflow-auto text-xs">
            {JSON.stringify(localResponses, null, 2)}
          </pre>
        </div>
      )}
    </div>
  )
}

"use client"
import { useUiTranslation } from "@/hooks/useUiTranslation"

import { useState } from "react"
import { useLang } from "@/lib/lang-context"
import type { MultipleChoiceConfig, MCQuestion } from "@/types/tool"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Textarea } from "../ui/textarea"

interface MultipleChoicePreviewProps {
  config: MultipleChoiceConfig
  responses?: Record<string, unknown>
  readOnly?: boolean
}

export function MultipleChoicePreview({ config, responses = {}, readOnly = false }: MultipleChoicePreviewProps) {
  const ui = useUiTranslation()

  const { lang } = useLang()
  const [draftAnswers, setAnswers] = useState<Record<string, unknown>>(responses)
  const [showAnswers, setShowAnswers] = useState(false)

  const answers = readOnly ? responses : draftAnswers

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
  }

  const renderMedia = (question: MCQuestion) => {
    if (!question.mediaUrl) {
      return (
        <div className="flex h-32 items-center justify-center rounded-lg border bg-muted/30 text-sm text-muted-foreground">
          {lang === "ar" ? "لم يتم تحميل الوسائط" : "No media uploaded"}
        </div>
      )
    }
    if (question.mediaType === "image") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
          <img
            src={question.mediaUrl}
            alt={ui("Media")}
            className="h-full w-full object-contain"
          />
        </div>
      )
    }
    if (question.mediaType === "video") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
          <video controls playsInline src={question.mediaUrl} className="h-full w-full object-contain" />
        </div>
      )
    }
    if (question.mediaType === "audio") {
      return (
        <div className="flex items-center justify-center rounded-lg border bg-muted/30 p-4">
          <audio src={question.mediaUrl} controls className="w-full" />
        </div>
      )
    }
    return null
  }

  const renderQuestion = (question: MCQuestion, index: number) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const showOptions =
      question.answerType === "single_choice" ||
      question.answerType === "multiple_choice"
    const correctOptions =
      question.options?.filter((o) => o.isCorrect).map((o) => o.value) || []
    const isMedia = question.answerType === "media"

    return (
      <div
        key={question.id}
        className="space-y-3 rounded-lg border bg-card p-4"
      >
        <div className="flex items-start gap-2">
          <Badge variant="outline" className="mt-0.5">
            {index + 1}
          </Badge>
          <Label className="flex-1 font-medium">
            {question.text}
            {question.required && (
              <span className="ms-1 text-destructive">*</span>
            )}
          </Label>
        </div>

        <div className="ms-7 space-y-3">
          {isMedia && renderMedia(question)}

          {question.answerType === "text" && (
            <Textarea
              placeholder={
                lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
              }
              value={(value as string) || ""}
              onChange={(e) => handleAnswer(question.id, e.target.value)}
            />
          )}
          {question.answerType === "number" && (
          <Input
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            placeholder="0"
            value={(value as string) || ""}
            onChange={(e) => {
              const filtered = e.target.value.replace(/[^0-9]/g, "")
              handleAnswer(question.id, filtered)
            }}
            />
          )}
          {showOptions && question.answerType === "single_choice" && (
            <RadioGroup
              value={(value as string) || ""}
              onValueChange={(v) => handleAnswer(question.id, v)}
            >
              {question.options?.map((opt) => (
                <div key={opt.value} className="flex items-center gap-2">
                  <RadioGroupItem
                    value={opt.value}
                    id={`mc-preview-${question.id}-${opt.value}`}
                  />
                  <Label
                    htmlFor={`mc-preview-${question.id}-${opt.value}`}
                    className={
                      showAnswers && opt.isCorrect
                        ? "font-medium text-green-600"
                        : ""
                    }
                  >
                    {opt.label} {showAnswers && opt.isCorrect && "✓"}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          )}
          {showOptions && question.answerType === "multiple_choice" && (
            <div className="space-y-2">
              {question.options?.map((opt) => (
                <div key={opt.value} className="flex items-center gap-2">
                  <Checkbox
                    id={`mc-preview-${question.id}-${opt.value}`}
                    checked={((value as string[]) || []).includes(opt.value)}
                    onCheckedChange={(checked) => {
                      const current = (value as string[]) || []
                      if (checked)
                        handleAnswer(question.id, [...current, opt.value])
                      else
                        handleAnswer(
                          question.id,
                          current.filter((v) => v !== opt.value)
                        )
                    }}
                  />
                  <Label
                    htmlFor={`mc-preview-${question.id}-${opt.value}`}
                    className={
                      showAnswers && opt.isCorrect
                        ? "font-medium text-green-600"
                        : ""
                    }
                  >
                    {opt.label} {showAnswers && opt.isCorrect && "✓"}
                  </Label>
                </div>
              ))}
            </div>
          )}
          {isMedia && question.responseType === "text" && (
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={(value as string) || ""}
              onChange={(e) => handleAnswer(question.id, e.target.value)}
            />
          )}
          {isMedia && question.responseType === "video" && (
            <div className="rounded-lg border bg-muted/30 p-4 text-center text-sm text-muted-foreground">
              {lang === "ar" ? "سجل فيديو إجابتك" : "Record video response"}
            </div>
          )}
          {isMedia && question.responseType === "audio" && (
            <div className="rounded-lg border bg-muted/30 p-4 text-center text-sm text-muted-foreground">
              {lang === "ar" ? "سجل صوت إجابتك" : "Record audio response"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const sortedQuestions = [...config.questions].sort(
    (a, b) => a.order - b.order
  )

  if (sortedQuestions.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          {ui("No questions yet")}
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold">{config.title[lang]}</h3>
      {sortedQuestions.map((q, idx) => renderQuestion(q, idx))}
      {!readOnly && (
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowAnswers(!showAnswers)}
          >
            {ui(showAnswers ? "Hide Answers" : "Show Correct Answers")}
          </Button>
        </div>
      )}
      {!readOnly && (
        <div className="rounded-lg bg-muted/30 p-4">
          <p className="mb-2 text-sm font-medium">{ui("Your Answers:")}</p>
          <pre className="overflow-auto text-xs">
            {JSON.stringify(answers, null, 2)}
          </pre>
        </div>
      )}
    </div>
  )
}

"use client"
import { useUiTranslation } from "@/hooks/useUiTranslation"
import { surveyOptionLabel } from "@/lib/survey-options"

import { useState } from "react"
import { useLang } from "@/lib/lang-context"
import type { SurveyConfig } from "@/types/tool"
import { Card, CardContent } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import { Badge } from "@/components/ui/badge"


interface SurveyPreviewProps {
  config: SurveyConfig
  responses?: Record<string, unknown>
  readOnly?: boolean
}

export function SurveyPreview({ config, responses = {}, readOnly = false }: SurveyPreviewProps) {
  const ui = useUiTranslation()

  const { lang } = useLang()
  const [draftAnswers, setAnswers] = useState<Record<string, unknown>>(responses)

  const answers = readOnly ? responses : draftAnswers

  const handleSingleAnswer = (questionId: string, value: string) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
  }

  const handleMultipleAnswer = (
    questionId: string,
    value: string,
    checked: boolean
  ) => {
    const current = ((answers[questionId] as string[]) || []).filter(Boolean)
    if (checked) {
      setAnswers((prev) => ({ ...prev, [questionId]: [...current, value] }))
    } else {
      setAnswers((prev) => ({
        ...prev,
        [questionId]: current.filter((v) => v !== value),
      }))
    }
  }

  const isMultipleChoice = config.answerType === "multiple_choice"
  const sortedOptions = [...config.options].sort((a, b) => a.order - b.order)
  const sortedQuestions = [...config.questions].sort(
    (a, b) => a.order - b.order
  )

  if (sortedQuestions.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          {ui("No questions yet")}
        </CardContent>
      </Card>
    )
  }

  if (sortedOptions.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          {ui("No options defined")}
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold">{config.title[lang]}</h3>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[600px] border-collapse">
          <thead>
            <tr>
              <th className="min-w-[200px] border-b-2 border-border bg-muted/30 p-3 text-left text-sm font-semibold">
                {ui("Questions")}
              </th>
              {sortedOptions.map((opt) => (
                <th
                  key={opt.id}
                  className="min-w-[100px] border-b-2 border-border bg-muted/30 p-2 text-center text-sm font-semibold"
                >
                  {surveyOptionLabel(opt, lang)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sortedQuestions.map((question) => {
              const value = answers[question.id]
              const selectedSingle = value as string | undefined
              const selectedMultiple = (value as string[]) || []

              return (
                <tr
                  key={question.id}
                  className="border-b border-border hover:bg-muted/10"
                >
                  <td className="p-3">
                    <div className="flex items-start gap-2">
                      <Badge variant="outline" className="mt-0.5">
                        {question.order + 1}
                      </Badge>
                      <Label className="flex-1 font-medium">
                        {question.text}
                        {question.required && (
                          <span className="ms-1 text-destructive">*</span>
                        )}
                      </Label>
                    </div>
                  </td>
                  {sortedOptions.map((opt) => {
                    if (isMultipleChoice) {
                      const isChecked = selectedMultiple.includes(opt.value)
                      return (
                        <td key={opt.id} className="p-2 text-center">
                          <Checkbox
                            id={`preview-${question.id}-${opt.id}`}
                            checked={isChecked}
                            disabled={readOnly}
                            onCheckedChange={readOnly ? undefined : (checked) =>
                              handleMultipleAnswer(
                                question.id,
                                opt.value,
                                !!checked
                              )
                            }
                          />
                        </td>
                      )
                    } else {
                      const isSelected = selectedSingle === opt.value
                      return (
                        <td key={opt.id} className="p-2 text-center">
                          <RadioGroup
                            value={selectedSingle || ""}
                            onValueChange={readOnly ? undefined : (v) =>
                              handleSingleAnswer(question.id, v)
                            }
                          >
                            <RadioGroupItem
                              value={opt.value}
                              id={`preview-${question.id}-${opt.id}`}
                            />
                          </RadioGroup>
                        </td>
                      )
                    }
                  })}
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}

"use client"

import { useFilePreviewUrls } from "@/hooks/useFilePreviewUrls"
import { useState, useRef, useMemo } from "react"
import { X, Image, Video, Music } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"
import type { MediaType, ResponseType } from "@/types/tool"

const MAX_SIZE_MB = 20
const MAX_SIZE_BYTES = MAX_SIZE_MB * 1024 * 1024

const MEDIA_TYPES: {
  value: MediaType
  label: { en: string; ar: string }
  icon: typeof Image
}[] = [
  { value: "image", label: { en: "Image", ar: "صورة" }, icon: Image },
  { value: "video", label: { en: "Video", ar: "فيديو" }, icon: Video },
  { value: "audio", label: { en: "Audio", ar: "صوت" }, icon: Music },
]

const RESPONSE_TYPES: { value: ResponseType; label: { en: string; ar: string } }[] = [
  { value: "text", label: { en: "Text Response", ar: "استجابة نصية" } },
  { value: "video", label: { en: "Video Response", ar: "استجابة فيديو" } },
  { value: "audio", label: { en: "Audio Response", ar: "استجابة صوتية" } },
]

interface MediaUploadProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onUpload: (data: {
    file: File
    mediaType: MediaType
    responseType: ResponseType
  }) => void
}

export function MediaUpload({
  open,
  onOpenChange,
  onUpload,
}: MediaUploadProps) {
  const { lang } = useLang()
  const [mediaType, setMediaType] = useState<MediaType>("image")
  const [responseType, setResponseType] = useState<ResponseType>("text")
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const previewFiles = useMemo(() => new Map<string, File>(selectedFile && open ? [["selected", selectedFile]] : []), [selectedFile, open])
  const previewUrl = useFilePreviewUrls(previewFiles).get("selected")
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setError(null)

    if (file.size > MAX_SIZE_BYTES) {
      setError(
        t(
          {
            en: `File too large. Max size is ${MAX_SIZE_MB}MB`,
            ar: `الملف كبير جداً. الحد الأقصى للحجم ${MAX_SIZE_MB} ميجابايت`,
          },
          lang
        )
      )
      return
    }

    setSelectedFile(file)
  }

  const handleSave = () => {
    if (!selectedFile) return
    onUpload({ file: selectedFile, mediaType, responseType })
    handleClose()
  }

  const handleClose = () => {
    setSelectedFile(null)
    setError(null)
    setMediaType("image")
    setResponseType("text")
    onOpenChange(false)
  }

  const renderPreview = () => {
    if (!previewUrl) return null

    if (mediaType === "image") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
          <img
            src={previewUrl}
            alt={t({ en: "Preview", ar: "معاينة" }, lang)}
            className="h-full w-full object-contain"
          />
        </div>
      )
    }

    if (mediaType === "video") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
          <video src={previewUrl} controls playsInline className="h-full w-full object-contain" />
        </div>
      )
    }

    if (mediaType === "audio") {
      return (
        <div className="flex items-center justify-center rounded-lg border bg-muted/30 p-8">
          <div className="flex flex-col items-center gap-2">
            <Music className="h-12 w-12 text-muted-foreground" />
            <audio src={previewUrl} controls className="w-full" />
          </div>
        </div>
      )
    }

    return null
  }

  return (
    <Dialog open={open} onOpenChange={(next) => next ? onOpenChange(true) : handleClose()}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {t({ en: "Upload Media", ar: "رفع وسائط" }, lang)}
          </DialogTitle>
          <DialogDescription>
            {t(
              {
                en: `Add image, video, or audio (max ${MAX_SIZE_MB}MB)`,
                ar: `أضف صورة أو فيديو أو صوت (بحد أقصى ${MAX_SIZE_MB} ميجابايت)`,
              },
              lang
            )}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>{t({ en: "Media Type", ar: "نوع الوسائط" }, lang)}</Label>
              <Select
                value={mediaType}
                onValueChange={(v) => setMediaType(v as MediaType)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {MEDIA_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      <div className="flex items-center gap-2">
                        <type.icon className="h-4 w-4" />
                        {t(type.label, lang)}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>
                {t({ en: "Response Type", ar: "نوع الاستجابة" }, lang)}
              </Label>
              <Select
                value={responseType}
                onValueChange={(v) => setResponseType(v as ResponseType)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {RESPONSE_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {t(type.label, lang)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {!selectedFile && (
            <div className="space-y-2">
              <Input
                ref={fileInputRef}
                type="file"
                accept={
                  mediaType === "image"
                    ? "image/*"
                    : mediaType === "video"
                      ? "video/*"
                      : "audio/*"
                }
                onChange={handleFileSelect}
                className="cursor-pointer"
              />
              {error && <p className="text-sm text-destructive">{error}</p>}
            </div>
          )}

          {selectedFile && (
            <div className="space-y-3">
              {renderPreview()}
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  setSelectedFile(null)
                                if (fileInputRef.current) fileInputRef.current.value = ""
                }}
              >
                <X className="me-2 h-4 w-4" />
                {t(
                  {
                    en: "Remove & Upload Different",
                    ar: "إزالة ورفع ملف مختلف",
                  },
                  lang
                )}
              </Button>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            {t(UI_STRINGS.cancel, lang)}
          </Button>
          <Button onClick={handleSave} disabled={!selectedFile}>
            {t({ en: "Add Media", ar: "إضافة وسائط" }, lang)}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"
import { useCallback, useEffect, useState } from "react"
import pb, { getErrorMessage } from "@/lib/pb"
import { useRequestGuard } from "./useRequestGuard"
export function useAssessmentCounts(enabled = true) {
  const [sessions, setSessions] = useState<
    { case: string; status: string; count: number }[]
  >([])
  const [error, setError] = useState("")
  const begin = useRequestGuard(String(enabled))
  const reload = useCallback(async () => {
    const valid = begin()
    setSessions([])
    setError("")
    if (!enabled) return
    try {
      const result = await pb.send<{
        items: { case: string; status: string; count: number }[]
      }>("/api/dsc/assessment-session-counts", { method: "GET" })
      if (valid()) setSessions(result.items)
    } catch (e) {
      if (valid()) setError(getErrorMessage(e))
    }
  }, [begin, enabled])
  useEffect(() => {
    void reload()
  }, [reload])
  return { sessions, error, reload }
}

"use client"
import { useRequestGuard } from "@/hooks/useRequestGuard"
import { DEFAULT_COUNTRY_CODE } from "@/lib/country-codes"

import { useCallback, useEffect, useState } from "react"
import pb, { getErrorMessage } from "@/lib/pb"
import type { ExpertProfile, ExpertProfileDraft } from "@/types/expert"

function toText(value: unknown): string {
  if (typeof value === "string") return value
  if (typeof value === "number") return String(value)
  return ""
}

import { toStringList, recordStringArray } from "@/lib/expert-list-fields"
export { toStringList, recordStringArray } from "@/lib/expert-list-fields"

export function emptyDraft(name = ""): ExpertProfileDraft {
  return {
    name,
    countryOfResidence: "",
    city: "",
    whatsappCountryCode: DEFAULT_COUNTRY_CODE,
    whatsappNumber: "",
    highestAcademicDegree: "",
    degreeTitle: "",
    fieldOfStudy: "",
    ageGroup: [],
    specialization: [],
    specialistRoles: [],
    consultationMode: "",
    fee: "",
    availability: "",
    bio: "",
    publicNameEn: "",
    publicNameAr: "",
    publicQualificationEn: "",
    publicQualificationAr: "",
    publicSpecialtyEn: "",
    publicSpecialtyAr: "",
    shortBioEn: "",
    shortBioAr: "",
    newPhoto: null,
    removePhoto: false,
    keptCv: [],
    newCv: [],
  }
}

/**
 * Builds an editable draft out of a stored profile record. A null record (an
 * expert with no profile row yet) yields an empty draft that save() creates.
 */
export function draftFromProfile(
  profile: ExpertProfile | null,
  name = ""
): ExpertProfileDraft {
  if (!profile) return emptyDraft(name)
  return {
    name,
    countryOfResidence: toText(profile.country_of_residence),
    city: toText(profile.city),
    whatsappCountryCode:
      toText(profile.whatsapp_country_code) || DEFAULT_COUNTRY_CODE,
    whatsappNumber: toText(profile.whatsapp_number),
    highestAcademicDegree: toText(profile.highest_academic_degree),
    degreeTitle: toText(profile.degree_title),
    fieldOfStudy: toText(profile.field_of_study),
    ageGroup: toStringList(profile.age_group),
    specialization: toStringList(profile.specialization_type),
    specialistRoles: recordStringArray(profile.specialist_roles),
    consultationMode: toText(profile.consultation_mode),
    fee: toText(profile.fee),
    availability: toText(profile.availability),
    bio: toText(profile.bio),
    publicNameEn:
      profile.public_name_en == null
        ? !/[\u0600-\u06ff]/.test(name)
          ? name
          : ""
        : toText(profile.public_name_en),
    publicNameAr:
      profile.public_name_ar == null
        ? /[\u0600-\u06ff]/.test(name)
          ? name
          : ""
        : toText(profile.public_name_ar),
    publicQualificationEn: toText(profile.public_qualification_en),
    publicQualificationAr: toText(profile.public_qualification_ar),
    publicSpecialtyEn: toText(profile.public_specialty_en),
    publicSpecialtyAr: toText(profile.public_specialty_ar),
    shortBioEn: toText(profile.short_bio_en),
    shortBioAr: toText(profile.short_bio_ar),
    newPhoto: null,
    removePhoto: false,
    keptCv: recordStringArray(profile.cv),
    newCv: [],
  }
}

/**
 * Builds a private file URL using the short-lived PocketBase file token, which
 * is required when the file's collection is not publicly readable.
 */
export function profileFileUrl(
  profile: ExpertProfile | null,
  filename: string,
  fileToken: string
): string {
  if (!profile || !filename) return ""
  return pb.files.getURL(
    profile as never,
    filename,
    fileToken ? { token: fileToken } : {}
  )
}

/** The stored profile photo filename, or "" when none is set. */
export function profilePhotoName(profile: ExpertProfile | null): string {
  return toText(profile?.profile_photo)
}

/**
 * Builds the expert_profiles payload for a draft. Shared by the expert's own
 * save and the admin's editor so the two cannot drift on field names or the
 * multi-select encoding.
 */
function expertProfileFormData(
  draft: ExpertProfileDraft,
  userId: string,
  profileId?: string
): FormData {
  const formData = new FormData()
  formData.set("country_of_residence", draft.countryOfResidence.trim())
  formData.set("city", draft.city.trim())
  formData.set("whatsapp_country_code", draft.whatsappCountryCode.trim())
  formData.set("whatsapp_number", draft.whatsappNumber.trim())
  formData.set("highest_academic_degree", draft.highestAcademicDegree)
  formData.set("degree_title", draft.degreeTitle.trim())
  formData.set("field_of_study", draft.fieldOfStudy.trim())
  formData.set("specialist_roles", JSON.stringify(draft.specialistRoles))

  formData.set("age_group", draft.ageGroup.join(", "))
  formData.set("specialization_type", draft.specialization.join(", "))

  formData.set("consultation_mode", draft.consultationMode)
  formData.set("fee", draft.fee.trim())
  formData.set("availability", draft.availability.trim())
  formData.set("public_name_en", draft.publicNameEn.trim())
  formData.set("public_name_ar", draft.publicNameAr.trim())
  formData.set("public_qualification_en", draft.publicQualificationEn.trim())
  formData.set("public_qualification_ar", draft.publicQualificationAr.trim())
  formData.set("public_specialty_en", draft.publicSpecialtyEn.trim())
  formData.set("public_specialty_ar", draft.publicSpecialtyAr.trim())
  formData.set("short_bio_en", draft.shortBioEn)
  formData.set("short_bio_ar", draft.shortBioAr)

  // An empty string clears a single-file field in PocketBase.
  if (draft.removePhoto) {
    formData.set("profile_photo", "")
    formData.set("confirm_profile_photo_removal", "true")
  } else if (draft.newPhoto) {
    formData.append("profile_photo", draft.newPhoto)
  }

  // Re-sending stored filenames preserves the documents on the record;
  // anything removed is simply left out.
  draft.keptCv.forEach((filename) => formData.append("cv", filename))
  draft.newCv.forEach((file) => formData.append("cv", file))
  if (!draft.keptCv.length && !draft.newCv.length) formData.set("cv", "")

  if (!profileId) {
    formData.set("user", userId)
  }
  return formData
}

/**
 * Writes an expert profile on behalf of a user. Works for the signed-in expert
 * and for an admin editing someone else's application.
 */
export async function saveExpertProfileFor(
  draft: ExpertProfileDraft,
  userId: string,
  profileId?: string
): Promise<ExpertProfile> {
  if (draft.shortBioEn.length > 250 || draft.shortBioAr.length > 250)
    throw new Error("Each short biography must be at most 250 characters.")
  if (!draft.publicNameAr.trim() || !draft.publicNameEn.trim())
    throw new Error(
      "يجب إدخال اسم الخبير بالعربية والإنجليزية قبل الحفظ. / Both Arabic and English expert names are required."
    )
  const formData = expertProfileFormData(draft, userId, profileId)
  const collection = pb.collection("expert_profiles")
  const saved = profileId
    ? await collection.update(profileId, formData)
    : await collection.create(formData)
  if (pb.authStore?.record?.id === userId)
    pb.authStore.save(pb.authStore.token, {
      ...pb.authStore.record,
      name: draft.publicNameAr.trim(),
    })
  return saved as unknown as ExpertProfile
}

export function useExpertProfile(userId?: string) {
  const [profile, setProfile] = useState<ExpertProfile | null>(null)
  const [fileToken, setFileToken] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const [loadError, setLoadError] = useState("")

  const beginRequest = useRequestGuard(userId || "")

  const load = useCallback(async () => {
    const isCurrent = beginRequest()
    setProfile(null)

    if (!userId) {
      setIsLoading(false)
      return
    }
    setIsLoading(true)
    setLoadError("")
    try {
      const record = await pb
        .collection("expert_profiles")
        .getFirstListItem(pb.filter("user = {:value0}", { value0: userId }))
      if (!isCurrent()) return
      setProfile(record as unknown as ExpertProfile)
    } catch (error) {
      if (!isCurrent()) return
      // An expert without a profile row is a valid state, not a failure.
      const status = (error as { status?: number }).status
      if (status === 404) {
        setProfile(null)
      } else {
        setProfile(null)
        setLoadError(getErrorMessage(error))
      }
    } finally {
      if (isCurrent()) setIsLoading(false)
    }
  }, [userId, beginRequest])

  useEffect(() => {
    // Begin the external profile fetch when the selected expert changes.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    load()
  }, [load])

  useEffect(() => {
    let cancelled = false
    const authIdentity = pb.authStore.record?.id
    setFileToken("")
    pb.files
      .getToken()
      .then((token) => {
        if (!cancelled && pb.authStore.record?.id === authIdentity)
          setFileToken(token)
      })
      .catch(() => {
        if (!cancelled && pb.authStore.record?.id === authIdentity)
          setFileToken("")
      })
    return () => {
      cancelled = true
    }
  }, [userId, beginRequest])

  const save = useCallback(
    async (draft: ExpertProfileDraft) => {
      if (!userId) throw new Error("No signed-in expert")
      const isCurrent = beginRequest()
      setIsSaving(true)
      try {
        // Updating users first syncs the PocketBase auth store on a self-update,
        // which keeps the sidebar name in step with the profile.
        const saved = await saveExpertProfileFor(draft, userId, profile?.id)
        if (isCurrent()) setProfile(saved)
        return saved
      } finally {
        if (isCurrent()) setIsSaving(false)
      }
    },
    [userId, profile?.id, beginRequest]
  )

  return {
    profile,
    fileToken,
    isLoading,
    isSaving,
    loadError,
    reload: load,
    save,
  }
}

