"use client"

import { useRequestGuard } from "@/hooks/useRequestGuard"
import { useState, useEffect, useCallback } from "react"
import { toolsCollection } from "@/lib/pb-collections"
import type { Tool, ToolType, ServiceType } from "@/types/tool"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

export function useTools() {
  const [tools, setTools] = useState<Tool[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState("")

  const beginRequest = useRequestGuard("tools")

  const fetchTools = useCallback(async () => {
    const isCurrent = beginRequest()
    setTools([])

    setIsLoading(true)
    setLoadError("")
    try {
      const data = await toolsCollection.getAll()
      if (!isCurrent()) return
      setTools(data)
    } catch (error) {
      if (!isCurrent()) return
      setLoadError(getErrorMessage(error))
      console.error("Failed to fetch tools:", error)
      toast.error(getErrorMessage(error))
    } finally {
      if (isCurrent()) setIsLoading(false)
    }
  }, [beginRequest])

  useEffect(() => {
    fetchTools()
  }, [fetchTools])

  const addTool = async (data: Partial<Tool>) => {
    try {
      const newTool = await toolsCollection.create(data)
      setTools((prev) => [...prev, newTool])
      return newTool.id
    } catch (error) {
      console.error("Failed to create tool:", error)
      throw error
    }
  }

  const updateTool = async (id: string, data: Partial<Tool>) => {
    try {
      const updated = await toolsCollection.update(id, data)
      setTools((prev) => prev.map((t) => (t.id === id ? updated : t)))
    } catch (error) {
      console.error("Failed to update tool:", error)
      throw error
    }
  }

  const deleteTool = async (id: string) => {
    try {
      await toolsCollection.delete(id)
      setTools((prev) => prev.filter((t) => t.id !== id))
    } catch (error) {
      console.error("Failed to delete tool:", error)
      throw error
    }
  }

  const getToolById = useCallback((id: string) => tools.find((t) => t.id === id), [tools])

  const getToolsByType = (type: ToolType) =>
    tools.filter((t) => t.type === type)

  const getToolsByServiceType = (serviceType: ServiceType) =>
    tools.filter(
      (t) => t.serviceType === serviceType || t.serviceType === "both"
    )

  const activeTools = tools.filter((t) => t.status === "active")

  return {
    tools,
    activeTools,
    isLoading,
    loadError,
    addTool,
    updateTool,
    deleteTool,
    getToolById,
    getToolsByType,
    getToolsByServiceType,
    refresh: fetchTools,
  }
}

"use client"

import { useState, useEffect, useCallback } from "react"
import type {
  TrainingProgram,
  TrainingRegistration,
  TrainingCertificate,
  CreateProgramInput,
  UpdateProgramInput,
  CreateCertificateInput,
  UpdateCertificateInput,
  ProgramStats,
} from "@/types/training"
import { getErrorMessage } from "@/lib/pb"
import { normalizeEmail } from "@/lib/validators"
import {
  trainingProgramsCollection,
  trainingRegistrationsCollection,
  trainingCertificatesCollection,
} from "@/lib/pb-training"

export function useTraining() {
  const [programs, setPrograms] = useState<TrainingProgram[]>([])
  const [registrations, setRegistrations] = useState<TrainingRegistration[]>([])
  const [certificates, setCertificates] = useState<TrainingCertificate[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const loadData = useCallback(async () => {
    setIsLoading(true)
    setError(null)
    try {
      const [programsData, registrationsData, certificatesData] =
        await Promise.all([
          trainingProgramsCollection.getAll(),
          trainingRegistrationsCollection.getAll(),
          trainingCertificatesCollection.getAll(),
        ])
      setPrograms(programsData)
      setRegistrations(registrationsData)
      setCertificates(certificatesData)
    } catch (err) {
      const message = getErrorMessage(err)
      setError(message)
      console.error("Failed to load training data:", err)
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData])

  // Program CRUD
  const addProgram = async (data: CreateProgramInput) => {
    const { thumbnail, ...rest } = data
    const file = thumbnail instanceof File ? thumbnail : undefined
    const newProgram = await trainingProgramsCollection.create(rest, file)
    setPrograms((prev) => [...prev, newProgram])
    return newProgram.id
  }

  const updateProgram = async (id: string, data: UpdateProgramInput) => {
    const { thumbnail, ...rest } = data
    const file = thumbnail instanceof File ? thumbnail : undefined
    const updated = await trainingProgramsCollection.update(id, rest, file)
    setPrograms((prev) => prev.map((p) => (p.id === id ? updated : p)))
  }

  const deleteProgram = async (id: string) => {
    await trainingProgramsCollection.delete(id)
    setPrograms((prev) => prev.filter((p) => p.id !== id))
    setRegistrations((prev) => prev.filter((r) => r.programId !== id))
  }

  const getProgramById = (id: string) => {
    return programs.find((p) => p.id === id)
  }

  // Filter: Programs
  const getPublishedPrograms = useCallback(() => {
    return programs
      .filter((p) => p.status === "published" || p.status === "in_progress")
      .sort(
        (a, b) =>
          new Date(a.schedule.startDate).getTime() -
          new Date(b.schedule.startDate).getTime()
      )
  }, [programs])

  const getUpcomingPrograms = useCallback(() => {
    const now = new Date()
    return programs
      .filter(
        (p) =>
          new Date(p.schedule.startDate) > now &&
          (p.status === "published" || p.status === "in_progress")
      )
      .sort(
        (a, b) =>
          new Date(a.schedule.startDate).getTime() -
          new Date(b.schedule.startDate).getTime()
      )
  }, [programs])

  const getPastPrograms = useCallback(() => {
    const now = new Date()
    return programs
      .filter(
        (p) => new Date(p.schedule.endDate) < now || p.status === "completed"
      )
      .sort(
        (a, b) =>
          new Date(b.schedule.endDate).getTime() -
          new Date(a.schedule.endDate).getTime()
      )
  }, [programs])

  // Registration
  const registerForProgram = async (
    programId: string,
    userData: {
      userId: string
      userName: string
      email: string
      phone?: string
    }
  ) => {
    const newRegistration = await trainingRegistrationsCollection.create({
      programId,
      ...userData,
      userName: userData.userName.trim(),
      email: normalizeEmail(userData.email),
      registeredAt: new Date().toISOString(),
      status: "registered",
    })
    setRegistrations((prev) => [...prev, newRegistration])
    await loadData()
    return newRegistration.id
  }

  const cancelRegistration = async (registrationId: string) => {
    const registration = registrations.find((r) => r.id === registrationId)
    if (!registration) return

    const updated = await trainingRegistrationsCollection.update(
      registrationId,
      {
        status: "cancelled",
      }
    )

    await loadData()

    setRegistrations((prev) =>
      prev.map((r) => (r.id === registrationId ? updated : r))
    )
  }

  const updateRegistrationStatus = async (
    registrationId: string,
    status: TrainingRegistration["status"]
  ) => {
    const updated = await trainingRegistrationsCollection.update(
      registrationId,
      { status } as unknown as Partial<TrainingRegistration>
    )
    setRegistrations((prev) =>
      prev.map((r) => (r.id === registrationId ? updated : r))
    )
    await loadData()
    return updated
  }

  const deleteRegistration = async (registrationId: string) => {
    const registration = registrations.find((r) => r.id === registrationId)
    if (!registration) return

    await trainingRegistrationsCollection.delete(registrationId)

    await loadData()

    setRegistrations((prev) => prev.filter((r) => r.id !== registrationId))
  }

  const getUserProgramRegistration = (programId: string, userId: string) => {
    return registrations.find(
      (r) =>
        r.programId === programId &&
        r.userId === userId &&
        r.status !== "cancelled"
    )
  }

  const getRegistrationsByProgram = (programId: string) => {
    return registrations.filter((r) => r.programId === programId)
  }

  const getUserRegistrations = (userId: string) => {
    return registrations.filter(
      (r) => r.userId === userId && r.status !== "cancelled"
    )
  }

  // Certificates
  const getUserCertificates = (userId: string) => {
    return certificates.filter((c) => c.userId === userId)
  }

  const getCertificateById = (id: string) => {
    return certificates.find((c) => c.id === id)
  }

  const addCertificate = async (data: CreateCertificateInput, file?: File) => {
    const newCertificate = await trainingCertificatesCollection.create(
      data,
      file
    )
    setCertificates((prev) => [...prev, newCertificate])
    return newCertificate.id
  }

  const updateCertificate = async (
    id: string,
    data: UpdateCertificateInput,
    file?: File
  ) => {
    const updated = await trainingCertificatesCollection.update(id, data, file)
    setCertificates((prev) => prev.map((c) => (c.id === id ? updated : c)))
    return updated
  }

  const deleteCertificate = async (id: string) => {
    await trainingCertificatesCollection.delete(id)
    setCertificates((prev) => prev.filter((c) => c.id !== id))
  }

  // Stats
  const getProgramStats = (programId: string): ProgramStats => {
    const programRegs = registrations.filter(
      (r) => r.programId === programId && r.status !== "cancelled"
    )
    const totalRegistered = programRegs.length
    const totalCompleted = programRegs.filter(
      (r) => r.status === "completed" || r.status === "attended"
    ).length
    const attendanceRate =
      totalRegistered > 0
        ? Math.round((totalCompleted / totalRegistered) * 100)
        : 0

    return {
      totalRegistered,
      totalCompleted,
      attendanceRate,
    }
  }

  // Helpers
  const isProgramFull = (programId: string) => {
    const program = getProgramById(programId)
    if (!program || !program.maxParticipants) return false
    return program.currentRegistrations >= program.maxParticipants
  }

  const isProgramPast = (programId: string) => {
    const program = getProgramById(programId)
    if (!program) return false
    return new Date(program.schedule.endDate) < new Date()
  }

  return {
    programs,
    registrations,
    certificates,
    isLoading,
    error,
    addProgram,
    updateProgram,
    deleteProgram,
    getProgramById,
    getPublishedPrograms,
    getUpcomingPrograms,
    getPastPrograms,
    registerForProgram,
    cancelRegistration,
    updateRegistrationStatus,
    deleteRegistration,
    getUserProgramRegistration,
    getRegistrationsByProgram,
    getUserRegistrations,
    getUserCertificates,
    getCertificateById,
    addCertificate,
    updateCertificate,
    deleteCertificate,
    getProgramStats,
    isProgramFull,
    isProgramPast,
    refresh: loadData,
  }
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { useLang } from "@/lib/lang-context"
import pb, { getErrorMessage } from "@/lib/pb"
import { ROLE_PROFILE_COLLECTION, type AnyUserProfile } from "@/types/account-profile"
import type { UserRole } from "@/types/user"
import { ROLE_PROFILE_SECTIONS } from "@/lib/user-profile-fields"

/**
 * Values the admin can change on a user: the two editable columns on the
 * account row, plus every field the role's profile collection holds.
 */
export interface UserProfileDraft {
  name: string
  contactNumber: string
  fields: Record<string, string>
  notes: string
}

export function draftFromUserProfile(
  user: { name: string; contact_number: string; role: UserRole },
  profile: AnyUserProfile | null
): UserProfileDraft {
  const source = (profile ?? {}) as unknown as Record<string, unknown>
  const fields: Record<string, string> = {}
  for (const section of ROLE_PROFILE_SECTIONS[user.role] ?? []) {
    for (const field of section.fields) {
      const value = source[field.field]
      fields[field.field] = typeof value === "string" ? value : ""
    }
  }
  return {
    name: user.name ?? "",
    contactNumber: user.contact_number ?? "",
    fields,
    notes: typeof profile?.notes === "string" ? profile.notes : "",
  }
}

/**
 * Loads the profile record that matches a user's role. Both a role with no
 * profile collection (admins) and a record that was never created resolve to
 * null without an error, since neither is a failure for an admin browsing
 * users.
 *
 * `role` being undefined means it is not known yet, which keeps `isLoading`
 * true. Treating that as "no profile" would briefly render an empty profile
 * before the users list resolves.
 */
/**
 * Select and date columns reject an empty string with an "Invalid value" error,
 * so a cleared control is sent as null, which PocketBase accepts to unset an
 * optional field. Text columns keep the empty string.
 */
function nullableFields(fields: Record<string, string>): Record<string, string | null> {
  const nonText = new Set<string>()
  for (const section of Object.values(ROLE_PROFILE_SECTIONS)) {
    for (const item of section ?? []) {
      for (const field of item.fields) {
        if (field.input === "select" || field.input === "date") {
          nonText.add(field.field)
        }
      }
    }
  }

  const payload: Record<string, string | null> = {}
  for (const [key, value] of Object.entries(fields)) {
    payload[key] = nonText.has(key) && !value ? null : value
  }
  return payload
}

export function useUserProfileRecord(userId?: string, role?: UserRole) {
  const { lang } = useLang()
  const generation = useRef(0)
  const activeRequest = useRef<AbortController | null>(null)
  const [profile, setProfile] = useState<AnyUserProfile | null>(null)
  const [fileToken, setFileToken] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const [loadError, setLoadError] = useState("")

  const collectionName = role ? ROLE_PROFILE_COLLECTION[role] : undefined
  const isRoleKnown = Boolean(role)

  const load = useCallback(async () => {
    const current = ++generation.current
    activeRequest.current?.abort()
    activeRequest.current = null
    setProfile(null)
    setLoadError("")
    if (!isRoleKnown) {
      setIsLoading(true)
      return
    }
    if (!userId || !collectionName) {
      setIsLoading(false)
      return
    }
    setIsLoading(true)
    const controller = new AbortController()
    activeRequest.current = controller
    let timedOut = false
    let timeout: ReturnType<typeof setTimeout> | undefined
    try {
      const deadline = new Promise<never>((_, reject) => {
        timeout = setTimeout(() => {
          timedOut = true
          controller.abort()
          reject(new Error("Profile request timed out"))
        }, 15_000)
      })
      const request = pb.collection(collectionName).getFirstListItem(
        pb.filter("user = {:value0}", { value0: userId }),
        {requestKey:null, signal:controller.signal}
      )
      const record = await Promise.race([request, deadline])
      if (generation.current === current) setProfile(record as unknown as AnyUserProfile)
    } catch (error) {
      if (generation.current !== current) return
      const status = (error as {status?:number}).status
      if (timedOut) {
        setLoadError(lang === "ar" ? "استغرق تحميل الملف وقتاً طويلاً. يرجى إعادة المحاولة." : "The profile request timed out. Please try again.")
      } else if (status !== 404) {
        setLoadError(getErrorMessage(error, lang))
      }
    } finally {
      if (timeout) clearTimeout(timeout)
      if (generation.current === current) {
        activeRequest.current = null
        setIsLoading(false)
      }
    }
  }, [userId, collectionName, isRoleKnown, lang])

  useEffect(() => {
    void load()
    return () => {
      // This ref is a request counter: invalidate even a manual reload on unmount.
      // eslint-disable-next-line react-hooks/exhaustive-deps
      generation.current++
      activeRequest.current?.abort()
      activeRequest.current = null
    }
  }, [load])

  useEffect(() => {
    let cancelled = false
    pb.files
      .getToken()
      .then((token) => {
        if (!cancelled) setFileToken(token)
      })
      .catch(() => {
        if (!cancelled) setFileToken("")
      })
    return () => {
      cancelled = true
    }
  }, [])

  /**
   * Writes the account columns first, then the profile record. The account row
   * is updated separately because it lives in a different collection. Creates
   * the profile row when the user has never submitted one.
   */
  const save = useCallback(
    async (draft: UserProfileDraft) => {
      if (!userId) throw new Error("No user selected")
      if (!collectionName) {
        // Admin accounts have no profile collection; only the row updates.
        await pb.collection("users").update(userId, {
          name: draft.name.trim(),
          contact_number: draft.contactNumber.trim(),
        })
        return null
      }

      setIsSaving(true)
      try {
        await pb.collection("users").update(userId, {
          name: draft.name.trim(),
          contact_number: draft.contactNumber.trim(),
        })

        const payload: Record<string, unknown> = {
          // Select and date fields reject an empty string, so a cleared value
          // is sent as null instead. PocketBase accepts null to unset an
          // optional field.
          ...nullableFields(draft.fields),
          notes: draft.notes.trim() || null,
        }
        if (!profile?.id) {
          payload.user = userId
        }
        const saved = profile?.id
          ? await pb.collection(collectionName).update(profile.id, payload)
          : await pb.collection(collectionName).create(payload)
        setProfile(saved as unknown as AnyUserProfile)
        return saved as unknown as AnyUserProfile
      } finally {
        setIsSaving(false)
      }
    },
    [userId, collectionName, profile?.id]
  )

  return {
    profile,
    fileToken,
    isLoading,
    isSaving,
    loadError,
    reload: load,
    save,
  }
}

"use client"

import { useRequestGuard } from "@/hooks/useRequestGuard"
import { boundedFullList } from "@/lib/bounded-records"
import { useState, useEffect, useCallback } from "react"
import pb, { getCurrentUser, getErrorMessage } from "@/lib/pb"
import { normalizeEmail } from "@/lib/validators"
import type { User } from "@/types/user"
import { toast } from "sonner"

export function useUsers(enabled = true) {
  const [users, setUsers] = useState<User[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState("")

  const beginRequest = useRequestGuard(enabled ? "enabled" : "disabled")

  const fetchUsers = useCallback(async () => {
    const isCurrent = beginRequest()
    setUsers([])

    if (!enabled) {
      setUsers([])
      setIsLoading(false)
      return
    }
    setIsLoading(true)
    setIsLoading(true)
    setLoadError("")
    try {
      const data = await boundedFullList(pb.collection("users"), {
        sort: "-created",
      })
      if (!isCurrent()) return
      setUsers(data as unknown as User[])
    } catch (error) {
      if (!isCurrent()) return
      setLoadError(getErrorMessage(error))
      console.error("Failed to fetch users:", error)
      toast.error(getErrorMessage(error))
    } finally {
      if (isCurrent()) setIsLoading(false)
    }
  }, [enabled, beginRequest])

  useEffect(() => {
    fetchUsers()
  }, [fetchUsers])

  const addUser = async (data: {
    email: string
    password: string
    passwordConfirm: string
    name: string
    role: string
    contact_number?: string
    is_active?: boolean
  }) => {
    try {
      const newUser = await pb.collection("users").create({
        ...data,
        email: normalizeEmail(data.email),
        name: data.name.trim(),
        emailVisibility: true,
      })
      setUsers((prev) => [newUser as unknown as User, ...prev])
      return newUser.id
    } catch (error) {
      console.error("Failed to create user:", error)
      throw error
    }
  }

  const updateUser = async (id: string, data: Partial<User>) => {
    try {
      const target = users.find((user) => user.id === id)
      const approvingExpert =
        getCurrentUser()?.role !== "super_admin" &&
        target?.role === "expert" &&
        !target.is_active &&
        data.is_active === true &&
        Object.keys(data).length === 1
      if (approvingExpert) {
        await pb.send(`/api/dsc/security/experts/${id}/approve`, {
          method: "POST",
        })
      }
      const updated = approvingExpert
        ? await pb.collection("users").getOne(id)
        : await pb.collection("users").update(id, data)
      setUsers((prev) =>
        prev.map((u) => (u.id === id ? (updated as unknown as User) : u))
      )
    } catch (error) {
      console.error("Failed to update user:", error)
      throw error
    }
  }

  /**
   * Sets a new password on a user's auth record. PocketBase stores only the
   * hash, so the admin has to communicate the plaintext out of band. Note this
   * does not revoke the user's existing sessions.
   */
  const resetPassword = async (id: string, password: string) => {
    try {
      const updated = await pb.collection("users").update(id, {
        password,
        passwordConfirm: password,
      })
      setUsers((prev) =>
        prev.map((u) => (u.id === id ? (updated as unknown as User) : u))
      )
    } catch (error) {
      console.error("Failed to reset password:", error)
      throw error
    }
  }

  const getDeletionBlockers = async (id: string) => {
    return pb.send<{ cases: number; assignments: number }>(
      `/api/dsc/security/users/${id}/deletion-check`,
      { method: "GET" }
    )
  }

  const deleteUser = async (id: string) => {
    try {
      const blockers = await getDeletionBlockers(id)
      if (blockers.cases > 0 || blockers.assignments > 0) {
        throw new Error(
          "This user has linked cases or expert assignments and cannot be deleted."
        )
      }

      await pb.collection("users").delete(id)
      setUsers((prev) => prev.filter((u) => u.id !== id))
    } catch (error) {
      console.error("Failed to delete user:", error)
      throw error
    }
  }

  const refresh = fetchUsers

  return {
    users,
    isLoading,
    loadError,
    addUser,
    updateUser,
    resetPassword,
    deleteUser,
    getDeletionBlockers,
    refresh,
  }
}

